def platform_family(platform_name: str | None = None) -> str:
    """Return the small platform set used by downloads and local launching."""
    selected = str(platform_name or sys.platform).casefold()
    if selected.startswith("win"):
        return "windows"
    if selected == "darwin":
        return "macos"
    return "linux"


def platform_application_data_directory(
    platform_name: str | None = None,
    home: Path | None = None,
    environment: dict[str, str] | None = None,
) -> Path:
    """Return the native per-user data folder without requiring admin rights."""
    family = platform_family(platform_name)
    selected_home = Path(home) if home is not None else Path.home()
    selected_environment = os.environ if environment is None else environment
    if family == "windows":
        root = str(selected_environment.get("LOCALAPPDATA", "")).strip()
        return Path(root or selected_home) / "SMWStreamTracker"
    if family == "macos":
        return (
            selected_home
            / "Library"
            / "Application Support"
            / "SMWStreamTracker"
        )
    xdg_root = str(selected_environment.get("XDG_DATA_HOME", "")).strip()
    return Path(xdg_root or selected_home / ".local" / "share") / (
        "SMWStreamTracker"
    )


def retroarch_core_download_url(machine: str | None = None) -> str:
    architecture = str(machine or system_platform.machine()).casefold()
    if architecture in {"arm64", "aarch64"}:
        return MACOS_RETROARCH_ARM_CORE_DOWNLOAD_URL
    return MACOS_RETROARCH_X86_CORE_DOWNLOAD_URL


def retroarch_core_filename(platform_name: str | None = None) -> str:
    extension = ".dll" if platform_family(platform_name) == "windows" else (
        ".dylib" if platform_family(platform_name) == "macos" else ".so"
    )
    return "bsnes_mercury_performance_libretro" + extension


def normalized_executable_name(path: Path | str) -> str:
    name = Path(path).name.casefold()
    return name[:-4] if name.endswith(".exe") else name


def connection_service_kind(path: Path | str) -> str:
    name = normalized_executable_name(path)
    if name == "sni":
        return "SNI"
    if name == "qusb2snes":
        return "QUsb2Snes"
    return ""


def retroarch_bundle_resources(executable: Path) -> Path:
    bundle = macos_application_bundle(executable)
    if bundle is not None:
        return bundle / "Contents" / "Resources"
    return executable.parent


def retroarch_core_directory(executable: Path) -> Path:
    if IS_MACOS:
        resources = retroarch_bundle_resources(executable)
        bundled_cores = resources / "cores"
        user_cores = (
            Path.home()
            / "Library"
            / "Application Support"
            / "RetroArch"
            / "cores"
        )
        # The tracker-managed RetroArch copy is writable, but an app already
        # installed in /Applications commonly is not. The core can be loaded
        # from either location, so prefer the bundle only when it is writable.
        if bundled_cores.is_dir() and os.access(bundled_cores, os.W_OK):
            return bundled_cores
        if (
            not bundled_cores.exists()
            and resources.is_dir()
            and os.access(resources, os.W_OK)
        ):
            return bundled_cores
        return user_cores
    return executable.parent / "cores"


def retroarch_config_path(executable: Path) -> Path:
    if IS_MACOS:
        return Path.home() / ".config" / "retroarch" / "retroarch.cfg"
    return executable.parent / "retroarch.cfg"


def macos_application_bundle(path: Path) -> Path | None:
    """Return the enclosing .app for a bundle executable, when applicable."""
    candidate = Path(path)
    for parent in (candidate, *candidate.parents):
        if parent.suffix.casefold() == ".app" and parent.is_dir():
            return parent
    return None


def open_local_path(path: Path | str) -> None:
    """Open a document or folder with the operating system's default app."""
    selected_path = str(path)
    if IS_WINDOWS:
        os.startfile(selected_path)
        return
    opener = "open" if IS_MACOS else "xdg-open"
    subprocess.Popen([opener, selected_path])


def launch_local_application(
    executable: Path | str,
    arguments: list[str] | tuple[str, ...] = (),
) -> None:
    """Launch an executable, preserving normal macOS .app behavior."""
    executable_path = Path(executable)
    argument_list = [str(value) for value in arguments]
    if IS_WINDOWS:
        if argument_list:
            subprocess.Popen([str(executable_path), *argument_list])
        else:
            os.startfile(str(executable_path))
        return
    if IS_MACOS:
        bundle = macos_application_bundle(executable_path)
        if bundle is not None:
            command = ["open", "-n", str(bundle)]
            if argument_list:
                command.extend(["--args", *argument_list])
            subprocess.Popen(command)
            return
    subprocess.Popen([str(executable_path), *argument_list])


def safe_extract_tar_archive(archive_path: Path, destination: Path) -> None:
    """Extract an official dependency tarball without permitting path escape."""
    destination.mkdir(parents=True, exist_ok=True)
    destination_root = destination.resolve()
    with tarfile.open(archive_path, "r:*") as archive:
        for member in archive.getmembers():
            member_target = (destination / member.name).resolve()
            if (
                member_target != destination_root
                and destination_root not in member_target.parents
            ):
                raise RuntimeError(
                    "The downloaded archive contains an unsafe path."
                )
        archive.extractall(destination, filter="data")


def macos_bundle_executable(bundle: Path) -> Path:
    """Find the primary executable declared by a macOS application bundle."""
    info_path = bundle / "Contents" / "Info.plist"
    try:
        info = plistlib.loads(info_path.read_bytes())
    except (OSError, plistlib.InvalidFileException) as error:
        raise RuntimeError(
            f"The downloaded Mac app has an unreadable Info.plist: {bundle}"
        ) from error
    executable_name = str(info.get("CFBundleExecutable", "")).strip()
    executable = bundle / "Contents" / "MacOS" / executable_name
    if not executable_name or not executable.is_file():
        raise FileNotFoundError(
            f"The downloaded Mac app has no usable executable: {bundle}"
        )
    executable.chmod(executable.stat().st_mode | stat.S_IXUSR)
    return executable


def selected_application_executable(path: Path | str) -> Path:
    """Convert a Finder-selected .app package into its real executable."""
    selected = Path(path)
    if IS_MACOS and selected.suffix.casefold() == ".app" and selected.is_dir():
        return macos_bundle_executable(selected)
    return selected


def install_macos_dmg_application(
    dmg_path: Path,
    destination: Path,
    expected_bundle_name: str,
) -> Path:
    """Copy one official .app from a DMG into the user's tracker tools."""
    if not IS_MACOS:
        raise RuntimeError("DMG installation is available only on macOS.")
    attach = subprocess.run(
        ["hdiutil", "attach", "-nobrowse", "-readonly", "-plist", str(dmg_path)],
        capture_output=True,
        check=False,
        timeout=120,
    )
    if attach.returncode != 0:
        raise RuntimeError(
            "macOS could not mount the downloaded disk image: "
            + attach.stderr.decode("utf-8", errors="replace").strip()
        )
    try:
        attach_info = plistlib.loads(attach.stdout)
    except plistlib.InvalidFileException as error:
        raise RuntimeError(
            "macOS returned an unreadable disk-image mount response."
        ) from error
    mount_points = [
        Path(str(entity.get("mount-point", "")))
        for entity in attach_info.get("system-entities", [])
        if str(entity.get("mount-point", "")).strip()
    ]
    if not mount_points:
        raise RuntimeError("The downloaded disk image did not mount.")
    mount_point = mount_points[-1]
    try:
        bundles = list(mount_point.rglob(expected_bundle_name))
        if not bundles:
            bundles = list(mount_point.rglob("*.app"))
        if len(bundles) != 1:
            raise FileNotFoundError(
                f"{expected_bundle_name} was not found in the downloaded disk image."
            )
        source_bundle = bundles[0]
        destination.mkdir(parents=True, exist_ok=True)
        installed_bundle = destination / source_bundle.name
        if installed_bundle.exists():
            shutil.rmtree(installed_bundle)
        copied = subprocess.run(
            ["ditto", str(source_bundle), str(installed_bundle)],
            capture_output=True,
            text=True,
            check=False,
            timeout=300,
        )
        if copied.returncode != 0:
            raise RuntimeError(
                "macOS could not copy the downloaded application: "
                + (copied.stderr or copied.stdout or "unknown error").strip()
            )
        return macos_bundle_executable(installed_bundle)
    finally:
        subprocess.run(
            ["hdiutil", "detach", str(mount_point)],
            capture_output=True,
            check=False,
            timeout=60,
        )


def _configure_installed_tcl_tk_runtime() -> bool:
    """Prefer the installer-provided Tcl/Tk scripts when they are available.

    PyInstaller's one-file bundle also carries these files, but Windows security
    software can occasionally interrupt their temporary extraction.  Keeping a
    verified copy beside the installed app gives Tk a stable fallback that does
    not depend on the per-launch ``_MEI`` directory.
    """
    if getattr(sys, "frozen", False):
        app_directory = Path(sys.executable).resolve().parent
    else:
        app_directory = Path(__file__).resolve().parent

    runtime_directory = app_directory / "runtime"
    tcl_directory = runtime_directory / "tcl"
    tk_directory = runtime_directory / "tk"
    if not (tcl_directory / "init.tcl").is_file():
        return False
    if not (tk_directory / "tk.tcl").is_file():
        return False

    os.environ["TCL_LIBRARY"] = str(tcl_directory)
    os.environ["TK_LIBRARY"] = str(tk_directory)
    return True


def _show_native_startup_error(message: str) -> None:
    """Show a native startup error without requiring a working Tk install."""
    if IS_MACOS:
        def apple_script_string(value: str) -> str:
            escaped = (
                value.replace("\\", "\\\\")
                .replace('"', '\\"')
                .replace("\r", "")
                .replace("\n", "\\n")
            )
            return '"' + escaped + '"'

        script = (
            f"display alert {apple_script_string(APP_NAME)} "
            f"message {apple_script_string(message)} as critical "
            'buttons {"OK"} default button "OK"'
        )
        try:
            subprocess.run(
                ["osascript", "-e", script],
                capture_output=True,
                check=False,
                timeout=30,
            )
            return
        except (OSError, subprocess.SubprocessError):
            print(f"{APP_NAME}: {message}", file=sys.stderr)
            return
    try:
        ctypes.windll.user32.MessageBoxW(
            None,
            message,
            APP_NAME,
            0x00000010,
        )
    except Exception:
        pass


def _start_previous_version_rollback(startup_error: BaseException) -> bool:
    """Start the verified rollback helper after an installed update fails."""
    if os.name != "nt" or not getattr(sys, "frozen", False):
        return False

    local_app_data = os.environ.get("LOCALAPPDATA", "").strip()
    if not local_app_data:
        return False

    rollback_directory = Path(local_app_data) / "SMWStreamTracker" / "Rollback"
    backup_executable = rollback_directory / "SMWStreamTracker_previous.exe"
    backup_hash_file = rollback_directory / "SMWStreamTracker_previous.sha256"
    current_executable = Path(sys.executable).resolve()
    rollback_script = current_executable.parent / "rollback_update.ps1"
    if not all(
        path.is_file()
        for path in (backup_executable, backup_hash_file, rollback_script)
    ):
        return False

    expected_hash = backup_hash_file.read_text(
        encoding="utf-8-sig",
        errors="replace",
    ).strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
        return False
    actual_hash = hashlib.sha256(backup_executable.read_bytes()).hexdigest()
    if actual_hash != expected_hash:
        return False

    append_error_log(
        "Updated app failed its Tk startup check; restoring previous version",
        f"{type(startup_error).__name__}: {startup_error}",
    )
    powershell_executable = shutil.which("powershell.exe")
    if not powershell_executable:
        return False
    subprocess.Popen(
        [
            powershell_executable,
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(rollback_script),
            "-CurrentExe",
            str(current_executable),
            "-BackupExe",
            str(backup_executable),
            "-ProcessId",
            str(os.getpid()),
            "-ExpectedSha256",
            expected_hash,
        ],
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        close_fds=True,
    )
    return True


def _run_tk_startup_check() -> int:
    """Return success only after the complete main interface is constructed.

    A bare ``tk.Tk()`` probe confirms Tcl/Tk was bundled, but it cannot catch
    missing widget attributes, invalid layout options, or menu construction
    errors. Updates and release builds use this same check, so constructing
    ``TrackerApp`` here prevents a package that crashes during ``_build_ui``
    from replacing a working installation.
    """
    _configure_installed_tcl_tk_runtime()
    probe_root = None
    try:
        probe_root = tk.Tk()
        probe_root.withdraw()
        probe_app = TrackerApp(probe_root, startup_check=True)
        required_runtime_callbacks = (
            "_translate_dialog_text",
            "_ask_localized_yes_no",
            "_guided_setup_hacks_downloaded",
            "_finish_filtered_hack_download",
        )
        missing_callbacks = [
            callback_name
            for callback_name in required_runtime_callbacks
            if not callable(getattr(probe_app, callback_name, None))
        ]
        if missing_callbacks:
            raise AttributeError(
                "Packaged app is missing required runtime callback(s): "
                + ", ".join(missing_callbacks)
            )
        probe_root.update_idletasks()
        return 0
    except Exception as error:
        append_error_log(
            "Tcl/Tk startup check failed",
            f"{type(error).__name__}: {error}",
        )
        return 21
    finally:
        if probe_root is not None:
            try:
                probe_root.destroy()
            except Exception:
                pass


def bundled_resource_path(*parts: str) -> Path:
    base_path = Path(
        getattr(
            sys,
            "_MEIPASS",
            Path(__file__).resolve().parent,
        )
    )
    return base_path.joinpath(*parts)


def repair_bowser_toenail_image(source_image):
    """Fill the small transparent notch in Bowser's rear toenail."""
    if Image is None or ImageDraw is None:
        return source_image

    repaired = source_image.convert("RGBA").copy()
    width, height = repaired.size

    repair_points = (
        (0.8505, 0.9043),
        (0.8640, 0.9043),
        (0.8775, 0.9226),
        (0.8860, 0.9453),
        (0.8848, 0.9636),
        (0.8750, 0.9750),
        (0.8627, 0.9704),
        (0.8529, 0.9567),
        (0.8480, 0.9362),
    )
    scaled_points = [
        (
            round(width * x_fraction),
            round(height * y_fraction),
        )
        for x_fraction, y_fraction in repair_points
    ]
    mask = Image.new("L", repaired.size, 0)
    ImageDraw.Draw(mask).polygon(scaled_points, fill=255)
    if ImageFilter is not None:
        mask = mask.filter(
            ImageFilter.GaussianBlur(
                radius=max(0.45, width / 816 * 0.65)
            )
        )

    repair_layer = Image.new(
        "RGBA",
        repaired.size,
        (0, 0, 0, 0),
    )
    repair_draw = ImageDraw.Draw(repair_layer)
    top_y = min(point[1] for point in scaled_points)
    bottom_y = max(point[1] for point in scaled_points)
    top_color = (255, 244, 224)
    bottom_color = (211, 146, 137)
    for repair_y in range(top_y, bottom_y + 1):
        blend = (
            (repair_y - top_y)
            / max(1, bottom_y - top_y)
        )
        color = tuple(
            round(
                top_color[channel]
                + (bottom_color[channel] - top_color[channel])
                * blend
            )
            for channel in range(3)
        )
        repair_draw.line(
            (0, repair_y, width, repair_y),
            fill=(*color, 255),
        )
    repair_layer.putalpha(mask)
    return Image.alpha_composite(repair_layer, repaired)


def recolor_yoshi_body_blue_image(source_image):
    """Recolor only the supplied tongue-pose Yoshi's green body."""
    if Image is None:
        return source_image

    recolored = source_image.convert("RGBA").copy()
    original_alpha = recolored.getchannel("A")
    original_rgb = recolored.convert("RGB")
    hue, saturation, value = original_rgb.convert("HSV").split()

    # Green body tones in the supplied render occupy this hue band. Keep
    # their original saturation/value shading and replace only the hue with
    # the previous royal-blue Yoshi color.
    green_body_mask = hue.point(
        lambda pixel: 255 if 45 <= pixel <= 115 else 0
    )
    blue_hue = Image.new("L", recolored.size, 170)
    blue_rgb = Image.merge(
        "HSV",
        (blue_hue, saturation, value),
    ).convert("RGB")
    recolored_rgb = Image.composite(
        blue_rgb,
        original_rgb,
        green_body_mask,
    )
    recolored = recolored_rgb.convert("RGBA")
    recolored.putalpha(original_alpha)
    return recolored


