def format_display_date(
    value: object,
    empty: str = "—",
) -> str:
    if value in (None, ""):
        return empty

    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, date):
        parsed = datetime.combine(
            value,
            datetime.min.time(),
        )
    else:
        raw = str(value).strip()
        parsed = None

        for pattern in (
            "%Y-%m-%d",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%dT%H:%M:%S",
            "%m/%d/%Y",
            "%m/%d/%y",
        ):
            try:
                parsed = datetime.strptime(
                    raw[:19],
                    pattern,
                )
                break
            except ValueError:
                continue

        if parsed is None:
            try:
                parsed = datetime.fromisoformat(
                    raw.replace("Z", "+00:00")
                )
            except ValueError:
                return raw or empty

    return (
        f"{parsed:%b} {parsed.day}, "
        f"{parsed:%Y}"
    )


def format_display_datetime(
    value: object,
    empty: str = "Never",
) -> str:
    if value in (None, ""):
        return empty

    if isinstance(value, datetime):
        parsed = value
    else:
        raw = str(value).strip()

        try:
            parsed = datetime.fromisoformat(
                raw.replace("Z", "+00:00")
            )
        except ValueError:
            for pattern in (
                "%Y-%m-%d %H:%M:%S",
                "%Y-%m-%dT%H:%M:%S",
            ):
                try:
                    parsed = datetime.strptime(
                        raw[:19],
                        pattern,
                    )
                    break
                except ValueError:
                    parsed = None

            if parsed is None:
                return raw or empty

    hour = parsed.strftime("%I").lstrip("0") or "0"

    return (
        f"{parsed:%b} {parsed.day}, "
        f"{parsed:%Y} "
        f"{hour}:{parsed:%M %p}"
    )


class SMWCentralCatalogHTMLParser(HTMLParser):
    """Collect raw catalog table cells and pagination links."""

    def __init__(self) -> None:
        super().__init__(
            convert_charrefs=True
        )
        self.rows: list[
            list[dict[str, Any]]
        ] = []
        self.page_links: set[str] = set()

        self._list_depth = 0
        self._table_depth = 0
        self._tbody_depth = 0
        self._row: (
            list[dict[str, Any]]
            | None
        ) = None
        self._cell: (
            dict[str, Any]
            | None
        ) = None
        self._link: (
            dict[str, Any]
            | None
        ) = None

    @staticmethod
    def _attributes(
        attributes,
    ) -> dict[str, str]:
        return {
            str(key): str(value or "")
            for key, value in attributes
        }

    def handle_starttag(
        self,
        tag: str,
        attributes,
    ) -> None:
        attrs = self._attributes(
            attributes
        )

        if (
            tag == "div"
            and attrs.get("id") == "list-content"
        ):
            self._list_depth = 1
            return

        if self._list_depth:
            if tag == "div":
                self._list_depth += 1

            if tag == "table":
                self._table_depth += 1

            elif (
                tag == "tbody"
                and self._table_depth
            ):
                self._tbody_depth += 1

            elif (
                tag == "tr"
                and self._tbody_depth
            ):
                self._row = []

            elif (
                tag == "td"
                and self._row is not None
            ):
                self._cell = {
                    "text": [],
                    "links": [],
                    "times": [],
                }

            elif (
                tag == "time"
                and self._cell is not None
            ):
                timestamp = attrs.get(
                    "datetime",
                    "",
                ).strip()

                if timestamp:
                    self._cell[
                        "times"
                    ].append(timestamp)

        if tag == "a":
            href = attrs.get(
                "href",
                "",
            ).strip()

            if href:
                absolute = urljoin(
                    "https://www.smwcentral.net/",
                    href,
                )
                parsed = urlparse(absolute)
                query = parse_qs(
                    parsed.query
                )

                if (
                    parsed.netloc.casefold()
                    in {
                        "www.smwcentral.net",
                        "smwcentral.net",
                    }
                    and query.get("p") == ["section"]
                    and query.get("s") == ["smwhacks"]
                ):
                    self.page_links.add(
                        absolute
                    )

            if self._cell is not None:
                self._link = {
                    "href": href,
                    "text": [],
                }
                self._cell[
                    "links"
                ].append(self._link)

    def handle_data(
        self,
        data: str,
    ) -> None:
        if self._cell is not None:
            self._cell["text"].append(data)

        if self._link is not None:
            self._link["text"].append(data)

    def handle_endtag(
        self,
        tag: str,
    ) -> None:
        if tag == "a":
            self._link = None

        elif (
            tag == "td"
            and self._cell is not None
            and self._row is not None
        ):
            self._cell["text"] = (
                " ".join(
                    "".join(
                        self._cell["text"]
                    ).split()
                )
            )

            for link in self._cell["links"]:
                link["text"] = (
                    " ".join(
                        "".join(
                            link["text"]
                        ).split()
                    )
                )

            self._row.append(
                self._cell
            )
            self._cell = None

        elif (
            tag == "tr"
            and self._row is not None
        ):
            if self._row:
                self.rows.append(
                    self._row
                )

            self._row = None

        elif (
            tag == "tbody"
            and self._tbody_depth
        ):
            self._tbody_depth -= 1

        elif (
            tag == "table"
            and self._table_depth
        ):
            self._table_depth -= 1

        elif (
            tag == "div"
            and self._list_depth
        ):
            self._list_depth -= 1


def parse_smwcentral_catalog_row(
    cells: list[dict[str, Any]],
) -> dict[str, Any] | None:
    detail_link: dict[str, Any] | None = None
    detail_url = ""
    smwc_id = ""

    for cell in cells:
        for link in cell.get(
            "links",
            [],
        ):
            absolute = urljoin(
                "https://www.smwcentral.net/",
                str(link.get("href", "")),
            )
            parsed = urlparse(absolute)
            query = parse_qs(
                parsed.query
            )

            if (
                query.get("a") == ["details"]
                and query.get("p") == ["section"]
                and query.get("id")
            ):
                detail_link = link
                detail_url = absolute
                smwc_id = str(
                    query["id"][0]
                ).strip()
                break

        if detail_link is not None:
            break

    if detail_link is None:
        return None

    title = unescape(
        str(
            detail_link.get(
                "text",
                "",
            )
        )
    ).strip()

    if not title:
        return None

    added_date = ""
    author = ""
    download_url = ""
    difficulty = "Unknown"
    hack_type = "Unknown"
    total_exits = 0
    rating: float | None = None
    used_cells: set[int] = set()

    for cell_index, cell in enumerate(cells):
        for timestamp in cell.get(
            "times",
            [],
        ):
            try:
                added_date = (
                    datetime.fromisoformat(
                        str(timestamp).replace(
                            "Z",
                            "+00:00",
                        )
                    )
                    .date()
                    .isoformat()
                )
                used_cells.add(
                    cell_index
                )
                break
            except ValueError:
                continue

        for link in cell.get(
            "links",
            [],
        ):
            href = urljoin(
                "https://www.smwcentral.net/",
                str(link.get("href", "")),
            )
            parsed = urlparse(href)
            query = parse_qs(
                parsed.query
            )
            host = parsed.netloc.casefold()
            link_text = unescape(
                str(
                    link.get(
                        "text",
                        "",
                    )
                )
            ).strip()

            is_download = (
                "dl.smwcentral.net" in host
                or "download" in parsed.path.casefold()
                or "download" in parsed.query.casefold()
                or parsed.path.casefold().endswith(
                    (".zip", ".bps", ".ips")
                )
            )

            if is_download:
                download_url = href
                used_cells.add(
                    cell_index
                )

            if (
                query.get("p")
                in (
                    ["profile"],
                    ["postsbyuser"],
                )
                and link_text
            ):
                author = link_text
                used_cells.add(
                    cell_index
                )

    for cell_index, cell in enumerate(cells):
        cell_text = unescape(
            str(cell.get("text", ""))
        ).strip()
        normalized = (
            cell_text.casefold()
            .replace("–", "-")
            .replace("—", "-")
        )

        if not cell_text:
            continue

        exit_match = re.search(
            r"\b(\d+)\s+"
            r"(?:exit|exits|level|levels)\b",
            normalized,
        )

        if exit_match:
            total_exits = int(
                exit_match.group(1)
            )
            used_cells.add(
                cell_index
            )
            continue

        compact = re.sub(
            r"\s+",
            " ",
            normalized,
        ).strip()

        if compact in SMWC_DIFFICULTIES:
            difficulty = cell_text
            used_cells.add(
                cell_index
            )
            continue

        type_tokens = {
            token.strip()
            for token in re.split(
                r"[,/|]",
                compact,
            )
            if token.strip()
        }

        if (
            type_tokens
            and type_tokens.issubset(
                SMWC_TYPES
            )
        ):
            hack_type = cell_text
            used_cells.add(
                cell_index
            )
            continue

        if re.fullmatch(
            r"(?:[0-4](?:\.\d+)?|5(?:\.0+)?)",
            compact,
        ):
            try:
                candidate_rating = float(
                    compact
                )

                if 0 <= candidate_rating <= 5:
                    rating = candidate_rating
                    used_cells.add(
                        cell_index
                    )
                    continue
            except ValueError:
                pass

    if not author:
        for cell_index, cell in enumerate(cells):
            if cell_index in used_cells:
                continue

            cell_text = unescape(
                str(cell.get("text", ""))
            ).strip()

            if (
                cell_text
                and cell_text != title
                and re.search(
                    r"[A-Za-z]",
                    cell_text,
                )
                and len(cell_text) <= 120
                and not re.search(
                    r"\b(?:added|downloads?|kb|mb)\b",
                    cell_text.casefold(),
                )
            ):
                author = cell_text
                break

    return {
        "catalog_key": (
            "SMWC:" + smwc_id
        ),
        "smwc_id": smwc_id,
        "title": title,
        "author": author or "Unknown",
        "total_exits": total_exits,
        "difficulty": difficulty,
        "hack_type": hack_type,
        "added_date": added_date,
        "smwc_rating": rating,
        "rating": rating,
        "page_url": detail_url,
        "download_url": download_url,
        "is_custom": False,
        "rom_path": "",
        "local_rom_path": "",
    }


def smwc_cancelable_wait(
    seconds: float,
    cancel_event: threading.Event | None,
    progress_callback=None,
    message: str = "Waiting before the next SMWCentral request",
) -> None:
    wait_seconds = max(
        0.0,
        float(seconds),
    )

    if wait_seconds <= 0:
        return

    deadline = (
        time.monotonic()
        + wait_seconds
    )
    last_reported_second: int | None = None

    while True:
        if (
            cancel_event is not None
            and cancel_event.is_set()
        ):
            raise RuntimeError(
                "Catalog refresh cancelled."
            )

        remaining = (
            deadline - time.monotonic()
        )

        if remaining <= 0:
            return

        rounded_remaining = max(
            1,
            int(remaining + 0.999),
        )

        if (
            progress_callback is not None
            and rounded_remaining
            != last_reported_second
        ):
            progress_callback(
                (
                    f"{message}. "
                    f"Retrying in "
                    f"{rounded_remaining:,} second"
                    + (
                        ""
                        if rounded_remaining == 1
                        else "s"
                    )
                    + "…"
                )
            )
            last_reported_second = (
                rounded_remaining
            )

        time.sleep(
            min(
                0.25,
                remaining,
            )
        )


def smwc_throttle_request(
    cancel_event: threading.Event | None,
    progress_callback=None,
) -> None:
    global SMWC_API_LAST_REQUEST_TIME

    with SMWC_API_REQUEST_LOCK:
        elapsed = (
            time.monotonic()
            - SMWC_API_LAST_REQUEST_TIME
        )
        required_wait = (
            SMWC_API_MINIMUM_INTERVAL_SECONDS
            - elapsed
        )

        if required_wait > 0:
            smwc_cancelable_wait(
                required_wait,
                cancel_event,
                None,
            )

        SMWC_API_LAST_REQUEST_TIME = (
            time.monotonic()
        )


def smwc_rate_limit_wait_seconds(
    error: HTTPError,
    attempt_index: int,
) -> float:
    headers = getattr(
        error,
        "headers",
        None,
    )
    retry_after = ""

    if headers is not None:
        retry_after = str(
            headers.get(
                "Retry-After",
                "",
            )
            or ""
        ).strip()

    if retry_after:
        try:
            parsed_retry = float(
                retry_after
            )

            if parsed_retry >= 0:
                return min(
                    SMWC_API_MAX_RATE_LIMIT_WAIT_SECONDS,
                    max(
                        2.0,
                        parsed_retry + 1.0,
                    ),
                )
        except ValueError:
            pass

    reset_value = ""

    if headers is not None:
        reset_value = str(
            headers.get(
                "X-RateLimit-Reset",
                "",
            )
            or ""
        ).strip()

    if reset_value:
        try:
            reset_timestamp = float(
                reset_value
            )
            seconds_until_reset = (
                reset_timestamp - time.time()
            )

            if seconds_until_reset > 0:
                return min(
                    SMWC_API_MAX_RATE_LIMIT_WAIT_SECONDS,
                    max(
                        2.0,
                        seconds_until_reset + 1.0,
                    ),
                )
        except ValueError:
            pass

    exponential_wait = (
        SMWC_API_DEFAULT_RATE_LIMIT_WAIT_SECONDS
        * (2 ** max(0, attempt_index))
    )
    return min(
        SMWC_API_MAX_RATE_LIMIT_WAIT_SECONDS,
        exponential_wait,
    )


def smwc_api_json(
    params: dict[str, object],
    cancel_event: threading.Event | None = None,
    timeout: int = 45,
    progress_callback=None,
    max_retries: int = SMWC_API_MAX_RETRIES,
) -> dict[str, Any]:
    if (
        cancel_event is not None
        and cancel_event.is_set()
    ):
        raise RuntimeError(
            "Catalog refresh cancelled."
        )

    query = urlencode(
        params,
        doseq=True,
    )
    url = SMWC_API_URL + "?" + query
    header_profiles = (
        {
            "User-Agent": SMWC_REFRESH_USER_AGENT,
            "Accept": (
                "application/json, "
                "text/plain, */*"
            ),
            "Referer": (
                "https://www.smwcentral.net/"
                "?p=section&s=smwhacks"
            ),
            "X-Requested-With": (
                "XMLHttpRequest"
            ),
            "Cache-Control": "no-cache",
        },
        {
            "User-Agent": (
                "python-requests/2.32.3"
            ),
            "Accept": "*/*",
        },
    )
    last_error: Exception | None = None
    attempts = max(
        1,
        int(max_retries),
    )

    for attempt_index in range(attempts):
        if (
            cancel_event is not None
            and cancel_event.is_set()
        ):
            raise RuntimeError(
                "Catalog refresh cancelled."
            )

        smwc_throttle_request(
            cancel_event,
            progress_callback,
        )

        headers = header_profiles[
            min(
                attempt_index,
                len(header_profiles) - 1,
            )
        ]
        request = Request(
            url,
            headers=headers,
            method="GET",
        )

        try:
            with urlopen(
                request,
                timeout=timeout,
            ) as response:
                raw = response.read().decode(
                    "utf-8",
                    errors="replace",
                )

            payload = json.loads(raw)

            if not isinstance(payload, dict):
                raise RuntimeError(
                    "SMWCentral returned an "
                    "unexpected JSON response."
                )

            return payload

        except HTTPError as error:
            last_error = error

            if error.code == 429:
                if attempt_index >= attempts - 1:
                    break

                wait_seconds = (
                    smwc_rate_limit_wait_seconds(
                        error,
                        attempt_index,
                    )
                )
                smwc_cancelable_wait(
                    wait_seconds,
                    cancel_event,
                    progress_callback,
                    (
                        "SMWCentral is temporarily "
                        "rate limiting the refresh"
                    ),
                )
                continue

            if error.code == 403:
                if attempt_index >= attempts - 1:
                    break

                wait_seconds = min(
                    60.0,
                    8.0
                    * (
                        2
                        ** min(
                            attempt_index,
                            3,
                        )
                    ),
                )
                smwc_cancelable_wait(
                    wait_seconds,
                    cancel_event,
                    progress_callback,
                    (
                        "SMWCentral temporarily "
                        "rejected the request"
                    ),
                )
                continue

            if error.code in {
                500,
                502,
                503,
                504,
            }:
                if attempt_index >= attempts - 1:
                    break

                smwc_cancelable_wait(
                    min(
                        45.0,
                        3.0
                        * (
                            2
                            ** attempt_index
                        ),
                    ),
                    cancel_event,
                    progress_callback,
                    (
                        "SMWCentral is temporarily "
                        "unavailable"
                    ),
                )
                continue

            break

        except (
            URLError,
            TimeoutError,
            json.JSONDecodeError,
            RuntimeError,
        ) as error:
            last_error = error

            if attempt_index >= attempts - 1:
                break

            smwc_cancelable_wait(
                min(
                    30.0,
                    2.0
                    * (
                        2
                        ** attempt_index
                    ),
                ),
                cancel_event,
                progress_callback,
                (
                    "The SMWCentral request did "
                    "not complete"
                ),
            )

    if isinstance(last_error, HTTPError):
        if last_error.code == 429:
            raise RuntimeError(
                (
                    "SMWCentral continued rate limiting "
                    "the catalog after several automatic "
                    "retries. The existing catalog was "
                    "left unchanged."
                )
            ) from last_error

        if last_error.code == 403:
            raise RuntimeError(
                (
                    "SMWCentral continued rejecting the "
                    "catalog request after several "
                    "automatic retries. The existing "
                    "catalog was left unchanged."
                )
            ) from last_error

        raise RuntimeError(
            "SMWCentral catalog API failed with HTTP "
            f"{last_error.code}."
        ) from last_error

    raise RuntimeError(
        "Could not read the SMWCentral catalog API: "
        + str(
            last_error
            or "unknown network error"
        )
    )


def smwc_section_lookups(
    cancel_event: threading.Event,
    progress_callback=None,
) -> dict[str, dict[str, str]]:
    lookups: dict[str, dict[str, str]] = {
        "difficulty": dict(
            SMWC_DIFFICULTY_FALLBACK
        )
    }

    try:
        payload = smwc_api_json(
            {
                "a": "getsectioninfo",
                "s": "smwhacks",
            },
            cancel_event,
            progress_callback=progress_callback,
        )
    except RuntimeError:
        return lookups

    fields = payload.get(
        "fields",
        [],
    )

    if not isinstance(fields, list):
        return lookups

    for field in fields:
        if not isinstance(field, dict):
            continue

        field_id = str(
            field.get("id", "")
        ).strip()
        options = field.get(
            "options",
            [],
        )

        if not field_id or not isinstance(
            options,
            list,
        ):
            continue

        mapping = dict(
            lookups.get(field_id, {})
        )

        for option in options:
            if not isinstance(option, dict):
                continue

            option_id = str(
                option.get("id", "")
            ).strip()
            friendly_name = str(
                option.get(
                    "friendly_name",
                    option.get("name", ""),
                )
            ).strip()

            if option_id and friendly_name:
                mapping[option_id] = (
                    friendly_name
                )

        if mapping:
            lookups[field_id] = mapping

    return lookups


def smwc_flat_values(
    value: object,
) -> list[object]:
    if value in (None, ""):
        return []

    if isinstance(value, dict):
        values: list[object] = []

        for key, nested_value in value.items():
            if isinstance(
                nested_value,
                (list, tuple, set, dict),
            ):
                values.extend(
                    smwc_flat_values(
                        nested_value
                    )
                )
            elif nested_value not in (
                None,
                "",
                False,
            ):
                values.append(
                    nested_value
                )

        if values:
            return values

        return list(value.keys())

    if isinstance(
        value,
        (list, tuple, set),
    ):
        values: list[object] = []

        for item in value:
            values.extend(
                smwc_flat_values(item)
            )

        return values

    if isinstance(value, str):
        stripped = value.strip()

        if not stripped:
            return []

        if re.search(r"[,|/]", stripped):
            return [
                item.strip()
                for item in re.split(
                    r"[,|/]",
                    stripped,
                )
                if item.strip()
            ]

        return [stripped]

    return [value]


def smwc_friendly_value(
    field_id: str,
    value: object,
    lookups: dict[str, dict[str, str]],
    unknown: str = "Unknown",
) -> str:
    mapping = lookups.get(
        field_id,
        {},
    )
    names: list[str] = []

    for raw_item in smwc_flat_values(
        value
    ):
        item = str(raw_item).strip()

        if not item:
            continue

        friendly = mapping.get(item, "")

        if not friendly:
            simplified = re.sub(
                r"^(?:diff|type)_",
                "",
                item,
                flags=re.IGNORECASE,
            )
            simplified = simplified.replace(
                "_",
                " ",
            ).strip()
            friendly = (
                simplified.title()
                if simplified
                else item
            )

        if friendly not in names:
            names.append(friendly)

    return ", ".join(names) or unknown


def smwc_author_text(
    value: object,
) -> str:
    authors: list[str] = []

    for item in smwc_flat_values(value):
        if isinstance(item, dict):
            author = ""

            for key in (
                "display_name",
                "friendly_name",
                "username",
                "name",
                "text",
            ):
                candidate = str(
                    item.get(key, "")
                ).strip()

                if candidate:
                    author = candidate
                    break
        else:
            author = str(item).strip()

        # Some SMWCentral records expose a raw numeric user ID instead of
        # the creator's display name. Never present that internal ID as the
        # author; a later catalog refresh can replace Unknown with the real
        # name when SMWCentral supplies it.
        raw_user_id = bool(
            re.fullmatch(
                r"[+-]?\d+(?:\.0+)?",
                author,
            )
        )

        if (
            author
            and not raw_user_id
            and author not in authors
        ):
            authors.append(author)

    return ", ".join(authors) or "Unknown"


def smwc_rating_value(
    value: object,
) -> float | None:
    if isinstance(value, dict):
        for key in (
            "average",
            "rating",
            "value",
            "score",
        ):
            if key in value:
                parsed = smwc_rating_value(
                    value[key]
                )

                if parsed is not None:
                    return parsed

        return None

    try:
        parsed = float(
            str(value).strip()
        )
    except (
        TypeError,
        ValueError,
    ):
        return None

    if 0 <= parsed <= 5:
        return parsed

    return None


def smwc_boolean_value(value: object) -> bool:
    """Interpret SMW Central's numeric/string feature flags correctly."""
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    if isinstance(value, (list, tuple, set)):
        return any(smwc_boolean_value(item) for item in value)
    normalized = str(value or "").strip().casefold()
    return normalized in {
        "1", "true", "yes", "y", "on", "featured",
        "hall of fame", "sa-1", "sa1",
    }


def smwc_added_date(
    value: object,
) -> str:
    if value in (None, ""):
        return ""

    try:
        timestamp = float(value)

        if timestamp > 10_000_000_000:
            timestamp /= 1000.0

        return datetime.fromtimestamp(
            timestamp,
            tz=timezone.utc,
        ).date().isoformat()
    except (
        TypeError,
        ValueError,
        OSError,
        OverflowError,
    ):
        pass

    raw = str(value).strip()

    try:
        return datetime.fromisoformat(
            raw.replace("Z", "+00:00")
        ).date().isoformat()
    except ValueError:
        return rom_builder_date_text(raw)


def parse_smwcentral_api_game(
    hack: dict[str, Any],
    lookups: dict[str, dict[str, str]],
    *,
    is_waiting: bool | None = None,
) -> dict[str, Any] | None:
    smwc_id = str(
        hack.get("id", "")
    ).strip()
    title = unescape(
        str(
            hack.get(
                "name",
                hack.get("title", ""),
            )
        )
    ).strip()

    if not smwc_id or not title:
        return None

    raw_fields = hack.get(
        "raw_fields",
        {},
    )

    if not isinstance(raw_fields, dict):
        raw_fields = {}

    if is_waiting is None:
        is_waiting = not bool(
            hack.get("moderated", True)
        )

    difficulty_raw = raw_fields.get(
        "difficulty",
        hack.get("difficulty", ""),
    )
    type_raw = raw_fields.get(
        "type",
        hack.get("type", ""),
    )
    total_exits_raw = raw_fields.get(
        "length",
        hack.get(
            "length",
            hack.get("exits", 0),
        ),
    )

    try:
        total_exits = max(
            0,
            int(float(total_exits_raw or 0)),
        )
    except (
        TypeError,
        ValueError,
    ):
        total_exits = 0

    rating = smwc_rating_value(
        hack.get("rating")
    )
    page_url = (
        "https://www.smwcentral.net/"
        "?p=section&a=details&id="
        + smwc_id
    )
    download_url = str(
        hack.get(
            "download_url",
            hack.get("download", ""),
        )
        or ""
    ).strip()

    if download_url:
        download_url = urljoin(
            "https://www.smwcentral.net/",
            download_url,
        )

    return {
        "catalog_key": "SMWC:" + smwc_id,
        "smwc_id": smwc_id,
        "title": title,
        "author": smwc_author_text(
            hack.get(
                "authors",
                hack.get("author", ""),
            )
        ),
        "total_exits": total_exits,
        "difficulty": smwc_friendly_value(
            "difficulty",
            difficulty_raw,
            lookups,
        ),
        "hack_type": smwc_friendly_value(
            "type",
            type_raw,
            lookups,
        ),
        "added_date": smwc_added_date(
            hack.get(
                "time",
                hack.get("date", ""),
            )
        ),
        "smwc_rating": rating,
        "rating": rating,
        "page_url": page_url,
        "download_url": download_url,
        "is_custom": False,
        "sa1": smwc_boolean_value(raw_fields.get("sa1", False)),
        "hall_of_fame": smwc_boolean_value(raw_fields.get("hof", False)),
        "is_waiting": bool(is_waiting),
        "rom_path": "",
        "local_rom_path": "",
    }


def fetch_smwcentral_catalog(
    cancel_event: threading.Event,
    progress_callback=None,
    known_ids: set[str] | None = None,
    *,
    waiting: bool = False,
) -> dict[str, Any]:
    lookups = smwc_section_lookups(
        cancel_event,
        progress_callback,
    )
    games_by_id: dict[
        str,
        dict[str, Any],
    ] = {}
    page = 1
    last_page = 1
    pages_read = 0
    known_only_page_streak = 0
    incremental = bool(known_ids) and not waiting
    complete_catalog = False

    while page <= last_page:
        if cancel_event.is_set():
            raise RuntimeError(
                "Catalog refresh cancelled."
            )

        if progress_callback is not None:
            progress_callback(
                (
                    f"Reading SMWCentral API page "
                    f"{page:,} of {last_page:,}… "
                    f"{len(games_by_id):,} hacks found"
                )
            )

        payload = smwc_api_json(
            {
                "a": "getsectionlist",
                "s": "smwhacks",
                "n": page,
                "u": "1" if waiting else "0",
            },
            cancel_event,
            progress_callback=progress_callback,
        )
        raw_games = payload.get(
            "data",
            [],
        )

        if not isinstance(raw_games, list):
            raise RuntimeError(
                "SMWCentral returned an invalid catalog data list."
            )

        try:
            last_page = max(
                page,
                int(
                    payload.get(
                        "last_page",
                        page,
                    )
                    or page
                ),
            )
        except (
            TypeError,
            ValueError,
        ):
            last_page = page

        page_ids: set[str] = set()
        for raw_game in raw_games:
            if not isinstance(raw_game, dict):
                continue

            game = parse_smwcentral_api_game(
                raw_game,
                lookups,
                is_waiting=waiting,
            )

            if game is None:
                continue

            games_by_id[
                str(game["smwc_id"])
            ] = game
            page_ids.add(
                str(game["smwc_id"])
            )

        pages_read += 1

        if not raw_games:
            complete_catalog = True
            break

        # SMW Central returns this section newest-first. During an ordinary
        # refresh, two consecutive pages containing only IDs already in the
        # local database establish a safe boundary below the new entries.
        # This keeps routine refreshes to two or three pages instead of all
        # 56 pages. An empty local catalog still performs the full scan.
        if incremental and page_ids:
            if page_ids.issubset(known_ids or set()):
                known_only_page_streak += 1
            else:
                known_only_page_streak = 0

            if known_only_page_streak >= 2:
                break

        page += 1

        if page > last_page:
            complete_catalog = True

        if (
            page <= last_page
            and SMWC_API_PAGE_DELAY_SECONDS > 0
        ):
            smwc_cancelable_wait(
                SMWC_API_PAGE_DELAY_SECONDS,
                cancel_event,
                progress_callback,
                (
                    "Preparing the next "
                    "SMWCentral catalog page"
                ),
            )

    games = sorted(
        games_by_id.values(),
        key=lambda game: str(
            game.get("title", "")
        ).casefold(),
    )

    if (
        not waiting
        and
        complete_catalog
        and
        len(games)
        < SMWC_CATALOG_MINIMUM_EXPECTED
    ):
        raise RuntimeError(
            (
                "SMWCentral returned only "
                f"{len(games):,} usable hacks through its catalog API. "
                "The existing catalog was left unchanged."
            )
        )

    return {
        "games": games,
        "complete": complete_catalog,
        "pages_read": pages_read,
        "total_pages": last_page,
        "incremental": incremental,
    }


def refresh_waiting_from_smwcentral_site(
    database,
    cancel_event: threading.Event,
    progress_callback=None,
) -> dict[str, Any]:
    """Replace the local waiting queue with SMW Central's live queue."""
    fetch_result = fetch_smwcentral_catalog(
        cancel_event,
        progress_callback,
        waiting=True,
    )
    games = list(fetch_result["games"])
    if cancel_event.is_set():
        raise RuntimeError("Waiting-hack refresh cancelled.")

    refreshed_at = (
        datetime.now()
        .astimezone()
        .isoformat(timespec="seconds")
    )
    if progress_callback is not None:
        progress_callback(
            f"Saving {len(games):,} SMW Central waiting entries…"
        )
    return database.refresh_waiting_from_smwcentral(
        games,
        refreshed_at,
    )


def refresh_catalog_from_smwcentral_site(
    database,
    cancel_event: threading.Event,
    progress_callback=None,
) -> dict[str, Any]:
    """Synchronize the local catalog with SMW Central's live API."""
    existing_by_id = github_catalog_existing_by_id(
        database
    )
    metadata_complete = (
        database.metadata().get("SMWC Feature Metadata Complete") == "1"
    )
    fetch_result = fetch_smwcentral_catalog(
        cancel_event,
        progress_callback,
        known_ids=(set(existing_by_id) if metadata_complete else set()),
    )
    games = list(fetch_result["games"])
    complete_catalog = bool(
        fetch_result["complete"]
    )
    if cancel_event.is_set():
        raise RuntimeError(
            "Catalog refresh cancelled."
        )

    refreshed_at = (
        datetime.now()
        .astimezone()
        .isoformat(timespec="seconds")
    )
    catalog_version = (
        "Live "
        + datetime.now()
        .astimezone()
        .strftime("%Y.%m.%d %H:%M")
    )

    if progress_callback is not None:
        progress_callback(
            f"Saving {len(games):,} live SMW Central catalog entries…"
        )

    summary = database.refresh_from_smwcentral(
        games,
        refreshed_at,
        catalog_version,
    )
    live_ids = {
        str(game.get("smwc_id", "")).strip()
        for game in games
        if str(game.get("smwc_id", "")).strip()
    }
    if complete_catalog:
        removal_summary = (
            database.remove_repository_catalog_ids(
                set(existing_by_id) - live_ids
            )
        )
        removed_count = len(
            set(existing_by_id) - live_ids
        )
        database.set_metadata(
            "SMWC Feature Metadata Complete",
            1,
        )
    else:
        removal_summary = {
            "deleted": 0,
            "preserved": 0,
        }
        removed_count = 0

    official_count = sum(
        1
        for game in database.load_catalog()
        if (
            not bool(game.get("is_custom", False))
            and not bool(game.get("is_waiting", False))
        )
    )
    refresh_mode = (
        "Live Full"
        if complete_catalog
        else "Live Incremental"
    )

    # A live refresh must not retain the GitHub mirror's sequence metadata;
    # otherwise a later mirror check can incorrectly report that an older
    # snapshot is current.
    database.set_metadata(
        "Catalog Sequence",
        0,
    )
    database.set_metadata(
        "Catalog Version",
        catalog_version,
    )
    database.set_metadata(
        "Official Hack Count",
        official_count,
    )
    database.set_metadata(
        "Catalog Last Refresh",
        refreshed_at,
    )
    database.set_metadata(
        "Catalog Source",
        "SMW Central Live API",
    )
    database.set_metadata(
        "Catalog Repository URL",
        "https://www.smwcentral.net/?p=section&s=smwhacks",
    )
    database.set_metadata(
        "Refresh Mode",
        refresh_mode,
    )

    summary.update(
        {
            "status": "refreshed",
            "mode": refresh_mode,
            "fetched": len(games),
            "pages_read": int(
                fetch_result["pages_read"]
            ),
            "total_pages": int(
                fetch_result["total_pages"]
            ),
            "removed": removed_count,
            "removed_deleted": removal_summary[
                "deleted"
            ],
            "removed_preserved": removal_summary[
                "preserved"
            ],
            "official": official_count,
            "version": catalog_version,
            "refreshed_at": refreshed_at,
        }
    )
    return summary



def github_catalog_cancelled(
    cancel_event: threading.Event,
) -> None:
    if cancel_event.is_set():
        raise RuntimeError(
            "Catalog refresh cancelled."
        )


def github_catalog_get_bytes(
    url: str,
    cancel_event: threading.Event,
    progress_callback=None,
    description: str = "catalog file",
) -> bytes:
    last_error: Exception | None = None

    for attempt in range(
        1,
        GITHUB_CATALOG_REQUEST_RETRIES + 1,
    ):
        github_catalog_cancelled(
            cancel_event
        )

        if progress_callback is not None:
            progress_callback(
                (
                    f"Downloading {description} "
                    f"from GitHub"
                    + (
                        ""
                        if attempt == 1
                        else f" — retry {attempt}"
                    )
                    + "…"
                )
            )

        request = Request(
            url,
            headers={
                "User-Agent": (
                    GITHUB_CATALOG_USER_AGENT
                ),
                "Accept": (
                    "application/json,text/csv,"
                    "text/plain,*/*"
                ),
                "Cache-Control": "no-cache",
                "Pragma": "no-cache",
            },
            method="GET",
        )

        try:
            with urlopen(
                request,
                timeout=45,
            ) as response:
                data = response.read()

            if not data:
                raise RuntimeError(
                    f"The downloaded {description} was empty."
                )

            return data

        except HTTPError as error:
            last_error = error

            # A missing delta is handled by the caller as a signal to use
            # the full-catalog recovery path, matching the spreadsheet.
            if error.code == 404:
                raise RuntimeError(
                    f"GitHub does not contain {description}."
                ) from error

        except (
            URLError,
            TimeoutError,
            OSError,
        ) as error:
            last_error = error

        if attempt < GITHUB_CATALOG_REQUEST_RETRIES:
            smwc_cancelable_wait(
                min(
                    8.0,
                    float(attempt),
                ),
                cancel_event,
                progress_callback,
                (
                    "The GitHub catalog request "
                    "did not complete"
                ),
            )

    if isinstance(
        last_error,
        HTTPError,
    ):
        raise RuntimeError(
            (
                f"GitHub returned HTTP "
                f"{last_error.code} while downloading "
                f"{description}."
            )
        ) from last_error

    raise RuntimeError(
        (
            f"Could not download {description} "
            "from GitHub: "
            + str(
                last_error
                or "unknown network error"
            )
        )
    )


def github_catalog_get_json(
    url: str,
    cancel_event: threading.Event,
    progress_callback=None,
) -> dict[str, Any]:
    raw = github_catalog_get_bytes(
        url,
        cancel_event,
        progress_callback,
        "catalog version information",
    )

    try:
        payload = json.loads(
            raw.decode(
                "utf-8-sig"
            )
        )
    except (
        UnicodeDecodeError,
        json.JSONDecodeError,
    ) as error:
        raise RuntimeError(
            "The GitHub version file is not valid JSON."
        ) from error

    if not isinstance(
        payload,
        dict,
    ):
        raise RuntimeError(
            "The GitHub version file has an invalid structure."
        )

    return payload


def github_catalog_integer(
    value: object,
    default: int = 0,
) -> int:
    try:
        return int(
            float(
                str(value).strip()
            )
        )
    except (
        TypeError,
        ValueError,
    ):
        return default


def catalog_available_new_hack_count(
    local_official_count: object,
    version_payload: dict[str, Any],
    local_catalog_sequence: object | None = None,
    local_catalog_source: object = "",
) -> int | None:
    """Return the net number of catalog hacks newer than the local copy."""
    if str(local_catalog_source or "").strip().casefold() == (
        "smw central live api"
    ).casefold():
        # A direct SMW Central refresh is newer and more authoritative than
        # the GitHub spreadsheet mirror. Their row counts can differ while the
        # mirror catches up, which must not create a false "new" badge.
        return 0

    remote_sequence = github_catalog_integer(
        version_payload.get("sequence"),
        -1,
    )
    if local_catalog_sequence is not None:
        local_sequence = github_catalog_integer(
            local_catalog_sequence,
            -1,
        )
        # The repository sequence is the authoritative freshness marker. A
        # count-only comparison can be temporarily off by one while catalog
        # assets are published, or when a retained history row is classified
        # differently. Once this sequence has been applied, nothing is new.
        if (
            remote_sequence >= 0
            and local_sequence >= remote_sequence
        ):
            return 0

    remote_value = version_payload.get("hack_count")

    if remote_value in (None, ""):
        return None

    remote_count = github_catalog_integer(
        remote_value,
        -1,
    )

    if remote_count < 0:
        return None

    local_count = max(
        0,
        github_catalog_integer(
            local_official_count,
            0,
        ),
    )
    return max(0, remote_count - local_count)


def github_catalog_rating(
    value: object,
) -> float | None:
    if value in (
        None,
        "",
    ):
        return None

    try:
        rating = float(
            str(value).strip()
        )
    except (
        TypeError,
        ValueError,
    ):
        return None

    if 0 <= rating <= 5:
        return rating

    return None


def github_catalog_clean_row(
    row: dict[
        object,
        object,
    ],
) -> dict[str, str]:
    cleaned: dict[str, str] = {}

    for raw_key, raw_value in row.items():
        key = str(
            raw_key or ""
        ).lstrip(
            "\ufeff"
        ).strip()
        value = str(
            raw_value or ""
        ).strip()

        if key:
            cleaned[key] = value

    return cleaned


def github_catalog_existing_by_id(
    database,
) -> dict[
    str,
    dict[str, Any],
]:
    return {
        str(
            game.get(
                "smwc_id",
                "",
            )
        ).strip(): dict(game)
        for game in database.load_catalog()
        if (
            not bool(
                game.get(
                    "is_custom",
                    False,
                )
            )
            and not bool(game.get("is_waiting", False))
            and str(
                game.get(
                    "smwc_id",
                    "",
                )
            ).strip()
        )
    }


def github_catalog_row_to_game(
    row: dict[str, str],
    existing: (
        dict[str, Any]
        | None
    ) = None,
) -> dict[str, Any] | None:
    title = (
        row.get(
            "ROM Hack Title",
            "",
        ).strip()
        or row.get(
            "Dropdown Selection",
            "",
        ).strip()
    )
    smwc_id = row.get(
        "SMWC ID",
        "",
    ).strip()

    if not title or not smwc_id:
        return None

    rating = github_catalog_rating(
        row.get(
            "SMWCentral Rating",
            "",
        )
    )

    # The public CSV can omit or leave rating blank. Preserve the user's
    # current catalog rating instead of erasing it during a full recovery.
    if (
        rating is None
        and existing is not None
    ):
        rating = github_catalog_rating(
            existing.get(
                "rating"
            )
        )

    page_url = row.get(
        "SMWCentral Page URL",
        "",
    ).strip()

    if not page_url:
        page_url = (
            "https://www.smwcentral.net/"
            "?a=details&id="
            + smwc_id
            + "&p=section"
        )

    return {
        "catalog_key": (
            "SMWC:" + smwc_id
        ),
        "smwc_id": smwc_id,
        "title": title,
        "author": (
            smwc_author_text(
                row.get(
                    "Created By",
                    "",
                )
            )
        ),
        "total_exits": max(
            0,
            github_catalog_integer(
                row.get(
                    "Exits",
                    0,
                )
            ),
        ),
        "difficulty": (
            row.get(
                "Difficulty",
                "",
            ).strip()
            or "Unknown"
        ),
        "hack_type": (
            row.get(
                "Type",
                "",
            ).strip()
            or "Unknown"
        ),
        "added_date": (
            rom_builder_date_text(
                row.get(
                    "Added Date",
                    "",
                )
            )
        ),
        "smwc_rating": rating,
        "rating": rating,
        "page_url": page_url,
        "download_url": row.get(
            "Direct Download URL",
            "",
        ).strip(),
        "is_custom": False,
        "sa1": bool(existing.get("sa1", False)) if existing else False,
        "hall_of_fame": (
            bool(existing.get("hall_of_fame", False)) if existing else False
        ),
        "is_waiting": (
            bool(existing.get("is_waiting", False)) if existing else False
        ),
        "rom_path": (
            str(
                existing.get(
                    "rom_path",
                    "",
                )
            )
            if existing is not None
            else ""
        ),
        "local_rom_path": (
            str(
                existing.get(
                    "local_rom_path",
                    "",
                )
            )
            if existing is not None
            else ""
        ),
    }


def github_catalog_signature(
    game: dict[str, Any],
) -> tuple[object, ...]:
    return (
        str(
            game.get(
                "smwc_id",
                "",
            )
        ),
        str(
            game.get(
                "title",
                "",
            )
        ),
        str(
            game.get(
                "author",
                "",
            )
        ),
        github_catalog_integer(
            game.get(
                "total_exits",
                0,
            )
        ),
        str(
            game.get(
                "difficulty",
                "",
            )
        ),
        str(
            game.get(
                "hack_type",
                "",
            )
        ),
        str(
            game.get(
                "added_date",
                "",
            )
        ),
        github_catalog_rating(
            game.get(
                "rating"
            )
        ),
        str(
            game.get(
                "page_url",
                "",
            )
        ),
        str(
            game.get(
                "download_url",
                "",
            )
        ),
    )


def github_catalog_parse_full_csv(
    csv_data: bytes,
    existing_by_id: dict[
        str,
        dict[str, Any],
    ],
) -> dict[
    str,
    dict[str, Any],
]:
    try:
        csv_text = csv_data.decode(
            "utf-8-sig"
        )
    except UnicodeDecodeError as error:
        raise RuntimeError(
            "The GitHub full catalog is not valid UTF-8."
        ) from error

    reader = csv.DictReader(
        io.StringIO(csv_text)
    )
    fieldnames = {
        str(name or "")
        .lstrip("\ufeff")
        .strip()
        for name in (
            reader.fieldnames
            or []
        )
    }
    required = {
        "ROM Hack Title",
        "SMWC ID",
    }

    if not required.issubset(
        fieldnames
    ):
        raise RuntimeError(
            "The GitHub full catalog has an invalid CSV header."
        )

    catalog: dict[
        str,
        dict[str, Any],
    ] = {}

    for raw_row in reader:
        row = github_catalog_clean_row(
            raw_row
        )
        smwc_id = row.get(
            "SMWC ID",
            "",
        ).strip()
        game = github_catalog_row_to_game(
            row,
            existing_by_id.get(
                smwc_id
            ),
        )

        if game is not None:
            catalog[
                str(game["smwc_id"])
            ] = game

    if (
        len(catalog)
        < GITHUB_CATALOG_MINIMUM_EXPECTED
    ):
        raise RuntimeError(
            (
                "The GitHub full catalog contained only "
                f"{len(catalog):,} usable hacks. "
                "The existing catalog was left unchanged."
            )
        )

    return catalog


def github_catalog_apply_delta_csv(
    csv_data: bytes,
    catalog_by_id: dict[
        str,
        dict[str, Any],
    ],
) -> dict[str, int]:
    try:
        csv_text = csv_data.decode(
            "utf-8-sig"
        )
    except UnicodeDecodeError as error:
        raise RuntimeError(
            "A GitHub delta file is not valid UTF-8."
        ) from error

    reader = csv.DictReader(
        io.StringIO(csv_text)
    )
    fieldnames = [
        str(name or "")
        .lstrip("\ufeff")
        .strip()
        for name in (
            reader.fieldnames
            or []
        )
    ]

    if (
        not fieldnames
        or fieldnames[0].upper()
        != "OPERATION"
    ):
        raise RuntimeError(
            "A GitHub delta file has an invalid CSV header."
        )

    counts = {
        "added": 0,
        "updated": 0,
        "removed": 0,
    }

    for raw_row in reader:
        row = github_catalog_clean_row(
            raw_row
        )
        operation = row.get(
            "OPERATION",
            "",
        ).upper()
        smwc_id = row.get(
            "SMWC ID",
            "",
        ).strip()

        if operation == "UPSERT":
            if not smwc_id:
                raise RuntimeError(
                    "A GitHub UPSERT row is missing its SMWC ID."
                )

            existing = catalog_by_id.get(
                smwc_id
            )
            game = github_catalog_row_to_game(
                row,
                existing,
            )

            if game is None:
                continue

            if existing is None:
                counts["added"] += 1
            elif (
                github_catalog_signature(
                    existing
                )
                != github_catalog_signature(
                    game
                )
            ):
                counts["updated"] += 1

            catalog_by_id[
                smwc_id
            ] = game

        elif operation == "DELETE":
            if (
                smwc_id
                and smwc_id
                in catalog_by_id
            ):
                del catalog_by_id[
                    smwc_id
                ]
                counts["removed"] += 1

    return counts


def github_catalog_delta_url(
    sequence: int,
) -> str:
    base = (
        GITHUB_CATALOG_VERSION_URL.rsplit(
            "/",
            1,
        )[0]
    )

    return (
        base
        + "/deltas/"
        + f"{int(sequence):08d}"
        + ".csv"
    )


def refresh_catalog_from_github_repository(
    database,
    cancel_event: threading.Event,
    progress_callback=None,
) -> dict[str, Any]:
    github_catalog_cancelled(
        cancel_event
    )

    if progress_callback is not None:
        progress_callback(
            "Checking the GitHub catalog version…"
        )

    version_payload = github_catalog_get_json(
        GITHUB_CATALOG_VERSION_URL,
        cancel_event,
        progress_callback,
    )
    remote_sequence = (
        github_catalog_integer(
            version_payload.get(
                "sequence",
                -1,
            ),
            -1,
        )
    )
    remote_count = (
        github_catalog_integer(
            version_payload.get(
                "hack_count",
                0,
            )
        )
    )
    remote_version = str(
        version_payload.get(
            "catalog_version",
            "",
        )
        or ""
    ).strip()
    schema = str(
        version_payload.get(
            "schema",
            "",
        )
        or ""
    ).strip()
    metadata = database.metadata()
    local_sequence = (
        github_catalog_integer(
            metadata.get(
                "Catalog Sequence",
                0,
            )
        )
    )
    existing_by_id = (
        github_catalog_existing_by_id(
            database
        )
    )
    refreshed_at = (
        datetime.now()
        .astimezone()
        .isoformat(
            timespec="seconds"
        )
    )

    # This matches the spreadsheet's protection against accidentally
    # replacing a newer local catalog with an older repository copy.
    if (
        remote_sequence >= 0
        and local_sequence > remote_sequence
    ):
        return {
            "status": "local_newer",
            "mode": "none",
            "fetched": len(
                existing_by_id
            ),
            "new": 0,
            "updated": 0,
            "removed": 0,
            "official": len(
                existing_by_id
            ),
            "version": remote_version,
            "sequence": remote_sequence,
            "local_sequence": local_sequence,
            "refreshed_at": "",
        }

    # Like the spreadsheet, an equal sequence only updates the visible
    # version/refresh metadata and avoids downloading the full catalog.
    if (
        remote_sequence >= 0
        and local_sequence == remote_sequence
        and existing_by_id
    ):
        database.set_metadata(
            "Catalog Sequence",
            remote_sequence,
        )
        database.set_metadata(
            "Catalog Version",
            remote_version,
        )
        database.set_metadata(
            "Official Hack Count",
            (
                remote_count
                or len(existing_by_id)
            ),
        )
        database.set_metadata(
            "Catalog Last Refresh",
            refreshed_at,
        )
        database.set_metadata(
            "Catalog Source",
            "GitHub Repository",
        )
        database.set_metadata(
            "Catalog Repository URL",
            GITHUB_CATALOG_REPOSITORY_URL,
        )
        database.set_metadata(
            "Refresh Mode",
            "Incremental",
        )

        if schema:
            database.set_metadata(
                "Catalog Schema",
                schema,
            )

        return {
            "status": "up_to_date",
            "mode": "version_check",
            "fetched": len(
                existing_by_id
            ),
            "new": 0,
            "updated": 0,
            "removed": 0,
            "official": (
                remote_count
                or len(existing_by_id)
            ),
            "version": remote_version,
            "sequence": remote_sequence,
            "local_sequence": local_sequence,
            "refreshed_at": refreshed_at,
        }

    catalog_by_id = {
        smwc_id: dict(game)
        for smwc_id, game
        in existing_by_id.items()
    }
    added_count = 0
    updated_count = 0
    removed_count = 0
    refresh_mode = "Incremental"
    used_full_catalog = False

    # Download only the missing deltas—the same normal path used by
    # Refresh Hacks in the spreadsheet.
    if (
        remote_sequence >= 0
        and local_sequence < remote_sequence
        and catalog_by_id
    ):
        try:
            for sequence in range(
                local_sequence + 1,
                remote_sequence + 1,
            ):
                github_catalog_cancelled(
                    cancel_event
                )

                if progress_callback is not None:
                    progress_callback(
                        (
                            "Applying GitHub catalog update "
                            f"{sequence:,} of "
                            f"{remote_sequence:,}…"
                        )
                    )

                delta_data = (
                    github_catalog_get_bytes(
                        github_catalog_delta_url(
                            sequence
                        ),
                        cancel_event,
                        progress_callback,
                        (
                            "catalog delta "
                            f"{sequence:08d}.csv"
                        ),
                    )
                )
                counts = (
                    github_catalog_apply_delta_csv(
                        delta_data,
                        catalog_by_id,
                    )
                )
                added_count += counts[
                    "added"
                ]
                updated_count += counts[
                    "updated"
                ]
                removed_count += counts[
                    "removed"
                ]

        except Exception:
            # The spreadsheet offers a full-catalog recovery after a
            # missing or damaged delta. The app performs that recovery
            # automatically so the user does not need a second refresh.
            refresh_mode = (
                "Full Catalog Recovery"
            )
            used_full_catalog = True

    else:
        refresh_mode = "Full Catalog"
        used_full_catalog = True

    if used_full_catalog:
        if progress_callback is not None:
            progress_callback(
                (
                    "Downloading the full GitHub catalog "
                    "for synchronization…"
                )
            )

        full_data = github_catalog_get_bytes(
            GITHUB_CATALOG_FULL_CSV_URL,
            cancel_event,
            progress_callback,
            "full catalog CSV",
        )
        remote_catalog = (
            github_catalog_parse_full_csv(
                full_data,
                existing_by_id,
            )
        )
        existing_ids = set(
            existing_by_id
        )
        remote_ids = set(
            remote_catalog
        )
        added_count = len(
            remote_ids - existing_ids
        )
        removed_count = len(
            existing_ids - remote_ids
        )
        updated_count = sum(
            1
            for smwc_id in (
                remote_ids
                & existing_ids
            )
            if (
                github_catalog_signature(
                    remote_catalog[
                        smwc_id
                    ]
                )
                != github_catalog_signature(
                    existing_by_id[
                        smwc_id
                    ]
                )
            )
        )
        catalog_by_id = remote_catalog

    github_catalog_cancelled(
        cancel_event
    )

    if (
        len(catalog_by_id)
        < GITHUB_CATALOG_MINIMUM_EXPECTED
    ):
        raise RuntimeError(
            (
                "The refreshed GitHub catalog contained "
                f"only {len(catalog_by_id):,} hacks. "
                "The existing catalog was left unchanged."
            )
        )

    if progress_callback is not None:
        progress_callback(
            (
                f"Saving {len(catalog_by_id):,} "
                "GitHub catalog entries…"
            )
        )

    summary = database.refresh_from_smwcentral(
        list(
            catalog_by_id.values()
        ),
        refreshed_at,
        remote_version,
    )
    removal_summary = (
        database.remove_repository_catalog_ids(
            set(existing_by_id)
            - set(catalog_by_id)
        )
    )
    database.set_metadata(
        "Catalog Sequence",
        max(
            0,
            remote_sequence,
        ),
    )
    database.set_metadata(
        "Catalog Version",
        remote_version,
    )
    database.set_metadata(
        "Official Hack Count",
        (
            remote_count
            or len(catalog_by_id)
        ),
    )
    database.set_metadata(
        "Catalog Last Refresh",
        refreshed_at,
    )
    database.set_metadata(
        "Catalog Source",
        "GitHub Repository",
    )
    database.set_metadata(
        "Catalog Repository URL",
        GITHUB_CATALOG_REPOSITORY_URL,
    )
    database.set_metadata(
        "Refresh Mode",
        refresh_mode,
    )

    if schema:
        database.set_metadata(
            "Catalog Schema",
            schema,
        )

    summary.update(
        {
            "status": "refreshed",
            "mode": refresh_mode,
            "fetched": len(
                catalog_by_id
            ),
            "new": added_count,
            "updated": updated_count,
            "removed": removed_count,
            "removed_deleted": (
                removal_summary[
                    "deleted"
                ]
            ),
            "removed_preserved": (
                removal_summary[
                    "preserved"
                ]
            ),
            "official": (
                remote_count
                or len(catalog_by_id)
            ),
            "version": remote_version,
            "sequence": remote_sequence,
            "local_sequence": local_sequence,
            "refreshed_at": refreshed_at,
        }
    )
    return summary



ANTIALIASED_TEXT_OUTLINE_OFFSETS = (
    (-1, 0),
    (1, 0),
    (0, -1),
    (0, 1),
)


def create_outlined_canvas_text(
    canvas: tk.Canvas,
    *coordinates,
    **options,
) -> int:
    """Draw Canvas text with a one-pixel black edge when it is light."""
    fill_color = str(options.get("fill", ""))
    needs_outline = False
    try:
        red, green, blue = canvas.winfo_rgb(fill_color)
        luminance = (
            red * 0.299
            + green * 0.587
            + blue * 0.114
        ) / 257
        needs_outline = luminance >= 220
    except tk.TclError:
        needs_outline = fill_color.casefold() == "white"

    if needs_outline and len(coordinates) >= 2:
        x = coordinates[0]
        y = coordinates[1]
        remaining = coordinates[2:]
        outline_options = dict(options)
        outline_options["fill"] = "#000000"
        for offset_x, offset_y in ANTIALIASED_TEXT_OUTLINE_OFFSETS:
            canvas.create_text(
                x + offset_x,
                y + offset_y,
                *remaining,
                **outline_options,
            )

    return int(
        canvas.create_text(
            *coordinates,
            **options,
        )
    )


class OutlinedButton(tk.Canvas):
    """Themeable rounded button with outlined sharp text."""

    def __init__(
        self,
        parent,
        text: str,
        command,
        font=("Segoe UI", 10, "bold"),
        fg: str = "white",
        bg: str = "#1177DD",
        activeforeground: str = "white",
        activebackground: str = "#0759C7",
        disabledforeground: str = "#9AA4B0",
        relief: str = "raised",
        bd: int = 2,
        cursor: str = "hand2",
        width: int = 18,
        padx: int = 8,
        pady: int = 6,
        min_width: int = 88,
        min_height: int = 36,
        fixed_pixel_width: int | None = None,
        corner_radius: int = 10,
        image=None,
        compound: str = "left",
        **kwargs,
    ) -> None:
        self._text = str(text)
        self._command = command
        self._font_description = font
        self._font = tkfont.Font(
            master=parent,
            font=font,
        )
        self._fg = fg
        self._bg = bg
        self._active_fg = activeforeground
        self._active_bg = activebackground
        self._disabled_fg = disabledforeground
        self._state = str(
            kwargs.pop("state", "normal")
        )
        self._pressed = False
        self._hovered = False
        self._padx = int(padx)
        self._pady = int(pady)
        self._character_width = int(width)
        self._minimum_width = max(18, int(min_width))
        self._minimum_height = max(18, int(min_height))
        self._fixed_pixel_width = (
            max(self._minimum_width, int(fixed_pixel_width))
            if fixed_pixel_width is not None
            else None
        )
        self._corner_radius = max(4, int(corner_radius))
        self._image = image
        self._compound = str(compound)

        text_width = self._font.measure(
            self._text
        )
        image_width = 0
        if self._image is not None:
            try:
                image_width = int(self._image.width()) + 6
            except (tk.TclError, AttributeError):
                image_width = 0
        line_height = self._font.metrics(
            "linespace"
        )
        pixel_width = max(
            self._minimum_width,
            self._character_width * 9,
            text_width
            + image_width
            + (self._padx * 2)
            + 16,
        )
        if self._fixed_pixel_width is not None:
            pixel_width = self._fixed_pixel_width
        pixel_height = max(
            self._minimum_height,
            line_height + (self._pady * 2) + 8,
        )

        try:
            canvas_background = str(
                parent.cget("bg")
            )
        except (tk.TclError, AttributeError):
            canvas_background = self._bg

        kwargs.pop("highlightthickness", None)
        kwargs.pop("takefocus", None)
        super().__init__(
            parent,
            width=pixel_width,
            height=pixel_height,
            bg=canvas_background,
            highlightthickness=0,
            relief="flat",
            bd=0,
            cursor=cursor,
            takefocus=True,
            **kwargs,
        )

        self.bind(
            "<Configure>",
            self._redraw,
        )
        self.bind(
            "<Enter>",
            self._on_enter,
        )
        self.bind(
            "<Leave>",
            self._on_leave,
        )
        self.bind(
            "<ButtonPress-1>",
            self._on_press,
        )
        self.bind(
            "<ButtonRelease-1>",
            self._on_release,
        )
        self.bind(
            "<space>",
            self._on_keyboard_activate,
        )
        self.bind(
            "<Return>",
            self._on_keyboard_activate,
        )

        self.after_idle(self._redraw)

    def _is_enabled(self) -> bool:
        return self._state not in {
            "disabled",
            str(tk.DISABLED),
        }

    def _current_background(self) -> str:
        if not self._is_enabled():
            return self._bg

        if self._pressed or self._hovered:
            return self._active_bg

        return self._bg

    def _current_foreground(self) -> str:
        if not self._is_enabled():
            return self._disabled_fg

        if self._pressed or self._hovered:
            return self._active_fg

        return self._fg

    def _redraw(self, event=None) -> None:
        self.delete("all")

        width = max(
            2,
            self.winfo_width(),
        )
        height = max(
            2,
            self.winfo_height(),
        )
        background = self._current_background()
        foreground = self._current_foreground()

        try:
            canvas_background = str(
                self.master.cget("bg")
            )
        except (tk.TclError, AttributeError):
            canvas_background = background
        super().configure(bg=canvas_background)

        radius = min(
            self._corner_radius,
            max(4, int((height - 4) / 2)),
            max(4, int((width - 4) / 2)),
        )

        def rounded_polygon(
            inset: int,
            *,
            fill: str,
            outline: str,
            line_width: int,
        ) -> None:
            x1 = inset
            y1 = inset
            x2 = width - inset - 1
            y2 = height - inset - 1
            local_radius = max(
                2,
                min(
                    radius - inset + 1,
                    int((x2 - x1) / 2),
                    int((y2 - y1) / 2),
                ),
            )
            points = (
                x1 + local_radius, y1,
                x1 + local_radius, y1,
                x2 - local_radius, y1,
                x2 - local_radius, y1,
                x2, y1,
                x2, y1 + local_radius,
                x2, y1 + local_radius,
                x2, y2 - local_radius,
                x2, y2 - local_radius,
                x2, y2,
                x2 - local_radius, y2,
                x2 - local_radius, y2,
                x1 + local_radius, y2,
                x1 + local_radius, y2,
                x1, y2,
                x1, y2 - local_radius,
                x1, y2 - local_radius,
                x1, y1 + local_radius,
                x1, y1 + local_radius,
                x1, y1,
            )
            self.create_polygon(
                points,
                smooth=True,
                splinesteps=24,
                fill=fill,
                outline=outline,
                width=line_width,
            )

        # Thin black outer edge and a subtle white inner highlight retain
        # the Mario-card look while making every corner visibly rounded.
        rounded_polygon(
            1,
            fill=background,
            outline="#000000",
            line_width=1,
        )
        rounded_polygon(
            3,
            fill="",
            outline="#FFFFFF",
            line_width=1,
        )

        x = width / 2
        y = height / 2

        if self._image is not None:
            try:
                image_width = int(self._image.width())
                text_width = self._font.measure(self._text)
                gap = 6 if self._text else 0
                if self._compound == "left":
                    total_width = image_width + gap + text_width
                    image_x = width / 2 - total_width / 2 + image_width / 2
                    x = width / 2 + total_width / 2 - text_width / 2
                else:
                    image_x = width / 2
                self.create_image(
                    image_x,
                    y,
                    image=self._image,
                    anchor="center",
                )
            except (tk.TclError, AttributeError):
                pass

        if str(foreground).casefold() in {
            "white",
            "#ffffff",
            "#f2f6ff",
        }:
            for offset_x, offset_y in ANTIALIASED_TEXT_OUTLINE_OFFSETS:
                self.create_text(
                    x + offset_x,
                    y + offset_y,
                    text=self._text,
                    font=self._font,
                    fill="#000000",
                    anchor="center",
                )

        self.create_text(
            x,
            y,
            text=self._text,
            font=self._font,
            fill=foreground,
            anchor="center",
        )

    def _on_enter(self, event=None) -> None:
        if self._is_enabled():
            self._hovered = True
            self._redraw()

    def _on_leave(self, event=None) -> None:
        self._hovered = False
        self._pressed = False
        self._redraw()

    def _on_press(self, event=None) -> None:
        if self._is_enabled():
            self._pressed = True
            self.focus_set()
            self._redraw()

    def _on_release(self, event=None) -> None:
        if not self._is_enabled():
            return

        was_pressed = self._pressed
        self._pressed = False
        self._redraw()

        if (
            was_pressed
            and event is not None
            and 0 <= event.x <= self.winfo_width()
            and 0 <= event.y <= self.winfo_height()
        ):
            self.invoke()

    def _on_keyboard_activate(self, event=None):
        if self._is_enabled():
            self.invoke()
            return "break"
        return None

    def invoke(self):
        if (
            self._is_enabled()
            and callable(self._command)
        ):
            return self._command()
        return None

    def configure(self, cnf=None, **kwargs):
        options = {}

        if isinstance(cnf, dict):
            options.update(cnf)
        elif cnf is not None:
            return super().configure(cnf)

        options.update(kwargs)

        aliases = {
            "background": "bg",
            "foreground": "fg",
        }
        normalized = {
            aliases.get(key, key): value
            for key, value in options.items()
        }

        redraw_needed = False
        geometry_refresh_needed = False

        if "text" in normalized:
            self._text = str(
                normalized.pop("text")
            )
            redraw_needed = True
            geometry_refresh_needed = True

        if "command" in normalized:
            self._command = normalized.pop(
                "command"
            )

        if "font" in normalized:
            self._font_description = (
                normalized.pop("font")
            )
            self._font.configure(
                **tkfont.Font(
                    master=self,
                    font=self._font_description,
                ).actual()
            )
            redraw_needed = True
            geometry_refresh_needed = True

        if "fg" in normalized:
            self._fg = str(
                normalized.pop("fg")
            )
            redraw_needed = True

        if "activeforeground" in normalized:
            self._active_fg = str(
                normalized.pop(
                    "activeforeground"
                )
            )
            redraw_needed = True

        if "disabledforeground" in normalized:
            self._disabled_fg = str(
                normalized.pop(
                    "disabledforeground"
                )
            )
            redraw_needed = True

        if "bg" in normalized:
            self._bg = str(
                normalized.pop("bg")
            )
            redraw_needed = True

        if "activebackground" in normalized:
            self._active_bg = str(
                normalized.pop(
                    "activebackground"
                )
            )
            redraw_needed = True

        if "image" in normalized:
            self._image = normalized.pop("image")
            redraw_needed = True
            geometry_refresh_needed = True

        if "compound" in normalized:
            self._compound = str(
                normalized.pop("compound")
            )
            redraw_needed = True

        if "state" in normalized:
            self._state = str(
                normalized.pop("state")
            )
            self.configure(
                cursor=(
                    "hand2"
                    if self._is_enabled()
                    else "arrow"
                )
            )
            redraw_needed = True

        if "width" in normalized:
            requested_width = int(
                normalized.pop("width")
            )
            self._character_width = requested_width
            normalized["width"] = max(
                self._minimum_width,
                requested_width * 9,
            )
            geometry_refresh_needed = True

        if "pady" in normalized:
            self._pady = int(
                normalized.pop("pady")
            )
            normalized["height"] = max(
                self._minimum_height,
                self._font.metrics(
                    "linespace"
                )
                + (self._pady * 2)
                + 8,
            )
            geometry_refresh_needed = True

        if geometry_refresh_needed:
            text_width = self._font.measure(
                self._text
            )
            image_width = 0
            if self._image is not None:
                try:
                    image_width = int(
                        self._image.width()
                    ) + 6
                except (
                    tk.TclError,
                    AttributeError,
                ):
                    image_width = 0
            normalized["width"] = max(
                int(normalized.get("width", 0)),
                self._minimum_width,
                self._character_width * 9,
                text_width
                + image_width
                + (self._padx * 2)
                + 16,
            )
            normalized["height"] = max(
                int(normalized.get("height", 0)),
                self._minimum_height,
                self._font.metrics("linespace")
                + (self._pady * 2)
                + 8,
            )

        if normalized:
            super().configure(**normalized)

        if redraw_needed:
            self.after_idle(self._redraw)

        return None

    config = configure

    def cget(self, option):
        aliases = {
            "background": "bg",
            "foreground": "fg",
        }
        normalized = aliases.get(
            option,
            option,
        )

        stored = {
            "text": self._text,
            "command": self._command,
            "font": self._font_description,
            "fg": self._fg,
            "bg": self._bg,
            "activeforeground": self._active_fg,
            "activebackground": self._active_bg,
            "disabledforeground": self._disabled_fg,
            "state": self._state,
            "width": self._character_width,
            "pady": self._pady,
            "image": self._image,
            "compound": self._compound,
        }

        if normalized in stored:
            return stored[normalized]

        return super().cget(option)


class RoundedMenuButton(OutlinedButton):
    """Rounded Canvas button that opens a normal Tk menu below itself."""

    def __init__(
        self,
        parent,
        *,
        direction: str = "below",
        **kwargs,
    ) -> None:
        self._menu: tk.Menu | None = None
        self._direction = direction
        super().__init__(
            parent,
            command=self._post_menu,
            **kwargs,
        )

    def _post_menu(self) -> None:
        if self._menu is None:
            return
        try:
            self._menu.tk_popup(
                self.winfo_rootx(),
                self.winfo_rooty() + self.winfo_height(),
            )
        finally:
            try:
                self._menu.grab_release()
            except tk.TclError:
                pass

    def configure(self, cnf=None, **kwargs):
        options = {}
        if isinstance(cnf, dict):
            options.update(cnf)
        elif cnf is not None:
            return super().configure(cnf)
        options.update(kwargs)
        if "menu" in options:
            self._menu = options.pop("menu")
        if "direction" in options:
            self._direction = str(
                options.pop("direction")
            )
        return super().configure(options)

    config = configure

    def cget(self, option):
        if option == "menu":
            return self._menu
        if option == "direction":
            return self._direction
        return super().cget(option)


class InAppPage(tk.Frame):
    """Frame-backed replacement for a Toplevel page inside the main app.

    The existing page builders were written for ``tk.Toplevel``.  This
    adapter deliberately supports the small window API surface they use so
    the same tables and forms can render in the main window without opening
    another native window.
    """

    def __init__(
        self,
        parent,
        app,
        page_key: str,
        title: str,
        **kwargs,
    ) -> None:
        super().__init__(parent, **kwargs)
        self._app = app
        self.page_key = str(page_key)
        self._page_title = str(title)
        self._protocols: dict[str, object] = {}
        self._closing_requested = False
        self._internal_destroy = False

    def title(self, value: str | None = None) -> str:
        if value is not None:
            self._page_title = str(value)
        return self._page_title

    def geometry(self, _value: str | None = None) -> str:
        return (
            f"{max(1, self.winfo_width())}x{max(1, self.winfo_height())}"
            f"+{self.winfo_x()}+{self.winfo_y()}"
        )

    def minsize(self, _width: int | None = None, _height: int | None = None):
        return None

    def maxsize(self, _width: int | None = None, _height: int | None = None):
        return None

    def resizable(self, _width: bool | None = None, _height: bool | None = None):
        return (True, True)

    def transient(self, _master=None):
        return None

    def grab_set(self):
        return None

    def grab_release(self):
        return None

    def iconphoto(self, *_args, **_kwargs):
        return None

    def attributes(self, *_args):
        return None

    wm_attributes = attributes

    def overrideredirect(self, *_args):
        return None

    def protocol(self, name: str, command=None):
        if command is not None:
            self._protocols[str(name)] = command
        return self._protocols.get(str(name))

    wm_protocol = protocol

    def state(self, _value: str | None = None) -> str:
        return "zoomed"

    wm_state = state

    def withdraw(self) -> None:
        try:
            self.pack_forget()
        except tk.TclError:
            pass

    def deiconify(self) -> None:
        if not self.winfo_manager():
            self.pack(fill="both", expand=True)

    def request_close(self) -> None:
        if self._internal_destroy or not self.winfo_exists():
            return
        if self._closing_requested:
            self._app._close_in_app_page(self)
            return
        self._closing_requested = True
        handler = self._protocols.get("WM_DELETE_WINDOW")
        try:
            if callable(handler):
                handler()
            if self.winfo_exists():
                self._app._close_in_app_page(self)
        finally:
            self._closing_requested = False

    def destroy(self) -> None:
        if self._internal_destroy:
            super().destroy()
            return
        self._app._close_in_app_page(self)

    def _destroy_from_app(self) -> None:
        if not self.winfo_exists():
            return
        self._internal_destroy = True
        try:
            super().destroy()
        finally:
            self._internal_destroy = False


class OutlinedLabel(tk.Canvas):
    """Canvas-backed label that gives light text a one-pixel black edge."""

    def __init__(
        self,
        parent,
        text: str = "",
        textvariable: tk.Variable | None = None,
        font=("Segoe UI", 10),
        fg: str = "white",
        bg: str = "#073B86",
        anchor: str = "center",
        justify: str = "center",
        wraplength: int = 0,
        width: int = 0,
        height: int = 0,
        padx: int = 0,
        pady: int = 0,
        activeforeground: str | None = None,
        **kwargs,
    ) -> None:
        self._text = str(text)
        self._textvariable = textvariable
        self._font_description = font
        self._font = tkfont.Font(
            master=parent,
            font=font,
        )
        self._fg = str(fg)
        self._bg = str(bg)
        self._anchor = str(anchor)
        self._justify = str(justify)
        self._wraplength = max(0, int(wraplength))
        self._character_width = max(0, int(width))
        self._line_count = max(0, int(height))
        self._padx = max(0, int(padx))
        self._pady = max(0, int(pady))
        self._activeforeground = (
            str(activeforeground)
            if activeforeground is not None
            else self._fg
        )
        self._variable_trace_id: str | None = None

        requested_width, requested_height = (
            self._requested_pixel_size()
        )
        super().__init__(
            parent,
            width=requested_width,
            height=requested_height,
            bg=self._bg,
            bd=int(kwargs.pop("bd", 0)),
            relief=kwargs.pop("relief", "flat"),
            highlightthickness=int(
                kwargs.pop("highlightthickness", 0)
            ),
            cursor=kwargs.pop("cursor", "arrow"),
            takefocus=kwargs.pop("takefocus", False),
            **kwargs,
        )
        self.bind("<Configure>", self._redraw, add="+")
        self.bind("<Destroy>", self._on_destroy, add="+")
        if self._textvariable is not None:
            self._variable_trace_id = (
                self._textvariable.trace_add(
                    "write",
                    self._on_variable_changed,
                )
            )
        self.after_idle(self._redraw)

    def _display_text(self) -> str:
        if self._textvariable is not None:
            try:
                return str(self._textvariable.get())
            except tk.TclError:
                return ""
        return self._text

    def _wrapped_text(self, text: str) -> str:
        if self._wraplength <= 0:
            return text

        wrapped_lines: list[str] = []
        for paragraph in text.splitlines() or [""]:
            words = paragraph.split()
            if not words:
                wrapped_lines.append("")
                continue
            current = words[0]
            for word in words[1:]:
                candidate = current + " " + word
                if self._font.measure(candidate) <= self._wraplength:
                    current = candidate
                else:
                    wrapped_lines.append(current)
                    current = word
            wrapped_lines.append(current)
        return "\n".join(wrapped_lines)

    def _requested_pixel_size(self) -> tuple[int, int]:
        display_text = self._wrapped_text(
            self._display_text()
        )
        lines = display_text.splitlines() or [""]
        measured_width = max(
            (self._font.measure(line) for line in lines),
            default=1,
        )
        if self._wraplength > 0:
            measured_width = min(
                max(1, measured_width),
                self._wraplength,
            )
        if self._character_width > 0:
            measured_width = max(
                measured_width,
                self._font.measure("0")
                * self._character_width,
            )
        line_total = max(
            len(lines),
            self._line_count,
            1,
        )
        requested_width = max(
            4,
            measured_width + self._padx * 2 + 4,
        )
        return (
            requested_width,
            max(
                4,
                self._font.metrics("linespace")
                * line_total
                + self._pady * 2
                + 4,
            ),
        )

    def _text_position(
        self,
        width: int,
        height: int,
    ) -> tuple[float, float]:
        x = width / 2
        y = height / 2
        anchor = self._anchor.casefold()
        if anchor in {"w", "nw", "sw"}:
            x = self._padx + 2
        elif anchor in {"e", "ne", "se"}:
            x = width - self._padx - 2
        if anchor in {"n", "ne", "nw"}:
            y = self._pady + 2
        elif anchor in {"s", "se", "sw"}:
            y = height - self._pady - 2
        return x, y

    def _needs_outline(self) -> bool:
        try:
            red, green, blue = self.winfo_rgb(self._fg)
            luminance = (
                red * 0.299
                + green * 0.587
                + blue * 0.114
            ) / 257
            return luminance >= 220
        except tk.TclError:
            return self._fg.casefold() == "white"

    def _redraw(self, event=None) -> None:
        try:
            if not self.winfo_exists():
                return
        except tk.TclError:
            return
        self.delete("all")
        display_text = self._wrapped_text(
            self._display_text()
        )
        width = max(2, self.winfo_width())
        height = max(2, self.winfo_height())
        x, y = self._text_position(width, height)
        text_options = {
            "text": display_text,
            "font": self._font,
            "anchor": self._anchor,
            "justify": self._justify,
        }
        if self._needs_outline():
            for offset_x, offset_y in ANTIALIASED_TEXT_OUTLINE_OFFSETS:
                self.create_text(
                    x + offset_x,
                    y + offset_y,
                    fill="#000000",
                    **text_options,
                )
        self.create_text(
            x,
            y,
            fill=self._fg,
            **text_options,
        )

    def _on_variable_changed(self, *_args) -> None:
        requested_width, requested_height = (
            self._requested_pixel_size()
        )
        super().configure(
            width=requested_width,
            height=requested_height,
        )
        self.after_idle(self._redraw)

    def _on_destroy(self, event=None) -> None:
        if (
            event is not None
            and event.widget is not self
        ):
            return
        if (
            self._textvariable is not None
            and self._variable_trace_id is not None
        ):
            try:
                self._textvariable.trace_remove(
                    "write",
                    self._variable_trace_id,
                )
            except tk.TclError:
                pass
            self._variable_trace_id = None

    def configure(self, cnf=None, **kwargs):
        options = {}
        if isinstance(cnf, dict):
            options.update(cnf)
        elif cnf is not None:
            return super().configure(cnf)
        options.update(kwargs)
        aliases = {
            "background": "bg",
            "foreground": "fg",
        }
        normalized = {
            aliases.get(key, key): value
            for key, value in options.items()
        }
        redraw_needed = False
        geometry_refresh_needed = False
        for key, attribute in (
            ("text", "_text"),
            ("fg", "_fg"),
            ("anchor", "_anchor"),
            ("justify", "_justify"),
        ):
            if key in normalized:
                setattr(
                    self,
                    attribute,
                    str(normalized.pop(key)),
                )
                redraw_needed = True
                if key == "text":
                    geometry_refresh_needed = True
        if "bg" in normalized:
            self._bg = str(normalized["bg"])
            redraw_needed = True
        if "font" in normalized:
            self._font_description = normalized.pop("font")
            self._font.configure(
                **tkfont.Font(
                    master=self,
                    font=self._font_description,
                ).actual()
            )
            redraw_needed = True
            geometry_refresh_needed = True
        if normalized:
            super().configure(**normalized)
        if geometry_refresh_needed:
            requested_width, requested_height = (
                self._requested_pixel_size()
            )
            super().configure(
                width=requested_width,
                height=requested_height,
            )
        if redraw_needed:
            self.after_idle(self._redraw)
        return None

    config = configure

    def cget(self, option):
        normalized = {
            "background": "bg",
            "foreground": "fg",
        }.get(option, option)
        stored = {
            "text": self._text,
            "textvariable": self._textvariable,
            "font": self._font_description,
            "fg": self._fg,
            "bg": self._bg,
            "anchor": self._anchor,
            "justify": self._justify,
            "wraplength": self._wraplength,
            "width": self._character_width,
            "height": self._line_count,
            "padx": self._padx,
            "pady": self._pady,
            "activeforeground": self._activeforeground,
        }
        if normalized in stored:
            return stored[normalized]
        return super().cget(option)


