ROM_BUILDER_PATCH_EXTENSIONS = {".bps", ".ips"}
ROM_BUILDER_USER_AGENT = "SMW-Stream-Tracker/1.0"


class RomBuilderPatchError(Exception):
    pass


class RomBuilderCancelled(Exception):
    pass


class RomBuilderBPSReader:
    def __init__(self, data: bytes) -> None:
        self.data = data
        self.pos = 0

    def read(self, size: int) -> bytes:
        if self.pos + size > len(self.data):
            raise RomBuilderPatchError(
                "Unexpected end of BPS patch."
            )

        result = self.data[
            self.pos:self.pos + size
        ]
        self.pos += size
        return result

    def read_byte(self) -> int:
        if self.pos >= len(self.data):
            raise RomBuilderPatchError(
                "Unexpected end of BPS patch."
            )

        value = self.data[self.pos]
        self.pos += 1
        return value

    def decode_number(self) -> int:
        data = 0
        shift = 1

        while True:
            value = self.read_byte()
            data += (value & 0x7F) * shift

            if value & 0x80:
                return data

            shift <<= 7
            data += shift

    def decode_signed(self) -> int:
        value = self.decode_number()
        negative = value & 1
        value >>= 1
        return -value if negative else value


def rom_builder_sanitize_filename(
    name: object,
    fallback: str = "Untitled",
) -> str:
    cleaned = str(name or "").strip()

    if not cleaned:
        cleaned = fallback

    cleaned = re.sub(
        r'[<>:"/\\|?*\x00-\x1F]',
        "_",
        cleaned,
    )
    cleaned = re.sub(
        r"\s+",
        " ",
        cleaned,
    ).strip(" .")

    if not cleaned:
        cleaned = fallback

    return cleaned[:160].strip(" .")


def rom_builder_fxpak_safe_title(
    title: object,
    smwc_id: object = "",
) -> str:
    """Replace every emoji with a readable name for the FXPAK-only stem."""
    raw_title = unicodedata.normalize(
        "NFC",
        str(title or "").strip(),
    )
    converted_parts: list[str] = []
    regional_letters: list[str] = []

    def flush_regional_letters() -> None:
        if regional_letters:
            converted_parts.append(
                " Flag " + "".join(regional_letters) + " "
            )
            regional_letters.clear()

    skin_tone_names = {
        0x1F3FB: "Light Skin Tone",
        0x1F3FC: "Medium Light Skin Tone",
        0x1F3FD: "Medium Skin Tone",
        0x1F3FE: "Medium Dark Skin Tone",
        0x1F3FF: "Dark Skin Tone",
    }
    ignored_codepoints = {
        0x200D,  # ZERO WIDTH JOINER
        0xFE0E,  # text presentation selector
        0xFE0F,  # emoji presentation selector
        0x20E3,  # COMBINING ENCLOSING KEYCAP
    }
    emoji_codepoints = {
        0x00A9,
        0x00AE,
        0x203C,
        0x2049,
        0x2122,
        0x2139,
        0x3030,
        0x303D,
        0x3297,
        0x3299,
    }

    for character in raw_title:
        codepoint = ord(character)
        if codepoint in ignored_codepoints:
            continue
        if 0xE0020 <= codepoint <= 0xE007F:
            # Subdivision-flag tag characters are invisible shaping data.
            continue
        if 0x1F1E6 <= codepoint <= 0x1F1FF:
            regional_letters.append(chr(ord("A") + codepoint - 0x1F1E6))
            continue

        flush_regional_letters()
        if codepoint in skin_tone_names:
            converted_parts.append(" " + skin_tone_names[codepoint] + " ")
            continue
        is_emoji = (
            0x1F000 <= codepoint <= 0x1FFFF
            or 0x2600 <= codepoint <= 0x27FF
            or 0x2B00 <= codepoint <= 0x2BFF
            or codepoint in emoji_codepoints
            # Several emoji-capable characters, including STOPWATCH (U+23F1),
            # live outside the familiar emoji blocks. Unicode classifies them
            # as Other Symbols, so name them too instead of letting a glyph
            # that the FXPAK cannot represent reach the SD-card path.
            or unicodedata.category(character) == "So"
        )
        if is_emoji:
            unicode_name = unicodedata.name(character, "").strip()
            if unicode_name:
                converted_parts.append(" " + unicode_name.title() + " ")
            continue
        converted_parts.append(character)

    flush_regional_letters()
    cleaned = rom_builder_sanitize_filename(
        "".join(converted_parts),
        "",
    )
    if cleaned:
        return cleaned

    safe_id = rom_builder_sanitize_filename(
        smwc_id,
        "",
    )
    return f"SMWC {safe_id}" if safe_id else "SMW Hack"


def rom_builder_fxpak_relative_rom_path(
    game: dict[str, Any],
) -> PurePosixPath:
    """Build the SD-card-only path while leaving the catalog title intact."""
    safe_title = rom_builder_fxpak_safe_title(
        game.get("title", ""),
        game.get("smwc_id", ""),
    )
    return PurePosixPath(
        rom_builder_alpha_folder(safe_title)
    ) / (safe_title + ".sfc")


def rom_builder_fxpak_title_requires_alias(
    game: dict[str, Any],
) -> bool:
    """Return whether the FXPAK-only filename must replace emoji text."""
    original_title = rom_builder_sanitize_filename(
        unicodedata.normalize(
            "NFC",
            str(game.get("title", "")).strip(),
        ),
        "",
    )
    safe_title = rom_builder_fxpak_safe_title(
        game.get("title", ""),
        game.get("smwc_id", ""),
    )
    return original_title != safe_title


def rom_builder_alpha_folder(
    title: object,
) -> str:
    raw_title = unicodedata.normalize("NFKC", str(title or "")).strip()
    if raw_title:
        first_raw = raw_title[0]
        first_category = unicodedata.category(first_raw)
        if first_category.startswith("S") or ord(first_raw) > 0xFFFF:
            return "Emoji"

    cleaned = rom_builder_sanitize_filename(
        title,
        "#",
    )

    if not cleaned:
        return "#"

    first = cleaned[0].upper()

    if "A" <= first <= "Z":
        return first

    if first.isdigit():
        return "0-9"

    return "#"


def rom_builder_normalized_name(
    name: object,
) -> str:
    return normalize_title(
        rom_builder_sanitize_filename(name)
    )


def rom_builder_exact_filename_key(
    name: object,
) -> str:
    """Keep an exact Unicode key so emoji-only filenames remain discoverable."""
    return "exact:" + unicodedata.normalize(
        "NFKC",
        str(name or ""),
    ).strip().casefold()


def rom_builder_date_text(
    value: object,
) -> str:
    if value in (None, ""):
        return ""

    if isinstance(value, datetime):
        return value.date().isoformat()

    if isinstance(value, date):
        return value.isoformat()

    text_value = str(value).strip()

    for format_text in (
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%m/%d/%y",
        "%Y/%m/%d",
    ):
        try:
            return datetime.strptime(
                text_value,
                format_text,
            ).date().isoformat()
        except ValueError:
            continue

    try:
        return datetime.fromisoformat(
            text_value
        ).date().isoformat()
    except ValueError:
        return text_value


def rom_builder_parse_date(
    value: object,
) -> date | None:
    text_value = rom_builder_date_text(
        value
    )

    if not text_value:
        return None

    try:
        return date.fromisoformat(
            text_value[:10]
        )
    except ValueError:
        return None


def calendar_month_cutoff(
    reference_date: date,
    months: int,
) -> date:
    """Return the same calendar day ``months`` earlier when possible."""
    month_count = (
        reference_date.year * 12
        + reference_date.month
        - 1
        - max(0, int(months))
    )
    cutoff_year, cutoff_month_index = divmod(month_count, 12)
    cutoff_month = cutoff_month_index + 1
    if cutoff_month == 12:
        following_month = date(cutoff_year + 1, 1, 1)
    else:
        following_month = date(cutoff_year, cutoff_month + 1, 1)
    final_day = (following_month - timedelta(days=1)).day
    return date(
        cutoff_year,
        cutoff_month,
        min(reference_date.day, final_day),
    )


def rom_builder_read_u24_be(
    data: bytes,
    offset: int,
) -> int:
    return (
        (data[offset] << 16)
        | (data[offset + 1] << 8)
        | data[offset + 2]
    )


def rom_builder_apply_ips_patch(
    source: bytes,
    patch: bytes,
) -> bytes:
    if not patch.startswith(b"PATCH"):
        raise RomBuilderPatchError(
            "Invalid IPS header."
        )

    output = bytearray(source)
    position = 5

    while True:
        if position + 3 > len(patch):
            raise RomBuilderPatchError(
                "Unexpected end of IPS patch."
            )

        if patch[
            position:position + 3
        ] == b"EOF":
            position += 3

            if position + 3 <= len(patch):
                truncate_size = (
                    rom_builder_read_u24_be(
                        patch,
                        position,
                    )
                )

                if truncate_size < len(output):
                    del output[truncate_size:]
                elif truncate_size > len(output):
                    output.extend(
                        b"\x00"
                        * (
                            truncate_size
                            - len(output)
                        )
                    )

            return bytes(output)

        offset = rom_builder_read_u24_be(
            patch,
            position,
        )
        position += 3

        if position + 2 > len(patch):
            raise RomBuilderPatchError(
                "Missing IPS record size."
            )

        size = (
            (patch[position] << 8)
            | patch[position + 1]
        )
        position += 2

        if size == 0:
            if position + 3 > len(patch):
                raise RomBuilderPatchError(
                    "Missing IPS RLE record."
                )

            rle_size = (
                (patch[position] << 8)
                | patch[position + 1]
            )
            value = patch[position + 2]
            position += 3
            end = offset + rle_size

            if end > len(output):
                output.extend(
                    b"\x00" * (end - len(output))
                )

            output[offset:end] = (
                bytes([value]) * rle_size
            )
        else:
            if position + size > len(patch):
                raise RomBuilderPatchError(
                    "IPS record extends past end "
                    "of file."
                )

            end = offset + size

            if end > len(output):
                output.extend(
                    b"\x00" * (end - len(output))
                )

            output[offset:end] = patch[
                position:position + size
            ]
            position += size


def rom_builder_apply_bps_patch(
    source: bytes,
    patch: bytes,
    validate: bool = True,
) -> bytes:
    if not patch.startswith(b"BPS1"):
        raise RomBuilderPatchError(
            "Invalid BPS header."
        )

    if len(patch) < 16:
        raise RomBuilderPatchError(
            "BPS patch is too short."
        )

    if validate:
        expected_patch_crc = int.from_bytes(
            patch[-4:],
            "little",
        )
        actual_patch_crc = (
            binascii.crc32(
                patch[:-4]
            )
            & 0xFFFFFFFF
        )

        if actual_patch_crc != expected_patch_crc:
            raise RomBuilderPatchError(
                "BPS patch CRC does not match."
            )

    expected_source_crc = int.from_bytes(
        patch[-12:-8],
        "little",
    )
    expected_target_crc = int.from_bytes(
        patch[-8:-4],
        "little",
    )

    reader = RomBuilderBPSReader(patch)

    if reader.read(4) != b"BPS1":
        raise RomBuilderPatchError(
            "Invalid BPS header."
        )

    source_size = reader.decode_number()
    target_size = reader.decode_number()
    metadata_size = reader.decode_number()
    reader.read(metadata_size)

    if len(source) != source_size:
        raise RomBuilderPatchError(
            "BPS source size mismatch: "
            f"expected {source_size}, "
            f"got {len(source)}."
        )

    if validate:
        actual_source_crc = (
            binascii.crc32(source)
            & 0xFFFFFFFF
        )

        if actual_source_crc != expected_source_crc:
            raise RomBuilderPatchError(
                "BPS source CRC mismatch."
            )

    target = bytearray()
    source_relative = 0
    target_relative = 0
    end_of_actions = len(patch) - 12

    while reader.pos < end_of_actions:
        instruction = reader.decode_number()
        command = instruction & 3
        length = (instruction >> 2) + 1

        if command == 0:
            start = len(target)
            target.extend(
                source[start:start + length]
            )

        elif command == 1:
            target.extend(
                reader.read(length)
            )

        elif command == 2:
            source_relative += (
                reader.decode_signed()
            )

            if (
                source_relative < 0
                or source_relative + length
                > len(source)
            ):
                raise RomBuilderPatchError(
                    "BPS source copy out of range."
                )

            target.extend(
                source[
                    source_relative:
                    source_relative + length
                ]
            )
            source_relative += length

        elif command == 3:
            target_relative += (
                reader.decode_signed()
            )

            if target_relative < 0:
                raise RomBuilderPatchError(
                    "BPS target copy out of range."
                )

            for _ in range(length):
                if target_relative >= len(target):
                    raise RomBuilderPatchError(
                        "BPS target copy out of range."
                    )

                target.append(
                    target[target_relative]
                )
                target_relative += 1

    if len(target) != target_size:
        raise RomBuilderPatchError(
            "BPS target size mismatch: "
            f"expected {target_size}, "
            f"got {len(target)}."
        )

    if validate:
        actual_target_crc = (
            binascii.crc32(target)
            & 0xFFFFFFFF
        )

        if actual_target_crc != expected_target_crc:
            raise RomBuilderPatchError(
                "BPS target CRC mismatch."
            )

    return bytes(target)


def rom_builder_source_variants(
    base_rom: bytes,
) -> list[tuple[str, bytes]]:
    variants = [
        ("as_uploaded", base_rom)
    ]

    if (
        len(base_rom) % 1024 == 512
        and len(base_rom) > 512
    ):
        variants.insert(
            0,
            (
                "unheadered",
                base_rom[512:],
            ),
        )

    return variants


def rom_builder_apply_patch_with_variants(
    base_rom: bytes,
    patch_path: Path,
) -> tuple[bytes, str]:
    patch_data = patch_path.read_bytes()
    suffix = patch_path.suffix.casefold()
    errors: list[str] = []

    for variant_name, source in (
        rom_builder_source_variants(
            base_rom
        )
    ):
        try:
            if suffix == ".bps":
                return (
                    rom_builder_apply_bps_patch(
                        source,
                        patch_data,
                    ),
                    variant_name,
                )

            if suffix == ".ips":
                return (
                    rom_builder_apply_ips_patch(
                        source,
                        patch_data,
                    ),
                    variant_name,
                )

            raise RomBuilderPatchError(
                f"Unsupported patch type: {suffix}"
            )

        except Exception as error:
            errors.append(
                f"{variant_name}: {error}"
            )

    raise RomBuilderPatchError(
        "; ".join(errors)
    )


def rom_builder_patch_archive_entries(
    archive: zipfile.ZipFile,
) -> list[zipfile.ZipInfo]:
    return [
        info
        for info in archive.infolist()
        if (
            not info.is_dir()
            and Path(info.filename).suffix.casefold()
            in ROM_BUILDER_PATCH_EXTENSIONS
        )
    ]


def rom_builder_validate_patch_archive(
    zip_path: Path,
) -> None:
    """Validate usable patch entries without reading unrelated ZIP files.

    A few moderated SMW Central archives contain a valid patch alongside an
    old or damaged README entry.  ``ZipFile.testzip()`` reads every member and
    rejects those archives even though the patch itself is intact.  The ROM
    builder only needs a readable BPS or IPS file, so validate those entries
    directly and leave unrelated documentation alone.
    """
    with zipfile.ZipFile(
        zip_path,
        "r",
    ) as archive:
        patch_entries = (
            rom_builder_patch_archive_entries(
                archive
            )
        )

        if not patch_entries:
            raise RuntimeError(
                "No .bps or .ips patch was found in the ZIP."
            )

        errors: list[str] = []

        for info in patch_entries:
            try:
                with archive.open(
                    info,
                    "r",
                ) as patch_file:
                    while patch_file.read(
                        1024 * 256
                    ):
                        pass
                return
            except Exception as error:
                errors.append(
                    f"{info.filename}: {error}"
                )

    raise RuntimeError(
        "No readable .bps or .ips patch was found in the ZIP"
        + (
            ": " + "; ".join(errors)
            if errors
            else "."
        )
    )


def rom_builder_download_file(
    url: str,
    destination: Path,
    cancel_event: threading.Event,
    retries: int = 4,
) -> None:
    destination.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    if (
        destination.exists()
        and destination.stat().st_size > 0
    ):
        try:
            rom_builder_validate_patch_archive(
                destination
            )
            return
        except Exception:
            destination.unlink(
                missing_ok=True
            )

    last_error: Exception | None = None

    for attempt in range(
        1,
        retries + 1,
    ):
        if cancel_event.is_set():
            raise RomBuilderCancelled()

        temporary_path = destination.with_suffix(
            destination.suffix + ".part"
        )
        temporary_path.unlink(
            missing_ok=True
        )

        try:
            request = Request(
                url,
                headers={
                    "User-Agent": (
                        ROM_BUILDER_USER_AGENT
                    )
                },
            )

            with urlopen(
                request,
                timeout=90,
            ) as response, temporary_path.open(
                "wb"
            ) as output_file:
                while True:
                    if cancel_event.is_set():
                        raise RomBuilderCancelled()

                    chunk = response.read(
                        1024 * 256
                    )

                    if not chunk:
                        break

                    output_file.write(chunk)

            if (
                not temporary_path.exists()
                or temporary_path.stat().st_size
                == 0
            ):
                raise RuntimeError(
                    "Downloaded file was empty."
                )

            rom_builder_validate_patch_archive(
                temporary_path
            )

            temporary_path.replace(
                destination
            )
            return

        except RomBuilderCancelled:
            temporary_path.unlink(
                missing_ok=True
            )
            raise

        except Exception as error:
            last_error = error
            temporary_path.unlink(
                missing_ok=True
            )

            if attempt < retries:
                time.sleep(
                    1.5 * attempt
                )

    raise RuntimeError(
        f"Download failed: {last_error}"
    )


def rom_builder_extract_patches(
    zip_path: Path,
    extract_directory: Path,
) -> list[Path]:
    shutil.rmtree(
        extract_directory,
        ignore_errors=True,
    )
    extract_directory.mkdir(
        parents=True,
        exist_ok=True,
    )
    patches: list[Path] = []

    with zipfile.ZipFile(
        zip_path,
        "r",
    ) as archive:
        patch_entries = (
            rom_builder_patch_archive_entries(
                archive
            )
        )

        for info in patch_entries:
            suffix = Path(
                info.filename
            ).suffix.casefold()

            filename = (
                rom_builder_sanitize_filename(
                    Path(info.filename).name,
                    "patch" + suffix,
                )
            )
            output_path = (
                extract_directory / filename
            )

            counter = 2
            original_stem = output_path.stem

            while output_path.exists():
                output_path = (
                    extract_directory
                    / (
                        original_stem
                        + "_"
                        + str(counter)
                        + suffix
                    )
                )
                counter += 1

            try:
                with archive.open(
                    info,
                    "r",
                ) as source_file, output_path.open(
                    "wb"
                ) as destination_file:
                    shutil.copyfileobj(
                        source_file,
                        destination_file,
                    )
            except Exception:
                output_path.unlink(
                    missing_ok=True
                )
                continue

            patches.append(output_path)

    patches.sort(
        key=lambda path: (
            0
            if path.suffix.casefold() == ".bps"
            else 1,
            len(path.name),
            path.name.casefold(),
        )
    )
    return patches


def rom_builder_detect_library_root(
    selected_folder: Path,
) -> Path:
    selected_folder = (
        selected_folder.expanduser().resolve()
    )

    if selected_folder.name.casefold() == (
        "patched roms"
    ):
        return selected_folder

    patched_subfolder = (
        selected_folder / "Patched ROMs"
    )

    if patched_subfolder.exists():
        return patched_subfolder

    return selected_folder


def rom_builder_load_json(
    path: Path,
) -> object:
    if not path.exists():
        return None

    try:
        return json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )
    except (
        OSError,
        json.JSONDecodeError,
    ):
        return None


def rom_builder_scan_existing_roms(
    library_root: Path,
) -> dict[str, Path]:
    found: dict[str, Path] = {}

    if not library_root.exists():
        return found

    # Walk the library once.  Two separate recursive glob passes were
    # noticeably slow for large libraries stored in OneDrive.
    for rom_path in library_root.rglob("*"):
        if rom_path.suffix.casefold() not in {".sfc", ".smc"}:
            continue
        key = rom_builder_normalized_name(
            rom_path.stem
        )

        if key and key not in found:
            found[key] = rom_path
        exact_key = rom_builder_exact_filename_key(rom_path.stem)
        if exact_key != "exact:" and exact_key not in found:
            found[exact_key] = rom_path

    return found


def rom_builder_load_existing_index(
    library_root: Path,
    *,
    existing_paths: set[str] | frozenset[str] | None = None,
) -> dict[str, Path]:
    by_id: dict[str, Path] = {}
    candidate_indexes = (
        library_root / "_library_index.json",
        library_root.parent
        / "_library_index.json",
    )

    for index_path in candidate_indexes:
        data = rom_builder_load_json(
            index_path
        )

        if not isinstance(data, dict):
            continue

        entries = data.get(
            "entries",
            data,
        )

        if not isinstance(entries, dict):
            continue

        for smwc_id, information in entries.items():
            if isinstance(information, dict):
                path_text = (
                    information.get(
                        "output_path"
                    )
                    or information.get("path")
                    or ""
                )
            else:
                path_text = information

            if not path_text:
                continue

            rom_path = Path(
                str(path_text)
            )

            if not rom_path.is_absolute():
                rom_path = (
                    library_root / rom_path
                )

            if existing_paths is None:
                path_exists = rom_path.exists()
            else:
                path_key = os.path.normcase(
                    os.path.abspath(os.path.expanduser(str(rom_path)))
                )
                path_exists = path_key in existing_paths

            if path_exists:
                by_id[str(smwc_id)] = (
                    rom_path
                )

    return by_id


def rom_builder_expected_rom_path(
    library_root: Path,
    game: dict[str, Any],
) -> Path:
    title = str(
        game.get("title", "Untitled")
    )

    return (
        library_root
        / rom_builder_alpha_folder(title)
        / (
            rom_builder_sanitize_filename(
                title
            )
            + ".sfc"
        )
    )


def rom_builder_file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def rom_builder_copy_rom_to_sd(
    source_path: Path,
    sd_root: Path,
    game: dict[str, Any],
) -> tuple[Path, str]:
    """Copy a completed ROM to the mounted SD card without clobbering files."""
    if not sd_root.is_dir():
        raise FileNotFoundError(
            "The selected SD-card folder is no longer available."
        )

    relative_destination = rom_builder_fxpak_relative_rom_path(
        game
    )
    destination = sd_root.joinpath(*relative_destination.parts)
    destination.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    if destination.exists():
        if (
            destination.stat().st_size == source_path.stat().st_size
            and rom_builder_file_sha256(destination)
            == rom_builder_file_sha256(source_path)
        ):
            return destination, "already_on_sd"
        raise FileExistsError(
            "A different ROM already exists at the SD-card destination: "
            + str(destination)
        )

    temporary_destination = destination.with_suffix(
        destination.suffix + ".part"
    )
    try:
        temporary_destination.unlink(missing_ok=True)
        shutil.copy2(
            source_path,
            temporary_destination,
        )
        if destination.exists():
            raise FileExistsError(
                "A ROM appeared at the SD-card destination while copying: "
                + str(destination)
            )
        temporary_destination.replace(destination)
    finally:
        temporary_destination.unlink(missing_ok=True)

    return destination, "copied"


def rom_builder_existing_game(
    game: dict[str, Any],
    library_root: Path,
    existing_by_name: dict[str, Path],
    existing_by_id: dict[str, Path],
    *,
    existing_paths: set[str] | frozenset[str] | None = None,
    probe_filesystem: bool = True,
    include_fxpak_mapping: bool = True,
) -> tuple[bool, str, str]:
    # A saved FXPAK path means this title is already part of the launchable
    # game library, even if the SD card is not mounted as a Windows drive.
    mapped_path = str(
        game.get("rom_path", "")
    ).strip()

    if include_fxpak_mapping and mapped_path:
        return (
            True,
            "Already mapped on FXPAK",
            mapped_path,
        )

    local_path = str(
        game.get(
            "local_rom_path",
            "",
        )
    ).strip()

    def normalized_path(value: str | Path) -> str:
        return os.path.normcase(
            os.path.abspath(os.path.expanduser(str(value)))
        )

    local_path_exists = bool(
        local_path
        and (
            (
                existing_paths is not None
                and normalized_path(local_path) in existing_paths
            )
            or (probe_filesystem and Path(local_path).exists())
        )
    )

    if local_path_exists:
        return (
            True,
            "Already in local library",
            local_path,
        )

    smwc_id = str(
        game.get("smwc_id", "")
    ).strip()

    if smwc_id and smwc_id in existing_by_id:
        return (
            True,
            "Already in local library",
            str(existing_by_id[smwc_id]),
        )

    expected_path = (
        rom_builder_expected_rom_path(
            library_root,
            game,
        )
    )

    expected_path_exists = bool(
        (
            existing_paths is not None
            and normalized_path(expected_path) in existing_paths
        )
        or (probe_filesystem and expected_path.exists())
    )

    if expected_path_exists:
        return (
            True,
            "Already in local library",
            str(expected_path),
        )

    title_key = rom_builder_normalized_name(
        game.get("title", "")
    )

    possible_keys = {
        title_key,
        rom_builder_exact_filename_key(game.get("title", "")),
    }

    if smwc_id:
        possible_keys.add(
            rom_builder_normalized_name(
                str(
                    game.get("title", "")
                )
                + " [SMWC "
                + smwc_id
                + "]"
            )
        )
        possible_keys.add(
            rom_builder_normalized_name(
                str(
                    game.get("title", "")
                )
                + " [SMWC #"
                + smwc_id
                + "]"
            )
        )

    for key in possible_keys:
        if key and key in existing_by_name:
            return (
                True,
                "Already in local library",
                str(existing_by_name[key]),
            )

    return (
        False,
        "Missing",
        "",
    )


def rom_builder_write_reports(
    library_root: Path,
    results: list[dict[str, str]],
    index_entries: dict[str, dict[str, str]],
) -> None:
    library_root.mkdir(
        parents=True,
        exist_ok=True,
    )
    fieldnames = (
        "status",
        "title",
        "smwc_id",
        "output_path",
        "patch_file",
        "patch_type",
        "source_variant",
        "sd_copy_status",
        "sd_output_path",
        "fxpak_path",
        "usb_upload_status",
        "usb_upload_error",
        "usb_device",
        "sd_copy_error",
        "message",
    )

    with (
        library_root
        / "build_report.csv"
    ).open(
        "w",
        encoding="utf-8-sig",
        newline="",
    ) as output_file:
        writer = csv.DictWriter(
            output_file,
            fieldnames=fieldnames,
        )
        writer.writeheader()

        for result in results:
            writer.writerow(
                {
                    name: result.get(name, "")
                    for name in fieldnames
                }
            )

    (
        library_root
        / "build_report.json"
    ).write_text(
        json.dumps(
            results,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    (
        library_root
        / "_library_index.json"
    ).write_text(
        json.dumps(
            {
                "entries": index_entries
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )


APP_DATA_DIR = platform_application_data_directory()
STATS_DB_FILE = APP_DATA_DIR / "SMWStreamTracker.db"
STATS_BACKUP_DIR = APP_DATA_DIR / "Backups"
AUTOMATIC_BACKUP_DIR = APP_DATA_DIR / "AutomaticBackups"
ROLLBACK_DIR = APP_DATA_DIR / "Rollback"
ROLLBACK_EXECUTABLE = ROLLBACK_DIR / "SMWStreamTracker_previous.exe"
ROLLBACK_HASH_FILE = ROLLBACK_DIR / "SMWStreamTracker_previous.sha256"
UPDATE_DOWNLOAD_DIR = APP_DATA_DIR / "Updates"
LOG_DIR = APP_DATA_DIR / "Logs"
CRASH_LOG_FILE = LOG_DIR / "SMWStreamTracker-errors.log"
UNINSTALL_OBS_PATH_FILE = APP_DATA_DIR / "UninstallObsOutputPath.txt"


def application_directory() -> Path:
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def select_livesplit_release_asset(
    release_payload: dict[str, Any],
) -> dict[str, Any]:
    """Select and validate the official Windows LiveSplit release ZIP."""
    assets = release_payload.get("assets", [])
    if not isinstance(assets, list):
        raise RuntimeError("The LiveSplit release did not include an asset list.")

    for asset in assets:
        if not isinstance(asset, dict):
            continue
        name = str(asset.get("name", "")).strip()
        if not re.fullmatch(
            r"LiveSplit_\d+(?:\.\d+)*\.zip",
            name,
            flags=re.IGNORECASE,
        ):
            continue
        url = str(asset.get("browser_download_url", "")).strip()
        parsed_url = urlparse(url)
        if (
            parsed_url.scheme.casefold() != "https"
            or (parsed_url.hostname or "").casefold() != "github.com"
            or not parsed_url.path.casefold().startswith(
                "/livesplit/livesplit/releases/download/"
            )
        ):
            continue
        try:
            size = int(asset.get("size", 0))
        except (TypeError, ValueError):
            continue
        if not 0 < size <= LIVESPLIT_RELEASE_MAX_BYTES:
            continue
        digest_text = str(asset.get("digest", "")).strip()
        digest_match = re.fullmatch(
            r"sha256:([0-9a-fA-F]{64})",
            digest_text,
        )
        return {
            "name": name,
            "url": url,
            "size": size,
            "sha256": digest_match.group(1) if digest_match else "",
            "version": str(
                release_payload.get("tag_name", "")
            ).strip(),
        }

    raise RuntimeError(
        "The latest official LiveSplit release did not contain a supported "
        "Windows ZIP download."
    )


def write_livesplit_tracker_settings(
    settings_path: Path,
    server_port: int,
) -> None:
    """Create or update LiveSplit settings for tracker TCP control."""
    port = int(server_port)
    if not 1 <= port <= 65535:
        raise ValueError("The LiveSplit server port must be between 1 and 65535.")

    settings_path = Path(settings_path)
    settings_path.parent.mkdir(parents=True, exist_ok=True)
    if settings_path.is_file():
        try:
            tree = ET.parse(settings_path)
        except (ET.ParseError, OSError) as error:
            raise RuntimeError(
                "The existing LiveSplit settings file could not be read."
            ) from error
        root = tree.getroot()
        if root.tag != "Settings":
            raise RuntimeError(
                "The existing LiveSplit settings file has an unexpected format."
            )
    else:
        root = ET.Element("Settings", {"version": "1.8.18"})
        hotkey_profiles = ET.SubElement(root, "HotkeyProfiles")
        hotkey_profile = ET.SubElement(
            hotkey_profiles,
            "HotkeyProfile",
            {"name": "Default"},
        )
        for key_name in (
            "SplitKey",
            "ResetKey",
            "SkipKey",
            "UndoKey",
            "PauseKey",
            "ToggleGlobalHotkeys",
            "SwitchComparisonPrevious",
            "SwitchComparisonNext",
        ):
            ET.SubElement(hotkey_profile, key_name)
        for setting_name, setting_value in (
            ("GlobalHotkeysEnabled", "False"),
            ("DeactivateHotkeysForOtherPrograms", "False"),
            ("DoubleTapPrevention", "True"),
            ("HotkeyDelay", "0"),
            ("AllowGamepadsAsHotkeys", "False"),
        ):
            ET.SubElement(hotkey_profile, setting_name).text = setting_value
        for setting_name, setting_value in (
            ("WarnOnReset", "True"),
            ("RaceViewer", "SpeedRunsLive"),
            ("AgreedToSRLRules", "False"),
            ("EnableDPIAwareness", "True"),
            ("UILanguage", ""),
        ):
            ET.SubElement(root, setting_name).text = setting_value
        ET.SubElement(root, "RecentSplits")
        ET.SubElement(root, "RecentLayouts")
        for setting_name, setting_value in (
            ("LastComparison", "Personal Best"),
            ("SimpleSumOfBest", "False"),
            ("RefreshRate", "40"),
            ("ServerPort", str(port)),
            # TCP server startup. LiveSplit's current enum defines TCP as 1.
            ("ServerStartup", "1"),
            ("ServerState", "0"),
        ):
            ET.SubElement(root, setting_name).text = setting_value
        ET.SubElement(root, "ComparisonGeneratorStates")
        ET.SubElement(root, "RaceProviderPlugins")
        ET.SubElement(root, "ActiveAutoSplitters")
        tree = ET.ElementTree(root)

    def set_root_value(name: str, value: str) -> None:
        element = root.find(name)
        if element is None:
            element = ET.SubElement(root, name)
        element.text = value

    set_root_value("ServerPort", str(port))
    # Starting the TCP server automatically removes the manual Control menu
    # step every time either installed copy is opened.
    set_root_value("ServerStartup", "1")

    ET.indent(tree, space="  ")
    temporary_path = settings_path.with_name(
        settings_path.name + f".{os.getpid()}.tmp"
    )
    try:
        tree.write(
            temporary_path,
            encoding="utf-8",
            xml_declaration=True,
        )
        os.replace(temporary_path, settings_path)
    finally:
        temporary_path.unlink(missing_ok=True)


def write_retroarch_tracker_settings(config_path: Path) -> None:
    """Enable the network controls required by live RetroArch tracking."""
    required_settings = {
        "network_cmd_enable": '"true"',
        "network_cmd_port": '"55355"',
        # One quit command must close the running content so Play/Random can
        # save state and switch games without waiting for a second key press.
        "quit_press_twice": '"false"',
        "config_save_on_exit": '"true"',
    }
    try:
        existing_text = config_path.read_text(
            encoding="utf-8-sig",
            errors="replace",
        )
    except OSError:
        existing_text = ""

    lines = existing_text.splitlines()
    found: set[str] = set()
    updated_lines: list[str] = []
    setting_pattern = re.compile(
        r"^\s*([A-Za-z0-9_]+)\s*="
    )
    for line in lines:
        match = setting_pattern.match(line)
        key = match.group(1) if match else ""
        if key in required_settings:
            if key not in found:
                updated_lines.append(
                    f"{key} = {required_settings[key]}"
                )
                found.add(key)
            continue
        updated_lines.append(line)

    if updated_lines and updated_lines[-1].strip():
        updated_lines.append("")
    for key, value in required_settings.items():
        if key not in found:
            updated_lines.append(f"{key} = {value}")

    config_path.parent.mkdir(parents=True, exist_ok=True)
    config_path.write_text(
        "\n".join(updated_lines).rstrip() + "\n",
        encoding="utf-8",
    )


def extract_7z_archive(archive_path: Path, destination: Path) -> None:
    """Extract a QUsb2Snes 7z bundle using available Windows tooling."""
    destination.mkdir(parents=True, exist_ok=True)
    extractor_candidates: list[list[str]] = []
    tar_executable = shutil.which("tar")
    if tar_executable:
        extractor_candidates.append(
            [
                tar_executable,
                "-xf",
                str(archive_path),
                "-C",
                str(destination),
            ]
        )
    for candidate in (
        shutil.which("7z"),
        str(
            Path(os.environ.get("PROGRAMFILES", "C:/Program Files"))
            / "7-Zip"
            / "7z.exe"
        ),
        str(
            Path(
                os.environ.get(
                    "PROGRAMFILES(X86)",
                    "C:/Program Files (x86)",
                )
            )
            / "7-Zip"
            / "7z.exe"
        ),
    ):
        if candidate and Path(candidate).is_file():
            extractor_candidates.append(
                [
                    candidate,
                    "x",
                    "-y",
                    f"-o{destination}",
                    str(archive_path),
                ]
            )

    errors: list[str] = []
    for command in extractor_candidates:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=180,
        )
        if result.returncode == 0:
            return
        errors.append(
            (result.stderr or result.stdout or "unknown error").strip()
        )
    raise RuntimeError(
        "Windows could not extract the QUsb2Snes 7z archive. Install "
        "7-Zip or use SNI instead."
        + ("\n\n" + "\n".join(errors[-2:]) if errors else "")
    )


def installed_document_path(filename: str) -> Path:
    external = application_directory() / filename
    if external.is_file():
        return external
    return bundled_resource_path("installer", filename)


def localized_installed_document_path(
    filename: str,
    language: object,
) -> Path:
    """Return a localized bundled notice, falling back to its base file."""
    language_code = str(language or "en").strip()
    source_name = Path(filename)
    if language_code not in {"", "en"}:
        localized_name = (
            source_name.stem
            + "."
            + language_code
            + source_name.suffix
        )
        localized_path = installed_document_path(localized_name)
        if localized_path.is_file():
            return localized_path
    return installed_document_path(filename)


def append_error_log(context: str, error_text: str) -> None:
    try:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        with CRASH_LOG_FILE.open("a", encoding="utf-8") as log_handle:
            log_handle.write(
                "\n["
                + datetime.now().astimezone().isoformat(timespec="seconds")
                + "] "
                + context
                + "\n"
                + error_text.rstrip()
                + "\n"
            )
    except OSError:
        pass


PRESERVE_TRACKER_TOTAL_DEATHS = object()


class TrackerDatabase:
    """SQLite-backed catalog, tracker, statistics, and ROM mappings."""

    def __init__(self, path: Path = STATS_DB_FILE) -> None:
        self.path = Path(path)

    def connect(self) -> sqlite3.Connection:
        self.path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        connection = sqlite3.connect(
            self.path,
            timeout=30,
        )
        connection.row_factory = sqlite3.Row
        connection.execute(
            "PRAGMA foreign_keys = ON"
        )
        connection.execute(
            "PRAGMA journal_mode = WAL"
        )
        return connection

    def initialize(self) -> None:
        with self.connect() as connection:
            existing_tracker_columns = {
                str(row["name"])
                for row in connection.execute(
                    "PRAGMA table_info(tracked_hacks)"
                ).fetchall()
            }
            upgrading_pre_death_tracker = bool(
                existing_tracker_columns
                and "total_deaths" not in existing_tracker_columns
            )
            connection.executescript(
                """
                CREATE TABLE IF NOT EXISTS catalog_hacks (
                    catalog_key TEXT PRIMARY KEY,
                    smwc_id TEXT NOT NULL DEFAULT '',
                    title TEXT NOT NULL,
                    normalized_title TEXT NOT NULL,
                    author TEXT NOT NULL DEFAULT 'Unknown',
                    total_exits INTEGER NOT NULL DEFAULT 0,
                    difficulty TEXT NOT NULL DEFAULT 'Unknown',
                    hack_type TEXT NOT NULL DEFAULT 'Unknown',
                    added_date TEXT NOT NULL DEFAULT '',
                    smwc_rating REAL,
                    page_url TEXT NOT NULL DEFAULT '',
                    download_url TEXT NOT NULL DEFAULT '',
                    is_custom INTEGER NOT NULL DEFAULT 0,
                    sa1 INTEGER NOT NULL DEFAULT 0,
                    hall_of_fame INTEGER NOT NULL DEFAULT 0,
                    is_waiting INTEGER NOT NULL DEFAULT 0,
                    rom_path TEXT NOT NULL DEFAULT '',
                    local_rom_path TEXT NOT NULL DEFAULT '',
                    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
                );

                CREATE INDEX IF NOT EXISTS
                    idx_catalog_normalized_title
                    ON catalog_hacks(normalized_title);

                CREATE INDEX IF NOT EXISTS
                    idx_catalog_smwc_id
                    ON catalog_hacks(smwc_id);

                CREATE TABLE IF NOT EXISTS tracked_hacks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    catalog_key TEXT NOT NULL UNIQUE,
                    display_order INTEGER,
                    title TEXT NOT NULL,
                    author TEXT NOT NULL DEFAULT 'Unknown',
                    total_exits INTEGER NOT NULL DEFAULT 0,
                    difficulty TEXT NOT NULL DEFAULT 'Unknown',
                    hack_type TEXT NOT NULL DEFAULT 'Unknown',
                    smwc_rating REAL,
                    date_started TEXT NOT NULL DEFAULT '',
                    date_completed TEXT NOT NULL DEFAULT '',
                    completed_exits INTEGER NOT NULL DEFAULT 0,
                    status TEXT NOT NULL DEFAULT 'Planned',
                    personal_rating REAL,
                    playtime_seconds INTEGER NOT NULL DEFAULT 0,
                    total_deaths INTEGER,
                    death_count_legacy INTEGER NOT NULL DEFAULT 0,
                    notes TEXT NOT NULL DEFAULT '',
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY(catalog_key)
                        REFERENCES catalog_hacks(catalog_key)
                        ON DELETE CASCADE
                );

                CREATE INDEX IF NOT EXISTS
                    idx_tracked_status
                    ON tracked_hacks(status);

                CREATE TABLE IF NOT EXISTS rom_mappings (
                    map_key TEXT PRIMARY KEY,
                    catalog_key TEXT,
                    title TEXT NOT NULL DEFAULT '',
                    smwc_id TEXT NOT NULL DEFAULT '',
                    rom_path TEXT NOT NULL,
                    last_launched TEXT NOT NULL DEFAULT '',
                    device TEXT NOT NULL DEFAULT '',
                    match_method TEXT NOT NULL DEFAULT '',
                    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
                );

                CREATE TABLE IF NOT EXISTS app_metadata (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL DEFAULT ''
                );

                CREATE TABLE IF NOT EXISTS play_sessions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    catalog_key TEXT,
                    started_at TEXT NOT NULL DEFAULT '',
                    ended_at TEXT NOT NULL DEFAULT '',
                    duration_seconds INTEGER NOT NULL DEFAULT 0,
                    exits_gained INTEGER NOT NULL DEFAULT 0,
                    notes TEXT NOT NULL DEFAULT ''
                );
                """
            )

            tracker_columns = {
                str(row["name"])
                for row in connection.execute(
                    "PRAGMA table_info(tracked_hacks)"
                ).fetchall()
            }
            catalog_columns = {
                str(row["name"])
                for row in connection.execute(
                    "PRAGMA table_info(catalog_hacks)"
                ).fetchall()
            }
            for column_name in (
                "sa1",
                "hall_of_fame",
                "is_waiting",
            ):
                if column_name not in catalog_columns:
                    connection.execute(
                        "ALTER TABLE catalog_hacks ADD COLUMN "
                        + column_name
                        + " INTEGER NOT NULL DEFAULT 0"
                    )
            if "total_deaths" not in tracker_columns:
                connection.execute(
                    "ALTER TABLE tracked_hacks ADD COLUMN total_deaths INTEGER"
                )
            if "death_count_legacy" not in tracker_columns:
                connection.execute(
                    "ALTER TABLE tracked_hacks ADD COLUMN "
                    "death_count_legacy INTEGER NOT NULL DEFAULT 0"
                )
            if upgrading_pre_death_tracker:
                connection.execute(
                    """
                    UPDATE tracked_hacks
                    SET death_count_legacy = 1
                    WHERE status = 'Completed'
                      AND total_deaths IS NULL
                    """
                )

    @staticmethod
    def _integer(
        value: object,
        default: int = 0,
    ) -> int:
        if value in (None, ""):
            return default

        try:
            return int(float(str(value).strip()))
        except (TypeError, ValueError):
            match = re.search(
                r"-?\d+",
                str(value),
            )
            return (
                int(match.group(0))
                if match
                else default
            )

    @staticmethod
    def _float(
        value: object,
    ) -> float | None:
        if value in (None, ""):
            return None

        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _date_text(
        value: object,
    ) -> str:
        if value in (None, ""):
            return ""

        if isinstance(value, datetime):
            return value.date().isoformat()

        if isinstance(value, date):
            return value.isoformat()

        if isinstance(value, (int, float)):
            try:
                excel_epoch = datetime(
                    1899,
                    12,
                    30,
                )
                return (
                    excel_epoch
                    + timedelta(days=float(value))
                ).date().isoformat()
            except (OverflowError, ValueError):
                return ""

        text_value = str(value).strip()

        for format_text in (
            "%Y-%m-%d",
            "%m/%d/%Y",
            "%m/%d/%y",
            "%Y/%m/%d",
        ):
            try:
                return datetime.strptime(
                    text_value,
                    format_text,
                ).date().isoformat()
            except ValueError:
                continue

        try:
            return datetime.fromisoformat(
                text_value
            ).date().isoformat()
        except ValueError:
            return text_value

    @staticmethod
    def _cell_url(cell) -> str:
        hyperlink = getattr(
            cell,
            "hyperlink",
            None,
        )

        if hyperlink is not None:
            target = getattr(
                hyperlink,
                "target",
                None,
            )

            if target:
                return str(target).strip()

        value = getattr(
            cell,
            "value",
            None,
        )

        if isinstance(value, str):
            stripped = value.strip()

            if stripped.casefold().startswith(
                ("https://", "http://")
            ):
                return stripped

        return ""

    @staticmethod
    def _playtime_seconds(
        hours_value: object,
        minutes_value: object,
        seconds_value: object,
    ) -> int:
        total = 0

        for value, multiplier in (
            (hours_value, 3600),
            (minutes_value, 60),
            (seconds_value, 1),
        ):
            if value in (None, ""):
                continue

            if isinstance(value, (int, float)):
                number = float(value)
            else:
                match = re.search(
                    r"-?\d+(?:\.\d+)?",
                    str(value),
                )
                number = (
                    float(match.group(0))
                    if match
                    else 0.0
                )

            total += int(round(number * multiplier))

        return max(0, total)

    @staticmethod
    def _header_map(sheet) -> dict[str, int]:
        return {
            normalize_title(cell.value): cell.column
            for cell in sheet[1]
            if cell.value not in (None, "")
        }

    @staticmethod
    def _column(
        headers: dict[str, int],
        *names: str,
    ) -> int | None:
        for name in names:
            column = headers.get(
                normalize_title(name)
            )

            if column is not None:
                return column

        return None

    @staticmethod
    def _normalize_smwc_id(
        value: object,
    ) -> str:
        if value in (None, ""):
            return ""

        text_value = str(value).strip()

        if text_value.casefold() in {
            "n/a",
            "na",
            "none",
        }:
            return ""

        try:
            return str(int(float(text_value)))
        except (TypeError, ValueError):
            return text_value

    def catalog_key(
        self,
        smwc_id: object,
        title: object,
        is_custom: bool = False,
        author: object = "",
    ) -> str:
        normalized_id = self._normalize_smwc_id(
            smwc_id
        )

        if normalized_id:
            return "SMWC:" + normalized_id

        normalized_title = (
            normalize_title(title)
            or "untitled"
        )

        if is_custom:
            digest = hashlib.sha1(
                (
                    str(title)
                    + "|"
                    + str(author)
                ).encode("utf-8")
            ).hexdigest()[:10]
            return (
                "CUSTOM:"
                + normalized_title
                + ":"
                + digest
            )

        return "TITLE:" + normalized_title

    def _upsert_catalog(
        self,
        connection: sqlite3.Connection,
        record: dict[str, Any],
    ) -> str:
        prepared = dict(record)
        prepared["title"] = str(
            prepared.get("title")
            or "Untitled"
        ).strip()
        prepared["author"] = str(
            prepared.get("author")
            or "Unknown"
        ).strip()
        prepared["smwc_id"] = (
            self._normalize_smwc_id(
                prepared.get("smwc_id")
            )
        )
        prepared["is_custom"] = (
            1
            if prepared.get("is_custom")
            else 0
        )
        prepared["sa1"] = 1 if prepared.get("sa1") else 0
        prepared["hall_of_fame"] = (
            1 if prepared.get("hall_of_fame") else 0
        )
        prepared["is_waiting"] = (
            1 if prepared.get("is_waiting") else 0
        )
        prepared["catalog_key"] = str(
            prepared.get("catalog_key")
            or self.catalog_key(
                prepared["smwc_id"],
                prepared["title"],
                bool(prepared["is_custom"]),
                prepared["author"],
            )
        )
        prepared["normalized_title"] = (
            normalize_title(prepared["title"])
        )
        prepared["total_exits"] = self._integer(
            prepared.get("total_exits")
        )
        prepared["difficulty"] = str(
            prepared.get("difficulty")
            or "Unknown"
        ).strip()
        prepared["hack_type"] = str(
            prepared.get("hack_type")
            or "Unknown"
        ).strip()
        prepared["added_date"] = self._date_text(
            prepared.get("added_date")
        )
        prepared["smwc_rating"] = self._float(
            prepared.get("smwc_rating")
            if "smwc_rating" in prepared
            else prepared.get("rating")
        )
        prepared["page_url"] = str(
            prepared.get("page_url")
            or ""
        ).strip()
        prepared["download_url"] = str(
            prepared.get("download_url")
            or ""
        ).strip()
        prepared["rom_path"] = str(
            prepared.get("rom_path")
            or ""
        ).strip()
        prepared["local_rom_path"] = str(
            prepared.get("local_rom_path")
            or ""
        ).strip()

        if (
            not prepared["page_url"]
            and prepared["smwc_id"]
        ):
            prepared["page_url"] = (
                "https://www.smwcentral.net/"
                "?a=details&id="
                + prepared["smwc_id"]
                + "&p=section"
            )

        connection.execute(
            """
            INSERT INTO catalog_hacks (
                catalog_key,
                smwc_id,
                title,
                normalized_title,
                author,
                total_exits,
                difficulty,
                hack_type,
                added_date,
                smwc_rating,
                page_url,
                download_url,
                is_custom,
                sa1,
                hall_of_fame,
                is_waiting,
                rom_path,
                local_rom_path,
                updated_at
            ) VALUES (
                :catalog_key,
                :smwc_id,
                :title,
                :normalized_title,
                :author,
                :total_exits,
                :difficulty,
                :hack_type,
                :added_date,
                :smwc_rating,
                :page_url,
                :download_url,
                :is_custom,
                :sa1,
                :hall_of_fame,
                :is_waiting,
                :rom_path,
                :local_rom_path,
                CURRENT_TIMESTAMP
            )
            ON CONFLICT(catalog_key) DO UPDATE SET
                smwc_id = excluded.smwc_id,
                title = excluded.title,
                normalized_title = excluded.normalized_title,
                author = excluded.author,
                total_exits = excluded.total_exits,
                difficulty = excluded.difficulty,
                hack_type = excluded.hack_type,
                added_date = excluded.added_date,
                smwc_rating = excluded.smwc_rating,
                page_url = excluded.page_url,
                download_url = excluded.download_url,
                is_custom = excluded.is_custom,
                sa1 = excluded.sa1,
                hall_of_fame = excluded.hall_of_fame,
                is_waiting = excluded.is_waiting,
                rom_path = CASE
                    WHEN excluded.rom_path <> ''
                    THEN excluded.rom_path
                    ELSE catalog_hacks.rom_path
                END,
                local_rom_path = CASE
                    WHEN excluded.local_rom_path <> ''
                    THEN excluded.local_rom_path
                    ELSE catalog_hacks.local_rom_path
                END,
                updated_at = CURRENT_TIMESTAMP
            """,
            prepared,
        )

        return prepared["catalog_key"]

    def catalog_count(self) -> int:
        self.initialize()

        with self.connect() as connection:
            return int(
                connection.execute(
                    "SELECT COUNT(*) FROM catalog_hacks"
                ).fetchone()[0]
            )

    def catalog_status_counts(self) -> dict[str, int]:
        """Return the current moderated/waiting split for the local catalog."""
        self.initialize()

        with self.connect() as connection:
            row = connection.execute(
                """
                SELECT
                    COUNT(*) AS total,
                    SUM(CASE WHEN is_waiting = 1 THEN 1 ELSE 0 END) AS waiting
                FROM catalog_hacks
                WHERE is_custom = 0
                """
            ).fetchone()
        total = int(row["total"] or 0)
        waiting = int(row["waiting"] or 0)
        return {
            "total": total,
            "waiting": waiting,
            "moderated": max(0, total - waiting),
        }

    def tracked_count(self) -> int:
        self.initialize()

        with self.connect() as connection:
            return int(
                connection.execute(
                    "SELECT COUNT(*) FROM tracked_hacks"
                ).fetchone()[0]
            )

    def import_workbook(
        self,
        workbook_path: Path,
    ) -> dict[str, int]:
        self.initialize()
        source_path = Path(workbook_path)

        if not source_path.exists():
            raise FileNotFoundError(source_path)

        temporary_folder = Path(
            tempfile.mkdtemp(
                prefix="SMWTrackerImport_"
            )
        )
        temporary_workbook = (
            temporary_folder / source_path.name
        )

        try:
            shutil.copy2(
                source_path,
                temporary_workbook,
            )
            workbook = load_workbook(
                temporary_workbook,
                data_only=True,
                read_only=False,
                keep_vba=(
                    source_path.suffix.casefold()
                    == ".xlsm"
                ),
            )

            summary = {
                "catalog": 0,
                "custom": 0,
                "tracked": 0,
                "completed": 0,
                "mappings": 0,
            }

            try:
                with self.connect() as connection:
                    catalog_by_title: dict[
                        str,
                        str,
                    ] = {}

                    def import_catalog_sheet(
                        sheet_name: str,
                        is_custom: bool,
                    ) -> None:
                        if sheet_name not in workbook.sheetnames:
                            return

                        sheet = workbook[sheet_name]
                        headers = self._header_map(sheet)
                        title_column = self._column(
                            headers,
                            "ROM Hack Title",
                            "Dropdown Selection",
                        )

                        if title_column is None:
                            return

                        author_column = self._column(
                            headers,
                            "Created By",
                        )
                        exits_column = self._column(
                            headers,
                            "Exits",
                        )
                        difficulty_column = self._column(
                            headers,
                            "Difficulty",
                        )
                        type_column = self._column(
                            headers,
                            "Type",
                        )
                        added_column = self._column(
                            headers,
                            "Added Date",
                        )
                        id_column = self._column(
                            headers,
                            "SMWC ID",
                            "SMWCentral ID",
                        )
                        rating_column = self._column(
                            headers,
                            "SMWCentral Rating",
                        )
                        page_column = self._column(
                            headers,
                            "SMWCentral Page URL",
                            "SMWCentral Page",
                            "Open Page",
                        )
                        download_column = self._column(
                            headers,
                            "Direct Download URL",
                            "Download Patch",
                            "Download",
                        )

                        for row_number in range(
                            2,
                            sheet.max_row + 1,
                        ):
                            title_value = sheet.cell(
                                row=row_number,
                                column=title_column,
                            ).value

                            # The workbook may contain a formula/date artifact
                            # as its first database row. Only text titles are
                            # imported into the application catalog.
                            if not isinstance(
                                title_value,
                                str,
                            ):
                                continue

                            title = title_value.strip()

                            if not title:
                                continue

                            record = {
                                "title": title,
                                "author": (
                                    sheet.cell(
                                        row=row_number,
                                        column=author_column,
                                    ).value
                                    if author_column
                                    else "Unknown"
                                ),
                                "total_exits": (
                                    sheet.cell(
                                        row=row_number,
                                        column=exits_column,
                                    ).value
                                    if exits_column
                                    else 0
                                ),
                                "difficulty": (
                                    sheet.cell(
                                        row=row_number,
                                        column=difficulty_column,
                                    ).value
                                    if difficulty_column
                                    else "Unknown"
                                ),
                                "hack_type": (
                                    sheet.cell(
                                        row=row_number,
                                        column=type_column,
                                    ).value
                                    if type_column
                                    else "Unknown"
                                ),
                                "added_date": (
                                    sheet.cell(
                                        row=row_number,
                                        column=added_column,
                                    ).value
                                    if added_column
                                    else ""
                                ),
                                "smwc_id": (
                                    sheet.cell(
                                        row=row_number,
                                        column=id_column,
                                    ).value
                                    if id_column
                                    else ""
                                ),
                                "smwc_rating": (
                                    sheet.cell(
                                        row=row_number,
                                        column=rating_column,
                                    ).value
                                    if rating_column
                                    else None
                                ),
                                "page_url": (
                                    self._cell_url(
                                        sheet.cell(
                                            row=row_number,
                                            column=page_column,
                                        )
                                    )
                                    if page_column
                                    else ""
                                ),
                                "download_url": (
                                    self._cell_url(
                                        sheet.cell(
                                            row=row_number,
                                            column=download_column,
                                        )
                                    )
                                    if download_column
                                    else ""
                                ),
                                "is_custom": is_custom,
                            }
                            catalog_key = self._upsert_catalog(
                                connection,
                                record,
                            )
                            catalog_by_title.setdefault(
                                normalize_title(title),
                                catalog_key,
                            )
                            summary[
                                "custom"
                                if is_custom
                                else "catalog"
                            ] += 1

                    if "Online Database" in workbook.sheetnames:
                        import_catalog_sheet(
                            "Online Database",
                            False,
                        )
                    else:
                        import_catalog_sheet(
                            DATABASE_SHEET,
                            False,
                        )

                    import_catalog_sheet(
                        "Manual Database",
                        True,
                    )

                    if FXPAK_MAP_SHEET in workbook.sheetnames:
                        map_sheet = workbook[
                            FXPAK_MAP_SHEET
                        ]
                        headers = self._header_map(
                            map_sheet
                        )
                        map_key_column = self._column(
                            headers,
                            "Map Key",
                        ) or 1
                        title_column = self._column(
                            headers,
                            "Hack Name",
                        ) or 2
                        id_column = self._column(
                            headers,
                            "SMWC ID",
                        ) or 3
                        path_column = self._column(
                            headers,
                            "FXPAK SD Path",
                        ) or 4
                        launched_column = self._column(
                            headers,
                            "Last Launched",
                        ) or 5
                        device_column = self._column(
                            headers,
                            "Device",
                        ) or 6
                        method_column = self._column(
                            headers,
                            "Match Method",
                        ) or 7

                        for row_number in range(
                            2,
                            map_sheet.max_row + 1,
                        ):
                            rom_path = str(
                                map_sheet.cell(
                                    row=row_number,
                                    column=path_column,
                                ).value
                                or ""
                            ).strip()

                            if not rom_path:
                                continue

                            map_key = str(
                                map_sheet.cell(
                                    row=row_number,
                                    column=map_key_column,
                                ).value
                                or ""
                            ).strip()
                            title = str(
                                map_sheet.cell(
                                    row=row_number,
                                    column=title_column,
                                ).value
                                or ""
                            ).strip()
                            smwc_id = self._normalize_smwc_id(
                                map_sheet.cell(
                                    row=row_number,
                                    column=id_column,
                                ).value
                            )
                            catalog_key = (
                                self.catalog_key(
                                    smwc_id,
                                    title,
                                )
                                if smwc_id or title
                                else ""
                            )

                            if not map_key:
                                map_key = (
                                    "SMWC:" + smwc_id
                                    if smwc_id
                                    else "TITLE:"
                                    + normalize_title(title)
                                )

                            connection.execute(
                                """
                                INSERT INTO rom_mappings (
                                    map_key,
                                    catalog_key,
                                    title,
                                    smwc_id,
                                    rom_path,
                                    last_launched,
                                    device,
                                    match_method,
                                    updated_at
                                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                                ON CONFLICT(map_key) DO UPDATE SET
                                    catalog_key = excluded.catalog_key,
                                    title = excluded.title,
                                    smwc_id = excluded.smwc_id,
                                    rom_path = excluded.rom_path,
                                    last_launched = excluded.last_launched,
                                    device = excluded.device,
                                    match_method = excluded.match_method,
                                    updated_at = CURRENT_TIMESTAMP
                                """,
                                (
                                    map_key,
                                    catalog_key,
                                    title,
                                    smwc_id,
                                    rom_path,
                                    self._date_text(
                                        map_sheet.cell(
                                            row=row_number,
                                            column=launched_column,
                                        ).value
                                    ),
                                    str(
                                        map_sheet.cell(
                                            row=row_number,
                                            column=device_column,
                                        ).value
                                        or ""
                                    ),
                                    str(
                                        map_sheet.cell(
                                            row=row_number,
                                            column=method_column,
                                        ).value
                                        or ""
                                    ),
                                ),
                            )

                            if catalog_key:
                                connection.execute(
                                    """
                                    UPDATE catalog_hacks
                                    SET rom_path = ?
                                    WHERE catalog_key = ?
                                    """,
                                    (
                                        rom_path,
                                        catalog_key,
                                    ),
                                )

                            summary["mappings"] += 1

                    if TRACKER_SHEET in workbook.sheetnames:
                        tracker_sheet = workbook[
                            TRACKER_SHEET
                        ]
                        headers = self._header_map(
                            tracker_sheet
                        )
                        title_column = self._column(
                            headers,
                            "ROM Hack Title",
                            "Select ROM Hack",
                        )

                        if title_column is not None:
                            order_column = self._column(
                                headers,
                                "Hack #",
                            )
                            author_column = self._column(
                                headers,
                                "Created By",
                            )
                            exits_column = self._column(
                                headers,
                                "Exits",
                            )
                            difficulty_column = self._column(
                                headers,
                                "Difficulty",
                            )
                            type_column = self._column(
                                headers,
                                "Type",
                            )
                            official_rating_column = self._column(
                                headers,
                                "SMWCentral Rating",
                            )
                            started_column = self._column(
                                headers,
                                "Date Started",
                            )
                            completed_date_column = self._column(
                                headers,
                                "Date Completed",
                            )
                            completed_exits_column = self._column(
                                headers,
                                "Completed Exits",
                            )
                            total_deaths_column = self._column(
                                headers,
                                "Total Deaths",
                                "Deaths",
                            )
                            personal_rating_column = self._column(
                                headers,
                                "Rating (1–5)",
                                "Rating (1-5)",
                            )
                            notes_column = self._column(
                                headers,
                                "Notes",
                            )
                            page_column = self._column(
                                headers,
                                "SMWCentral Page",
                            )
                            download_column = self._column(
                                headers,
                                "Download Patch",
                            )

                            for row_number in range(
                                2,
                                tracker_sheet.max_row + 1,
                            ):
                                title = str(
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=title_column,
                                    ).value
                                    or ""
                                ).strip()

                                if not title:
                                    continue

                                normalized = normalize_title(
                                    title
                                )
                                catalog_key = (
                                    catalog_by_title.get(
                                        normalized
                                    )
                                )

                                if not catalog_key:
                                    fallback_record = {
                                        "title": title,
                                        "author": (
                                            tracker_sheet.cell(
                                                row=row_number,
                                                column=author_column,
                                            ).value
                                            if author_column
                                            else "Unknown"
                                        ),
                                        "total_exits": (
                                            tracker_sheet.cell(
                                                row=row_number,
                                                column=exits_column,
                                            ).value
                                            if exits_column
                                            else 0
                                        ),
                                        "difficulty": (
                                            tracker_sheet.cell(
                                                row=row_number,
                                                column=difficulty_column,
                                            ).value
                                            if difficulty_column
                                            else "Unknown"
                                        ),
                                        "hack_type": (
                                            tracker_sheet.cell(
                                                row=row_number,
                                                column=type_column,
                                            ).value
                                            if type_column
                                            else "Unknown"
                                        ),
                                        "smwc_rating": (
                                            tracker_sheet.cell(
                                                row=row_number,
                                                column=official_rating_column,
                                            ).value
                                            if official_rating_column
                                            else None
                                        ),
                                        "page_url": (
                                            self._cell_url(
                                                tracker_sheet.cell(
                                                    row=row_number,
                                                    column=page_column,
                                                )
                                            )
                                            if page_column
                                            else ""
                                        ),
                                        "download_url": (
                                            self._cell_url(
                                                tracker_sheet.cell(
                                                    row=row_number,
                                                    column=download_column,
                                                )
                                            )
                                            if download_column
                                            else ""
                                        ),
                                        "is_custom": True,
                                    }
                                    catalog_key = self._upsert_catalog(
                                        connection,
                                        fallback_record,
                                    )
                                    catalog_by_title[
                                        normalized
                                    ] = catalog_key

                                catalog_row = connection.execute(
                                    """
                                    SELECT *
                                    FROM catalog_hacks
                                    WHERE catalog_key = ?
                                    """,
                                    (catalog_key,),
                                ).fetchone()

                                completed_value = (
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=completed_exits_column,
                                    ).value
                                    if completed_exits_column
                                    else 0
                                )
                                completed_text = str(
                                    completed_value or "0"
                                )
                                completed_exits = self._integer(
                                    completed_text.split(
                                        "/",
                                        1,
                                    )[0]
                                )
                                total_exits = self._integer(
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=exits_column,
                                    ).value
                                    if exits_column
                                    else catalog_row[
                                        "total_exits"
                                    ]
                                )
                                date_started = self._date_text(
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=started_column,
                                    ).value
                                    if started_column
                                    else ""
                                )
                                date_completed = self._date_text(
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=completed_date_column,
                                    ).value
                                    if completed_date_column
                                    else ""
                                )

                                if (
                                    date_completed
                                    or (
                                        total_exits > 0
                                        and completed_exits
                                        >= total_exits
                                    )
                                ):
                                    status = "Completed"
                                elif (
                                    completed_exits > 0
                                    or date_started
                                ):
                                    status = "In Progress"
                                else:
                                    status = "Planned"

                                imported_total_deaths = None
                                death_count_legacy = 0
                                if total_deaths_column is not None:
                                    raw_total_deaths = tracker_sheet.cell(
                                        row=row_number,
                                        column=total_deaths_column,
                                    ).value
                                    deaths_text = str(
                                        raw_total_deaths or ""
                                    ).strip()
                                    if deaths_text == "*":
                                        death_count_legacy = 1
                                    elif deaths_text:
                                        imported_total_deaths = max(
                                            0,
                                            self._integer(
                                                raw_total_deaths
                                            ),
                                        )
                                elif status == "Completed":
                                    # Older tracker workbooks had no death
                                    # column, so zero would be misleading.
                                    death_count_legacy = 1

                                personal_rating = self._float(
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=personal_rating_column,
                                    ).value
                                    if personal_rating_column
                                    else None
                                )
                                playtime_seconds = self._playtime_seconds(
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=14,
                                    ).value,
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=15,
                                    ).value,
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=16,
                                    ).value,
                                )
                                notes = (
                                    str(
                                        tracker_sheet.cell(
                                            row=row_number,
                                            column=notes_column,
                                        ).value
                                        or ""
                                    )
                                    if notes_column
                                    else ""
                                )
                                display_order = self._integer(
                                    tracker_sheet.cell(
                                        row=row_number,
                                        column=order_column,
                                    ).value
                                    if order_column
                                    else row_number - 1,
                                    row_number - 1,
                                )

                                connection.execute(
                                    """
                                    INSERT INTO tracked_hacks (
                                        catalog_key,
                                        display_order,
                                        title,
                                        author,
                                        total_exits,
                                        difficulty,
                                        hack_type,
                                        smwc_rating,
                                        date_started,
                                        date_completed,
                                        completed_exits,
                                        status,
                                        personal_rating,
                                        playtime_seconds,
                                        total_deaths,
                                        death_count_legacy,
                                        notes,
                                        created_at,
                                        updated_at
                                    ) VALUES (
                                        ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                                        ?, ?, ?, ?, ?, ?, ?,
                                        CURRENT_TIMESTAMP,
                                        CURRENT_TIMESTAMP
                                    )
                                    ON CONFLICT(catalog_key) DO UPDATE SET
                                        display_order = excluded.display_order,
                                        title = excluded.title,
                                        author = excluded.author,
                                        total_exits = excluded.total_exits,
                                        difficulty = excluded.difficulty,
                                        hack_type = excluded.hack_type,
                                        smwc_rating = excluded.smwc_rating,
                                        date_started = excluded.date_started,
                                        date_completed = excluded.date_completed,
                                        completed_exits = excluded.completed_exits,
                                        status = excluded.status,
                                        personal_rating = excluded.personal_rating,
                                        playtime_seconds = excluded.playtime_seconds,
                                        total_deaths = excluded.total_deaths,
                                        death_count_legacy = excluded.death_count_legacy,
                                        notes = excluded.notes,
                                        updated_at = CURRENT_TIMESTAMP
                                    """,
                                    (
                                        catalog_key,
                                        display_order,
                                        title,
                                        str(
                                            catalog_row["author"]
                                        ),
                                        total_exits,
                                        str(
                                            catalog_row["difficulty"]
                                        ),
                                        str(
                                            catalog_row["hack_type"]
                                        ),
                                        catalog_row["smwc_rating"],
                                        date_started,
                                        date_completed,
                                        completed_exits,
                                        status,
                                        personal_rating,
                                        playtime_seconds,
                                        imported_total_deaths,
                                        death_count_legacy,
                                        notes,
                                    ),
                                )
                                summary["tracked"] += 1

                                if status == "Completed":
                                    summary["completed"] += 1

                    if "Settings" in workbook.sheetnames:
                        settings_sheet = workbook[
                            "Settings"
                        ]

                        for row_number in range(
                            2,
                            settings_sheet.max_row + 1,
                        ):
                            setting_name = str(
                                settings_sheet.cell(
                                    row=row_number,
                                    column=1,
                                ).value
                                or ""
                            ).strip()
                            setting_value = str(
                                settings_sheet.cell(
                                    row=row_number,
                                    column=2,
                                ).value
                                or ""
                            )

                            if setting_name:
                                connection.execute(
                                    """
                                    INSERT INTO app_metadata (
                                        key,
                                        value
                                    ) VALUES (?, ?)
                                    ON CONFLICT(key) DO UPDATE SET
                                        value = excluded.value
                                    """,
                                    (
                                        setting_name,
                                        setting_value,
                                    ),
                                )

                    if FXPAK_SETTINGS_SHEET in workbook.sheetnames:
                        settings_sheet = workbook[
                            FXPAK_SETTINGS_SHEET
                        ]

                        for row_number in range(
                            2,
                            settings_sheet.max_row + 1,
                        ):
                            setting_name = str(
                                settings_sheet.cell(
                                    row=row_number,
                                    column=1,
                                ).value
                                or ""
                            ).strip()
                            setting_value = str(
                                settings_sheet.cell(
                                    row=row_number,
                                    column=2,
                                ).value
                                or ""
                            ).strip()

                            if setting_name:
                                connection.execute(
                                    """
                                    INSERT INTO app_metadata (
                                        key,
                                        value
                                    ) VALUES (?, ?)
                                    ON CONFLICT(key) DO UPDATE SET
                                        value = excluded.value
                                    """,
                                    (
                                        "FXPAK:" + setting_name,
                                        setting_value,
                                    ),
                                )

                    connection.execute(
                        """
                        INSERT INTO app_metadata (
                            key,
                            value
                        ) VALUES (?, ?)
                        ON CONFLICT(key) DO UPDATE SET
                            value = excluded.value
                        """,
                        (
                            "Last Workbook Import",
                            datetime.now().isoformat(
                                timespec="seconds"
                            ),
                        ),
                    )

            finally:
                workbook.close()

            return summary

        finally:
            shutil.rmtree(
                temporary_folder,
                ignore_errors=True,
            )

    def remove_repository_catalog_ids(
        self,
        smwc_ids: set[str],
    ) -> dict[str, int]:
        self.initialize()
        deleted = 0
        preserved = 0

        if not smwc_ids:
            return {
                "deleted": 0,
                "preserved": 0,
            }

        with self.connect() as connection:
            for smwc_id in sorted(
                {
                    str(value).strip()
                    for value in smwc_ids
                    if str(value).strip()
                }
            ):
                row = connection.execute(
                    """
                    SELECT catalog_key
                    FROM catalog_hacks
                    WHERE
                        smwc_id = ?
                        AND is_custom = 0
                        AND is_waiting = 0
                    LIMIT 1
                    """,
                    (smwc_id,),
                ).fetchone()

                if row is None:
                    continue

                catalog_key = str(
                    row["catalog_key"]
                )
                is_tracked = (
                    connection.execute(
                        """
                        SELECT 1
                        FROM tracked_hacks
                        WHERE catalog_key = ?
                        LIMIT 1
                        """,
                        (catalog_key,),
                    ).fetchone()
                    is not None
                )
                is_mapped = (
                    connection.execute(
                        """
                        SELECT 1
                        FROM rom_mappings
                        WHERE
                            catalog_key = ?
                            OR smwc_id = ?
                        LIMIT 1
                        """,
                        (
                            catalog_key,
                            smwc_id,
                        ),
                    ).fetchone()
                    is not None
                )

                if (
                    is_tracked
                    or is_mapped
                ):
                    connection.execute(
                        """
                        UPDATE catalog_hacks
                        SET
                            is_custom = 1,
                            updated_at = CURRENT_TIMESTAMP
                        WHERE catalog_key = ?
                        """,
                        (catalog_key,),
                    )
                    preserved += 1
                else:
                    connection.execute(
                        """
                        DELETE FROM catalog_hacks
                        WHERE catalog_key = ?
                        """,
                        (catalog_key,),
                    )
                    deleted += 1

        return {
            "deleted": deleted,
            "preserved": preserved,
        }

    def set_metadata(
        self,
        key: str,
        value: object,
    ) -> None:
        self.initialize()

        with self.connect() as connection:
            connection.execute(
                """
                INSERT INTO app_metadata (
                    key,
                    value
                ) VALUES (?, ?)
                ON CONFLICT(key) DO UPDATE SET
                    value = excluded.value
                """,
                (
                    str(key),
                    str(value),
                ),
            )

    def refresh_from_smwcentral(
        self,
        games: list[dict[str, Any]],
        refreshed_at: str,
        catalog_version: str,
    ) -> dict[str, int | str]:
        self.initialize()

        with self.connect() as connection:
            existing_rows = {
                str(row["catalog_key"]): dict(row)
                for row in connection.execute(
                    """
                    SELECT *
                    FROM catalog_hacks
                    WHERE is_custom = 0 AND is_waiting = 0
                    """
                )
            }
            new_count = 0
            updated_count = 0

            comparison_fields = (
                "smwc_id",
                "title",
                "author",
                "total_exits",
                "difficulty",
                "hack_type",
                "added_date",
                "smwc_rating",
                "page_url",
                "download_url",
                "sa1",
                "hall_of_fame",
                "is_waiting",
            )

            for game in games:
                prepared_game = dict(game)
                prepared_game["is_custom"] = False
                prepared_game["is_waiting"] = False
                catalog_key = self.catalog_key(
                    prepared_game.get("smwc_id"),
                    prepared_game.get("title"),
                    False,
                    prepared_game.get("author"),
                )
                prepared_game[
                    "catalog_key"
                ] = catalog_key
                existing = existing_rows.get(
                    catalog_key
                )

                if existing is None:
                    new_count += 1
                else:
                    normalized_new = {
                        "smwc_id": self._normalize_smwc_id(
                            prepared_game.get("smwc_id")
                        ),
                        "title": str(
                            prepared_game.get("title")
                            or "Untitled"
                        ).strip(),
                        "author": str(
                            prepared_game.get("author")
                            or "Unknown"
                        ).strip(),
                        "total_exits": self._integer(
                            prepared_game.get(
                                "total_exits"
                            )
                        ),
                        "difficulty": str(
                            prepared_game.get(
                                "difficulty"
                            )
                            or "Unknown"
                        ).strip(),
                        "hack_type": str(
                            prepared_game.get(
                                "hack_type"
                            )
                            or "Unknown"
                        ).strip(),
                        "added_date": self._date_text(
                            prepared_game.get(
                                "added_date"
                            )
                        ),
                        "smwc_rating": self._float(
                            prepared_game.get(
                                "smwc_rating"
                            )
                        ),
                        "page_url": str(
                            prepared_game.get(
                                "page_url"
                            )
                            or ""
                        ).strip(),
                        "download_url": str(
                            prepared_game.get(
                                "download_url"
                            )
                            or ""
                        ).strip(),
                        "sa1": 1 if prepared_game.get("sa1") else 0,
                        "hall_of_fame": (
                            1 if prepared_game.get("hall_of_fame") else 0
                        ),
                        "is_waiting": 0,
                    }

                    if any(
                        existing[field]
                        != normalized_new[field]
                        for field in comparison_fields
                    ):
                        updated_count += 1

                self._upsert_catalog(
                    connection,
                    prepared_game,
                )

            connection.execute(
                """
                UPDATE tracked_hacks
                SET
                    title = (
                        SELECT title
                        FROM catalog_hacks
                        WHERE catalog_hacks.catalog_key
                            = tracked_hacks.catalog_key
                    ),
                    author = (
                        SELECT author
                        FROM catalog_hacks
                        WHERE catalog_hacks.catalog_key
                            = tracked_hacks.catalog_key
                    ),
                    total_exits = (
                        SELECT total_exits
                        FROM catalog_hacks
                        WHERE catalog_hacks.catalog_key
                            = tracked_hacks.catalog_key
                    ),
                    difficulty = (
                        SELECT difficulty
                        FROM catalog_hacks
                        WHERE catalog_hacks.catalog_key
                            = tracked_hacks.catalog_key
                    ),
                    hack_type = (
                        SELECT hack_type
                        FROM catalog_hacks
                        WHERE catalog_hacks.catalog_key
                            = tracked_hacks.catalog_key
                    ),
                    smwc_rating = (
                        SELECT smwc_rating
                        FROM catalog_hacks
                        WHERE catalog_hacks.catalog_key
                            = tracked_hacks.catalog_key
                    ),
                    status = CASE
                        WHEN (
                            SELECT total_exits
                            FROM catalog_hacks
                            WHERE catalog_hacks.catalog_key
                                = tracked_hacks.catalog_key
                        ) > 0
                        AND completed_exits >= (
                            SELECT total_exits
                            FROM catalog_hacks
                            WHERE catalog_hacks.catalog_key
                                = tracked_hacks.catalog_key
                        )
                        THEN 'Completed'
                        WHEN completed_exits > 0
                        THEN 'In Progress'
                        ELSE status
                    END,
                    updated_at = CURRENT_TIMESTAMP
                WHERE catalog_key IN (
                    SELECT catalog_key
                    FROM catalog_hacks
                    WHERE is_custom = 0
                      AND is_waiting = 0
                )
                """
            )

            metadata_values = {
                "Catalog Version": catalog_version,
                "Catalog Last Refresh": refreshed_at,
                "Catalog Source": "SMWCentral",
            }

            for key, value in (
                metadata_values.items()
            ):
                connection.execute(
                    """
                    INSERT INTO app_metadata (
                        key,
                        value
                    ) VALUES (?, ?)
                    ON CONFLICT(key) DO UPDATE SET
                        value = excluded.value
                    """,
                    (key, value),
                )

            official_count = int(
                connection.execute(
                    """
                    SELECT COUNT(*)
                    FROM catalog_hacks
                    WHERE is_custom = 0
                    """
                ).fetchone()[0]
            )

        return {
            "fetched": len(games),
            "new": new_count,
            "updated": updated_count,
            "official": official_count,
            "version": catalog_version,
            "refreshed_at": refreshed_at,
        }

    def reset_smwcentral_catalog(self) -> dict[str, int]:
        """Remove the downloaded SMW Central catalog without losing user data."""
        self.initialize()
        deleted = 0
        preserved = 0

        with self.connect() as connection:
            rows = connection.execute(
                """
                SELECT catalog_key, smwc_id
                FROM catalog_hacks
                WHERE is_custom = 0
                """
            ).fetchall()

            for row in rows:
                catalog_key = str(row["catalog_key"])
                smwc_id = str(row["smwc_id"] or "")
                referenced = connection.execute(
                    """
                    SELECT 1
                    FROM tracked_hacks
                    WHERE catalog_key = ?
                    UNION
                    SELECT 1
                    FROM rom_mappings
                    WHERE catalog_key = ? OR smwc_id = ?
                    LIMIT 1
                    """,
                    (catalog_key, catalog_key, smwc_id),
                ).fetchone()

                if referenced is not None:
                    # The catalog row is the foreign-key owner for tracker
                    # progress. Reclassify it as a personal record so the
                    # SMW Central catalog can be emptied without cascading
                    # into My Tracker or breaking a saved ROM mapping.
                    connection.execute(
                        """
                        UPDATE catalog_hacks
                        SET
                            is_custom = 1,
                            is_waiting = 0,
                            updated_at = CURRENT_TIMESTAMP
                        WHERE catalog_key = ?
                        """,
                        (catalog_key,),
                    )
                    preserved += 1
                else:
                    connection.execute(
                        "DELETE FROM catalog_hacks WHERE catalog_key = ?",
                        (catalog_key,),
                    )
                    deleted += 1

            connection.execute(
                """
                DELETE FROM app_metadata
                WHERE key IN (
                    'Catalog Sequence',
                    'Catalog Version',
                    'Official Hack Count',
                    'Catalog Last Refresh',
                    'Catalog Source',
                    'Catalog Repository URL',
                    'Waiting Last Refresh',
                    'Waiting Count',
                    'Waiting New Since Last Refresh'
                )
                """
            )

        return {
            "removed": deleted + preserved,
            "deleted": deleted,
            "preserved": preserved,
        }

    def refresh_waiting_from_smwcentral(
        self,
        games: list[dict[str, Any]],
        refreshed_at: str,
    ) -> dict[str, int | str]:
        """Replace waiting rows while preserving tracked or mapped entries."""
        self.initialize()
        incoming_keys: set[str] = set()
        with self.connect() as connection:
            existing_waiting_keys = {
                str(row["catalog_key"])
                for row in connection.execute(
                    "SELECT catalog_key FROM catalog_hacks WHERE is_waiting = 1"
                )
            }
            for game in games:
                prepared_game = dict(game)
                prepared_game["is_custom"] = False
                prepared_game["is_waiting"] = True
                catalog_key = self.catalog_key(
                    prepared_game.get("smwc_id"),
                    prepared_game.get("title"),
                    False,
                    prepared_game.get("author"),
                )
                prepared_game["catalog_key"] = catalog_key
                incoming_keys.add(catalog_key)
                self._upsert_catalog(connection, prepared_game)

            stale_rows = connection.execute(
                "SELECT catalog_key, smwc_id FROM catalog_hacks "
                "WHERE is_waiting = 1"
            ).fetchall()
            removed = 0
            preserved = 0
            for row in stale_rows:
                catalog_key = str(row["catalog_key"])
                if catalog_key in incoming_keys:
                    continue
                referenced = connection.execute(
                    "SELECT 1 FROM tracked_hacks WHERE catalog_key = ? "
                    "UNION SELECT 1 FROM rom_mappings "
                    "WHERE catalog_key = ? OR smwc_id = ? LIMIT 1",
                    (catalog_key, catalog_key, str(row["smwc_id"] or "")),
                ).fetchone()
                if referenced is not None:
                    preserved += 1
                    continue
                connection.execute(
                    "DELETE FROM catalog_hacks WHERE catalog_key = ?",
                    (catalog_key,),
                )
                removed += 1

            new_count = len(incoming_keys - existing_waiting_keys)
            for key, value in {
                "Waiting Last Refresh": refreshed_at,
                "Waiting Count": len(games),
                "Waiting New Since Last Refresh": new_count,
            }.items():
                connection.execute(
                    "INSERT INTO app_metadata (key, value) VALUES (?, ?) "
                    "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
                    (key, str(value)),
                )
        return {
            "fetched": len(games),
            "removed": removed,
            "preserved": preserved,
            "new": new_count,
            "refreshed_at": refreshed_at,
        }

    def metadata(self) -> dict[str, str]:
        self.initialize()

        with self.connect() as connection:
            return {
                str(row["key"]): str(row["value"])
                for row in connection.execute(
                    "SELECT key, value FROM app_metadata"
                )
            }

    def load_catalog(self) -> list[dict[str, Any]]:
        self.initialize()

        with self.connect() as connection:
            rows = connection.execute(
                """
                SELECT
                    catalog_key,
                    smwc_id,
                    title,
                    author,
                    total_exits,
                    difficulty,
                    hack_type,
                    added_date,
                    smwc_rating,
                    page_url,
                    download_url,
                    is_custom,
                    sa1,
                    hall_of_fame,
                    is_waiting,
                    rom_path,
                    local_rom_path
                FROM catalog_hacks
                ORDER BY title COLLATE NOCASE
                """
            ).fetchall()

        games: list[dict[str, Any]] = []

        for row in rows:
            smwc_id = str(row["smwc_id"] or "")
            title = str(row["title"])
            mapping_key = (
                "SMWC:" + smwc_id
                if smwc_id
                else "TITLE:"
                + title.casefold().strip()
            )
            games.append(
                {
                    "catalog_key": str(
                        row["catalog_key"]
                    ),
                    "title": title,
                    "author": str(
                        smwc_author_text(
                            row["author"]
                        )
                    ),
                    "total_exits": int(
                        row["total_exits"] or 0
                    ),
                    "difficulty": str(
                        row["difficulty"]
                        or "Unknown"
                    ),
                    "hack_type": str(
                        row["hack_type"]
                        or "Unknown"
                    ),
                    "rating": (
                        float(row["smwc_rating"])
                        if row["smwc_rating"]
                        is not None
                        else None
                    ),
                    "added_date": str(
                        row["added_date"] or ""
                    ),
                    "download_url": str(
                        row["download_url"] or ""
                    ),
                    "smwc_id": smwc_id,
                    "page_url": str(
                        row["page_url"] or ""
                    ),
                    "rom_path": str(
                        row["rom_path"] or ""
                    ),
                    "local_rom_path": str(
                        row["local_rom_path"] or ""
                    ),
                    "mapping_key": mapping_key,
                    "is_custom": bool(
                        row["is_custom"]
                    ),
                    "sa1": bool(row["sa1"]),
                    "hall_of_fame": bool(row["hall_of_fame"]),
                    "is_waiting": bool(row["is_waiting"]),
                }
            )

        return games

    def rom_mapping_map(self) -> dict[str, str]:
        self.initialize()
        mapping: dict[str, str] = {}

        with self.connect() as connection:
            rows = connection.execute(
                """
                SELECT map_key, title, smwc_id, rom_path
                FROM rom_mappings
                WHERE rom_path <> ''
                """
            ).fetchall()

        for row in rows:
            rom_path = str(row["rom_path"])
            map_key = str(row["map_key"] or "")
            title = str(row["title"] or "")
            smwc_id = str(row["smwc_id"] or "")

            if map_key:
                mapping[map_key.casefold()] = rom_path

            if smwc_id:
                mapping[
                    ("SMWC:" + smwc_id).casefold()
                ] = rom_path

            if title:
                mapping[
                    (
                        "TITLE:"
                        + title.casefold().strip()
                    ).casefold()
                ] = rom_path
                normalized = normalize_title(title)

                if normalized:
                    mapping[
                        "NORMALIZED:" + normalized
                    ] = rom_path

        return mapping

    def _ensure_game_catalog_record(
        self,
        connection: sqlite3.Connection,
        game: dict[str, Any],
    ) -> str:
        catalog_key = str(
            game.get("catalog_key")
            or ""
        ).strip()

        if catalog_key:
            existing = connection.execute(
                """
                SELECT catalog_key
                FROM catalog_hacks
                WHERE catalog_key = ?
                """,
                (catalog_key,),
            ).fetchone()

            if existing:
                return catalog_key

        record = dict(game)
        record["is_custom"] = not bool(
            str(game.get("smwc_id", "")).strip()
        )
        record["smwc_rating"] = game.get(
            "rating"
        )
        return self._upsert_catalog(
            connection,
            record,
        )

    def add_to_tracker(
        self,
        game: dict[str, Any],
        completed_exits: int = 0,
        playtime_seconds: int = 0,
    ) -> dict[str, Any]:
        self.initialize()
        today = date.today().isoformat()

        with self.connect() as connection:
            catalog_key = (
                self._ensure_game_catalog_record(
                    connection,
                    game,
                )
            )
            catalog_row = connection.execute(
                """
                SELECT *
                FROM catalog_hacks
                WHERE catalog_key = ?
                """,
                (catalog_key,),
            ).fetchone()
            existing = connection.execute(
                """
                SELECT *
                FROM tracked_hacks
                WHERE catalog_key = ?
                """,
                (catalog_key,),
            ).fetchone()
            total_exits = self._integer(
                game.get(
                    "total_exits",
                    catalog_row["total_exits"],
                )
            )
            completed = max(
                0,
                int(completed_exits),
            )
            playtime = max(
                0,
                int(playtime_seconds),
            )

            if total_exits > 0 and completed >= total_exits:
                status = "Completed"
                completed_date = today
            else:
                status = "In Progress"
                completed_date = ""

            if existing:
                connection.execute(
                    """
                    UPDATE tracked_hacks
                    SET
                        completed_exits = MAX(
                            completed_exits,
                            ?
                        ),
                        playtime_seconds = MAX(
                            playtime_seconds,
                            ?
                        ),
                        date_started = CASE
                            WHEN date_started = ''
                            THEN ?
                            ELSE date_started
                        END,
                        date_completed = CASE
                            WHEN ? <> ''
                            THEN ?
                            ELSE date_completed
                        END,
                        status = CASE
                            WHEN ? = 'Completed'
                            THEN 'Completed'
                            WHEN status = 'Planned'
                            THEN 'In Progress'
                            ELSE status
                        END,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE catalog_key = ?
                    """,
                    (
                        completed,
                        playtime,
                        today,
                        completed_date,
                        completed_date,
                        status,
                        catalog_key,
                    ),
                )
                row_id = int(existing["id"])
                created = False
            else:
                display_order = int(
                    connection.execute(
                        """
                        SELECT COALESCE(
                            MAX(display_order),
                            0
                        ) + 1
                        FROM tracked_hacks
                        """
                    ).fetchone()[0]
                )
                cursor = connection.execute(
                    """
                    INSERT INTO tracked_hacks (
                        catalog_key,
                        display_order,
                        title,
                        author,
                        total_exits,
                        difficulty,
                        hack_type,
                        smwc_rating,
                        date_started,
                        date_completed,
                        completed_exits,
                        status,
                        playtime_seconds,
                        created_at,
                        updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                    """,
                    (
                        catalog_key,
                        display_order,
                        str(catalog_row["title"]),
                        str(catalog_row["author"]),
                        total_exits,
                        str(catalog_row["difficulty"]),
                        str(catalog_row["hack_type"]),
                        catalog_row["smwc_rating"],
                        today,
                        completed_date,
                        completed,
                        status,
                        playtime,
                    ),
                )
                row_id = int(cursor.lastrowid)
                created = True

            percentage = (
                min(
                    100,
                    round(
                        completed
                        / total_exits
                        * 100
                    ),
                )
                if total_exits > 0
                else 0
            )

            return {
                "id": row_id,
                "created": created,
                "completed": completed,
                "total": total_exits,
                "percentage": percentage,
                "status": status,
            }

    def update_progress(
        self,
        title: str,
        completed_exits: int,
        total_exits: int,
        game: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        self.initialize()
        normalized = normalize_title(title)
        today = date.today().isoformat()
        selected_game = game or {}
        catalog_key = str(
            selected_game.get(
                "catalog_key",
                "",
            )
        ).strip()
        smwc_id = str(
            selected_game.get(
                "smwc_id",
                "",
            )
        ).strip()

        with self.connect() as connection:
            if catalog_key:
                row = connection.execute(
                    """
                    SELECT *
                    FROM tracked_hacks
                    WHERE catalog_key = ?
                    LIMIT 1
                    """,
                    (catalog_key,),
                ).fetchone()
            elif smwc_id:
                row = connection.execute(
                    """
                    SELECT tracked_hacks.*
                    FROM tracked_hacks
                    JOIN catalog_hacks
                        ON catalog_hacks.catalog_key
                        = tracked_hacks.catalog_key
                    WHERE catalog_hacks.smwc_id = ?
                    ORDER BY tracked_hacks.id
                    LIMIT 1
                    """,
                    (smwc_id,),
                ).fetchone()
            else:
                row = connection.execute(
                    """
                    SELECT tracked_hacks.*
                    FROM tracked_hacks
                    JOIN catalog_hacks
                        ON catalog_hacks.catalog_key
                        = tracked_hacks.catalog_key
                    WHERE catalog_hacks.normalized_title = ?
                    ORDER BY tracked_hacks.id
                    LIMIT 1
                    """,
                    (normalized,),
                ).fetchone()

            if row is None:
                return {
                    "found": False,
                    "percentage": 0,
                }

            completed = max(
                int(row["completed_exits"] or 0),
                max(0, int(completed_exits)),
            )
            total = max(
                int(row["total_exits"] or 0),
                max(0, int(total_exits)),
            )
            is_complete = (
                total > 0
                and completed >= total
            )
            status = (
                "Completed"
                if is_complete
                else "In Progress"
            )
            connection.execute(
                """
                UPDATE tracked_hacks
                SET
                    total_exits = ?,
                    completed_exits = ?,
                    status = ?,
                    date_started = CASE
                        WHEN date_started = ''
                        THEN ?
                        ELSE date_started
                    END,
                    date_completed = CASE
                        WHEN ? = 1
                             AND date_completed = ''
                        THEN ?
                        ELSE date_completed
                    END,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (
                    total,
                    completed,
                    status,
                    today,
                    1 if is_complete else 0,
                    today,
                    int(row["id"]),
                ),
            )
            percentage = (
                min(
                    100,
                    round(completed / total * 100),
                )
                if total > 0
                else 0
            )
            return {
                "found": True,
                "id": int(row["id"]),
                "completed": completed,
                "total": total,
                "percentage": percentage,
                "status": status,
            }

    def complete_hack(
        self,
        game: dict[str, Any],
        completed_exits: int,
        total_exits: int,
        playtime_seconds: int,
        rating: float,
        notes: str,
        total_deaths: int = 0,
    ) -> dict[str, Any]:
        if rating < 1 or rating > 5:
            raise ValueError(
                "Personal rating must be from 1 through 5."
            )

        self.initialize()
        today = date.today().isoformat()

        with self.connect() as connection:
            catalog_key = (
                self._ensure_game_catalog_record(
                    connection,
                    game,
                )
            )
            catalog_row = connection.execute(
                """
                SELECT *
                FROM catalog_hacks
                WHERE catalog_key = ?
                """,
                (catalog_key,),
            ).fetchone()
            existing = connection.execute(
                """
                SELECT *
                FROM tracked_hacks
                WHERE catalog_key = ?
                """,
                (catalog_key,),
            ).fetchone()
            catalog_total = int(
                catalog_row["total_exits"] or 0
            )
            requested_total = max(
                0,
                self._integer(total_exits),
            )
            total = (
                requested_total
                if requested_total > 0
                else catalog_total
            )
            completed = max(
                0,
                int(completed_exits),
            )
            if total > 0:
                completed = min(
                    completed,
                    total,
                )
            playtime = max(
                0,
                int(playtime_seconds),
            )
            recorded_deaths = max(
                0,
                int(total_deaths),
            )
            is_complete = (
                total > 0
                and completed >= total
            )
            status = (
                "Completed"
                if is_complete
                else "In Progress"
            )
            completed_date = (
                today
                if is_complete
                else ""
            )

            if existing:
                connection.execute(
                    """
                    UPDATE tracked_hacks
                    SET
                        total_exits = ?,
                        completed_exits = ?,
                        status = ?,
                        date_started = CASE
                            WHEN date_started = ''
                            THEN ?
                            ELSE date_started
                        END,
                        date_completed = ?,
                        personal_rating = ?,
                        playtime_seconds = MAX(
                            playtime_seconds,
                            ?
                        ),
                        total_deaths = ?,
                        death_count_legacy = 0,
                        notes = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE catalog_key = ?
                    """,
                    (
                        total,
                        completed,
                        status,
                        today,
                        completed_date,
                        float(rating),
                        playtime,
                        recorded_deaths,
                        str(notes),
                        catalog_key,
                    ),
                )
                row_id = int(existing["id"])
                created = False
            else:
                display_order = int(
                    connection.execute(
                        """
                        SELECT COALESCE(
                            MAX(display_order),
                            0
                        ) + 1
                        FROM tracked_hacks
                        """
                    ).fetchone()[0]
                )
                cursor = connection.execute(
                    """
                    INSERT INTO tracked_hacks (
                        catalog_key,
                        display_order,
                        title,
                        author,
                        total_exits,
                        difficulty,
                        hack_type,
                        smwc_rating,
                        date_started,
                        date_completed,
                        completed_exits,
                        status,
                        personal_rating,
                        playtime_seconds,
                        total_deaths,
                        death_count_legacy,
                        notes,
                        created_at,
                        updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                    """,
                    (
                        catalog_key,
                        display_order,
                        str(catalog_row["title"]),
                        str(catalog_row["author"]),
                        total,
                        str(catalog_row["difficulty"]),
                        str(catalog_row["hack_type"]),
                        catalog_row["smwc_rating"],
                        today,
                        completed_date,
                        completed,
                        status,
                        float(rating),
                        playtime,
                        recorded_deaths,
                        str(notes),
                    ),
                )
                row_id = int(cursor.lastrowid)
                created = True

            percentage = (
                min(
                    100,
                    round(
                        completed / total * 100
                    ),
                )
                if total > 0
                else 0
            )
            return {
                "id": row_id,
                "created": created,
                "completed": completed,
                "total": total,
                "percentage": percentage,
                "status": status,
                "total_deaths": recorded_deaths,
            }

    def overview(self) -> dict[str, Any]:
        self.initialize()

        with self.connect() as connection:
            official_metadata = (
                connection.execute(
                    """
                    SELECT value
                    FROM app_metadata
                    WHERE key = 'Official Hack Count'
                    """
                ).fetchone()
            )

            if official_metadata is not None:
                official = self._integer(
                    official_metadata["value"]
                )
            else:
                official = int(
                    connection.execute(
                        """
                        SELECT COUNT(*)
                        FROM catalog_hacks
                        WHERE is_custom = 0
                        """
                    ).fetchone()[0]
                )
            custom = int(
                connection.execute(
                    """
                    SELECT COUNT(*)
                    FROM catalog_hacks
                    WHERE is_custom = 1
                    """
                ).fetchone()[0]
            )
            totals = connection.execute(
                """
                SELECT
                    COUNT(*) AS tracked,
                    SUM(
                        CASE
                            WHEN status = 'Completed'
                            THEN 1
                            ELSE 0
                        END
                    ) AS completed,
                    SUM(
                        CASE
                            WHEN status = 'In Progress'
                            THEN 1
                            ELSE 0
                        END
                    ) AS in_progress,
                    SUM(
                        CASE
                            WHEN status = 'Planned'
                            THEN 1
                            ELSE 0
                        END
                    ) AS planned,
                    COALESCE(
                        SUM(completed_exits),
                        0
                    ) AS completed_exits,
                    COALESCE(
                        SUM(total_exits),
                        0
                    ) AS total_exits,
                    AVG(personal_rating) AS average_rating,
                    COALESCE(
                        SUM(playtime_seconds),
                        0
                    ) AS playtime_seconds
                FROM tracked_hacks
                """
            ).fetchone()
            difficulty_rows = connection.execute(
                """
                SELECT
                    difficulty,
                    COUNT(*) AS tracked,
                    SUM(
                        CASE
                            WHEN status = 'Completed'
                            THEN 1
                            ELSE 0
                        END
                    ) AS completed,
                    COALESCE(
                        SUM(completed_exits),
                        0
                    ) AS completed_exits,
                    COALESCE(
                        SUM(total_exits),
                        0
                    ) AS total_exits
                FROM tracked_hacks
                GROUP BY difficulty
                ORDER BY difficulty COLLATE NOCASE
                """
            ).fetchall()
            status_rows = connection.execute(
                """
                SELECT status, COUNT(*) AS count
                FROM tracked_hacks
                GROUP BY status
                ORDER BY status
                """
            ).fetchall()
            recent_rows = connection.execute(
                """
                SELECT
                    id,
                    title,
                    status,
                    date_started,
                    date_completed,
                    completed_exits,
                    total_exits,
                    playtime_seconds
                FROM tracked_hacks
                ORDER BY
                    CASE
                        WHEN date_completed <> ''
                        THEN date_completed
                        ELSE date_started
                    END DESC,
                    updated_at DESC
                LIMIT 25
                """
            ).fetchall()
            metadata_rows = connection.execute(
                "SELECT key, value FROM app_metadata"
            ).fetchall()

        tracked = int(totals["tracked"] or 0)
        completed = int(totals["completed"] or 0)

        return {
            "official": official,
            "custom": custom,
            "tracked": tracked,
            "completed": completed,
            "in_progress": int(
                totals["in_progress"] or 0
            ),
            "planned": int(
                totals["planned"] or 0
            ),
            "completion_rate": (
                completed / tracked
                if tracked
                else 0.0
            ),
            "completed_exits": int(
                totals["completed_exits"] or 0
            ),
            "total_exits": int(
                totals["total_exits"] or 0
            ),
            "average_rating": (
                float(totals["average_rating"])
                if totals["average_rating"]
                is not None
                else None
            ),
            "playtime_seconds": int(
                totals["playtime_seconds"] or 0
            ),
            "difficulty": [
                dict(row)
                for row in difficulty_rows
            ],
            "status": [
                dict(row)
                for row in status_rows
            ],
            "recent": [
                dict(row)
                for row in recent_rows
            ],
            "metadata": {
                str(row["key"]): str(row["value"])
                for row in metadata_rows
            },
        }

    def list_tracked(self) -> list[dict[str, Any]]:
        self.initialize()

        with self.connect() as connection:
            rows = connection.execute(
                """
                SELECT
                    tracked_hacks.*,
                    catalog_hacks.smwc_id,
                    catalog_hacks.page_url,
                    catalog_hacks.download_url,
                    catalog_hacks.rom_path,
                    catalog_hacks.local_rom_path
                FROM tracked_hacks
                JOIN catalog_hacks
                    ON catalog_hacks.catalog_key
                    = tracked_hacks.catalog_key
                ORDER BY
                    COALESCE(
                        tracked_hacks.display_order,
                        tracked_hacks.id
                    ),
                    tracked_hacks.title COLLATE NOCASE
                """
            ).fetchall()

        records = [
            dict(row)
            for row in rows
        ]
        for record in records:
            record["author"] = (
                smwc_author_text(
                    record.get(
                        "author",
                        "Unknown",
                    )
                )
            )
        return records

    def get_tracked(
        self,
        record_id: int,
    ) -> dict[str, Any] | None:
        self.initialize()

        with self.connect() as connection:
            row = connection.execute(
                """
                SELECT
                    tracked_hacks.*,
                    catalog_hacks.smwc_id,
                    catalog_hacks.page_url,
                    catalog_hacks.download_url,
                    catalog_hacks.rom_path,
                    catalog_hacks.local_rom_path
                FROM tracked_hacks
                JOIN catalog_hacks
                    ON catalog_hacks.catalog_key
                    = tracked_hacks.catalog_key
                WHERE tracked_hacks.id = ?
                """,
                (int(record_id),),
            ).fetchone()

        if row is None:
            return None

        record = dict(row)
        record["author"] = smwc_author_text(
            record.get(
                "author",
                "Unknown",
            )
        )
        return record

    def get_catalog_game(
        self,
        catalog_key: str,
    ) -> dict[str, Any] | None:
        for game in self.load_catalog():
            if str(game.get("catalog_key")) == str(
                catalog_key
            ):
                return game

        return None

    def save_tracked(
        self,
        record_id: int,
        completed_exits: int,
        status: str,
        personal_rating: float | None,
        playtime_seconds: int,
        date_started: str,
        date_completed: str,
        notes: str,
        total_deaths: int | None | object = (
            PRESERVE_TRACKER_TOTAL_DEATHS
        ),
    ) -> None:
        self.initialize()
        valid_statuses = {
            "Planned",
            "In Progress",
            "Completed",
        }

        if status not in valid_statuses:
            raise ValueError(
                "Status must be Planned, In Progress, or Completed."
            )

        if (
            personal_rating is not None
            and not 1 <= personal_rating <= 5
        ):
            raise ValueError(
                "Personal rating must be blank or from 1 through 5."
            )

        started = self._date_text(date_started)
        completed_date = self._date_text(
            date_completed
        )

        with self.connect() as connection:
            row = connection.execute(
                """
                SELECT *
                FROM tracked_hacks
                WHERE id = ?
                """,
                (int(record_id),),
            ).fetchone()

            if row is None:
                raise RuntimeError(
                    "The selected tracker record no longer exists."
                )

            total = int(row["total_exits"] or 0)
            completed = max(
                0,
                int(completed_exits),
            )

            if total > 0 and completed >= total:
                status = "Completed"

            if status == "Completed":
                if total > 0:
                    completed = max(completed, total)
                if not completed_date:
                    completed_date = date.today().isoformat()
                if not started:
                    started = completed_date
            elif status == "In Progress":
                if not started:
                    started = date.today().isoformat()
                completed_date = ""
            else:
                completed_date = ""

            if total_deaths is PRESERVE_TRACKER_TOTAL_DEATHS:
                saved_total_deaths = row["total_deaths"]
                death_count_legacy = int(
                    row["death_count_legacy"] or 0
                )
            elif total_deaths is None:
                saved_total_deaths = None
                death_count_legacy = (
                    1 if status == "Completed" else 0
                )
            else:
                saved_total_deaths = int(total_deaths)
                if saved_total_deaths < 0:
                    raise ValueError(
                        "Total deaths cannot be negative."
                    )
                death_count_legacy = 0

            connection.execute(
                """
                UPDATE tracked_hacks
                SET
                    completed_exits = ?,
                    status = ?,
                    personal_rating = ?,
                    playtime_seconds = ?,
                    date_started = ?,
                    date_completed = ?,
                    total_deaths = ?,
                    death_count_legacy = ?,
                    notes = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (
                    completed,
                    status,
                    personal_rating,
                    max(0, int(playtime_seconds)),
                    started,
                    completed_date,
                    saved_total_deaths,
                    death_count_legacy,
                    str(notes),
                    int(record_id),
                ),
            )

    def remove_tracked(
        self,
        record_id: int,
    ) -> None:
        self.initialize()

        with self.connect() as connection:
            connection.execute(
                "DELETE FROM tracked_hacks WHERE id = ?",
                (int(record_id),),
            )

    def list_custom(self) -> list[dict[str, Any]]:
        self.initialize()

        with self.connect() as connection:
            rows = connection.execute(
                """
                SELECT *
                FROM catalog_hacks
                WHERE is_custom = 1
                ORDER BY title COLLATE NOCASE
                """
            ).fetchall()

        return [dict(row) for row in rows]

    def save_custom(
        self,
        record: dict[str, Any],
    ) -> str:
        self.initialize()
        prepared = dict(record)
        prepared["is_custom"] = True
        prepared["smwc_rating"] = prepared.get(
            "smwc_rating",
            prepared.get("rating"),
        )

        with self.connect() as connection:
            catalog_key = self._upsert_catalog(
                connection,
                prepared,
            )
            row = connection.execute(
                """
                SELECT *
                FROM catalog_hacks
                WHERE catalog_key = ?
                """,
                (catalog_key,),
            ).fetchone()
            connection.execute(
                """
                UPDATE tracked_hacks
                SET
                    title = ?,
                    author = ?,
                    total_exits = ?,
                    difficulty = ?,
                    hack_type = ?,
                    smwc_rating = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE catalog_key = ?
                """,
                (
                    str(row["title"]),
                    str(row["author"]),
                    int(row["total_exits"] or 0),
                    str(row["difficulty"]),
                    str(row["hack_type"]),
                    row["smwc_rating"],
                    catalog_key,
                ),
            )
            return catalog_key

    def delete_custom(
        self,
        catalog_key: str,
    ) -> None:
        self.initialize()

        with self.connect() as connection:
            connection.execute(
                """
                DELETE FROM catalog_hacks
                WHERE catalog_key = ?
                  AND is_custom = 1
                """,
                (str(catalog_key),),
            )

    def update_catalog_rom_path(
        self,
        smwc_id: str,
        title: str,
        rom_path: str,
        local: bool = False,
    ) -> None:
        self.initialize()
        normalized_id = self._normalize_smwc_id(
            smwc_id
        )
        normalized = normalize_title(title)
        column_name = (
            "local_rom_path"
            if local
            else "rom_path"
        )

        with self.connect() as connection:
            if normalized_id:
                connection.execute(
                    f"""
                    UPDATE catalog_hacks
                    SET {column_name} = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE smwc_id = ?
                    """,
                    (
                        str(rom_path),
                        normalized_id,
                    ),
                )
            elif normalized:
                connection.execute(
                    f"""
                    UPDATE catalog_hacks
                    SET {column_name} = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE normalized_title = ?
                    """,
                    (
                        str(rom_path),
                        normalized,
                    ),
                )

    def save_rom_mapping(
        self,
        game: dict[str, Any],
        rom_path: str,
        device: str = "FXPAK Pro",
        match_method: str = "saved mapping",
    ) -> None:
        self.initialize()
        smwc_id = self._normalize_smwc_id(
            game.get("smwc_id")
        )
        title = str(
            game.get("title")
            or ""
        ).strip()
        catalog_key = str(
            game.get("catalog_key")
            or self.catalog_key(
                smwc_id,
                title,
            )
        )
        # SMW Central IDs are permanent even when the catalog title contains
        # emoji and the FXPAK-only filename has to use a readable alias.
        # Always make the ID the canonical mapping key when one is available.
        map_key = (
            "SMWC:" + smwc_id
            if smwc_id
            else str(
                game.get("mapping_key")
                or "TITLE:" + title.casefold().strip()
            )
        )

        with self.connect() as connection:
            connection.execute(
                """
                INSERT INTO rom_mappings (
                    map_key,
                    catalog_key,
                    title,
                    smwc_id,
                    rom_path,
                    last_launched,
                    device,
                    match_method,
                    updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                ON CONFLICT(map_key) DO UPDATE SET
                    catalog_key = excluded.catalog_key,
                    title = excluded.title,
                    smwc_id = excluded.smwc_id,
                    rom_path = excluded.rom_path,
                    last_launched = excluded.last_launched,
                    device = excluded.device,
                    match_method = excluded.match_method,
                    updated_at = CURRENT_TIMESTAMP
                """,
                (
                    map_key,
                    catalog_key,
                    title,
                    smwc_id,
                    str(rom_path),
                    datetime.now().isoformat(
                        timespec="seconds"
                    ),
                    str(device),
                    str(match_method),
                ),
            )
            if smwc_id:
                connection.execute(
                    """
                    UPDATE catalog_hacks
                    SET rom_path = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE smwc_id = ?
                    """,
                    (str(rom_path), smwc_id),
                )
            else:
                connection.execute(
                    """
                    UPDATE catalog_hacks
                    SET rom_path = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE catalog_key = ?
                    """,
                    (str(rom_path), catalog_key),
                )

    def clear_remote_rom_paths(
        self,
        rom_paths: list[str],
    ) -> None:
        """Forget only FXPAK paths that were removed from the SD card."""

        def normalize_remote_path(value: object) -> str:
            normalized = re.sub(
                r"/+",
                "/",
                str(value or "").replace("\\", "/"),
            ).rstrip("/")
            if normalized and not normalized.startswith("/"):
                normalized = "/" + normalized
            return normalized.casefold()

        normalized_paths = {
            normalize_remote_path(path)
            for path in rom_paths
            if str(path).strip()
        }
        if not normalized_paths:
            return

        self.initialize()
        with self.connect() as connection:
            catalog_rows = connection.execute(
                """
                SELECT catalog_key, rom_path
                FROM catalog_hacks
                WHERE rom_path <> ''
                """
            ).fetchall()
            for row in catalog_rows:
                normalized = normalize_remote_path(row["rom_path"])
                if normalized in normalized_paths:
                    connection.execute(
                        """
                        UPDATE catalog_hacks
                        SET rom_path = '', updated_at = CURRENT_TIMESTAMP
                        WHERE catalog_key = ?
                        """,
                        (str(row["catalog_key"]),),
                    )

            mapping_rows = connection.execute(
                """
                SELECT map_key, rom_path
                FROM rom_mappings
                WHERE rom_path <> ''
                """
            ).fetchall()
            for row in mapping_rows:
                normalized = normalize_remote_path(row["rom_path"])
                if normalized in normalized_paths:
                    connection.execute(
                        "DELETE FROM rom_mappings WHERE map_key = ?",
                        (str(row["map_key"]),),
                    )

    def _tracker_export_data(
        self,
    ) -> tuple[
        tuple[str, ...],
        list[dict[str, Any]],
    ]:
        rows = self.list_tracked()
        fieldnames = (
            "Hack #",
            "ROM Hack Title",
            "Created By",
            "Exits",
            "Difficulty",
            "Type",
            "SMWCentral Rating",
            "Date Started",
            "Date Completed",
            "Completed Exits",
            "Total Deaths",
            "Status",
            "Rating (1-5)",
            "Playtime Seconds",
            "Playtime",
            "SMWCentral Page",
            "Download Patch",
            "Notes",
        )
        export_rows: list[dict[str, Any]] = []

        for index, row in enumerate(
            rows,
            start=1,
        ):
            export_rows.append(
                {
                    "Hack #": row.get(
                        "display_order"
                    ) or index,
                    "ROM Hack Title": row["title"],
                    "Created By": row["author"],
                    "Exits": row["total_exits"],
                    "Difficulty": row["difficulty"],
                    "Type": row["hack_type"],
                    "SMWCentral Rating": row[
                        "smwc_rating"
                    ],
                    "Date Started": row[
                        "date_started"
                    ],
                    "Date Completed": row[
                        "date_completed"
                    ],
                    "Completed Exits": (
                        str(row["completed_exits"])
                        + "/"
                        + str(row["total_exits"])
                    ),
                    "Total Deaths": (
                        "*"
                        if bool(row.get("death_count_legacy"))
                        and row.get("total_deaths") is None
                        else (
                            row.get("total_deaths")
                            if row.get("total_deaths") is not None
                            else ""
                        )
                    ),
                    "Status": row["status"],
                    "Rating (1-5)": row[
                        "personal_rating"
                    ],
                    "Playtime Seconds": row[
                        "playtime_seconds"
                    ],
                    "Playtime": format_timer(
                        int(
                            row["playtime_seconds"]
                            or 0
                        ),
                        False,
                    ),
                    "SMWCentral Page": row[
                        "page_url"
                    ],
                    "Download Patch": row[
                        "download_url"
                    ],
                    "Notes": row["notes"],
                }
            )

        return fieldnames, export_rows

    def export_tracker_csv(
        self,
        destination: Path,
    ) -> None:
        fieldnames, export_rows = (
            self._tracker_export_data()
        )

        with Path(destination).open(
            "w",
            encoding="utf-8-sig",
            newline="",
        ) as output_file:
            writer = csv.DictWriter(
                output_file,
                fieldnames=fieldnames,
            )
            writer.writeheader()

            writer.writerows(export_rows)

    def export_tracker_xlsx(
        self,
        destination: Path,
    ) -> None:
        fieldnames, export_rows = (
            self._tracker_export_data()
        )
        workbook = Workbook()
        worksheet = workbook.active
        worksheet.title = "My Tracker"
        worksheet.freeze_panes = "A2"
        worksheet.sheet_view.showGridLines = False
        worksheet.append(list(fieldnames))

        header_fill = PatternFill(
            fill_type="solid",
            fgColor="0F4C97",
        )
        even_fill = PatternFill(
            fill_type="solid",
            fgColor="EAF2FB",
        )
        odd_fill = PatternFill(
            fill_type="solid",
            fgColor="FFFFFF",
        )

        for cell in worksheet[1]:
            cell.fill = header_fill
            cell.font = Font(
                color="FFFFFF",
                bold=True,
            )
            cell.alignment = Alignment(
                horizontal="center",
                vertical="center",
            )
        worksheet.row_dimensions[1].height = 24

        for row_number, export_row in enumerate(
            export_rows,
            start=2,
        ):
            worksheet.append(
                [
                    export_row.get(fieldname, "")
                    for fieldname in fieldnames
                ]
            )
            row_fill = (
                even_fill
                if row_number % 2 == 0
                else odd_fill
            )
            for cell in worksheet[row_number]:
                cell.fill = row_fill
                cell.alignment = Alignment(
                    vertical="top",
                )

        for column_number, fieldname in enumerate(
            fieldnames,
            start=1,
        ):
            values = [
                fieldname,
                *(
                    str(row.get(fieldname, "") or "")
                    for row in export_rows
                ),
            ]
            width = min(
                52,
                max(
                    10,
                    max(len(value) for value in values) + 2,
                ),
            )
            worksheet.column_dimensions[
                get_column_letter(column_number)
            ].width = width

        worksheet.auto_filter.ref = (
            f"A1:{get_column_letter(len(fieldnames))}"
            f"{max(1, len(export_rows) + 1)}"
        )

        for hyperlink_column in (
            "SMWCentral Page",
            "Download Patch",
        ):
            column_number = (
                fieldnames.index(hyperlink_column)
                + 1
            )
            for row_number in range(
                2,
                len(export_rows) + 2,
            ):
                cell = worksheet.cell(
                    row=row_number,
                    column=column_number,
                )
                url = str(cell.value or "").strip()
                if url:
                    cell.hyperlink = url
                    cell.font = Font(
                        color="0563C1",
                        underline="single",
                    )

        try:
            workbook.save(Path(destination))
        finally:
            workbook.close()

    def backup_to(
        self,
        destination: Path,
    ) -> None:
        self.initialize()
        destination = Path(destination)
        destination.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        if destination.exists():
            destination.unlink()

        with self.connect() as source_connection:
            target_connection = sqlite3.connect(
                destination
            )

            try:
                source_connection.backup(
                    target_connection
                )
            finally:
                target_connection.close()

    def restore_from(
        self,
        source: Path,
    ) -> None:
        source = Path(source)

        if not source.exists():
            raise FileNotFoundError(source)

        source_connection = sqlite3.connect(
            source
        )

        try:
            table = source_connection.execute(
                """
                SELECT name
                FROM sqlite_master
                WHERE type = 'table'
                  AND name = 'catalog_hacks'
                """
            ).fetchone()

            if table is None:
                raise RuntimeError(
                    "The selected file is not an SMW Stream Tracker database backup."
                )

            with self.connect() as destination_connection:
                source_connection.backup(
                    destination_connection
                )
        finally:
            source_connection.close()

        self.initialize()




GOOGLE_SHEETS_AUTOSYNC_DELAY_MS = 1800

# Paste this into Extensions > Apps Script from the Google Sheet that will
# receive the tracker mirror, then deploy it as a Web App. The local SQLite
# database remains the source of truth; Google Sheets is a synchronized copy.
GOOGLE_SHEETS_APPS_SCRIPT = r"""function doPost(e) {
  try {
    const payload = JSON.parse(e.postData.contents || '{}');
    const spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
    if (!spreadsheet) {
      throw new Error('This Apps Script must be bound to a Google Sheet.');
    }

    const baseName = String(payload.sheet_base_name || 'SMW Stream Tracker').trim();
    writeTrackerSheet_(spreadsheet, baseName + ' - Tracker', payload.tracker || []);
    writeStatsSheet_(spreadsheet, baseName + ' - Stats', payload.overview || {}, payload.generated_at || '');

    return ContentService
      .createTextOutput(JSON.stringify({ok: true, rows: (payload.tracker || []).length}))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (error) {
    return ContentService
      .createTextOutput(JSON.stringify({ok: false, error: String(error)}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function getOrCreateSheet_(spreadsheet, name) {
  return spreadsheet.getSheetByName(name) || spreadsheet.insertSheet(name);
}

function resetSheet_(sheet) {
  sheet.clear();
  sheet.clearConditionalFormatRules();
  sheet.setFrozenRows(1);
}

function writeTrackerSheet_(spreadsheet, name, tracker) {
  const sheet = getOrCreateSheet_(spreadsheet, name);
  resetSheet_(sheet);

  const headers = [
    'Hack #', 'ROM Hack Title', 'Created By', 'Total Exits',
    'Completed Exits', 'Percentage Complete', 'Status', 'Difficulty',
    'Type', 'SMWCentral Rating', 'My Rating', 'Playtime',
    'Date Started', 'Date Completed', 'Notes', 'SMWCentral Page'
  ];

  const rows = tracker.map((item, index) => [
    item.display_order || index + 1,
    item.title || '',
    item.author || '',
    Number(item.total_exits || 0),
    Number(item.completed_exits || 0),
    Number(item.percentage_complete || 0) / 100,
    item.status || '',
    item.difficulty || '',
    item.hack_type || '',
    item.smwc_rating === null || item.smwc_rating === undefined ? '' : Number(item.smwc_rating),
    item.personal_rating === null || item.personal_rating === undefined ? '' : Number(item.personal_rating),
    item.playtime || '',
    item.date_started || '',
    item.date_completed || '',
    item.notes || '',
    item.page_url || ''
  ]);

  sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
  if (rows.length) {
    sheet.getRange(2, 1, rows.length, headers.length).setValues(rows);
    sheet.getRange(2, 6, rows.length, 1).setNumberFormat('0%');
    sheet.getRange(2, 10, rows.length, 2).setNumberFormat('0.00');
    applyDifficultyColors_(sheet, rows);
  }

  const header = sheet.getRange(1, 1, 1, headers.length);
  header.setBackground('#073B86').setFontColor('#FFFFFF').setFontWeight('bold');
  header.setHorizontalAlignment('center');
  sheet.getDataRange().setVerticalAlignment('middle');
  sheet.getDataRange().setWrap(true);
  sheet.autoResizeColumns(1, headers.length);
  sheet.setColumnWidth(2, 260);
  sheet.setColumnWidth(3, 150);
  sheet.setColumnWidth(15, 260);
  sheet.setColumnWidth(16, 190);
}

function applyDifficultyColors_(sheet, rows) {
  const colors = {
    'Newcomer': ['#E2F0D9', '#2E5D2E'],
    'Casual': ['#DDEBF7', '#1F4E78'],
    'Intermediate': ['#D9EAD3', '#376237'],
    'Advanced': ['#FFF2CC', '#7F6000'],
    'Expert': ['#FCE4D6', '#9C3D10'],
    'Master': ['#E4DFEC', '#5F497A'],
    'Grandmaster': ['#F4CCCC', '#9C0006'],
    'Unranked': ['#E7E6E6', '#595959'],
    'Unknown': ['#E7E6E6', '#595959']
  };

  rows.forEach((row, index) => {
    const difficulty = String(row[7] || 'Unknown');
    const style = colors[difficulty] || colors.Unknown;
    sheet.getRange(index + 2, 8).setBackground(style[0]).setFontColor(style[1]).setFontWeight('bold');
  });
}

function writeStatsSheet_(spreadsheet, name, overview, generatedAt) {
  const sheet = getOrCreateSheet_(spreadsheet, name);
  resetSheet_(sheet);

  const rows = [
    ['SMW Stream Tracker Statistics', ''],
    ['Last synchronized', generatedAt],
    ['Official hacks', overview.official || 0],
    ['Tracked hacks', overview.tracked || 0],
    ['Completed hacks', overview.completed || 0],
    ['In-progress hacks', overview.in_progress || 0],
    ['Planned hacks', overview.planned || 0],
    ['Overall completion', Number(overview.completion_percent || 0) / 100],
    ['Completed exits', overview.completed_exits || 0],
    ['Total tracked exits', overview.total_exits || 0],
    ['Average personal rating', overview.average_rating || 0],
    ['Total playtime', overview.playtime || '00:00'],
    ['Custom hacks', overview.custom || 0]
  ];

  sheet.getRange(1, 1, rows.length, 2).setValues(rows);
  sheet.getRange('A1:B1').setBackground('#35A936').setFontColor('#FFFFFF').setFontWeight('bold');
  sheet.getRange(8, 2).setNumberFormat('0%');
  sheet.getRange(11, 2).setNumberFormat('0.00');
  sheet.getRange(2, 1, rows.length - 1, 1).setFontWeight('bold');
  sheet.setColumnWidth(1, 220);
  sheet.setColumnWidth(2, 190);
}
"""

