def blend_hex_colors(
    start_color: str,
    end_color: str,
    fraction: float,
) -> str:
    fraction = max(
        0.0,
        min(1.0, float(fraction)),
    )

    def components(color: str) -> tuple[int, int, int]:
        cleaned = color.lstrip("#")
        return (
            int(cleaned[0:2], 16),
            int(cleaned[2:4], 16),
            int(cleaned[4:6], 16),
        )

    start = components(start_color)
    end = components(end_color)
    mixed = tuple(
        round(
            start[index]
            + (end[index] - start[index])
            * fraction
        )
        for index in range(3)
    )
    return "#" + "".join(
        f"{component:02X}"
        for component in mixed
    )

