def normalize_title(value: object) -> str:
    text = str(value or "").casefold().strip()
    text = text.replace("&", " and ")
    return re.sub(r"[^a-z0-9]+", "", text)


def remove_fxpak_timestamp(filename: str) -> str:
    return re.sub(
        r"\s*\(\d{4}_\d{2}_\d{2}\s+"
        r"\d{2}_\d{2}_\d{2}\s+UTC\)\s*$",
        "",
        filename,
        flags=re.IGNORECASE,
    ).strip()


def remove_trailing_version(filename: str) -> str:
    patterns = [
        r"\s+v(?:er(?:sion)?)?[\s._-]*\d+(?:[\s._-]*\d+)*$",
        r"\s+version[\s._-]*\d+(?:[\s._-]*\d+)*$",
        r"\s+rev(?:ision)?[\s._-]*\d+(?:[\s._-]*\d+)*$",
        r"\s+\(\s*v\d+(?:[._-]\d+)*\s*\)$",
        r"\s+\[\s*v\d+(?:[._-]\d+)*\s*\]$",
        r"\s+(?:final|fixed|updated|update)$",
    ]

    cleaned = filename.strip()
    changed = True

    while changed:
        changed = False

        for pattern in patterns:
            updated = re.sub(
                pattern,
                "",
                cleaned,
                flags=re.IGNORECASE,
            ).strip()

            if updated != cleaned:
                cleaned = updated
                changed = True

    return cleaned


def clean_rom_filename(rom_path: str) -> str:
    filename = PurePosixPath(str(rom_path).replace("\\", "/")).stem
    filename = remove_fxpak_timestamp(filename)
    filename = remove_trailing_version(filename)
    return filename.strip()


def format_timer(seconds: float, milliseconds: bool = False) -> str:
    total_seconds = max(0, int(seconds))
    hours, remainder = divmod(total_seconds, 3600)
    minutes, secs = divmod(remainder, 60)

    if hours:
        return f"{hours}:{minutes:02d}:{secs:02d}"
    if minutes:
        return f"{minutes:02d}:{secs:02d}"
    return f"00:{secs:02d}"


def timer_grace_seconds(config: dict[str, Any]) -> int:
    """Return the interruption grace, including legacy-config support."""
    raw_value = config.get(
        "timer_grace_seconds",
        config.get("overworld_idle_seconds", 30),
    )
    try:
        return max(0, int(raw_value))
    except (TypeError, ValueError):
        return 30


def windows_foreground_executable_name() -> str | None:
    """Return the foreground Windows process name without extra packages.

    ``None`` means that Windows did not provide a reliable answer.  Callers
    deliberately treat that as "unknown" instead of "not focused" so a
    transient Win32 lookup failure can never pause somebody's timers.
    """
    if os.name != "nt":
        return None

    process_handle = None
    try:
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        user32.GetForegroundWindow.restype = ctypes.c_void_p
        user32.GetWindowThreadProcessId.argtypes = [
            ctypes.c_void_p,
            ctypes.POINTER(ctypes.c_ulong),
        ]
        kernel32.OpenProcess.argtypes = [
            ctypes.c_ulong,
            ctypes.c_int,
            ctypes.c_ulong,
        ]
        kernel32.OpenProcess.restype = ctypes.c_void_p
        kernel32.QueryFullProcessImageNameW.argtypes = [
            ctypes.c_void_p,
            ctypes.c_ulong,
            ctypes.c_wchar_p,
            ctypes.POINTER(ctypes.c_ulong),
        ]
        kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
        foreground_window = user32.GetForegroundWindow()
        if not foreground_window:
            return None

        process_id = ctypes.c_ulong(0)
        user32.GetWindowThreadProcessId(
            foreground_window,
            ctypes.byref(process_id),
        )
        if not process_id.value:
            return None

        process_handle = kernel32.OpenProcess(
            0x1000,  # PROCESS_QUERY_LIMITED_INFORMATION
            False,
            process_id.value,
        )
        if not process_handle:
            return None

        executable_path = ctypes.create_unicode_buffer(32768)
        path_length = ctypes.c_ulong(len(executable_path))
        if not kernel32.QueryFullProcessImageNameW(
            process_handle,
            0,
            executable_path,
            ctypes.byref(path_length),
        ):
            return None
        return Path(executable_path.value).name.casefold()
    except (AttributeError, OSError, ValueError):
        return None
    finally:
        if process_handle:
            try:
                ctypes.windll.kernel32.CloseHandle(process_handle)
            except (AttributeError, OSError):
                pass


def render_obs_text_template(
    template: object,
    default_template: str,
    **values: object,
) -> str:
    selected_template = (
        str(template)
        if template is not None
        else default_template
    )
    try:
        return selected_template.format(**values)
    except (KeyError, ValueError, AttributeError, IndexError):
        return default_template.format(**values)


def ensure_obs_text_files(
    config: dict[str, Any],
) -> Path | None:
    folder_text = str(config.get("output_folder", "")).strip()
    if not folder_text:
        return None

    output_folder = Path(folder_text)
    output_folder.mkdir(parents=True, exist_ok=True)
    try:
        APP_DATA_DIR.mkdir(parents=True, exist_ok=True)
        UNINSTALL_OBS_PATH_FILE.write_text(
            str(output_folder.resolve()),
            encoding="utf-8",
        )
    except OSError:
        # This bookkeeping file lets the Windows uninstaller remove only the
        # tracker-created OBS files without ever deleting the user's folder.
        # OBS output must continue working even when bookkeeping is blocked.
        pass
    defaults = {
        "author.txt": render_obs_text_template(
            config.get("obs_author_text_format"),
            "By: {author}",
            author="Unknown",
        ),
        "exits.txt": render_obs_text_template(
            config.get("obs_exits_text_format"),
            "Exits: {completed} / {total}",
            completed=0,
            total="Unknown",
        ),
        "level_deaths.txt": render_obs_text_template(
            config.get("obs_deaths_text_format"),
            "Level Deaths: {deaths}",
            deaths=0,
        ),
        # Keep the original filename as a mirror of Level Deaths so existing
        # OBS and Streamlabs scenes continue working after this update.
        "death_counter.txt": render_obs_text_template(
            config.get("obs_deaths_text_format"),
            "Level Deaths: {deaths}",
            deaths=0,
        ),
        "total_deaths.txt": render_obs_text_template(
            config.get("obs_total_deaths_text_format"),
            "Total Deaths: {total_deaths}",
            total_deaths=0,
        ),
        "hack_name.txt": "No game detected",
        "level_timer.txt": "00:00",
        "game_timer.txt": "00:00",
    }
    for filename, initial_text in defaults.items():
        file_path = output_folder / filename
        if not file_path.exists():
            file_path.write_text(initial_text, encoding="utf-8")
    return output_folder


def load_config() -> dict[str, Any]:
    config = DEFAULT_CONFIG.copy()
    saved: dict[str, Any] = {}

    if CONFIG_FILE.exists():
        try:
            saved = json.loads(
                CONFIG_FILE.read_text(encoding="utf-8")
            )

            for key in config:
                if key in saved:
                    config[key] = saved[key]

        except (OSError, json.JSONDecodeError):
            pass

    # Do not surprise established users with the new welcome page after an
    # update.  A completed legacy first-run health check is treated as an
    # already completed welcome flow; genuinely new installs still see it.
    if "first_launch_welcome_completed" not in saved:
        config["first_launch_welcome_completed"] = bool(
            saved.get("first_run_health_check_completed", False)
        )

    # Migrate the original overworld-only grace setting without changing a
    # user's saved value. Newer builds use the same grace anywhere gameplay
    # is temporarily interrupted inside a hack.
    if "timer_grace_seconds" not in saved:
        config["timer_grace_seconds"] = config.get(
            "overworld_idle_seconds",
            30,
        )
    config["overworld_idle_seconds"] = config.get(
        "timer_grace_seconds",
        30,
    )

    # Existing installations can retain the manifest address from the former
    # repository in their saved configuration. GitHub correctly returns 404
    # for that retired path, so migrate only the known legacy value while
    # leaving deliberate custom update feeds untouched.
    if str(config.get("update_manifest_url", "")).strip() in (
        LEGACY_UPDATE_MANIFEST_URLS
    ):
        config["update_manifest_url"] = DEFAULT_UPDATE_MANIFEST_URL

    # Installer-provided tools live beside the frozen executable. Discover
    # them automatically so a new install works even if the wizard's default
    # path changes slightly between third-party releases.
    if getattr(sys, "frozen", False):
        application_directory = Path(sys.executable).resolve().parent
    else:
        application_directory = Path(__file__).resolve().parent

    # Versions before the full UI localization update saved the selected
    # installer guide but not the language itself.  Recover that choice from
    # the installed README once, so existing non-English installations do not
    # silently fall back to an English interface after updating.
    if "app_language" not in saved:
        installed_readme = application_directory / "README.txt"
        try:
            readme_sample = installed_readme.read_text(
                encoding="utf-8-sig"
            )[:2500].casefold()
        except OSError:
            readme_sample = ""
        language_markers = (
            ("es", ("guía completa", "configuración inicial")),
            ("fr", ("guide complet", "configuration initiale")),
            ("de", ("vollständige", "erste einrichtung")),
            ("pt-BR", ("guia completo", "configuração inicial")),
            ("au", ("g'day", "first cab off the rank", "bits and bobs")),
        )
        for language_code, markers in language_markers:
            if any(marker in readme_sample for marker in markers):
                config["app_language"] = language_code
                break

    # Older versions stored SNI and QUsb2Snes in one shared field. Split that
    # value by executable name, then discover and retain both tools
    # independently so either service can be selected or used as a fallback.
    legacy_interface_text = str(
        config.get("platform_interface_path", "")
    ).strip()
    saved_sni_text = str(config.get("sni_path", "")).strip()
    saved_qusb_text = str(config.get("qusb2snes_path", "")).strip()
    if connection_service_kind(saved_qusb_text) == "SNI":
        if not saved_sni_text:
            saved_sni_text = saved_qusb_text
        saved_qusb_text = ""
    legacy_service = connection_service_kind(legacy_interface_text)
    if legacy_service == "SNI" and not saved_sni_text:
        saved_sni_text = legacy_interface_text
    elif legacy_service == "QUsb2Snes" and not saved_qusb_text:
        saved_qusb_text = legacy_interface_text

    local_app_data = Path(os.environ.get("LOCALAPPDATA", ""))

    def discover_connection_service(
        configured_text: str,
        executable_names: tuple[str, ...],
        candidates: tuple[Path, ...],
        search_roots: tuple[Path, ...],
    ) -> str:
        configured_path = Path(configured_text)
        if (
            configured_text
            and configured_path.is_file()
            and configured_path.name.casefold()
            in {name.casefold() for name in executable_names}
        ):
            return str(configured_path)
        for candidate in candidates:
            if candidate.is_file():
                return str(candidate)
        for search_root in search_roots:
            if not search_root.is_dir():
                continue
            try:
                for executable_name in executable_names:
                    match = next(
                        (
                            candidate
                            for candidate in search_root.rglob(executable_name)
                            if candidate.is_file()
                        ),
                        None,
                    )
                    if match is not None:
                        return str(match)
            except StopIteration:
                continue
        return configured_text

    user_applications = Path.home() / "Applications"
    system_applications = Path("/Applications")
    sni_names = ("sni.exe",) if IS_WINDOWS else ("sni",)
    qusb_names = (
        ("QUsb2Snes.exe",)
        if IS_WINDOWS
        else ("QUsb2Snes", "qusb2snes")
    )

    sni_text = discover_connection_service(
        saved_sni_text,
        sni_names,
        (
            application_directory / "Tools" / "SNI" / "sni.exe",
            APP_DATA_DIR / "Tools" / "SNI" / "sni.exe",
            local_app_data / "Programs" / "SNI" / "sni.exe",
            application_directory / "Tools" / "SNI" / "sni",
            APP_DATA_DIR / "Tools" / "SNI" / "sni",
        ),
        (
            application_directory / "Tools" / "SNI",
            APP_DATA_DIR / "Tools" / "SNI",
        ),
    )
    qusb_text = discover_connection_service(
        saved_qusb_text,
        qusb_names,
        (
            application_directory
            / "Tools"
            / "QUsb2Snes"
            / "QUsb2Snes.exe",
            APP_DATA_DIR / "Tools" / "QUsb2Snes" / "QUsb2Snes.exe",
            local_app_data
            / "Programs"
            / "QUsb2Snes"
            / "QUsb2Snes.exe",
            APP_DATA_DIR
            / "Tools"
            / "QUsb2Snes"
            / "QUsb2Snes.app"
            / "Contents"
            / "MacOS"
            / "QUsb2Snes",
            user_applications
            / "QUsb2Snes.app"
            / "Contents"
            / "MacOS"
            / "QUsb2Snes",
            system_applications
            / "QUsb2Snes.app"
            / "Contents"
            / "MacOS"
            / "QUsb2Snes",
        ),
        (
            application_directory / "Tools" / "QUsb2Snes",
            APP_DATA_DIR / "Tools" / "QUsb2Snes",
        ),
    )
    config["sni_path"] = sni_text
    config["qusb2snes_path"] = qusb_text
    preference = str(
        config.get("connection_service_preference", "Automatic")
    ).strip()
    if preference not in {"Automatic", "SNI", "QUsb2Snes"}:
        preference = "Automatic"
    config["connection_service_preference"] = preference
    if preference == "QUsb2Snes":
        config["platform_interface_path"] = qusb_text or sni_text
    else:
        config["platform_interface_path"] = sni_text or qusb_text

    retroarch_text = str(
        config.get("retroarch_executable_path", "")
    ).strip()
    if not retroarch_text or not Path(retroarch_text).is_file():
        retroarch_candidates = [
            Path("C:/RetroArch-Win64/retroarch.exe"),
            APP_DATA_DIR
            / "Tools"
            / "RetroArch"
            / "retroarch.exe",
            Path(os.environ.get("PROGRAMFILES", "C:/Program Files"))
            / "RetroArch-Win64"
            / "retroarch.exe",
            Path(os.environ.get("LOCALAPPDATA", ""))
            / "Programs"
            / "RetroArch"
            / "retroarch.exe",
            Path(os.environ.get("APPDATA", ""))
            / "RetroArch"
            / "retroarch.exe",
            APP_DATA_DIR
            / "Tools"
            / "RetroArch"
            / "RetroArch.app"
            / "Contents"
            / "MacOS"
            / "RetroArch",
            user_applications
            / "RetroArch.app"
            / "Contents"
            / "MacOS"
            / "RetroArch",
            system_applications
            / "RetroArch.app"
            / "Contents"
            / "MacOS"
            / "RetroArch",
        ]
        path_retroarch = shutil.which("retroarch")
        if path_retroarch:
            retroarch_candidates.append(Path(path_retroarch))
        for retroarch_candidate in retroarch_candidates:
            if retroarch_candidate.is_file():
                retroarch_text = str(retroarch_candidate)
                config["retroarch_executable_path"] = retroarch_text
                break

    core_text = str(
        config.get("retroarch_core_path", "")
    ).strip()
    if (
        retroarch_text
        and (not core_text or not Path(core_text).is_file())
    ):
        core_directory = retroarch_core_directory(Path(retroarch_text))
        core_extension = (
            ".dll" if IS_WINDOWS else ".dylib" if IS_MACOS else ".so"
        )
        core_candidates = tuple(
            core_directory / (core_name + core_extension)
            for core_name in (
                "bsnes_mercury_performance_libretro",
                "bsnes_mercury_balanced_libretro",
                "bsnes_mercury_accuracy_libretro",
                "snes9x_libretro",
                "snes9x2010_libretro",
                "bsnes_libretro",
            )
        )
        for core_candidate in core_candidates:
            if core_candidate.is_file():
                config["retroarch_core_path"] = str(core_candidate)
                break

    # SNI's RetroArch driver exposes bsnes-mercury sessions, while the older
    # Earlier installers could supply Snes9x. Prefer the updater-installed compatible
    # core for existing SNI + RetroArch users without changing QUsb2Snes users'
    # explicitly selected cores.
    selected_platform = str(
        config.get("selected_platform", "FXPAK Pro")
    ).strip()
    interface_name = normalized_executable_name(
        str(config.get("platform_interface_path", ""))
    )
    configured_core_name = Path(
        str(config.get("retroarch_core_path", ""))
    ).name.casefold()
    bundled_mercury_core = (
        application_directory
        / "Tools"
        / "RetroArch"
        / "cores"
        / retroarch_core_filename()
    )
    if (
        selected_platform == "RetroArch"
        and interface_name == "sni"
        and configured_core_name.startswith("snes9x")
        and bundled_mercury_core.is_file()
    ):
        config["retroarch_core_path"] = str(bundled_mercury_core)

    return config


def save_config(config: dict[str, Any]) -> None:
    CONFIG_FILE.write_text(
        json.dumps(config, indent=2),
        encoding="utf-8",
    )
    output_folder = str(config.get("output_folder", "")).strip()
    if output_folder:
        try:
            APP_DATA_DIR.mkdir(parents=True, exist_ok=True)
            UNINSTALL_OBS_PATH_FILE.write_text(
                str(Path(output_folder).resolve()),
                encoding="utf-8",
            )
        except OSError:
            pass


def is_transient_connection_error(error: object) -> bool:
    """Return True for bridge/socket errors that the tracker can reconnect from."""
    message = str(error or "").strip().casefold()
    if not message:
        return False
    transient_phrases = (
        "connection to remote host was lost",
        "connection was forcibly closed",
        "connection reset by peer",
        "connection aborted",
        "broken pipe",
        "websocket connection is closed",
        "socket is already closed",
        "timed out",
        "winerror 10053",
        "winerror 10054",
    )
    return any(phrase in message for phrase in transient_phrases)


def connection_loss_needs_user_attention(
    error: object,
    last_successful_sample_at: float,
    now: float,
    grace_seconds: float = 15.0,
) -> bool:
    """Hide brief recoverable bridge drops while live samples are recent."""
    if not is_transient_connection_error(error):
        return True
    if last_successful_sample_at <= 0:
        return True
    return now - last_successful_sample_at >= max(0.0, grace_seconds)


def connection_service_candidates(
    config: dict[str, Any],
) -> list[tuple[str, str]]:
    """Return both configured SNES bridges in the requested fallback order."""
    configured = [
        ("SNI", str(config.get("sni_path", "")).strip()),
        (
            "QUsb2Snes",
            str(config.get("qusb2snes_path", "")).strip(),
        ),
    ]
    preference = str(
        config.get("connection_service_preference", "Automatic")
    ).strip()
    if preference == "QUsb2Snes":
        configured.reverse()

    legacy_path = str(
        config.get("platform_interface_path", "")
    ).strip()
    if legacy_path:
        legacy_service = connection_service_kind(legacy_path)
        if legacy_service and all(
            Path(path).resolve() != Path(legacy_path).resolve()
            for _, path in configured
            if path
        ):
            configured.append((legacy_service, legacy_path))
    return [(service, path) for service, path in configured if path]


def preferred_connection_service_path(config: dict[str, Any]) -> str:
    candidates = connection_service_candidates(config)
    return candidates[0][1] if candidates else ""


def livesplit_endpoint(
    config: dict[str, Any],
    timer: str,
) -> tuple[str, int]:
    timer_name = "game" if timer == "game" else "level"
    port_key = f"{timer_name}_livesplit_port"
    default_port = 16834 if timer_name == "game" else 16835
    host = str(config.get("livesplit_host", "127.0.0.1")).strip()
    return host or "127.0.0.1", int(config.get(port_key, default_port))


def livesplit_server_is_running(
    config: dict[str, Any],
    timer: str,
    timeout: float = 0.18,
) -> bool:
    """Check a LiveSplit server without sending it timer information."""
    try:
        endpoint = livesplit_endpoint(config, timer)
        with socket.create_connection(endpoint, timeout=timeout):
            return True
    except (OSError, TypeError, ValueError):
        return False


class TrackerWorker:
    def __init__(
        self,
        config: dict[str, Any],
        event_queue: queue.Queue,
    ) -> None:
        self.config = config
        self.event_queue = event_queue
        self.stop_event = threading.Event()
        self.thread: threading.Thread | None = None

        self.command_queue: queue.Queue[str] = queue.Queue()

        self.game_started = False
        self.game_finished = False
        self.game_elapsed = 0.0
        self.overworld_entered_at: float | None = None

        self.level_id: int | None = None
        self.level_elapsed = 0.0
        self.level_finished = False

        self.previous_mode: int | None = None
        self.previous_exit_count: int | None = None
        self.displayed_exit_count: int | None = None
        self.provisional_goal_exit = False
        self.provisional_goal_base_exit_count: int | None = None
        self.pending_goal_route: tuple[str, int, str] | None = None
        self.authoritative_exit_count: int | None = None
        self.previous_rom_path: str | None = None
        self.timers_paused = False
        self.game_manual_paused = False
        self.level_manual_paused = False
        self.pause_combo_was_pressed = False
        self.level_livesplit_running = False
        # A missing optional LiveSplit server should never receive repeated
        # command attempts. Availability probes open and close a connection
        # without sending timer data, then cache the result briefly.
        self.livesplit_health_cache: dict[
            str,
            tuple[str, int, bool, float],
        ] = {}
        self.level_waiting_for_start = True
        # Selecting Mario A/B/C starts the visible level timer immediately.
        # Until the first translevel is readable, elapsed time is held here
        # and then attached to that level's persistent timer.
        self.level_prestart_tracking = False
        # Opening story/intro levels use the same game mode as normal levels.
        # Automatic level timing is armed only after the ROM reaches its
        # overworld once, keeping cutscenes and scripted deaths out of both
        # the level timer and death counters.
        self.level_auto_tracking_armed = False
        self.intro_level_notice_logged = False
        self.level_overworld_entered_at: float | None = None
        self.level_livesplit_overworld_paused = False
        self.game_livesplit_overworld_paused = False
        self.retroarch_focus_paused = False
        self.retroarch_runloop_paused = False
        self.retroarch_status_checked_at = float("-inf")
        self.current_rom_key: str | None = None
        self.current_time_key: str | None = None
        self.active_save_slot: int | None = None
        self.pending_save_slot: int | None = None
        # True from the Mario A/B/C confirmation input until SMW leaves the
        # file-select mode.  The fade can remain in mode $0A for several
        # samples, so this keeps both elapsed clocks moving immediately rather
        # than displaying a started-but-frozen 00:00 during that transition.
        self.file_selection_confirmed = False
        # Remain in the file-start sequence until SMW reaches actual playable
        # gameplay. Many hacks reuse title/cutscene modes after Mario A/B/C is
        # selected; those modes must not reset or pause the two clocks.
        self.startup_sequence_active = False
        self.parked_time_key: str | None = None
        self.slot_blank_states: dict[int, bool] = {}
        # death_count is the saved total for the active ROM + Mario slot.
        # Level time and level_death_count are saved separately for each
        # ROM + Mario slot + translevel so revisiting a level restores both.
        self.death_count = 0
        self.level_death_count = 0
        self.previous_player_state: int | None = None
        self.previous_player_lives: int | None = None
        # Keep the last clean lives value observed inside a playable level.
        # Traditional hacks can leave the level through an intermediate game
        # mode after a death, so the rolling previous sample may already hold
        # the reduced lives value by the time the overworld is readable.  This
        # level-scoped baseline lets that later overworld sample still confirm
        # the death without inferring deaths from a bare level transition.
        self.last_level_player_lives: int | None = None
        # $0DBE (current player lives) can lag behind $010A (save slot)
        # briefly while switching between Mario A/B/C. During that handoff,
        # learn the new slot's stable lives value before using a decrease as
        # the backup death signal. The primary $71 = $09 signal stays active.
        self.slot_lives_baseline_pending = False
        self.slot_lives_baseline_value: int | None = None
        self.slot_lives_baseline_samples = 0
        self.death_detection_latched = False
        self.death_alive_samples = 0
        # A normal death can expose $71 = $09 and the $0DBE lives decrement
        # in different USB samples. Remember whether the current latched event
        # has already consumed the lives signal so the latch can rearm as soon
        # as the death cycle is complete instead of waiting for three perfect
        # gameplay samples (which loses rapid or unusual hack deaths).
        self.death_latch_saw_lives_drop = False
        # Some retry systems reload the current level/checkpoint without
        # showing a retry prompt, decrementing the vanilla lives byte, or
        # leaving $71 = $09 visible long enough for a USB sample.  Preserve
        # an uncleared attempt while SMW passes through its level-loading,
        # overworld, or title modes.  Returning to the same translevel (or to
        # the title screen) confirms one failed attempt.  record_death() uses
        # the same latch as the ordinary death/lives signals, so whichever
        # signal arrives first wins and the event is never counted twice.
        self.death_retry_transition_pending = False
        self.death_retry_origin_level: int | None = None
        # File selection/loading can expose a stale $71 = 09 or a lives-byte
        # handoff. Require one normal playable sample before accepting either
        # as a real death for the newly selected slot.
        self.death_startup_guard_active = False
        self.last_time_save = 0.0
        self.game_time_parked_at_title = False
        self.run_reached_gameplay = False

        self.database: dict[str, list[dict[str, str]]] = {}
        self.current_total = "Unknown"
        self.current_matched = False
        self.current_hack_title = ""
        self.current_hack_url = ""
        self.current_hack_record: dict[str, Any] = {}
        self.hack_catalog: list[dict[str, Any]] = []
        self.fxpak_settings: dict[str, str] = {}
        self.fxpak_path_map: dict[str, str] = {}
        self.current_mode: int | None = None
        self.current_translevel: int | None = None

        # Legacy workbook writes are retained only for optional export/import compatibility.
        self.spreadsheet_update_lock = threading.Lock()
        self.progress_sync_lock = threading.Lock()
        self.pending_progress_sync: dict[str, Any] | None = None
        self.progress_sync_thread: threading.Thread | None = None
        self.last_progress_exit_count: int | None = None
        self.last_connection_error = ""
        self.last_connection_error_logged_at = 0.0
        self.last_successful_connection_sample_at = 0.0
        self.connection_gate_lock = threading.Lock()
        self.connection_pause_event = threading.Event()
        self.connection_released_event = threading.Event()
        self.connection_released_event.set()

    def start(self) -> None:
        if self.thread and self.thread.is_alive():
            return

        self.stop_event.clear()
        self.thread = threading.Thread(
            target=self._main_loop,
            daemon=True,
        )
        self.thread.start()

    def stop(self) -> None:
        self.stop_event.set()

    def request_console_refresh(self) -> None:
        """Reset a controllable FXPAK session, then stop for reconnection."""
        self.command_queue.put("refresh_console")

    def pause_connection(self, timeout: float = 15.0) -> bool:
        """Release the SNES bridge while an exclusive SD-file job runs."""
        with self.connection_gate_lock:
            self.connection_pause_event.set()
        return self.connection_released_event.wait(max(0.1, timeout))

    def resume_connection(self) -> None:
        with self.connection_gate_lock:
            self.connection_pause_event.clear()

    def reset_game_timer(self) -> None:
        self.command_queue.put("reset_game")

    def reset_death_counter(self) -> None:
        """Backward-compatible alias for the visible Level Deaths reset."""
        self.reset_level_death_counter()

    def reset_level_death_counter(self) -> None:
        self.command_queue.put("reset_level_deaths")

    def reset_total_death_counter(self) -> None:
        self.command_queue.put("reset_total_deaths")

    def toggle_game_timer(self) -> None:
        self.command_queue.put("toggle_game")

    def finish_game_timer(self) -> None:
        self.command_queue.put("finish_game_timer")

    def toggle_level_timer(self) -> None:
        self.command_queue.put("toggle_level")

    def reset_level_timer(self) -> None:
        self.command_queue.put("reset_level")

    def toggle_both_timers(self) -> None:
        self.command_queue.put("toggle_both")

    def complete_in_spreadsheet(
        self,
        rating: float,
        notes: str,
    ) -> None:
        payload = json.dumps(
            {
                "rating": float(rating),
                "notes": str(notes),
            },
            ensure_ascii=False,
        )
        self.command_queue.put(
            f"complete_spreadsheet:{payload}"
        )

    def add_current_hack_to_tracker(self) -> None:
        self.command_queue.put("add_to_tracker")

    def override_timers(
        self,
        game_seconds: float | None,
        level_seconds: float | None,
        level_deaths: int | None = None,
        total_deaths: int | None = None,
    ) -> None:
        payload = json.dumps(
            {
                "game_seconds": game_seconds,
                "level_seconds": level_seconds,
                "level_deaths": level_deaths,
                "total_deaths": total_deaths,
            }
        )
        self.command_queue.put(
            f"override_timers:{payload}"
        )

    def reload_spreadsheet(self, spreadsheet_path: str) -> None:
        self.config["spreadsheet_path"] = spreadsheet_path
        self.command_queue.put("reload_spreadsheet")

    def notify_catalog_launch(self) -> None:
        """Re-arm ROM detection after an app-initiated platform launch."""
        self.command_queue.put("catalog_launch")

    def send_event(self, event_type: str, **data: object) -> None:
        self.event_queue.put({"type": event_type, **data})

    def log(self, message: str, show_status: bool = True) -> None:
        output_folder = Path(str(self.config["output_folder"]))
        log_file = output_folder / "SMWTracker.log"

        try:
            output_folder.mkdir(parents=True, exist_ok=True)

            with log_file.open("a", encoding="utf-8") as file:
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                file.write(f"[{timestamp}] {message}\n")

        except OSError:
            pass

        if show_status:
            self.send_event("log", message=message)

    def load_saved_times(self) -> dict[str, float]:
        if not TIMER_SAVE_FILE.exists():
            return {}

        try:
            data = json.loads(
                TIMER_SAVE_FILE.read_text(encoding="utf-8")
            )

            if not isinstance(data, dict):
                return {}

            return {
                str(key): max(0.0, float(value))
                for key, value in data.items()
            }

        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            return {}

    def load_saved_deaths(self) -> dict[str, int]:
        if not DEATH_SAVE_FILE.exists():
            return {}

        try:
            data = json.loads(
                DEATH_SAVE_FILE.read_text(encoding="utf-8")
            )

            if not isinstance(data, dict):
                return {}

            return {
                str(key): max(0, int(value))
                for key, value in data.items()
            }

        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            return {}

    def write_saved_deaths(self, saved_deaths: dict[str, int]) -> None:
        try:
            DEATH_SAVE_FILE.write_text(
                json.dumps(saved_deaths, indent=2),
                encoding="utf-8",
            )
        except OSError as error:
            self.log(f"Could not save death counter: {error}")

    def load_saved_level_progress(
        self,
    ) -> dict[str, dict[str, object]]:
        if not LEVEL_PROGRESS_SAVE_FILE.exists():
            return {}

        try:
            data = json.loads(
                LEVEL_PROGRESS_SAVE_FILE.read_text(encoding="utf-8")
            )
        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            return {}

        if not isinstance(data, dict):
            return {}

        progress: dict[str, dict[str, object]] = {}
        for raw_key, raw_value in data.items():
            if not isinstance(raw_value, dict):
                continue
            try:
                elapsed = max(
                    0.0,
                    float(raw_value.get("elapsed", 0.0)),
                )
                deaths = max(
                    0,
                    int(raw_value.get("deaths", 0)),
                )
            except (TypeError, ValueError):
                continue
            goal_routes = raw_value.get("goal_routes", [])
            if not isinstance(goal_routes, list):
                goal_routes = []
            progress[str(raw_key)] = {
                "elapsed": elapsed,
                "deaths": deaths,
                "goal_routes": [
                    route
                    for route in goal_routes
                    if route in {"normal", "secret"}
                ],
            }
        return progress

    def write_saved_level_progress(
        self,
        progress: dict[str, dict[str, object]],
    ) -> None:
        try:
            LEVEL_PROGRESS_SAVE_FILE.write_text(
                json.dumps(progress, indent=2),
                encoding="utf-8",
            )
        except OSError as error:
            self.log(f"Could not save level progress: {error}")

    def slot_name(self, slot: int | None) -> str:
        return {
            0: "Mario A",
            1: "Mario B",
            2: "Mario C",
        }.get(slot, "Unknown Slot")

    def make_rom_save_key(self, rom_path: str) -> str:
        cleaned_name = clean_rom_filename(rom_path)
        normalized = normalize_title(cleaned_name)

        if normalized:
            return normalized

        return str(PurePosixPath(rom_path)).casefold()

    def make_time_save_key(
        self,
        rom_key: str,
        slot: int,
    ) -> str:
        return f"{rom_key}::slot{slot}"

    def make_level_save_key(self, translevel: int) -> str | None:
        if not self.current_time_key:
            return None
        return f"{self.current_time_key}::level{int(translevel) & 0xFF:02X}"

    def get_saved_level_progress(
        self,
        translevel: int,
    ) -> tuple[float, int]:
        key = self.make_level_save_key(translevel)
        if not key:
            return 0.0, 0
        saved = self.load_saved_level_progress().get(key, {})
        return (
            max(0.0, float(saved.get("elapsed", 0.0))),
            max(0, int(saved.get("deaths", 0))),
        )

    def save_current_level_progress(self) -> bool:
        if not self.current_time_key or self.level_id is None:
            return False
        key = self.make_level_save_key(self.level_id)
        if not key:
            return False
        progress = self.load_saved_level_progress()
        saved = dict(progress.get(key, {}))
        saved["elapsed"] = max(0.0, float(self.level_elapsed))
        saved["deaths"] = max(0, int(self.level_death_count))
        saved.setdefault("goal_routes", [])
        progress[key] = saved
        self.write_saved_level_progress(progress)
        return True

    def goal_route_was_confirmed(
        self,
        translevel: int,
        route: str,
    ) -> bool:
        key = self.make_level_save_key(translevel)
        if not key:
            return False
        saved = self.load_saved_level_progress().get(key, {})
        routes = saved.get("goal_routes", [])
        return isinstance(routes, list) and route in routes

    def mark_goal_route_confirmed(
        self,
        translevel: int,
        route: str,
    ) -> None:
        key = self.make_level_save_key(translevel)
        if not key:
            return
        progress = self.load_saved_level_progress()
        saved = dict(progress.get(key, {}))
        routes = saved.get("goal_routes", [])
        if not isinstance(routes, list):
            routes = []
        routes = [
            saved_route
            for saved_route in routes
            if saved_route in {"normal", "secret"}
        ]
        if route not in routes:
            routes.append(route)
        saved["goal_routes"] = routes
        saved.setdefault("elapsed", max(0.0, float(self.level_elapsed)))
        saved.setdefault("deaths", max(0, int(self.level_death_count)))
        progress[key] = saved
        self.write_saved_level_progress(progress)

    def select_save_slot(self, slot: int) -> None:
        if not self.current_rom_key:
            return

        # Vanilla SMW uses 0, 1 and 2 for Mario A, B and C.
        # Ignore transient/invalid values used by heavily modified menus.
        if slot not in {0, 1, 2}:
            return

        switching_slots = (
            self.active_save_slot is not None
            and self.active_save_slot != slot
        )
        if switching_slots:
            self.save_current_level_progress()
        self.active_save_slot = slot
        self.current_time_key = self.make_time_save_key(
            self.current_rom_key,
            slot,
        )
        self.death_count = self.load_saved_deaths().get(
            self.current_time_key,
            0,
        )
        if self.level_id is not None:
            (
                self.level_elapsed,
                self.level_death_count,
            ) = self.get_saved_level_progress(self.level_id)
            self.load_level_time_into_livesplit()
            if (
                self.level_finished
                or self.timers_paused
                or self.level_manual_paused
                or self.level_livesplit_overworld_paused
            ):
                self.send_livesplit_command("level", "pause")
                self.level_livesplit_running = False
        else:
            self.level_death_count = 0
        self.previous_player_state = None
        self.previous_player_lives = None
        self.last_level_player_lives = None
        self.slot_lives_baseline_pending = switching_slots
        self.slot_lives_baseline_value = None
        self.slot_lives_baseline_samples = 0
        self.death_detection_latched = False
        self.death_alive_samples = 0
        self.death_latch_saw_lives_drop = False
        self.death_retry_transition_pending = False
        self.death_retry_origin_level = None
        # File selection/loading can expose a stale $71 = 09 or a lives-byte
        # handoff. Require one normal playable sample before accepting either
        # as a real death for the newly selected slot.
        self.death_startup_guard_active = False
        self.update_death_file()
        self.update_timer_files()

    def save_current_game_time(self) -> None:
        if not self.current_time_key:
            return

        saved_times = self.load_saved_times()
        saved_times[self.current_time_key] = max(
            0.0,
            float(self.game_elapsed),
        )

        try:
            TIMER_SAVE_FILE.write_text(
                json.dumps(saved_times, indent=2),
                encoding="utf-8",
            )
        except OSError as error:
            self.log(f"Could not save game time: {error}")

    def save_current_death_count(self) -> None:
        if not self.current_time_key:
            return

        saved_deaths = self.load_saved_deaths()
        saved_deaths[self.current_time_key] = max(
            0,
            int(self.death_count),
        )
        self.write_saved_deaths(saved_deaths)

    def get_saved_game_time_for_slot(self, slot: int) -> float:
        self.select_save_slot(slot)

        if not self.current_time_key:
            return 0.0

        return self.load_saved_times().get(
            self.current_time_key,
            0.0,
        )

    def clear_saved_game_time(self) -> None:
        if not self.current_time_key:
            return

        saved_times = self.load_saved_times()
        saved_times[self.current_time_key] = 0.0

        try:
            TIMER_SAVE_FILE.write_text(
                json.dumps(saved_times, indent=2),
                encoding="utf-8",
            )
        except OSError as error:
            self.log(f"Could not reset saved game time: {error}")

    def clear_saved_death_count(self) -> bool:
        if not self.current_time_key:
            return False

        self.death_count = 0
        saved_deaths = self.load_saved_deaths()
        saved_deaths[self.current_time_key] = 0
        self.write_saved_deaths(saved_deaths)
        self.update_death_file()
        return True

    def clear_level_death_count(self) -> bool:
        if not self.current_time_key:
            return False

        self.level_death_count = 0
        self.save_current_level_progress()
        self.update_death_file()
        self.update_timer_files()
        return True

    def format_livesplit_time(self, seconds: float) -> str:
        total_ms = max(0, int(seconds * 1000))
        hours, remainder = divmod(total_ms, 3_600_000)
        minutes, remainder = divmod(remainder, 60_000)
        secs, millis = divmod(remainder, 1000)
        return f"{hours}:{minutes:02d}:{secs:02d}.{millis:03d}"

    def load_game_time_into_livesplit(self) -> None:
        saved_time = self.format_livesplit_time(self.game_elapsed)

        # LiveSplit must initialize Game Time before setgametime works.
        # Start the timer first, initialize Game Time, restore the saved
        # value, switch the display to Game Time, then allow it to run.
        self.send_livesplit_command("game", "reset")
        self.send_livesplit_command("game", "starttimer")
        self.send_livesplit_command("game", "initgametime")
        self.send_livesplit_command(
            "game",
            f"setgametime {saved_time}",
        )
        self.send_livesplit_command("game", "switchto gametime")
        self.send_livesplit_command("game", "unpausegametime")

    def load_level_time_into_livesplit(self) -> None:
        override_time = self.format_livesplit_time(
            self.level_elapsed
        )

        self.send_livesplit_command(
            "level",
            "reset",
        )
        self.send_livesplit_command(
            "level",
            "starttimer",
        )
        self.send_livesplit_command(
            "level",
            "initgametime",
        )
        self.send_livesplit_command(
            "level",
            f"setgametime {override_time}",
        )
        self.send_livesplit_command(
            "level",
            "switchto gametime",
        )
        self.send_livesplit_command(
            "level",
            "unpausegametime",
        )

    def send_livesplit_command(
        self,
        timer: str,
        command: str,
    ) -> bool:
        if not self._livesplit_server_available(timer):
            return False

        try:
            host, port = livesplit_endpoint(self.config, timer)

            with socket.create_connection(
                (host, port),
                timeout=0.35,
            ) as connection:
                connection.sendall(
                    f"{command}\r\n".encode("ascii")
                )

            self._cache_livesplit_availability(timer, True)
            self.send_event(
                "livesplit",
                timer=timer,
                connected=True,
                command=command,
            )
            return True

        except (OSError, ValueError) as error:
            self._cache_livesplit_availability(timer, False)
            self.send_event(
                "livesplit",
                timer=timer,
                connected=False,
                command=command,
                error=str(error),
            )
            self.log(
                f"Could not send {command} to "
                f"{timer} LiveSplit: {error}"
            )
            return False

    def _cache_livesplit_availability(
        self,
        timer: str,
        available: bool,
    ) -> None:
        try:
            host, port = livesplit_endpoint(self.config, timer)
        except (TypeError, ValueError):
            return
        self.livesplit_health_cache[timer] = (
            host,
            port,
            bool(available),
            time.monotonic(),
        )

    def _livesplit_server_available(
        self,
        timer: str,
        force: bool = False,
    ) -> bool:
        try:
            host, port = livesplit_endpoint(self.config, timer)
        except (TypeError, ValueError):
            return False

        now = time.monotonic()
        cached = self.livesplit_health_cache.get(timer)
        if cached is not None:
            cached_host, cached_port, available, checked_at = cached
            cache_seconds = 10.0 if available else 2.0
            if (
                not force
                and cached_host == host
                and cached_port == port
                and now - checked_at < cache_seconds
            ):
                return available

        available = livesplit_server_is_running(
            self.config,
            timer,
        )
        self.livesplit_health_cache[timer] = (
            host,
            port,
            available,
            now,
        )
        return available

    def reset_both_livesplits(self) -> None:
        self.send_livesplit_command("game", "reset")
        self.send_livesplit_command("level", "reset")

    def pause_both_livesplits(self) -> None:
        self.send_livesplit_command("game", "pause")
        self.send_livesplit_command("level", "pause")

    def resume_both_livesplits(self) -> None:
        self.send_livesplit_command("game", "resume")
        self.send_livesplit_command("level", "resume")

    def write_text_file(self, filename: str, text: str) -> None:
        output_folder = Path(str(self.config["output_folder"]))
        output_folder.mkdir(parents=True, exist_ok=True)
        file_path = output_folder / filename

        try:
            current = (
                file_path.read_text(
                    encoding="utf-8",
                    errors="replace",
                )
                if file_path.exists()
                else ""
            )

            if current != text:
                file_path.write_text(text, encoding="utf-8")

        except OSError as error:
            self.log(f"Could not update {filename}: {error}")

    def update_title_files(self, hack_name: str, author: str) -> None:
        self.write_text_file("hack_name.txt", hack_name)
        self.write_text_file(
            "author.txt",
            render_obs_text_template(
                self.config.get("obs_author_text_format"),
                "By: {author}",
                author=author,
            ),
        )

    def update_exit_file(self, completed: object, total: object) -> None:
        self.write_text_file(
            "exits.txt",
            render_obs_text_template(
                self.config.get("obs_exits_text_format"),
                "Exits: {completed} / {total}",
                completed=completed,
                total=total,
            ),
        )

    def update_death_file(self) -> None:
        level_deaths = max(0, int(self.level_death_count))
        total_deaths = max(0, int(self.death_count))
        level_death_text = render_obs_text_template(
            self.config.get("obs_deaths_text_format"),
            "Level Deaths: {deaths}",
            deaths=level_deaths,
        )
        total_death_text = render_obs_text_template(
            self.config.get("obs_total_deaths_text_format"),
            "Total Deaths: {total_deaths}",
            total_deaths=total_deaths,
        )
        self.write_text_file("level_deaths.txt", level_death_text)
        self.write_text_file("death_counter.txt", level_death_text)
        self.write_text_file("total_deaths.txt", total_death_text)
        self.send_event(
            "deaths",
            # deaths remains for compatibility with older UI consumers.
            deaths=level_deaths,
            level_deaths=level_deaths,
            total_deaths=total_deaths,
        )

    def update_timer_files(self) -> None:
        game_text = format_timer(self.game_elapsed, milliseconds=False)
        level_text = format_timer(self.level_elapsed, milliseconds=False)

        self.write_text_file(
            "game_timer.txt",
            game_text,
        )
        self.write_text_file(
            "level_timer.txt",
            level_text,
        )

        game_running = (
            self.game_started
            and not self.game_finished
            and not self.timers_paused
            and not self.game_manual_paused
            and not self.game_livesplit_overworld_paused
            and not self.retroarch_focus_paused
        )
        level_running = (
            (self.level_id is not None or self.level_prestart_tracking)
            and not self.level_finished
            and not self.timers_paused
            and not self.level_manual_paused
            and self.level_livesplit_running
            and not self.retroarch_focus_paused
        )

        self.send_event(
            "timers",
            game=game_text,
            level=level_text,
            game_started=self.game_started,
            game_finished=self.game_finished,
            level_finished=self.level_finished,
            timers_paused=self.timers_paused,
            game_running=game_running,
            level_running=level_running,
        )

    def write_no_game_files(self) -> None:
        self.update_title_files("No game detected", "Unknown")
        self.update_exit_file(0, "Unknown")
        self.death_count = 0
        self.level_death_count = 0
        self.update_death_file()
        self.update_timer_files()

