        def make_live_time_death_metric(
            column: int,
            time_title: str,
            time_variable: tk.StringVar,
            time_accent: str,
            death_title: str,
            death_variable: tk.StringVar,
            death_accent: str,
            reset_text: str,
            reset_command: Callable[[], None],
        ) -> tuple[tk.Frame, tk.Button]:
            metric = tk.Frame(
                live_game_grid,
                bg="#F1FFF0",
                highlightbackground=THEME["border"],
                highlightthickness=1,
            )
            metric.grid(row=0, column=column, sticky="nsew")
            metric.columnconfigure(0, weight=1)
            metric.rowconfigure(0, weight=1)
            metric.rowconfigure(6, weight=1)

            tk.Label(
                metric,
                text=time_title,
                font=("Segoe UI", 8, "bold"),
                fg=time_accent,
                bg="#F1FFF0",
                anchor="center",
            ).grid(
                row=1,
                column=0,
                sticky="ew",
            )
            OutlinedLabel(
                metric,
                textvariable=time_variable,
                font=("Segoe UI", 17, "bold"),
                fg=THEME["text"],
                bg="#F1FFF0",
                anchor="center",
                justify="center",
            ).grid(row=2, column=0, sticky="ew")

            tk.Label(
                metric,
                text=death_title,
                font=("Segoe UI", 8, "bold"),
                fg=death_accent,
                bg="#F1FFF0",
                anchor="center",
            ).grid(
                row=3,
                column=0,
                sticky="ew",
                pady=(self._ui_px(4), 0),
            )
            OutlinedLabel(
                metric,
                textvariable=death_variable,
                font=("Segoe UI", 12, "bold"),
                fg=THEME["text"],
                bg="#F1FFF0",
                anchor="center",
                justify="center",
            ).grid(row=4, column=0, sticky="ew")

            button = self._make_action_button(
                metric,
                text=reset_text,
                command=reset_command,
                bg=death_accent,
                active_bg=THEME["navy"],
                width=18,
                pad_y=2,
                font_size=8,
            )
            button.grid(
                row=5,
                column=0,
                pady=(self._ui_px(2), 0),
            )
            return metric, button

