    def _build_menu_bar(self) -> None:
        colors = self._menu_colors()

        self.custom_menu_bar = tk.Frame(
            self.root,
            bg=colors["bar_bg"],
            height=self._ui_px(34),
            highlightthickness=0,
            bd=0,
        )
        if not getattr(self, "responsive_ui_rebuilding", False):
            self.custom_menu_bar.pack(
                side="top",
                fill="x",
            )
        self.custom_menu_bar.pack_propagate(False)

        self.menu_buttons: list[RoundedMenuButton] = []

        def create_menu_button(
            label: str,
            active_color: str,
            icon_name: str,
        ) -> tuple[RoundedMenuButton, tk.Menu]:
            button_options = {
                "text": label,
                "font": (
                    "Segoe UI",
                    10,
                    "bold",
                ),
                "bg": colors["bar_bg"],
                "fg": colors["fg"],
                "activebackground": active_color,
                "activeforeground": "white",
                "padx": self._ui_px(8),
                "pady": self._ui_px(4),
                "width": max(5, len(label) + 3),
                "min_width": self._ui_px(66),
                "min_height": self._ui_px(32),
                "corner_radius": self._ui_px(8),
                "cursor": "hand2",
                "direction": "below",
            }
            button_icon = (
                self.mario_menu_photos.get(
                    icon_name
                )
            )
            if button_icon is not None:
                button_options.update(
                    {
                        "image": button_icon,
                        "compound": "left",
                    }
                )
            button = RoundedMenuButton(
                self.custom_menu_bar,
                **button_options,
            )
            button.pack(
                side="left",
                fill="y",
            )

            dropdown = tk.Menu(
                button,
                tearoff=False,
                bg=colors["bg"],
                fg=colors["fg"],
                activebackground=active_color,
                activeforeground="white",
                disabledforeground=colors["disabled_fg"],
                selectcolor=colors["select"],
                relief="solid",
                bd=1,
                font=(
                    "Segoe UI",
                    10,
                    "bold",
                ),
            )
            button.configure(menu=dropdown)
            self.menu_buttons.append(button)
            return button, dropdown

        def add_mario_command(
            menu: tk.Menu,
            label: str,
            command,
            icon_name: str,
            state: str | None = None,
        ) -> None:
            options = {
                "label": label,
                "command": command,
            }
            if state is not None:
                options["state"] = state
            menu.add_command(**options)

        def add_mario_radio(
            menu: tk.Menu,
            label: str,
            value: str,
            command,
            icon_name: str,
            variable: tk.Variable | None = None,
        ) -> None:
            options = {
                "label": label,
                "variable": (
                    variable
                    if variable is not None
                    else self.appearance_var
                ),
                "value": value,
                "command": command,
            }
            menu.add_radiobutton(**options)

        def protected_menu_action(
            scope_key: str,
            scope_label: str,
            action_label: str,
            action,
        ):
            return lambda: self._run_with_streamer_privacy_warning(
                scope_key,
                scope_label,
                action_label,
                action,
            )

