    def _update_catalog_menu_labels(
        self,
    ) -> None:
        if self.catalog_menu is None:
            return

        metadata = self.stats_db.metadata()
        version = str(
            metadata.get(
                "Catalog Version",
                "Unknown",
            )
            or "Unknown"
        )
        last_refresh = (
            format_display_datetime(
                metadata.get(
                    "Catalog Last Refresh",
                    "",
                )
            )
        )

        try:
            if (
                self.catalog_version_menu_index
                is not None
            ):
                self.catalog_menu.entryconfigure(
                    self.catalog_version_menu_index,
                    label=(
                        "Catalog Version: "
                        + version
                    ),
                )

            if (
                self.catalog_refresh_date_menu_index
                is not None
            ):
                self.catalog_menu.entryconfigure(
                    self.catalog_refresh_date_menu_index,
                    label=(
                        "Last Refresh: "
                        + last_refresh
                    ),
                )
        except tk.TclError:
            pass

    def _ask_localized_yes_no(
        self,
        title: str,
        message: str,
        *,
        parent: tk.Widget | None = None,
    ) -> bool:
        """Show a fully app-localized confirmation, including its buttons."""
        owner = parent or self.root
        palette = self._library_palette()
        answer = {"confirmed": False}
        dialog = tk.Toplevel(owner)
        # Treat confirmations as complete dialog text.  This avoids the
        # phrase-by-phrase fallback producing mixed-language sentences when
        # an older localized fragment is still present after a language
        # switch.
        dialog_translator = getattr(
            self,
            "_translate_dialog_text",
            None,
        )
        if not callable(dialog_translator):
            dialog_translator = self._translate_ui_text
        localized_title = dialog_translator(title)
        localized_message = dialog_translator(message)
        dialog.title(localized_title)
        self._size_dialog_for_ui(
            dialog,
            760,
            430,
            660,
            380,
        )
        dialog.resizable(False, False)
        dialog.transient(owner)
        dialog.configure(bg=palette["window"])

        title_bar = tk.Frame(
            dialog,
            bg=THEME["blue"],
            padx=self._ui_px(18),
            pady=self._ui_px(12),
        )
        title_bar.pack(fill="x")
        OutlinedLabel(
            title_bar,
            text=localized_title.upper(),
            font=("Segoe UI", 14, "bold"),
            fg="white",
            bg=THEME["blue"],
            anchor="center",
            justify="center",
        ).pack(fill="x")

        body = tk.Frame(
            dialog,
            bg=palette["panel"],
            padx=self._ui_px(24),
            pady=self._ui_px(22),
            highlightbackground=palette["border"],
            highlightthickness=1,
        )
        body.pack(
            fill="both",
            expand=True,
            padx=self._ui_px(12),
            pady=(0, self._ui_px(12)),
        )
        tk.Label(
            body,
            text=localized_message,
            font=("Segoe UI", 11),
            fg=palette["text"],
            bg=palette["panel"],
            anchor="nw",
            justify="left",
            wraplength=self._ui_px(690),
        ).pack(fill="both", expand=True)

        def finish(confirmed: bool) -> None:
            answer["confirmed"] = confirmed
            try:
                dialog.grab_release()
            except tk.TclError:
                pass
            dialog.destroy()

        button_bar = tk.Frame(
            body,
            bg=palette["panel"],
        )
        button_bar.pack(fill="x", pady=(self._ui_px(18), 0))
        centered_buttons = tk.Frame(
            button_bar,
            bg=palette["panel"],
        )
        centered_buttons.pack(anchor="center")
        no_button = self._make_action_button(
            centered_buttons,
            text=self._translate_ui_text("No"),
            command=lambda: finish(False),
            bg="#63788F",
            active_bg="#4A6078",
            width=12,
            pad_y=6,
            fixed_pixel_width=self._ui_px(150),
        )
        no_button.pack(side="left", padx=self._ui_px(7))
        yes_button = self._make_action_button(
            centered_buttons,
            text=self._translate_ui_text("Yes"),
            command=lambda: finish(True),
            bg=THEME["green"],
            active_bg="#208A39",
            width=12,
            pad_y=6,
            fixed_pixel_width=self._ui_px(150),
        )
        yes_button.pack(side="left", padx=self._ui_px(7))

        dialog.protocol("WM_DELETE_WINDOW", lambda: finish(False))
        dialog.bind("<Escape>", lambda _event: finish(False))
        dialog.bind("<Return>", lambda _event: finish(True))
        self._apply_widget_appearance(
            dialog,
            dark=(self.appearance_var.get() == "dark"),
        )
        dialog.grab_set()
        yes_button.focus_set()
        owner.wait_window(dialog)
        return bool(answer["confirmed"])

    def _show_localized_info(
        self,
        title: str,
        message: str,
        *,
        parent: tk.Widget | None = None,
    ) -> None:
        """Show an app-localized information dialog, including its button."""
        owner = parent or self.root
        try:
            if not owner.winfo_exists():
                owner = self.root
        except (AttributeError, tk.TclError):
            owner = self.root
        palette = self._library_palette()
        dialog = tk.Toplevel(owner)
        localized_title = self._translate_dialog_text(title)
        localized_message = self._translate_dialog_text(message)
        dialog.title(localized_title)
        self._size_dialog_for_ui(dialog, 760, 330, 660, 290)
        dialog.resizable(False, False)
        dialog.transient(owner)
        dialog.configure(bg=palette["window"])

        title_bar = tk.Frame(
            dialog,
            bg=THEME["blue"],
            padx=self._ui_px(18),
            pady=self._ui_px(12),
        )
        title_bar.pack(fill="x")
        OutlinedLabel(
            title_bar,
            text=localized_title.upper(),
            font=("Segoe UI", 14, "bold"),
            fg="white",
            bg=THEME["blue"],
            anchor="center",
            justify="center",
        ).pack(fill="x")

        body = tk.Frame(
            dialog,
            bg=palette["panel"],
            padx=self._ui_px(24),
            pady=self._ui_px(22),
            highlightbackground=palette["border"],
            highlightthickness=1,
        )
        body.pack(
            fill="both",
            expand=True,
            padx=self._ui_px(12),
            pady=(0, self._ui_px(12)),
        )
        tk.Label(
            body,
            text=localized_message,
            font=("Segoe UI", 11),
            fg=palette["text"],
            bg=palette["panel"],
            anchor="center",
            justify="center",
            wraplength=self._ui_px(690),
        ).pack(fill="both", expand=True)

        def close_dialog() -> None:
            try:
                dialog.grab_release()
            except tk.TclError:
                pass
            dialog.destroy()

        ok_button = self._make_action_button(
            body,
            text=self._translate_ui_text("OK"),
            command=close_dialog,
            bg=THEME["blue"],
            active_bg="#1768B2",
            width=12,
            pad_y=6,
            fixed_pixel_width=self._ui_px(150),
        )
        ok_button.pack(anchor="center", pady=(self._ui_px(16), 0))

        dialog.protocol("WM_DELETE_WINDOW", close_dialog)
        dialog.bind("<Escape>", lambda _event: close_dialog())
        dialog.bind("<Return>", lambda _event: close_dialog())
        try:
            dialog_is_dark = self.appearance_var.get() == "dark"
        except (AttributeError, tk.TclError):
            dialog_is_dark = (
                str(self.config.get("ui_theme", "dark")).casefold()
                == "dark"
            )
        self._apply_widget_appearance(
            dialog,
            dark=dialog_is_dark,
        )
        dialog.grab_set()
        ok_button.focus_set()
        owner.wait_window(dialog)

    def reset_smwcentral_catalog(self) -> None:
        """Reset the downloaded catalog while preserving personal data."""
        parent = self.downloader_dialog or self.root
        if (
            self.catalog_refresh_thread is not None
            and self.catalog_refresh_thread.is_alive()
        ):
            self._show_localized_info(
                "SMW Central Catalog",
                (
                    "Finish or cancel the current catalog refresh before "
                    "resetting the catalog."
                ),
                parent=parent,
            )
            return

        confirmed = self._ask_localized_yes_no(
            "Reset SMW Central Catalog?",
            (
                "Remove every moderated and waiting hack from the local "
                "SMW Central catalog?\n\n"
                "Your tracked progress, ratings, notes, custom hacks, ROM "
                "mappings, and ROM files will be preserved. A recovery "
                "backup will be created first.\n\n"
                "You can download the catalog again with Refresh Moderated "
                "Hacks from SMW Central."
            ),
            parent=parent,
        )
        if not confirmed:
            return

        backup_path = self._create_recovery_backup(
            reason="before_catalog_reset",
        )
        if backup_path is None:
            self._show_localized_info(
                "Backup Failed",
                (
                    "The catalog could not be reset because a recovery "
                    "backup could not be created."
                ),
                parent=parent,
            )
            return

        try:
            summary = self.stats_db.reset_smwcentral_catalog()
        except Exception as error:
            append_error_log(
                "SMW Central catalog reset failed",
                traceback.format_exc(),
            )
            self._show_localized_info(
                "SMW Central Catalog",
                str(error),
                parent=parent,
            )
            return

        self.hack_catalog = self.stats_db.load_catalog()
        self._downloader_catalog_metadata_cache = None
        self._catalog_playable_filter_cache = None
        self._catalog_direct_file_cache = {}
        self._refresh_database_status()
        self._check_catalog_freshness_async(force=True)

        if (
            self.worker is not None
            and self.worker.thread is not None
            and self.worker.thread.is_alive()
        ):
            self.worker.reload_spreadsheet(
                self.spreadsheet_path_var.get().strip()
            )

        if (
            self.game_library_dialog is not None
            and self.game_library_dialog.winfo_exists()
        ):
            self._populate_game_library()
        if (
            self.tracker_list_dialog is not None
            and self.tracker_list_dialog.winfo_exists()
        ):
            self._refresh_my_tracker()
        if (
            self.stats_overview_dialog is not None
            and self.stats_overview_dialog.winfo_exists()
        ):
            self.open_stats_overview()
        if (
            self.downloader_dialog is not None
            and self.downloader_dialog.winfo_exists()
        ):
            self._refresh_downloader_preview()

        self.status_var.set(
            self._translate_ui_text("Catalog reset complete.")
        )
        message = self._translate_ui_text(
            "The SMW Central catalog was reset. {removed} catalog entries "
            "were removed. {preserved} tracked or mapped entries were "
            "preserved as personal records.\n\nA recovery backup was "
            "created. Select Refresh Moderated Hacks from SMW Central "
            "whenever you want to download the catalog again."
        ).format(
            removed=f"{int(summary.get('removed', 0)):,}",
            preserved=f"{int(summary.get('preserved', 0)):,}",
        )
        self._show_localized_info(
            "Catalog Reset Complete",
            message,
            parent=parent,
        )

    def refresh_smwcentral_catalog(
        self,
        *,
        waiting: bool = False,
    ) -> None:
        if (
            self.catalog_refresh_thread is not None
            and self.catalog_refresh_thread.is_alive()
        ):
            if (
                self.catalog_refresh_dialog is not None
                and self.catalog_refresh_dialog.winfo_exists()
            ):
                self.catalog_refresh_dialog.lift()
            return

        refresh_title = (
            "Refresh Waiting Hacks from SMW Central"
            if waiting
            else "Refresh Moderated Hacks from SMW Central"
        )
        refresh_message = (
            "Refresh waiting hacks directly from SMW Central's live "
            "catalog?\n\nWaiting entries are not moderated yet and "
            "will appear in bright red throughout the app."
            if waiting
            else "Refresh moderated hacks directly from SMW Central's "
            "live catalog?\n\n"
            "This retrieves the current moderated list from the site, "
            "including hacks that may not have reached the GitHub "
            "spreadsheet mirror yet. Routine refreshes use a fast "
            "newest-first scan and stop after reaching already-known "
            "hacks.\n\n"
            "Your tracked progress, ratings, notes, custom hacks, "
            "and ROM mappings will be preserved."
        )
        confirmed = self._ask_localized_yes_no(
            refresh_title,
            refresh_message,
            parent=self.root,
        )

        if not confirmed:
            return

        palette = self._library_palette()
        dialog = tk.Toplevel(self.root)
        self.catalog_refresh_dialog = dialog
        localized_refresh_title = self._translate_ui_text(refresh_title)
        dialog.title(localized_refresh_title)
        self._size_dialog_for_ui(
            dialog,
            620,
            190,
        )
        dialog.resizable(False, False)
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.configure(
            bg=palette["window"]
        )

        status_var = self._localized_string_var(
            value=(
                "Connecting to the live SMW Central catalog…"
            ),
            master=dialog,
        )
        self.catalog_refresh_status_var = (
            status_var
        )

        title_bar = tk.Frame(
            dialog,
            bg=THEME["orange"],
            padx=16,
            pady=11,
        )
        title_bar.pack(fill="x")
        self._add_dialog_window_controls(
            title_bar,
            dialog,
            THEME["orange"],
        )
        OutlinedLabel(
            title_bar,
            text="↻  " + localized_refresh_title.upper(),
            font=("Segoe UI", 14, "bold"),
            fg="white",
            bg=THEME["orange"],
        ).pack(side="left", anchor="w")

        body = tk.Frame(
            dialog,
            bg=palette["panel"],
            padx=16,
            pady=14,
        )
        body.pack(
            fill="both",
            expand=True,
            padx=8,
            pady=(0, 8),
        )
        OutlinedLabel(
            body,
            textvariable=status_var,
            font=("Segoe UI", 10, "bold"),
            fg=palette["text"],
            bg=palette["panel"],
            anchor="w",
            justify="left",
            wraplength=560,
        ).pack(
            fill="x",
            pady=(0, 10),
        )
        progress = ttk.Progressbar(
            body,
            mode="indeterminate",
        )
        progress.pack(fill="x")
        progress.start(12)

        cancel_button = self._make_action_button(
            body,
            text="Cancel",
            command=self._cancel_catalog_refresh,
            bg=THEME["red"],
            active_bg="#B92824",
            width=11,
            pad_y=4,
        )
        cancel_button.pack(
            anchor="e",
            pady=(10, 0),
        )

        self.catalog_refresh_cancel_event.clear()

        if (
            self.catalog_menu is not None
            and self.catalog_refresh_menu_index
            is not None
        ):
            try:
                self.catalog_menu.entryconfigure(
                    self.catalog_refresh_menu_index,
                    state="disabled",
                )
            except tk.TclError:
                pass

        self.status_var.set(
            "Refreshing the catalog directly from SMW Central…"
        )
        self._catalog_refresh_waiting = waiting
        self.catalog_refresh_thread = (
            threading.Thread(
                target=lambda: self._catalog_refresh_worker(waiting=waiting),
                daemon=True,
            )
        )
        self.catalog_refresh_thread.start()

        dialog.protocol(
            "WM_DELETE_WINDOW",
            self._cancel_catalog_refresh,
        )
        self._apply_widget_appearance(
            dialog,
            dark=(
                self.appearance_var.get()
                == "dark"
            ),
        )

    def _cancel_catalog_refresh(self) -> None:
        self.catalog_refresh_cancel_event.set()

        if self.catalog_refresh_status_var is not None:
            self.catalog_refresh_status_var.set(
                "Cancel requested…"
            )

    def _catalog_refresh_progress(
        self,
        message: str,
    ) -> None:
        self.root.after(
            0,
            lambda: (
                self.catalog_refresh_status_var.set(
                    message
                )
                if self.catalog_refresh_status_var
                is not None
                else None
            ),
        )

    def _catalog_refresh_worker(self, *, waiting: bool = False) -> None:
        summary: dict[str, Any] | None = None
        error_message = ""

        try:
            summary = (
                (
                    refresh_waiting_from_smwcentral_site
                    if waiting
                    else refresh_catalog_from_smwcentral_site
                )(
                    self.stats_db,
                    self.catalog_refresh_cancel_event,
                    self._catalog_refresh_progress,
                )
            )

        except Exception as error:
            error_message = str(error)

        self.root.after(
            0,
            lambda: self._finish_catalog_refresh(
                summary,
                error_message,
            ),
        )

    def _finish_catalog_refresh(
        self,
        summary: dict[str, Any] | None,
        error_message: str,
    ) -> None:
        if (
            self.catalog_refresh_dialog is not None
            and self.catalog_refresh_dialog.winfo_exists()
        ):
            try:
                self.catalog_refresh_dialog.grab_release()
            except tk.TclError:
                pass

            self.catalog_refresh_dialog.destroy()

        self.catalog_refresh_dialog = None
        self.catalog_refresh_status_var = None

        if (
            self.catalog_menu is not None
            and self.catalog_refresh_menu_index
            is not None
        ):
            try:
                self.catalog_menu.entryconfigure(
                    self.catalog_refresh_menu_index,
                    state="normal",
                )
            except tk.TclError:
                pass

        self._update_catalog_menu_labels()

        if summary is None:
            self.status_var.set(
                error_message
                or "Catalog refresh failed."
            )
            messagebox.showerror(
                "SMWCentral Catalog",
                error_message
                or "Catalog refresh failed.",
                parent=self.root,
            )
            return

        self.hack_catalog = (
            self.stats_db.load_catalog()
        )
        self._refresh_database_status()
        self._check_catalog_freshness_async(force=True)

        if (
            self.worker is not None
            and self.worker.thread is not None
            and self.worker.thread.is_alive()
        ):
            self.worker.reload_spreadsheet(
                self.spreadsheet_path_var.get().strip()
            )

        if (
            self.game_library_dialog is not None
            and self.game_library_dialog.winfo_exists()
        ):
            self._populate_game_library()

        if (
            self.tracker_list_dialog is not None
            and self.tracker_list_dialog.winfo_exists()
        ):
            self._refresh_my_tracker()

        if (
            self.stats_overview_dialog is not None
            and self.stats_overview_dialog.winfo_exists()
        ):
            self.open_stats_overview()

        if (
            self.downloader_dialog is not None
            and self.downloader_dialog.winfo_exists()
        ):
            self._refresh_downloader_preview()

        refresh_status = str(
            summary.get(
                "status",
                "refreshed",
            )
        )

        if refresh_status == "up_to_date":
            message = self._translate_ui_text(
                "Your hack catalog is already up to date. Catalog version: "
                "{version}; sequence: {sequence}."
            ).format(
                version=summary.get("version", self._translate_ui_text("Unknown")),
                sequence=f"{int(summary.get('sequence', 0)):,}",
            )

        elif refresh_status == "local_newer":
            message = self._translate_ui_text(
                "No catalog changes were applied because your local catalog "
                "sequence ({local_sequence}) is newer than the GitHub "
                "repository sequence ({sequence}). Your current catalog was "
                "preserved."
            ).format(
                local_sequence=(
                    f"{int(summary.get('local_sequence', 0)):,}"
                ),
                sequence=f"{int(summary.get('sequence', 0)):,}",
            )

        else:
            message = self._translate_ui_text(
                "Live SMW Central catalog refresh complete. Pages checked: "
                "{pages}; hacks checked: {checked}; new: {new}; updated: "
                "{updated}; removed: {removed}; official catalog: {official}."
            ).format(
                pages=f"{int(summary.get('pages_read', 0)):,}",
                checked=f"{int(summary.get('fetched', 0)):,}",
                new=f"{int(summary.get('new', 0)):,}",
                updated=f"{int(summary.get('updated', 0)):,}",
                removed=f"{int(summary.get('removed', 0)):,}",
                official=f"{int(summary.get('official', 0)):,}",
            )

            preserved_removed = int(
                summary.get(
                    "removed_preserved",
                    0,
                )
            )

            if preserved_removed:
                message += " " + self._translate_ui_text(
                    "{count} removed catalog entry or entries were retained "
                    "as local history because they are tracked or have ROM "
                    "mappings."
                ).format(count=f"{preserved_removed:,}")
        self.status_var.set(message)
        self._show_localized_info(
            "SMWCentral Catalog",
            message,
            parent=self.root,
        )
        if not bool(getattr(self, "_catalog_refresh_waiting", False)):
            self._guided_setup_catalog_refreshed()

    def _reload_selected_spreadsheet(self) -> None:
        spreadsheet_text = self.spreadsheet_path_var.get().strip()

        if spreadsheet_text:
            spreadsheet_path = Path(spreadsheet_text)

            if spreadsheet_path.exists():
                self.import_existing_spreadsheet(
                    spreadsheet_path
                )
                return

        self.import_existing_spreadsheet()

