    def _configure_tray(self) -> None:
        if pystray is None or Image is None:
            return

        selected_image = (
            self.app_icon_tracking_image
            if self.tracking_icon_active
            else self.app_icon_idle_image
        )
        if selected_image is not None:
            image = selected_image.resize(
                (64, 64),
                Image.Resampling.LANCZOS,
            )
        else:
            image = Image.new(
                "RGB",
                (64, 64),
                (224, 44, 38),
            )

        menu = pystray.Menu(
            pystray.MenuItem(
                "Show",
                self.show_from_tray,
                default=True,
            ),
            pystray.MenuItem(
                "Exit",
                self.exit_from_tray,
            ),
        )

        self.tray_icon = pystray.Icon(
            "SMWStreamTracker",
            image,
            APP_NAME,
            menu,
        )

        threading.Thread(
            target=self.tray_icon.run,
            daemon=True,
        ).start()

    def save_settings(self) -> bool:
        try:
            idle_seconds = int(self.idle_seconds_var.get().strip())
            if idle_seconds < 0:
                raise ValueError
        except ValueError:
            messagebox.showerror(
                APP_NAME,
                "Timer grace must be a whole number that is 0 or greater.",
            )
            return False

        try:
            game_port = int(self.game_livesplit_port_var.get().strip())
            level_port = int(self.level_livesplit_port_var.get().strip())

            if not (1 <= game_port <= 65535):
                raise ValueError
            if not (1 <= level_port <= 65535):
                raise ValueError
            if game_port == level_port:
                raise ValueError

        except ValueError:
            messagebox.showerror(
                APP_NAME,
                "LiveSplit ports must be different numbers "
                "between 1 and 65535.",
            )
            return False

        updated_config = dict(self.config)
        updated_config.update(
            {
                "sni_path": self.sni_path_var.get().strip(),
                "qusb2snes_path": self.qusb_path_var.get().strip(),
                "connection_service_preference": (
                    self.connection_service_var.get().strip()
                    or "Automatic"
                ),
                "spreadsheet_path": (
                    self.spreadsheet_path_var.get().strip()
                ),
                "output_folder": (
                    self.output_folder_var.get().strip()
                ),
                "timer_grace_seconds": idle_seconds,
                "overworld_idle_seconds": idle_seconds,
                "livesplit_host": "127.0.0.1",
                "game_livesplit_port": game_port,
                "level_livesplit_port": level_port,
                "ui_theme": self.appearance_var.get(),
                "selected_platform": self.platform_var.get(),
            }
        )
        updated_config["platform_interface_path"] = (
            preferred_connection_service_path(updated_config)
        )
        self.config = updated_config
        save_config(self.config)
        try:
            ensure_obs_text_files(self.config)
        except OSError as error:
            messagebox.showerror(
                APP_NAME,
                f"Could not create the OBS text files:\n{error}",
                parent=self.root,
            )
            return False
        if self.worker is not None:
            self.worker.config.update(self.config)
        return True

    def parse_timer_override(self, value: str) -> float:
        cleaned = value.strip()

        if not cleaned:
            raise ValueError

        parts = cleaned.split(":")

        if len(parts) == 1:
            seconds = float(parts[0])
            if seconds < 0:
                raise ValueError
            return seconds

        if len(parts) == 2:
            minutes = int(parts[0])
            seconds = float(parts[1])

            if minutes < 0 or not 0 <= seconds < 60:
                raise ValueError

            return (minutes * 60) + seconds

        if len(parts) == 3:
            hours = int(parts[0])
            minutes = int(parts[1])
            seconds = float(parts[2])

            if (
                hours < 0
                or not 0 <= minutes < 60
                or not 0 <= seconds < 60
            ):
                raise ValueError

            return (hours * 3600) + (minutes * 60) + seconds

        raise ValueError

    def apply_timer_overrides(self) -> None:
        game_text = (
            self.game_time_override_var.get().strip()
        )
        level_text = (
            self.level_time_override_var.get().strip()
        )
        level_deaths_text = (
            self.level_deaths_override_var.get().strip()
        )
        total_deaths_text = (
            self.total_deaths_override_var.get().strip()
        )

        if not any(
            (
                game_text,
                level_text,
                level_deaths_text,
                total_deaths_text,
            )
        ):
            messagebox.showerror(
                APP_NAME,
                (
                    "Enter at least one timer or death-counter value "
                    "before applying the override."
                ),
                parent=self.root,
            )
            return

        game_seconds: float | None = None
        level_seconds: float | None = None
        level_deaths: int | None = None
        total_deaths: int | None = None

        if game_text:
            try:
                game_seconds = self.parse_timer_override(
                    game_text
                )
            except ValueError:
                messagebox.showerror(
                    APP_NAME,
                    (
                        "The Game Time override is invalid.\n\n"
                        "Use SS, MM:SS, or H:MM:SS.\n"
                        "Examples: 45, 12:34, or 1:02:30"
                    ),
                    parent=self.root,
                )
                return

        if level_text:
            try:
                level_seconds = self.parse_timer_override(
                    level_text
                )
            except ValueError:
                messagebox.showerror(
                    APP_NAME,
                    (
                        "The Level Time override is invalid.\n\n"
                        "Use SS, MM:SS, or H:MM:SS.\n"
                        "Examples: 45, 12:34, or 1:02:30"
                    ),
                    parent=self.root,
                )
                return

        for label, text_value, target_name in (
            (
                "Level Deaths",
                level_deaths_text,
                "level_deaths",
            ),
            (
                "Total Deaths",
                total_deaths_text,
                "total_deaths",
            ),
        ):
            if not text_value:
                continue
            try:
                parsed_value = int(text_value)
                if parsed_value < 0:
                    raise ValueError
            except ValueError:
                messagebox.showerror(
                    APP_NAME,
                    (
                        f"The {label} override is invalid.\n\n"
                        "Enter a whole number that is 0 or greater."
                    ),
                    parent=self.root,
                )
                return
            if target_name == "level_deaths":
                level_deaths = parsed_value
            else:
                total_deaths = parsed_value

        if not self.worker:
            messagebox.showerror(
                APP_NAME,
                (
                    "The tracker is reconnecting. Try the "
                    "override again in a moment."
                ),
                parent=self.root,
            )
            return

        self.worker.override_timers(
            game_seconds=game_seconds,
            level_seconds=level_seconds,
            level_deaths=level_deaths,
            total_deaths=total_deaths,
        )

        targets: list[str] = []
        if game_seconds is not None:
            targets.append("game timer")
        if level_seconds is not None:
            targets.append("level timer")
        if level_deaths is not None:
            targets.append("level deaths")
        if total_deaths is not None:
            targets.append("total deaths")

        self.status_var.set(
            "Applying "
            + " and ".join(targets)
            + " override…"
        )

    def apply_idle_time(self) -> None:
        try:
            idle_seconds = int(self.idle_seconds_var.get().strip())
            if idle_seconds < 0:
                raise ValueError
        except ValueError:
            messagebox.showerror(
                APP_NAME,
                "Timer grace must be a whole number "
                "that is 0 or greater.",
            )
            return

        self.config["timer_grace_seconds"] = idle_seconds
        self.config["overworld_idle_seconds"] = idle_seconds
        save_config(self.config)

        if self.worker:
            self.worker.config["timer_grace_seconds"] = idle_seconds
            self.worker.config["overworld_idle_seconds"] = idle_seconds

        self.status_var.set(
            f"Timer grace set to {idle_seconds} seconds."
        )

    def toggle_pause_timers(self) -> None:
        if self.worker:
            self.worker.toggle_pause_timers()

