        def draw_title_gradient(event=None) -> None:
            width = max(
                1,
                title_gradient.winfo_width(),
            )
            height = max(
                1,
                title_gradient.winfo_height(),
            )
            color_stops = (
                THEME["red"],
                THEME["orange"],
                THEME["yellow"],
                THEME["green"],
                THEME["blue"],
                THEME["purple"],
            )
            title_gradient.delete(
                "tracker_title_gradient"
            )
            steps = min(
                180,
                max(
                    24,
                    width,
                ),
            )
            for step in range(steps):
                overall = (
                    step
                    / max(
                        1,
                        steps - 1,
                    )
                )
                scaled = overall * (
                    len(color_stops) - 1
                )
                segment = min(
                    len(color_stops) - 2,
                    int(scaled),
                )
                fraction = (
                    scaled - segment
                )
                start_x = round(
                    width * step / steps
                )
                end_x = round(
                    width
                    * (step + 1)
                    / steps
                )
                title_gradient.create_rectangle(
                    start_x,
                    0,
                    max(
                        start_x + 1,
                        end_x,
                    ),
                    height,
                    fill=blend_hex_colors(
                        color_stops[segment],
                        color_stops[
                            segment + 1
                        ],
                        fraction,
                    ),
                    outline="",
                    tags=(
                        "tracker_title_gradient",
                    ),
                )

