    def _refresh_my_tracker_appearance(self) -> None:
        """Apply the active light/dark palette to the open tracker window."""
        dialog = self.tracker_list_dialog
        if dialog is None:
            return

        try:
            if not dialog.winfo_exists():
                return
        except tk.TclError:
            return

        dark_mode = self.appearance_var.get() == "dark"
        palette = self._library_palette()
        border_color = self._tracker_grid_border_color()

        try:
            # Update every ordinary Tk child first, then set the tracker-specific
            # surfaces explicitly so similarly colored entries and panels retain
            # their intended roles in both appearance modes.
            self._apply_widget_appearance(
                dialog,
                dark=dark_mode,
            )
            dialog.configure(bg=palette["window"])

            for widget_key, background in (
                ("filters", palette["panel"]),
                ("tree_frame", palette["panel"]),
                ("spreadsheet_bar", palette["window"]),
                ("button_bar", palette["window"]),
                ("legacy_note_frame", palette["window"]),
            ):
                widget = self.tracker_list_widgets.get(
                    widget_key
                )
                if widget is not None:
                    widget.configure(bg=background)

            search_entry = self.tracker_list_widgets.get(
                "search_entry"
            )
            if search_entry is not None:
                search_entry.configure(
                    bg=palette["entry"],
                    fg=palette["text"],
                    insertbackground=palette["text"],
                    highlightbackground=palette["border"],
                    highlightcolor=palette["selected"],
                    selectbackground=palette["selected"],
                    selectforeground="#FFFFFF",
                )

            button_hint_label = self.tracker_list_widgets.get(
                "button_hint_label"
            )
            if button_hint_label is not None:
                button_hint_label.configure(
                    bg=palette["window"],
                    fg=palette["muted"],
                )

            legacy_note_label = self.tracker_list_widgets.get(
                "legacy_note_label"
            )
            if legacy_note_label is not None:
                legacy_note_label.configure(
                    bg=palette["window"],
                    fg=palette["muted"],
                )
            legacy_note_star = self.tracker_list_widgets.get(
                "legacy_note_star"
            )
            if legacy_note_star is not None:
                legacy_note_star.configure(
                    bg=palette["window"],
                    fg=THEME["yellow"],
                )

            tree_frame = self.tracker_list_widgets.get(
                "tree_frame"
            )
            if tree_frame is not None:
                tree_frame.configure(
                    highlightbackground=border_color
                )

            right_edge_border = self.tracker_list_widgets.get(
                "right_edge_border"
            )
            if right_edge_border is not None:
                right_edge_border.configure(
                    bg=border_color
                )

            tracker_style = ttk.Style(dialog)
            tracker_style.configure(
                "MyTracker.Treeview",
                background=palette["tree"],
                fieldbackground=palette["tree"],
                foreground=palette["text"],
                bordercolor=border_color,
                lightcolor=border_color,
                darkcolor=border_color,
            )
            tracker_style.map(
                "MyTracker.Treeview",
                background=[
                    ("selected", palette["selected"])
                ],
                foreground=[
                    ("selected", "#FFFFFF")
                ],
            )
            tracker_style.configure(
                "MyTracker.Treeview.Heading",
                background=THEME["navy"],
                foreground="#FFFFFF",
                bordercolor=border_color,
                lightcolor=border_color,
                darkcolor=border_color,
            )
            tracker_style.configure(
                "MyTracker.TCombobox",
                fieldbackground=palette["entry"],
                background=THEME["blue"],
                foreground=palette["text"],
                arrowcolor="#FFFFFF",
                bordercolor=palette["border"],
                lightcolor=palette["border"],
                darkcolor=palette["border"],
                arrowsize=self._ui_px(21),
            )
            tracker_style.map(
                "MyTracker.TCombobox",
                fieldbackground=[
                    ("readonly", palette["entry"])
                ],
                foreground=[
                    ("readonly", palette["text"])
                ],
                selectbackground=[
                    ("readonly", palette["selected"])
                ],
                selectforeground=[
                    ("readonly", "#FFFFFF")
                ],
            )
        except tk.TclError:
            return

        # Rebuild the rows and custom canvases so all alternating fills, rating
        # bars, and difficulty cells switch to their light/dark variants too.
        self._refresh_my_tracker()

    def _refresh_my_tracker(self) -> None:
        if not self.tracker_list_widgets:
            return

        tree = self.tracker_list_widgets.get("tree")

        if tree is None:
            self._hide_tracker_paint_cover()
            return

        self._show_tracker_paint_cover()
        self.tracker_overlay_retry_count = 0
        self._clear_tracker_cell_overlays()
        tree.delete(*tree.get_children(""))
        self.tracker_list_records = {}
        search_text = self.tracker_list_widgets[
            "search_var"
        ].get().casefold().strip()
        status_filter = self.tracker_list_widgets[
            "status_filter"
        ].get()
        difficulty_filter = self.tracker_list_widgets[
            "difficulty_filter"
        ].get()
        type_filter = self.tracker_list_widgets[
            "type_filter"
        ].get()
        letter_filter = self.tracker_list_widgets[
            "letter_filter"
        ].get()
        visible = 0

        for record in self.stats_db.list_tracked():
            haystack = (
                str(record["title"])
                + " "
                + str(record["author"])
            ).casefold()

            if search_text and search_text not in haystack:
                continue

            if (
                letter_filter != "All"
                and self._alphabet_segment(str(record["title"]))
                != letter_filter
            ):
                continue

            if (
                status_filter != "Any"
                and str(record["status"])
                != status_filter
            ):
                continue

            if (
                difficulty_filter != "Any"
                and str(record["difficulty"])
                != difficulty_filter
            ):
                continue

            if type_filter != "Any":
                type_tokens = {
                    token.strip().casefold()
                    for token in str(
                        record["hack_type"]
                    ).split(",")
                    if token.strip()
                }

                if type_filter.casefold() not in type_tokens:
                    continue

            iid = "tracked::" + str(record["id"])
            personal_rating = record["personal_rating"]
            smwc_rating = record["smwc_rating"]
            total_exits = max(
                0,
                int(record["total_exits"] or 0),
            )
            completed_exits = max(
                0,
                int(record["completed_exits"] or 0),
            )
            percentage_complete = (
                min(
                    100,
                    round(
                        completed_exits
                        / total_exits
                        * 100
                    ),
                )
                if total_exits > 0
                else 0
            )
            difficulty_name = str(
                record["difficulty"] or "Unknown"
            )
            display_record = dict(record)
            display_record[
                "_percentage_complete"
            ] = percentage_complete
            display_record[
                "_difficulty_name"
            ] = difficulty_name
            display_record[
                "_personal_rating_value"
            ] = (
                float(personal_rating)
                if personal_rating is not None
                else None
            )
            display_record[
                "_smwc_rating_value"
            ] = (
                float(smwc_rating)
                if smwc_rating is not None
                else None
            )
            total_deaths = record.get("total_deaths")
            legacy_death_count = bool(
                record.get("death_count_legacy")
            ) and total_deaths is None
            display_record["_legacy_death_count"] = (
                legacy_death_count
            )
            self.tracker_list_records[
                iid
            ] = display_record

            hack_number = (
                int(record["display_order"])
                if record["display_order"]
                not in (None, "")
                else int(record["id"])
            )
            tree.insert(
                "",
                "end",
                iid=iid,
                text=str(hack_number),
                values=(
                    str(record["title"]),
                    str(record["author"]),
                    difficulty_name,
                    str(record["hack_type"]),
                    (
                        str(completed_exits)
                        + "/"
                        + str(total_exits)
                    ),
                    (
                        "*"
                        if legacy_death_count
                        else (
                            str(max(0, int(total_deaths)))
                            if total_deaths is not None
                            else "—"
                        )
                    ),
                    f"{percentage_complete}%",
                    (
                        f"{float(personal_rating):.2f}"
                        .rstrip("0")
                        .rstrip(".")
                        if personal_rating is not None
                        else "—"
                    ),
                    format_timer(
                        int(record["playtime_seconds"] or 0),
                        False,
                    ),
                    format_display_date(
                        record["date_started"]
                    ),
                    format_display_date(
                        record["date_completed"]
                    ),
                    (
                        f"{float(smwc_rating):.2f}"
                        .rstrip("0")
                        .rstrip(".")
                        if smwc_rating is not None
                        else "\u2014"
                    ),
                ),
            )
            if smwc_rating is None:
                tree.set(
                    iid,
                    "smwc_rating",
                    "\u2014",
                )
            self._apply_difficulty_color_to_tree_item(
                tree,
                iid,
                str(record["difficulty"]),
            )
            visible += 1

        self.tracker_list_widgets["count_var"].set(
            self._format_ui_text(
                "{count} hack(s)",
                count=f"{visible:,}",
            )
        )
        self._reapply_treeview_sorting(tree)
        self._schedule_tracker_cell_overlays()

    def _show_tracker_paint_cover(self) -> None:
        """Keep raw Treeview row colors hidden until its cell canvas is ready."""
        cover = self.tracker_list_widgets.get("paint_cover")
        tree = self.tracker_list_widgets.get("tree")
        if cover is None or tree is None:
            return
        if self.tracker_paint_cover_after_id is not None:
            try:
                self.root.after_cancel(self.tracker_paint_cover_after_id)
            except tk.TclError:
                pass
            self.tracker_paint_cover_after_id = None
        try:
            cover.configure(bg=self._library_palette()["tree"])
            cover.place(x=0, y=0, relwidth=1.0, relheight=1.0)
            cover.lift()
            # Never leave the table covered if a destroyed window or unusual
            # theme callback interrupts its normal overlay render.
            self.tracker_paint_cover_after_id = self.root.after(
                1500,
                self._hide_tracker_paint_cover,
            )
        except tk.TclError:
            self.tracker_paint_cover_after_id = None

    def _hide_tracker_paint_cover(self) -> None:
        pending = self.tracker_paint_cover_after_id
        self.tracker_paint_cover_after_id = None
        if pending is not None:
            try:
                self.root.after_cancel(pending)
            except tk.TclError:
                pass
        cover = self.tracker_list_widgets.get("paint_cover")
        if cover is not None:
            try:
                cover.place_forget()
            except tk.TclError:
                pass

    def _clear_tracker_cell_overlays(self) -> None:
        overlays = self.tracker_list_widgets.get(
            "cell_overlays",
            {},
        )

        for overlay in overlays.values():
            try:
                overlay.destroy()
            except tk.TclError:
                pass

        if self.tracker_list_widgets:
            self.tracker_list_widgets[
                "cell_overlays"
            ] = {}

    def _tracker_grid_border_color(
        self,
    ) -> str:
        return self._table_grid_line_color()

    def _tracker_column_label(
        self,
        column: str,
    ) -> str:
        return {
            "#0": "Hack #",
            "title": "ROM Hack Title",
            "author": "Created By",
            "difficulty": "Difficulty",
            "type": "Type",
            "exits": "Completed Exits",
            "deaths": "Total Deaths",
            "percentage": "% Complete",
            "rating": "My Rating",
            "playtime": "Playtime",
            "started": "Started",
            "completed": "Completed",
            "smwc_rating": "SMW Central Rating",
        }.get(column, "Tracker")

    @staticmethod
    def _tracker_rating_bar_percentage(
        rating: float,
    ) -> int:
        rating_value = max(
            0.0,
            min(5.0, float(rating)),
        )
        return min(
            100,
            round(rating_value / 5.0 * 100),
        )

    def _tracker_custom_style(
        self,
        column: str,
    ) -> dict[str, str] | None:
        styles = self.config.get(
            "tracker_column_styles",
            {},
        )
        if not isinstance(styles, dict):
            return None

        style = styles.get(column)
        if not isinstance(style, dict):
            style = styles.get("*")
        if not isinstance(style, dict):
            return None

        mode = str(style.get("mode", "solid"))
        start = str(style.get("start", ""))
        end = str(style.get("end", ""))
        if not re.fullmatch(r"#[0-9A-Fa-f]{6}", start):
            return None
        if not re.fullmatch(r"#[0-9A-Fa-f]{6}", end):
            end = start

        # "Use Overview alternating colors" is a semantic theme choice, not
        # a request to permanently store whichever dark/light hex values were
        # active at the time. Recognize both newly marked styles and existing
        # saved Overview pairs so older configurations follow Appearance too.
        normalized_pair = (
            start.upper(),
            end.upper(),
        )
        overview_pairs = {
            ("#101827", "#1D2A40"),
            ("#FFFFFF", "#ECF6FF"),
        }
        theme_linked = (
            bool(style.get("theme_linked"))
            or (
                mode == "alternating"
                and normalized_pair in overview_pairs
            )
        )
        if theme_linked:
            palette = self._library_palette()
            start = palette["tree"]
            end = palette["panel_alt"]

        return {
            "mode": (
                mode
                if mode in {
                    "solid",
                    "gradient",
                    "alternating",
                    "data_bar",
                }
                else "solid"
            ),
            "start": start.upper(),
            "end": end.upper(),
        }

    def _tracker_difficulty_color(
        self,
        difficulty: str,
    ) -> str | None:
        colors = self.config.get(
            "tracker_difficulty_colors",
            {},
        )
        if not isinstance(colors, dict):
            return None
        selected = str(colors.get(difficulty, ""))
        if not re.fullmatch(
            r"#[0-9A-Fa-f]{6}",
            selected,
        ):
            return None
        return selected.upper()

    def _effective_difficulty_color(
        self,
        difficulty: str,
        fallback: str | None = None,
    ) -> str:
        """Return the user's shared color for a difficulty, or its default."""
        difficulty_name = str(difficulty or "Unknown").strip() or "Unknown"
        selected = self._tracker_difficulty_color(
            difficulty_name
        )
        if selected is not None:
            return selected
        if fallback is not None:
            return fallback
        return DIFFICULTY_ROW_COLORS.get(
            difficulty_name,
            DIFFICULTY_ROW_COLORS["Unknown"],
        )[0]

    def _refresh_current_difficulty_color(self) -> None:
        label = getattr(
            self,
            "current_difficulty_label",
            None,
        )
        if label is None:
            return
        try:
            if not label.winfo_exists():
                return
        except tk.TclError:
            return

        display_text = str(self.difficulty_var.get()).strip()
        difficulty_name = display_text
        if ":" in display_text:
            difficulty_name = display_text.split(":", 1)[1].strip()
        difficulty_name = difficulty_name or "Unknown"
        custom_color = self._tracker_difficulty_color(
            difficulty_name
        )
        if custom_color is not None:
            background = custom_color
            foreground = self._tracker_contrast_text_color(
                custom_color
            )
        else:
            background, foreground = DIFFICULTY_ROW_COLORS.get(
                difficulty_name,
                DIFFICULTY_ROW_COLORS["Unknown"],
            )
        try:
            label.configure(
                bg=background,
                fg=foreground,
            )
        except tk.TclError:
            pass

    def _apply_difficulty_color_to_tree_item(
        self,
        tree: ttk.Treeview,
        iid: str,
        difficulty: str,
    ) -> None:
        """Apply a saved difficulty color to a Treeview row when needed."""
        try:
            existing_tags = tuple(
                tag
                for tag in tree.item(iid, "tags")
                if not str(tag).startswith(
                    "difficulty_palette_"
                )
            )
        except tk.TclError:
            return

        custom_color = self._tracker_difficulty_color(
            str(difficulty or "Unknown").strip() or "Unknown"
        )
        if custom_color is None:
            try:
                tree.item(iid, tags=existing_tags)
            except tk.TclError:
                pass
            return

        tag_name = (
            "difficulty_palette_"
            + custom_color.lstrip("#")
        )
        try:
            tree.tag_configure(
                tag_name,
                background=custom_color,
                foreground=self._tracker_contrast_text_color(
                    custom_color
                ),
            )
            tree.item(
                iid,
                tags=(*existing_tags, tag_name),
            )
        except tk.TclError:
            pass

    def _refresh_difficulty_color_surfaces(self) -> None:
        """Refresh every open view that displays difficulty colors."""
        self._refresh_current_difficulty_color()
        self._schedule_tracker_cell_overlays()

        stats_widgets = getattr(
            self,
            "stats_overview_widgets",
            {},
        )
        if isinstance(stats_widgets, dict):
            difficulty_tree = stats_widgets.get(
                "difficulty_tree"
            )
            if difficulty_tree is not None:
                self._apply_statistics_table_colors(
                    difficulty_tree,
                    "difficulty",
                )
            redraw_graph = stats_widgets.get(
                "redraw_difficulty_graph"
            )
            if callable(redraw_graph):
                try:
                    redraw_graph()
                except tk.TclError:
                    pass

        custom_tree = self.custom_hacks_widgets.get("tree")
        if custom_tree is not None:
            self._apply_statistics_table_colors(
                custom_tree,
                "unmoderated_hacks",
            )

        library_tree = self.game_library_widgets.get("tree")
        if library_tree is not None:
            self._schedule_game_library_difficulty_overlays()

        downloader_tree = self.downloader_widgets.get("tree")
        if downloader_tree is not None:
            downloader_table_key = (
                "complete_catalog"
                if self.downloader_widgets.get("catalog_view_only", False)
                else "missing_hacks"
            )
            self._apply_statistics_table_colors(
                downloader_tree,
                downloader_table_key,
            )
            self._schedule_downloader_difficulty_overlays()

    def _set_tracker_difficulty_color(
        self,
        difficulty: str,
    ) -> None:
        parent = (
            self.tracker_list_dialog
            or self.stats_overview_dialog
            or self.downloader_dialog
            or self.root
        )
        current = self._tracker_difficulty_color(
            difficulty
        )
        default_color = DIFFICULTY_ROW_COLORS.get(
            difficulty,
            DIFFICULTY_ROW_COLORS["Unknown"],
        )[0]
        _rgb, selected = colorchooser.askcolor(
            color=current or default_color,
            title=self._format_ui_text(
                "Choose the color for all {difficulty} hacks",
                difficulty=difficulty,
            ),
            parent=parent,
        )
        if not selected:
            return

        raw_colors = self.config.get(
            "tracker_difficulty_colors",
            {},
        )
        colors = (
            dict(raw_colors)
            if isinstance(raw_colors, dict)
            else {}
        )
        colors[difficulty] = str(selected).upper()
        self.config["tracker_difficulty_colors"] = colors

        # A former whole-column or whole-table style would otherwise cover
        # the value-specific colors. Keep an explicit default override for
        # the Difficulty column so these choices remain visible.
        raw_styles = self.config.get(
            "tracker_column_styles",
            {},
        )
        styles = (
            dict(raw_styles)
            if isinstance(raw_styles, dict)
            else {}
        )
        if (
            isinstance(styles.get("difficulty"), dict)
            or isinstance(styles.get("*"), dict)
        ):
            styles["difficulty"] = {"mode": "default"}
            self.config["tracker_column_styles"] = styles

        save_config(self.config)
        self._refresh_difficulty_color_surfaces()

    def _reset_tracker_difficulty_color(
        self,
        difficulty: str | None = None,
    ) -> None:
        raw_colors = self.config.get(
            "tracker_difficulty_colors",
            {},
        )
        colors = (
            dict(raw_colors)
            if isinstance(raw_colors, dict)
            else {}
        )
        if difficulty is None:
            colors.clear()
        else:
            colors.pop(difficulty, None)
        self.config["tracker_difficulty_colors"] = colors
        save_config(self.config)
        self._refresh_difficulty_color_surfaces()

    def _tracker_contrast_text_color(
        self,
        start_color: str,
        end_color: str | None = None,
    ) -> str:
        colors = (
            start_color,
            end_color or start_color,
        )
        brightness_values = []
        for color in colors:
            value = color.lstrip("#")
            try:
                red, green, blue = (
                    int(value[index:index + 2], 16)
                    for index in (0, 2, 4)
                )
            except (TypeError, ValueError):
                return "#FFFFFF"
            brightness_values.append(
                red * 0.299
                + green * 0.587
                + blue * 0.114
            )

        return (
            "#102037"
            if sum(brightness_values)
            / len(brightness_values)
            >= 155
            else "#FFFFFF"
        )

    def _set_tracker_column_style(
        self,
        target: str,
        mode: str,
    ) -> None:
        parent = self.tracker_list_dialog or self.root
        current = self._tracker_custom_style(target)
        palette = self._library_palette()
        if mode == "data_bar":
            if target == "smwc_rating":
                fallback_start = (
                    TRACKER_SMWC_RATING_GRADIENT_START
                )
                fallback_end = (
                    TRACKER_SMWC_RATING_GRADIENT_END
                )
            elif target == "rating":
                fallback_start = (
                    TRACKER_RATING_GRADIENT_START
                )
                fallback_end = (
                    TRACKER_RATING_GRADIENT_END
                )
            else:
                fallback_start = (
                    TRACKER_PERCENT_GRADIENT_START
                )
                fallback_end = (
                    TRACKER_PERCENT_GRADIENT_END
                )
        else:
            fallback_start = palette["tree"]
            fallback_end = palette["panel_alt"]
        default_start = (
            current["start"]
            if current is not None
            else fallback_start
        )
        label = (
            "all tracker columns"
            if target == "*"
            else self._tracker_column_label(target)
        )
        _rgb, start_color = colorchooser.askcolor(
            color=default_start,
            title=self._format_ui_text(
                (
                    "Choose {label} data-bar starting color"
                    if mode == "data_bar"
                    else "Choose {label} color"
                ),
                label=label,
            ),
            parent=parent,
        )
        if not start_color:
            return

        start_color = str(start_color).upper()
        end_color = start_color
        if mode in {
            "gradient",
            "alternating",
            "data_bar",
        }:
            default_end = (
                current["end"]
                if current is not None
                else fallback_end
            )
            _rgb, selected_end = colorchooser.askcolor(
                color=default_end,
                title=self._format_ui_text(
                    (
                        "Choose {label} data-bar ending color"
                        if mode == "data_bar"
                        else "Choose {label} ending color"
                        if mode == "gradient"
                        else "Choose {label} alternate-row color"
                    ),
                    label=label,
                ),
                parent=parent,
            )
            if not selected_end:
                return
            end_color = str(selected_end).upper()

        raw_styles = self.config.get(
            "tracker_column_styles",
            {},
        )
        styles = (
            dict(raw_styles)
            if isinstance(raw_styles, dict)
            else {}
        )
        if target == "*":
            styles.clear()
        styles[target] = {
            "mode": (
                mode
                if mode in {
                    "gradient",
                    "alternating",
                    "data_bar",
                }
                else "solid"
            ),
            "start": start_color,
            "end": end_color,
        }
        self.config["tracker_column_styles"] = styles
        save_config(self.config)
        self._schedule_tracker_cell_overlays()

    def _set_tracker_overview_alternating_colors(
        self,
    ) -> None:
        palette = self._library_palette()
        self.config["tracker_column_styles"] = {
            "*": {
                "mode": "alternating",
                "start": palette["tree"],
                "end": palette["panel_alt"],
                "theme_linked": True,
            }
        }
        save_config(self.config)
        self._schedule_tracker_cell_overlays()

    def _reset_tracker_column_style(
        self,
        target: str,
    ) -> None:
        raw_styles = self.config.get(
            "tracker_column_styles",
            {},
        )
        styles = (
            dict(raw_styles)
            if isinstance(raw_styles, dict)
            else {}
        )
        if target == "*":
            styles.clear()
        elif isinstance(styles.get("*"), dict):
            # Keep a deliberate per-column reset even while an
            # entire-table color is active.
            styles[target] = {"mode": "default"}
        else:
            styles.pop(target, None)
        self.config["tracker_column_styles"] = styles
        save_config(self.config)
        self._schedule_tracker_cell_overlays()

    def _tracker_column_at_event(
        self,
        event,
    ) -> str:
        tree = self.tracker_list_widgets.get("tree")
        if tree is None:
            return "title"
        try:
            display_column = str(
                tree.identify_column(int(event.x))
            )
        except tk.TclError:
            return "title"
        if display_column == "#0":
            return "#0"
        try:
            index = int(display_column[1:]) - 1
        except (TypeError, ValueError):
            return "title"
        columns = tuple(tree["columns"])
        if 0 <= index < len(columns):
            return str(columns[index])
        return "title"

    def _remember_tracker_cell(self, iid: str, column: str) -> None:
        if iid:
            self.tracker_list_widgets["active_cell"] = (
                str(iid),
                str(column),
            )

    def _active_tracker_cell(self) -> tuple[str, str]:
        active = self.tracker_list_widgets.get("active_cell")
        if (
            isinstance(active, tuple)
            and len(active) == 2
            and active[0] in self.tracker_list_records
        ):
            return str(active[0]), str(active[1])
        tree = self.tracker_list_widgets.get("tree")
        if tree is not None:
            try:
                selected = tree.selection()
            except tk.TclError:
                selected = ()
            if selected:
                return str(selected[0]), "title"
        return "", ""

    def _copy_tracker_cell(self) -> str:
        tree = self.tracker_list_widgets.get("tree")
        iid, column = self._active_tracker_cell()
        if tree is None or not iid:
            return "break"
        value = self._treeview_display_value(tree, iid, column)
        try:
            self.root.clipboard_clear()
            self.root.clipboard_append(value)
        except tk.TclError:
            pass
        return "break"

    def _add_table_appearance_menu_items(
        self,
        menu: tk.Menu,
        tree: ttk.Treeview,
        table_key: str,
    ) -> None:
        """Add persistent whole-table appearance controls to a menu."""
        label = self._statistics_table_label(table_key)
        menu.add_command(
            label=f"Solid color for {label}...",
            command=lambda: self._set_statistics_table_style(
                tree,
                table_key,
                "solid",
            ),
        )
        menu.add_command(
            label=f"Two-color gradient for {label}...",
            command=lambda: self._set_statistics_table_style(
                tree,
                table_key,
                "gradient",
            ),
        )
        menu.add_command(
            label=f"Alternating row colors for {label}...",
            command=lambda: self._set_statistics_table_style(
                tree,
                table_key,
                "alternating",
            ),
        )
        menu.add_command(
            label="Use Overview alternating colors",
            command=lambda: self._set_statistics_overview_alternating(
                tree,
                table_key,
            ),
        )
        menu.add_separator()
        menu.add_command(
            label="Restore default table colors",
            command=lambda: self._reset_statistics_table_style(
                tree,
                table_key,
            ),
        )

    def _show_table_appearance_menu(
        self,
        event,
        tree: ttk.Treeview,
        table_key: str,
    ) -> str:
        """Show the shared appearance menu used by non-tracker tables."""
        palette = self._library_palette()
        menu = tk.Menu(
            self._table_style_parent(table_key),
            tearoff=False,
            bg=palette["panel"],
            fg=palette["text"],
            activebackground=THEME["blue"],
            activeforeground="#FFFFFF",
            font=("Segoe UI", 10),
        )
        self._add_table_appearance_menu_items(menu, tree, table_key)
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                menu.grab_release()
            except tk.TclError:
                pass
        return "break"

    def _register_customizable_table(
        self,
        tree: ttk.Treeview,
        table_key: str,
        *,
        after_style=None,
    ) -> None:
        """Enable persistent right-click colors for an application table."""
        tree._smw_table_style_key = table_key
        tree._smw_after_table_style = after_style
        tree.bind(
            "<Button-3>",
            lambda event: self._show_table_appearance_menu(
                event,
                tree,
                table_key,
            ),
            add="+",
        )
        self._apply_statistics_table_colors(tree, table_key)

    def _statistics_rate_bar_style(self) -> dict[str, str]:
        raw_style = self.config.get("statistics_rate_bar_style", {})
        style = raw_style if isinstance(raw_style, dict) else {}
        start = str(
            style.get("start", TRACKER_PERCENT_GRADIENT_START)
        ).upper()
        end = str(
            style.get("end", TRACKER_PERCENT_GRADIENT_END)
        ).upper()
        if not re.fullmatch(r"#[0-9A-F]{6}", start):
            start = TRACKER_PERCENT_GRADIENT_START
        if not re.fullmatch(r"#[0-9A-F]{6}", end):
            end = TRACKER_PERCENT_GRADIENT_END
        return {"start": start, "end": end}

    def _set_statistics_rate_bar_style(
        self,
        tree: ttk.Treeview,
    ) -> None:
        current = self._statistics_rate_bar_style()
        parent = self.stats_overview_dialog or self.root
        _rgb, start = colorchooser.askcolor(
            color=current["start"],
            title=self._format_ui_text(
                "Choose {label} data-bar starting color",
                label="Rate",
            ),
            parent=parent,
        )
        if not start:
            return
        _rgb, end = colorchooser.askcolor(
            color=current["end"],
            title=self._format_ui_text(
                "Choose {label} data-bar ending color",
                label="Rate",
            ),
            parent=parent,
        )
        if not end:
            return
        self.config["statistics_rate_bar_style"] = {
            "start": str(start).upper(),
            "end": str(end).upper(),
        }
        save_config(self.config)
        self._schedule_statistics_difficulty_overlays(tree)

    def _reset_statistics_rate_bar_style(
        self,
        tree: ttk.Treeview,
    ) -> None:
        self.config.pop("statistics_rate_bar_style", None)
        save_config(self.config)
        self._schedule_statistics_difficulty_overlays(tree)

    def _schedule_statistics_difficulty_overlays(
        self,
        tree: ttk.Treeview,
        event=None,
    ) -> None:
        pending = getattr(
            tree,
            "_smw_statistics_overlay_after_id",
            None,
        )
        if pending is not None:
            return
        try:
            tree._smw_statistics_overlay_after_id = self.root.after_idle(
                lambda: self._render_statistics_difficulty_overlays(tree)
            )
        except tk.TclError:
            pass

    def _statistics_row_background(
        self,
        tree: ttk.Treeview,
        iid: str,
        row_index: int,
    ) -> str:
        palette = self._library_palette()
        try:
            tags = tuple(tree.item(iid, "tags"))
        except tk.TclError:
            tags = ()
        for tag in tags:
            try:
                background = str(
                    tree.tag_configure(tag, "background") or ""
                )
            except tk.TclError:
                background = ""
            if background:
                return background
        return palette["tree"] if row_index % 2 == 0 else palette["panel_alt"]

    def _statistics_overlay_select(
        self,
        tree: ttk.Treeview,
        canvas: tk.Canvas,
        event,
    ) -> str:
        origin_y = int(getattr(canvas, "_smw_origin_y", 0) or 0)
        try:
            iid = str(tree.identify_row(event.y + origin_y) or "")
            if iid:
                tree.selection_set(iid)
                tree.focus(iid)
        except tk.TclError:
            pass
        self._schedule_statistics_difficulty_overlays(tree)
        return "break"

    def _statistics_overlay_scroll(
        self,
        tree: ttk.Treeview,
        event,
    ) -> str:
        units = self._fast_scroll_units(event)
        if units:
            try:
                tree.yview_scroll(units, "units")
            except tk.TclError:
                return "break"
            self._schedule_statistics_difficulty_overlays(tree)
        return "break"

    def _statistics_overlay_menu(
        self,
        tree: ttk.Treeview,
        column: str,
        event,
    ) -> str:
        self._statistics_overlay_select(tree, event.widget, event)
        event._smw_forced_column = column
        return self._show_statistics_table_color_menu(
            event,
            tree,
            "difficulty",
        )

    def _render_statistics_difficulty_overlays(
        self,
        tree: ttk.Treeview,
    ) -> None:
        tree._smw_statistics_overlay_after_id = None
        try:
            if not tree.winfo_exists():
                return
            tree_height = max(1, tree.winfo_height())
        except tk.TclError:
            return

        children = tuple(tree.get_children(""))
        visible: list[tuple[int, str]] = []
        for row_index, iid in enumerate(children):
            try:
                if tree.bbox(iid, "#0"):
                    visible.append((row_index, str(iid)))
            except tk.TclError:
                continue

        overlays = getattr(tree, "_smw_statistics_overlays", None)
        if not isinstance(overlays, dict):
            overlays = {}
            tree._smw_statistics_overlays = overlays
        if not visible:
            for canvas in overlays.values():
                try:
                    canvas.place_forget()
                except tk.TclError:
                    pass
            return

        palette = self._library_palette()
        selected = set(tree.selection())
        rate_style = self._statistics_rate_bar_style()
        for column in ("#0", "rate"):
            boxes: dict[str, tuple[int, int, int, int]] = {}
            row_indexes: dict[str, int] = {}
            for row_index, iid in visible:
                try:
                    box = tree.bbox(iid, column)
                except tk.TclError:
                    box = ()
                if box:
                    boxes[iid] = box
                    row_indexes[iid] = row_index
            if not boxes:
                continue

            reference_box = next(iter(boxes.values()))
            column_x = reference_box[0]
            column_width = reference_box[2]
            origin_y = min(box[1] for box in boxes.values())
            overlay_height = max(1, tree_height - origin_y)
            canvas = overlays.get(column)
            if canvas is None:
                canvas = tk.Canvas(
                    tree,
                    bd=0,
                    highlightthickness=0,
                    takefocus=False,
                )
                canvas.bind(
                    "<Button-1>",
                    lambda event, widget=canvas: self._statistics_overlay_select(
                        tree,
                        widget,
                        event,
                    ),
                )
                canvas.bind(
                    "<Button-3>",
                    lambda event, selected_column=column: self._statistics_overlay_menu(
                        tree,
                        selected_column,
                        event,
                    ),
                )
                for wheel_event in (
                    "<MouseWheel>",
                    "<Button-4>",
                    "<Button-5>",
                ):
                    canvas.bind(
                        wheel_event,
                        lambda event: self._statistics_overlay_scroll(
                            tree,
                            event,
                        ),
                    )
                overlays[column] = canvas

            canvas._smw_origin_y = origin_y
            canvas.configure(
                width=column_width,
                height=overlay_height,
                bg=palette["tree"],
            )
            canvas.place(
                x=column_x,
                y=origin_y,
                width=column_width,
                height=overlay_height,
            )
            canvas.delete("all")

            for iid, box in boxes.items():
                row_y = box[1] - origin_y
                row_height = box[3]
                row_index = row_indexes[iid]
                base_background = (
                    palette["selected"]
                    if iid in selected
                    else self._statistics_row_background(
                        tree,
                        iid,
                        row_index,
                    )
                )
                text = self._treeview_display_value(tree, iid, column)
                if column == "#0":
                    background = self._effective_difficulty_color(text)
                    foreground = self._tracker_contrast_text_color(background)
                    display_text = self._translate_ui_text(text)
                    canvas.create_rectangle(
                        0,
                        row_y,
                        column_width,
                        row_y + row_height,
                        fill=background,
                        outline=self._table_grid_line_color(),
                        width=1,
                    )
                else:
                    display_text = text
                    foreground = palette["text"]
                    canvas.create_rectangle(
                        0,
                        row_y,
                        column_width,
                        row_y + row_height,
                        fill=base_background,
                        outline=self._table_grid_line_color(),
                        width=1,
                    )
                    match = re.search(r"([0-9]+(?:\.[0-9]+)?)", text)
                    percentage = (
                        max(0, min(100, round(float(match.group(1)))))
                        if match
                        else 0
                    )
                    inner_width = max(0, column_width - 2)
                    filled_width = round(inner_width * percentage / 100)
                    if filled_width > 0:
                        gradient = self._tracker_gradient_photo(
                            canvas,
                            filled_width,
                            max(1, row_height - 3),
                            rate_style["start"],
                            rate_style["end"],
                        )
                        if gradient is not None:
                            canvas.create_image(
                                1,
                                row_y + 1,
                                image=gradient,
                                anchor="nw",
                            )
                        else:
                            canvas.create_rectangle(
                                1,
                                row_y + 1,
                                1 + filled_width,
                                row_y + row_height - 1,
                                fill=rate_style["start"],
                                outline="",
                            )
                        foreground = self._tracker_contrast_text_color(
                            blend_hex_colors(
                                rate_style["start"],
                                rate_style["end"],
                                0.5,
                            )
                        )
                        canvas.create_rectangle(
                            0,
                            row_y,
                            column_width,
                            row_y + row_height,
                            fill="",
                            outline=self._table_grid_line_color(),
                            width=1,
                        )

                create_outlined_canvas_text(
                    canvas,
                    column_width / 2,
                    row_y + row_height / 2,
                    text=display_text,
                    fill=foreground,
                    font=("Segoe UI", 9, "bold"),
                    anchor="center",
                )
            try:
                canvas.tk.call("raise", canvas._w)
            except tk.TclError:
                pass

    def _tracker_clipboard_date(self, value: str) -> str:
        stripped = value.strip()
        if not stripped or stripped in {"\u2014", "-"}:
            return ""
        parsed = rom_builder_parse_date(stripped)
        if parsed is None:
            for date_format in ("%b %d, %Y", "%B %d, %Y"):
                try:
                    parsed = datetime.strptime(
                        stripped,
                        date_format,
                    ).date()
                    break
                except ValueError:
                    continue
        if parsed is None:
            raise ValueError(
                "Dates must use YYYY-MM-DD or a displayed month/day/year date."
            )
        return parsed.isoformat()

    def _set_tracker_cell_value(
        self,
        iid: str,
        column: str,
        value: str,
    ) -> None:
        editable_columns = {
            "exits",
            "deaths",
            "percentage",
            "rating",
            "playtime",
            "started",
            "completed",
        }
        if column not in editable_columns:
            raise ValueError(
                "That catalog-backed cell is read-only. You can still copy it."
            )
        record = self.tracker_list_records.get(iid)
        if record is None:
            raise ValueError("The selected tracker row is no longer available.")

        completed_exits = max(0, int(record.get("completed_exits") or 0))
        total_exits = max(0, int(record.get("total_exits") or 0))
        personal_rating = record.get("personal_rating")
        playtime_seconds = max(0, int(record.get("playtime_seconds") or 0))
        total_deaths_update: int | None | object = (
            PRESERVE_TRACKER_TOTAL_DEATHS
        )
        date_started = str(record.get("date_started") or "")
        date_completed = str(record.get("date_completed") or "")
        stripped = str(value).strip()

        if column == "exits":
            completed_text = stripped.split("/", 1)[0].strip()
            completed_exits = int(completed_text or "0")
            if completed_exits < 0:
                raise ValueError("Completed exits cannot be negative.")
        elif column == "percentage":
            percent_text = stripped.rstrip("%").strip()
            percentage = float(percent_text or "0")
            if not 0 <= percentage <= 100:
                raise ValueError("Percent complete must be from 0 through 100.")
            completed_exits = (
                round(total_exits * percentage / 100)
                if total_exits
                else 0
            )
        elif column == "rating":
            if not stripped or stripped in {"\u2014", "-"}:
                personal_rating = None
            else:
                personal_rating = float(stripped)
                if not 1 <= personal_rating <= 5:
                    raise ValueError("My Rating must be from 1 through 5.")
        elif column == "deaths":
            if not stripped or stripped in {"*", "—", "-"}:
                total_deaths_update = None
            else:
                total_deaths_update = int(stripped)
                if total_deaths_update < 0:
                    raise ValueError(
                        "Total deaths cannot be negative."
                    )
        elif column == "playtime":
            playtime_seconds = (
                int(self.parse_timer_override(stripped))
                if stripped
                else 0
            )
        elif column == "started":
            date_started = self._tracker_clipboard_date(stripped)
        elif column == "completed":
            date_completed = self._tracker_clipboard_date(stripped)

        status = str(record.get("status") or "Planned")
        if total_exits and completed_exits >= total_exits:
            status = "Completed"
        elif completed_exits > 0:
            status = "In Progress"
        elif status == "Completed":
            status = "Planned"

        self.stats_db.save_tracked(
            int(record["id"]),
            completed_exits,
            status,
            (
                float(personal_rating)
                if personal_rating is not None
                else None
            ),
            playtime_seconds,
            date_started,
            date_completed,
            str(record.get("notes") or ""),
            total_deaths=total_deaths_update,
        )
        self._refresh_my_tracker()
        self._refresh_database_status()
        self._queue_google_sheets_sync()

    def _paste_tracker_cell(self) -> str:
        iid, column = self._active_tracker_cell()
        if not iid:
            return "break"
        try:
            value = self.root.clipboard_get()
            self._set_tracker_cell_value(iid, column, value)
        except (tk.TclError, ValueError) as error:
            messagebox.showerror(
                "Cannot Paste Cell",
                str(error) or "The clipboard does not contain usable text.",
                parent=self.tracker_list_dialog or self.root,
            )
        return "break"

    def _cut_tracker_cell(self) -> str:
        iid, column = self._active_tracker_cell()
        if not iid:
            return "break"
        self._copy_tracker_cell()
        try:
            self._set_tracker_cell_value(iid, column, "")
        except ValueError as error:
            messagebox.showerror(
                "Cannot Cut Cell",
                str(error),
                parent=self.tracker_list_dialog or self.root,
            )
        return "break"

    def _show_tracker_appearance_menu(
        self,
        event,
        *,
        from_overlay: bool,
    ) -> str:
        tree = self.tracker_list_widgets.get("tree")
        if tree is None:
            return "break"

        if from_overlay:
            iid = self._tracker_overlay_iid_at_event(event)
        else:
            try:
                iid = str(tree.identify_row(event.y) or "")
            except tk.TclError:
                iid = ""
        if iid:
            self._select_tracker_overlay_row(iid)

        column = self._tracker_column_at_event(event)
        self._remember_tracker_cell(iid, column)
        column_label = self._tracker_column_label(column)
        palette = self._library_palette()
        menu = tk.Menu(
            self.tracker_list_dialog or self.root,
            tearoff=False,
            bg=palette["panel"],
            fg=palette["text"],
            activebackground=THEME["blue"],
            activeforeground="#FFFFFF",
            selectcolor=THEME["yellow"],
            font=("Segoe UI", 10),
        )
        if iid:
            menu.add_command(
                label="Copy cell",
                accelerator="Ctrl+C",
                command=self._copy_tracker_cell,
            )
            menu.add_command(
                label="Cut cell",
                accelerator="Ctrl+X",
                command=self._cut_tracker_cell,
            )
            menu.add_command(
                label="Paste into cell",
                accelerator="Ctrl+V",
                command=self._paste_tracker_cell,
            )
            menu.add_separator()
            menu.add_command(
                label="Edit deaths, rating, progress, and tracker entry",
                command=self._edit_tracker_record,
            )
            menu.add_separator()
        if column == "difficulty":
            selected_record = (
                self.tracker_list_records.get(iid)
                if iid
                else None
            )
            selected_difficulty = ""
            if selected_record is not None:
                selected_difficulty = str(
                    selected_record.get(
                        "_difficulty_name",
                        selected_record.get(
                            "difficulty",
                            "Unknown",
                        ),
                    )
                    or "Unknown"
                )
                menu.add_command(
                    label=(
                        f"Set color for all {selected_difficulty} hacks..."
                    ),
                    command=lambda value=selected_difficulty: (
                        self._set_tracker_difficulty_color(value)
                    ),
                )
                menu.add_command(
                    label=(
                        f"Reset {selected_difficulty} difficulty color"
                    ),
                    command=lambda value=selected_difficulty: (
                        self._reset_tracker_difficulty_color(value)
                    ),
                )

            difficulty_menu = tk.Menu(
                menu,
                tearoff=False,
                bg=palette["panel"],
                fg=palette["text"],
                activebackground=THEME["blue"],
                activeforeground="#FFFFFF",
                font=("Segoe UI", 10),
            )
            difficulty_names = list(
                dict.fromkeys(
                    (
                        *DIFFICULTY_ROW_COLORS.keys(),
                        *self._difficulty_values(),
                    )
                )
            )
            for difficulty_name in difficulty_names:
                difficulty_menu.add_command(
                    label=f"{difficulty_name}...",
                    command=lambda value=difficulty_name: (
                        self._set_tracker_difficulty_color(value)
                    ),
                )
            menu.add_cascade(
                label="Choose another difficulty color",
                menu=difficulty_menu,
            )
            menu.add_command(
                label="Reset all per-difficulty colors",
                command=lambda: (
                    self._reset_tracker_difficulty_color()
                ),
            )
            menu.add_separator()
        if column in {
            "rating",
            "percentage",
            "smwc_rating",
        }:
            menu.add_command(
                label=(
                    f"Edit gradient data bar for {column_label}..."
                ),
                command=lambda: self._set_tracker_column_style(
                    column,
                    "data_bar",
                ),
            )
            menu.add_separator()
        menu.add_command(
            label=f"Solid color for {column_label}...",
            command=lambda: self._set_tracker_column_style(
                column,
                "solid",
            ),
        )
        menu.add_command(
            label=f"Gradient for {column_label}...",
            command=lambda: self._set_tracker_column_style(
                column,
                "gradient",
            ),
        )
        menu.add_command(
            label=f"Alternating rows for {column_label}...",
            command=lambda: self._set_tracker_column_style(
                column,
                "alternating",
            ),
        )
        menu.add_command(
            label=f"Reset {column_label} colors",
            command=lambda: self._reset_tracker_column_style(
                column
            ),
        )
        menu.add_separator()
        menu.add_command(
            label="Solid color for entire table...",
            command=lambda: self._set_tracker_column_style(
                "*",
                "solid",
            ),
        )
        menu.add_command(
            label="Gradient for entire table...",
            command=lambda: self._set_tracker_column_style(
                "*",
                "gradient",
            ),
        )
        menu.add_command(
            label="Alternating rows for entire table...",
            command=lambda: self._set_tracker_column_style(
                "*",
                "alternating",
            ),
        )
        menu.add_command(
            label="Use Overview alternating colors",
            command=(
                self._set_tracker_overview_alternating_colors
            ),
        )
        menu.add_command(
            label="Restore Mario theme colors",
            command=lambda: self._reset_tracker_column_style(
                "*"
            ),
        )
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                menu.grab_release()
            except tk.TclError:
                pass
        return "break"

    def _schedule_tracker_cell_overlays(
        self,
        event=None,
    ) -> None:
        event_type = getattr(event, "type", None)
        configure_event = (
            getattr(event_type, "name", "") == "Configure"
            or str(event_type) in {
                "22",
                "Configure",
                "EventType.Configure",
            }
        )
        if self.tracker_overlay_after_id is not None:
            if not configure_event:
                return
            try:
                self.root.after_cancel(
                    self.tracker_overlay_after_id
                )
            except tk.TclError:
                pass
            self.tracker_overlay_after_id = None

        self.tracker_overlay_after_id = (
            self.root.after(
                # Repainting the full colored table for every intermediate
                # resize event creates hundreds of gradients and text items.
                # Debounce Configure events, but retain the fast path for
                # scrolling, selection, and data updates.
                110 if configure_event else 16,
                self._render_tracker_cell_overlays,
            )
        )

    def _sync_tracker_overlay_scroll(self) -> None:
        tree = self.tracker_list_widgets.get("tree")
        canvas = self.tracker_list_widgets.get(
            "cell_overlays",
            {},
        ).get("table")
        if tree is None or canvas is None:
            return

        try:
            first, _last = tree.yview()
            canvas.yview_moveto(first)
        except tk.TclError:
            pass

    def _render_tracker_cell_overlays(self) -> None:
        self.tracker_overlay_after_id = None

        tree = self.tracker_list_widgets.get(
            "tree"
        )

        if tree is None:
            self._hide_tracker_paint_cover()
            return

        try:
            if not tree.winfo_exists():
                self._hide_tracker_paint_cover()
                return
        except tk.TclError:
            self._hide_tracker_paint_cover()
            return

        palette = self._library_palette()
        dark_mode = (
            self.appearance_var.get()
            == "dark"
        )
        column_gradients = (
            TRACKER_MARIO_DARK_GRADIENTS
            if dark_mode
            else TRACKER_MARIO_LIGHT_GRADIENTS
        )
        selected_items = set(
            tree.selection()
        )
        display_columns = (
            "#0",
            "title",
            "author",
            "difficulty",
            "type",
            "exits",
            "deaths",
            "percentage",
            "rating",
            "playtime",
            "started",
            "completed",
            "smwc_rating",
        )
        overlays: dict[
            str,
            tk.Canvas,
        ] = self.tracker_list_widgets.setdefault(
            "cell_overlays",
            {},
        )
        visible_keys: set[str] = set()
        border_color = (
            self._tracker_grid_border_color()
        )

        visible_row_boxes: dict[
            str,
            tuple[int, int, int, int],
        ] = {}
        for iid in self.tracker_list_records:
            try:
                row_box = tree.bbox(iid, "#0")
            except tk.TclError:
                continue
            if row_box:
                visible_row_boxes[iid] = row_box

        if not visible_row_boxes:
            for canvas in overlays.values():
                try:
                    canvas.place_forget()
                except tk.TclError:
                    pass
            if self.tracker_list_records:
                retry_count = int(self.tracker_overlay_retry_count) + 1
                self.tracker_overlay_retry_count = retry_count
                if retry_count <= 8:
                    try:
                        self.tracker_overlay_after_id = self.root.after(
                            24 * retry_count,
                            self._render_tracker_cell_overlays,
                        )
                        return
                    except tk.TclError:
                        self.tracker_overlay_after_id = None
            self._hide_tracker_paint_cover()
            return

        ordered_iids = [
            iid
            for iid in tree.get_children("")
            if iid in self.tracker_list_records
        ]
        if not ordered_iids:
            self._hide_tracker_paint_cover()
            return

        reference_iid = next(iter(visible_row_boxes))
        self.tracker_overlay_retry_count = 0
        reference_row_box = visible_row_boxes[reference_iid]
        overlay_origin_y = min(
            box[1]
            for box in visible_row_boxes.values()
        )
        overlay_width = max(1, tree.winfo_width())
        overlay_height = max(
            1,
            tree.winfo_height() - overlay_origin_y,
        )
        row_height = max(1, reference_row_box[3])
        total_table_height = max(
            overlay_height,
            row_height * len(ordered_iids),
        )
        column_boxes: dict[
            str,
            tuple[int, int],
        ] = {}
        for column in display_columns:
            try:
                reference_box = tree.bbox(
                    reference_iid,
                    column,
                )
            except tk.TclError:
                reference_box = ()
            if reference_box:
                column_boxes[column] = (
                    reference_box[0],
                    reference_box[2],
                )

        row_canvas = overlays.get("table")

        if row_canvas is None:
            row_canvas = tk.Canvas(
                tree,
                bd=0,
                highlightthickness=0,
                takefocus=False,
            )
            row_canvas.bind(
                "<Button-1>",
                self._select_tracker_overlay_event,
            )
            row_canvas.bind(
                "<Double-1>",
                self._edit_tracker_overlay_event,
            )
            row_canvas.bind(
                "<Button-3>",
                lambda event: (
                    self._show_tracker_appearance_menu(
                        event,
                        from_overlay=True,
                    )
                ),
            )
            row_canvas.bind(
                "<Control-c>",
                lambda _event: self._copy_tracker_cell(),
            )
            row_canvas.bind(
                "<Control-x>",
                lambda _event: self._cut_tracker_cell(),
            )
            row_canvas.bind(
                "<Control-v>",
                lambda _event: self._paste_tracker_cell(),
            )
            for wheel_event in (
                "<MouseWheel>",
                "<Button-4>",
                "<Button-5>",
            ):
                row_canvas.bind(
                    wheel_event,
                    self._scroll_tracker_from_overlay,
                )
            overlays["table"] = row_canvas

        row_canvas.configure(
            width=overlay_width,
            height=overlay_height,
            bg=palette["tree"],
            yscrollincrement=row_height,
            scrollregion=(
                0,
                0,
                overlay_width,
                total_table_height,
            ),
        )
        row_canvas.place(
            x=0,
            y=overlay_origin_y,
            width=overlay_width,
            height=overlay_height,
        )
        row_canvas.delete("all")
        visible_keys.add("table")
        self.tracker_list_widgets[
            "overlay_origin_y"
        ] = overlay_origin_y
        self.tracker_list_widgets[
            "overlay_ordered_iids"
        ] = tuple(ordered_iids)
        self.tracker_list_widgets[
            "overlay_row_height"
        ] = row_height

        for row_index, iid in enumerate(ordered_iids):
            record = self.tracker_list_records[iid]
            try:
                if not tree.exists(iid):
                    continue
            except tk.TclError:
                return

            is_selected = iid in selected_items
            difficulty_name = str(
                record.get(
                    "_difficulty_name",
                    record.get(
                        "difficulty",
                        "Unknown",
                    ),
                )
                or "Unknown"
            )
            (
                difficulty_background,
                difficulty_foreground,
            ) = DIFFICULTY_ROW_COLORS.get(
                difficulty_name,
                DIFFICULTY_ROW_COLORS[
                    "Unknown"
                ],
            )
            custom_difficulty_color = (
                self._tracker_difficulty_color(
                    difficulty_name
                )
            )
            percentage_complete = max(
                0,
                min(
                    100,
                    int(
                        record.get(
                            "_percentage_complete",
                            0,
                        )
                        or 0
                    ),
                ),
            )
            personal_rating_value = record.get(
                "_personal_rating_value"
            )
            smwc_rating_value = record.get(
                "_smwc_rating_value"
            )

            for column in display_columns:
                try:
                    column_box = column_boxes.get(column)
                    if column_box is None:
                        continue
                    box = (
                        column_box[0],
                        row_index * row_height,
                        column_box[1],
                        row_height,
                    )

                    if column == "#0":
                        cell_text = str(
                            tree.item(
                                iid,
                                "text",
                            )
                        )
                    else:
                        cell_text = str(
                            tree.set(
                                iid,
                                column,
                            )
                        )
                except tk.TclError:
                    continue

                background = (
                    palette["selected"]
                    if is_selected
                    else palette["tree"]
                )
                foreground = (
                    "#FFFFFF"
                    if is_selected
                    else palette["text"]
                )
                bar_percentage = None
                bar_start_color = None
                bar_end_color = None
                cell_gradient_start = None
                cell_gradient_end = None
                text_outline_color = None
                bold = False

                gradient_pair = (
                    column_gradients.get(
                        column
                    )
                )
                if gradient_pair is not None:
                    (
                        cell_gradient_start,
                        cell_gradient_end,
                    ) = gradient_pair
                    background = (
                        cell_gradient_start
                    )
                    foreground = (
                        "#FFFFFF"
                        if dark_mode
                        else THEME["text"]
                    )

                if column == "difficulty":
                    if custom_difficulty_color is not None:
                        background = custom_difficulty_color
                        foreground = (
                            self._tracker_contrast_text_color(
                                custom_difficulty_color,
                            )
                        )
                        cell_gradient_start = None
                        cell_gradient_end = None
                    elif dark_mode:
                        cell_gradient_start = (
                            blend_hex_colors(
                                difficulty_background,
                                "#101827",
                                0.58,
                            )
                        )
                        cell_gradient_end = (
                            blend_hex_colors(
                                difficulty_background,
                                "#101827",
                                0.34,
                            )
                        )
                        foreground = "#FFFFFF"
                    else:
                        cell_gradient_start = (
                            blend_hex_colors(
                                difficulty_background,
                                "#FFFFFF",
                                0.38,
                            )
                        )
                        cell_gradient_end = (
                            difficulty_background
                        )
                        foreground = (
                            difficulty_foreground
                        )
                    if custom_difficulty_color is None:
                        background = (
                            cell_gradient_start
                        )
                    cell_text = difficulty_name
                    bold = True

                elif column == "percentage":
                    if dark_mode:
                        cell_gradient_start = (
                            "#623000"
                        )
                        cell_gradient_end = (
                            "#9A6800"
                        )
                        foreground = "#FFFFFF"
                    else:
                        cell_gradient_start = (
                            "#FFE2B8"
                        )
                        cell_gradient_end = (
                            "#F7C928"
                        )
                        foreground = "#10214A"
                    background = (
                        cell_gradient_start
                    )
                    text_outline_color = None
                    cell_text = (
                        f"{percentage_complete}%"
                    )
                    bar_percentage = (
                        percentage_complete
                    )
                    bar_start_color = (
                        TRACKER_PERCENT_GRADIENT_START
                    )
                    bar_end_color = (
                        TRACKER_PERCENT_GRADIENT_END
                    )
                    bold = True

                elif column == "rating":
                    cell_gradient_start = (
                        "#35214F"
                        if dark_mode
                        else "#F0E7FF"
                    )
                    cell_gradient_end = (
                        "#653B91"
                        if dark_mode
                        else "#CEB4F1"
                    )
                    background = (
                        cell_gradient_start
                    )
                    foreground = (
                        "#FFFFFF"
                        if dark_mode
                        else THEME["text"]
                    )
                    if personal_rating_value is not None:
                        # Use true fifths: 1, 2, 3, 4, and 5 fill
                        # 20%, 40%, 60%, 80%, and 100% respectively.
                        bar_percentage = (
                            self._tracker_rating_bar_percentage(
                                float(personal_rating_value)
                            )
                        )
                        bar_start_color = (
                            TRACKER_RATING_GRADIENT_START
                        )
                        bar_end_color = (
                            TRACKER_RATING_GRADIENT_END
                        )
                        foreground = "#000000"
                        text_outline_color = None
                        bold = True

                elif column == "smwc_rating":
                    cell_gradient_start = (
                        "#35214F"
                        if dark_mode
                        else "#F0E7FF"
                    )
                    cell_gradient_end = (
                        "#653B91"
                        if dark_mode
                        else "#CEB4F1"
                    )
                    background = cell_gradient_start
                    foreground = (
                        "#FFFFFF"
                        if dark_mode
                        else THEME["text"]
                    )
                    if smwc_rating_value is not None:
                        bar_percentage = (
                            self._tracker_rating_bar_percentage(
                                float(smwc_rating_value)
                            )
                        )
                        bar_start_color = (
                            TRACKER_SMWC_RATING_GRADIENT_START
                        )
                        bar_end_color = (
                            TRACKER_SMWC_RATING_GRADIENT_END
                        )
                        foreground = "#000000"
                        text_outline_color = None
                        bold = True

                elif column == "deaths":
                    # Match the clean alternating colors used by Overview.
                    # A custom column or entire-table style can still replace
                    # these colors in the shared customization block below.
                    background = (
                        palette["tree"]
                        if row_index % 2 == 0
                        else palette["panel_alt"]
                    )
                    foreground = palette["text"]
                    cell_gradient_start = None
                    cell_gradient_end = None

                elif column in {
                    "#0",
                    "title",
                }:
                    bold = True

                custom_style = (
                    self._tracker_custom_style(column)
                )
                if custom_style is not None:
                    custom_start = custom_style["start"]
                    custom_end = custom_style["end"]
                    if (
                        custom_style["mode"] == "data_bar"
                        and column in {
                            "rating",
                            "percentage",
                            "smwc_rating",
                        }
                    ):
                        bar_start_color = custom_start
                        bar_end_color = custom_end
                        text_outline_color = None
                    elif custom_style["mode"] == "alternating":
                        row_color = (
                            custom_start
                            if row_index % 2 == 0
                            else custom_end
                        )
                        background = row_color
                        foreground = (
                            self._tracker_contrast_text_color(
                                row_color,
                            )
                        )
                        cell_gradient_start = None
                        cell_gradient_end = None
                    elif custom_style["mode"] == "gradient":
                        background = custom_start
                        foreground = (
                            self._tracker_contrast_text_color(
                                custom_start,
                                custom_end,
                            )
                        )
                        cell_gradient_start = custom_start
                        cell_gradient_end = custom_end
                    else:
                        background = custom_start
                        foreground = (
                            self._tracker_contrast_text_color(
                                custom_start,
                            )
                        )
                        cell_gradient_start = None
                        cell_gradient_end = None
                    if custom_style["mode"] != "data_bar":
                        bar_percentage = None
                        bar_start_color = None
                        bar_end_color = None
                        text_outline_color = None

                if (
                    column == "deaths"
                    and bool(record.get("_legacy_death_count"))
                ):
                    # The marker stays conspicuously yellow even when the
                    # user gives the rest of this column a custom color.
                    foreground = THEME["yellow"]
                    text_outline_color = "#000000"
                    bold = True

                if is_selected:
                    background = (
                        palette["selected"]
                    )
                    foreground = "#FFFFFF"
                    cell_gradient_start = None
                    cell_gradient_end = None
                    bar_percentage = None
                    bar_start_color = None
                    bar_end_color = None
                    text_outline_color = None

                self._draw_tracker_cell_overlay(
                    row_canvas,
                    box=box,
                    background=background,
                    foreground=foreground,
                    border_color=border_color,
                    text=cell_text,
                    cell_gradient_start=cell_gradient_start,
                    cell_gradient_end=cell_gradient_end,
                    bar_percentage=bar_percentage,
                    bar_start_color=bar_start_color,
                    bar_end_color=bar_end_color,
                    text_outline_color=text_outline_color,
                    alignment="center",
                    bold=bold,
                )

        self._sync_tracker_overlay_scroll()
        self._hide_tracker_paint_cover()

        right_edge_border = self.tracker_list_widgets.get(
            "right_edge_border"
        )
        if right_edge_border is not None:
            try:
                right_edge_border.configure(
                    bg=border_color,
                )
                right_edge_border.place(
                    relx=1.0,
                    x=-TRACKER_GRID_BORDER_WIDTH,
                    y=0,
                    width=TRACKER_GRID_BORDER_WIDTH,
                    relheight=1.0,
                )
                right_edge_border.lift()
            except tk.TclError:
                pass

        for iid, canvas in overlays.items():
            if iid not in visible_keys:
                try:
                    canvas.place_forget()
                except tk.TclError:
                    pass

    def _tracker_gradient_photo(
        self,
        canvas: tk.Canvas,
        width: int,
        height: int,
        start_color: str,
        end_color: str,
    ):
        if (
            Image is None
            or ImageTk is None
            or width <= 0
            or height <= 0
        ):
            return None

        cache = self.tracker_list_widgets.setdefault(
            "gradient_images",
            {},
        )
        key = (
            width,
            height,
            start_color,
            end_color,
        )
        cached = cache.get(key)
        if cached is not None:
            return cached

        def rgb(color: str) -> tuple[int, int, int]:
            value = color.lstrip("#")
            return tuple(
                int(value[index:index + 2], 16)
                for index in (0, 2, 4)
            )

        start_rgb = rgb(start_color)
        end_rgb = rgb(end_color)
        denominator = max(1, width - 1)
        pixels = [
            tuple(
                round(
                    start_rgb[channel]
                    + (
                        end_rgb[channel]
                        - start_rgb[channel]
                    )
                    * position
                    / denominator
                )
                for channel in range(3)
            )
            for position in range(width)
        ]
        image = Image.new("RGB", (width, 1))
        image.putdata(pixels)
        if height > 1:
            image = image.resize((width, height))
        photo = ImageTk.PhotoImage(
            image,
            master=canvas,
        )
        cache[key] = photo
        return photo

    def _fit_tracker_cell_text(
        self,
        canvas: tk.Canvas,
        text: str,
        font_description,
        maximum_width: int,
    ) -> str:
        """Keep overlay text inside its column, using an ellipsis if needed."""
        if maximum_width <= 0:
            return ""

        font_cache = self.tracker_list_widgets.setdefault(
            "cell_text_fonts",
            {},
        )
        font_key = tuple(font_description)
        cell_font = font_cache.get(font_key)
        if cell_font is None:
            cell_font = tkfont.Font(
                master=canvas,
                font=font_description,
            )
            font_cache[font_key] = cell_font

        display_text = str(text)
        if cell_font.measure(display_text) <= maximum_width:
            return display_text

        ellipsis = "…"
        ellipsis_width = cell_font.measure(ellipsis)
        if ellipsis_width > maximum_width:
            return ""

        low = 0
        high = len(display_text)
        while low < high:
            middle = (low + high + 1) // 2
            candidate = (
                display_text[:middle].rstrip()
                + ellipsis
            )
            if cell_font.measure(candidate) <= maximum_width:
                low = middle
            else:
                high = middle - 1

        return display_text[:low].rstrip() + ellipsis

    def _draw_tracker_cell_overlay(
        self,
        canvas: tk.Canvas,
        *,
        box: tuple[int, int, int, int],
        background: str,
        foreground: str,
        border_color: str,
        text: str,
        cell_gradient_start: str | None,
        cell_gradient_end: str | None,
        bar_percentage: int | None,
        bar_start_color: str | None,
        bar_end_color: str | None,
        text_outline_color: str | None,
        alignment: str = "center",
        bold: bool = False,
    ) -> None:
        x, y, width, height = box

        if width <= 2 or height <= 2:
            return

        canvas.create_rectangle(
            x,
            y,
            x + width - 1,
            y + height - 1,
            fill=background,
            outline=border_color,
            width=TRACKER_GRID_BORDER_WIDTH,
        )

        if (
            cell_gradient_start is not None
            and cell_gradient_end is not None
        ):
            inset = (
                TRACKER_GRID_BORDER_WIDTH
            )
            inner_width = max(
                0,
                width - (inset * 2),
            )
            gradient_height = max(
                1,
                height - (inset * 2) - 1,
            )
            gradient_photo = (
                self._tracker_gradient_photo(
                    canvas,
                    inner_width,
                    gradient_height,
                    cell_gradient_start,
                    cell_gradient_end,
                )
            )
            if gradient_photo is not None:
                canvas.create_image(
                    x + inset,
                    y + inset,
                    image=gradient_photo,
                    anchor="nw",
                )
            else:
                canvas.create_rectangle(
                    x + inset,
                    y + inset,
                    x + width - inset - 1,
                    y + height - inset - 1,
                    fill=cell_gradient_start,
                    outline="",
                )

            canvas.create_rectangle(
                x,
                y,
                x + width - 1,
                y + height - 1,
                fill="",
                outline=border_color,
                width=TRACKER_GRID_BORDER_WIDTH,
            )

        if (
            bar_percentage is not None
            and bar_percentage > 0
            and bar_start_color is not None
            and bar_end_color is not None
        ):
            inset = TRACKER_GRID_BORDER_WIDTH
            inner_width = max(
                0,
                width - (inset * 2),
            )
            filled_width = max(
                0,
                min(
                    inner_width,
                    round(
                        inner_width
                        * bar_percentage
                        / 100
                    ),
                ),
            )

            if filled_width > 0:
                gradient_height = max(
                    1,
                    height - (inset * 2) - 1,
                )
                gradient_photo = (
                    self._tracker_gradient_photo(
                        canvas,
                        filled_width,
                        gradient_height,
                        bar_start_color,
                        bar_end_color,
                    )
                )
                if gradient_photo is not None:
                    canvas.create_image(
                        x + inset,
                        y + inset,
                        image=gradient_photo,
                        anchor="nw",
                    )
                else:
                    canvas.create_rectangle(
                        x + inset,
                        y + inset,
                        x + inset + filled_width,
                        y + height - inset - 1,
                        fill=bar_start_color,
                        outline="",
                    )

                # Restore the medium outline above the gradient strips.
                canvas.create_rectangle(
                    x,
                    y,
                    x + width - 1,
                    y + height - 1,
                    fill="",
                    outline=border_color,
                    width=TRACKER_GRID_BORDER_WIDTH,
                )

        is_left_aligned = (
            alignment == "left"
        )
        text_x = (
            x + 8
            if is_left_aligned
            else x + width / 2
        )
        text_anchor = (
            "w"
            if is_left_aligned
            else "center"
        )
        text_font = (
            "Segoe UI",
            9,
            (
                "bold"
                if bold
                else "normal"
            ),
        )
        display_text = self._fit_tracker_cell_text(
            canvas,
            text,
            text_font,
            max(0, width - 16),
        )

        if text_outline_color:
            for offset_x, offset_y in (
                (-1, 0),
                (1, 0),
                (0, -1),
                (0, 1),
            ):
                canvas.create_text(
                    text_x + offset_x,
                    y + height / 2 + offset_y,
                    text=display_text,
                    fill=text_outline_color,
                    font=text_font,
                    anchor=text_anchor,
                )

        create_outlined_canvas_text(
            canvas,
            text_x,
            y + height / 2,
            text=display_text,
            fill=foreground,
            font=text_font,
            anchor=text_anchor,
        )

    def _tracker_overlay_iid_at_event(
        self,
        event,
    ) -> str:
        canvas = self.tracker_list_widgets.get(
            "cell_overlays",
            {},
        ).get("table")
        ordered_iids = tuple(
            self.tracker_list_widgets.get(
                "overlay_ordered_iids",
                (),
            )
        )
        row_height = int(
            self.tracker_list_widgets.get(
                "overlay_row_height",
                0,
            )
            or 0
        )
        if (
            canvas is None
            or not ordered_iids
            or row_height <= 0
        ):
            return ""

        try:
            canvas_y = float(canvas.canvasy(event.y))
        except tk.TclError:
            return ""
        row_index = int(canvas_y // row_height)
        if not (0 <= row_index < len(ordered_iids)):
            return ""
        return str(ordered_iids[row_index])

    def _select_tracker_overlay_event(
        self,
        event,
    ) -> str:
        iid = self._tracker_overlay_iid_at_event(event)
        if iid:
            self._select_tracker_overlay_row(iid)
            self._remember_tracker_cell(
                iid,
                self._tracker_column_at_event(event),
            )
        return "break"

    def _remember_tracker_tree_cell_event(self, event) -> None:
        tree = self.tracker_list_widgets.get("tree")
        if tree is None:
            return
        try:
            iid = str(tree.identify_row(event.y) or "")
        except tk.TclError:
            iid = ""
        if iid:
            self._remember_tracker_cell(
                iid,
                self._tracker_column_at_event(event),
            )

    def _edit_tracker_overlay_event(
        self,
        event,
    ) -> str:
        iid = self._tracker_overlay_iid_at_event(event)
        if iid:
            self._edit_tracker_overlay_row(iid)
        return "break"

    def _select_tracker_overlay_row(
        self,
        iid: str,
    ) -> str:
        tree = self.tracker_list_widgets.get(
            "tree"
        )

        if tree is not None:
            try:
                tree.focus_set()
                tree.selection_set(iid)
                tree.focus(iid)
                self._schedule_tracker_cell_overlays()
            except tk.TclError:
                pass

        return "break"

    def _edit_tracker_overlay_row(
        self,
        iid: str,
    ) -> str:
        self._select_tracker_overlay_row(iid)
        self._edit_tracker_record()
        return "break"

    def _scroll_tracker_from_overlay(
        self,
        event,
    ) -> str:
        tree = self.tracker_list_widgets.get(
            "tree"
        )

        if tree is None:
            return "break"

        units = self._fast_scroll_units(
            event,
            rows_per_notch=2,
        )

        if not units:
            return "break"

        try:
            tree.yview_scroll(
                units,
                "units",
            )
        except tk.TclError:
            return "break"

        self._sync_tracker_overlay_scroll()
        return "break"

    def _selected_tracker_record(self) -> dict[str, Any] | None:
        tree = self.tracker_list_widgets.get("tree")

        if tree is None:
            return None

        selection = tree.selection()

        if not selection:
            messagebox.showinfo(
                "My Tracker",
                "Select a tracker row first.",
                parent=self.tracker_list_dialog or self.root,
            )
            return None

        return self.tracker_list_records.get(
            selection[0]
        )

