    def _close_game_library(self) -> None:
        pending_overlay = self.game_library_widgets.get(
            "difficulty_overlay_after_id"
        )
        if pending_overlay is not None:
            try:
                self.root.after_cancel(pending_overlay)
            except tk.TclError:
                pass

        if (
            self.game_library_dialog is not None
            and self.game_library_dialog.winfo_exists()
        ):
            self.game_library_dialog.destroy()

        self.game_library_dialog = None
        self.game_library_widgets = {}
        self.game_library_games_by_iid = {}

    def _library_segment_ids(self) -> list[str]:
        if not self.game_library_widgets:
            return []

        tree = self.game_library_widgets.get(
            "tree"
        )

        if tree is None:
            return []

        return [
            iid
            for iid in tree.get_children("")
            if str(iid).startswith(
                "segment::"
            )
        ]

    def _sync_library_expand_button(
        self,
    ) -> None:
        if not self.game_library_widgets:
            return

        tree = self.game_library_widgets.get(
            "tree"
        )
        button = self.game_library_widgets.get(
            "expand_button"
        )

        if tree is None or button is None:
            return

        segment_ids = self._library_segment_ids()

        if not segment_ids:
            button.configure(
                text="Expand All",
                state="disabled",
            )
            return

        all_expanded = all(
            bool(
                tree.item(
                    segment_iid,
                    "open",
                )
            )
            for segment_iid in segment_ids
        )

        button.configure(
            text=(
                "Collapse All"
                if all_expanded
                else "Expand All"
            ),
            state="normal",
        )

    def _toggle_library_segments(
        self,
    ) -> None:
        if not self.game_library_widgets:
            return

        tree = self.game_library_widgets.get(
            "tree"
        )

        if tree is None:
            return

        segment_ids = self._library_segment_ids()

        if not segment_ids:
            self._sync_library_expand_button()
            return

        all_expanded = all(
            bool(
                tree.item(
                    segment_iid,
                    "open",
                )
            )
            for segment_iid in segment_ids
        )
        expand_segments = not all_expanded

        for segment_iid in segment_ids:
            tree.item(
                segment_iid,
                open=expand_segments,
            )

        if not expand_segments:
            try:
                tree.yview_moveto(0.0)
                tree.see(segment_ids[0])
            except tk.TclError:
                pass

        self._sync_library_expand_button()
        self._schedule_game_library_difficulty_overlays()

        if hasattr(
            self,
            "game_library_status_var",
        ):
            self.game_library_status_var.set(
                (
                    "Expanded all alphabetical segments."
                    if expand_segments
                    else "Collapsed all alphabetical segments."
                )
            )

    def _jump_to_library_segment(
        self,
        event=None,
    ) -> None:
        if not self.game_library_widgets:
            return

        tree = self.game_library_widgets.get(
            "tree"
        )
        jump_var = self.game_library_widgets.get(
            "jump_var"
        )

        if tree is None or jump_var is None:
            return

        selected = jump_var.get().strip()

        if selected in {"", "Top"}:
            children = tree.get_children("")

            if children:
                try:
                    tree.yview_moveto(0.0)
                    tree.see(children[0])
                except tk.TclError:
                    pass

            return

        target_iid = "segment::" + selected

        if not tree.exists(target_iid):
            if hasattr(
                self,
                "game_library_status_var",
            ):
                self.game_library_status_var.set(
                    (
                        "No matching games are currently "
                        f"available in the {selected} segment."
                    )
                )
            return

        tree.item(
            target_iid,
            open=True,
        )
        tree.focus(target_iid)
        tree.see(target_iid)

        self._sync_library_expand_button()
        self._schedule_game_library_difficulty_overlays()

        if hasattr(
            self,
            "game_library_status_var",
        ):
            self.game_library_status_var.set(
                f"Jumped to the {selected} segment."
            )

    def _reset_game_library_filters(self) -> None:
        if not self.game_library_widgets:
            return

        self.game_library_widgets["search_var"].set("")
        self.game_library_widgets["rating_var"].set("Any")
        self.game_library_widgets["difficulty_var"].set("Any")
        self.game_library_widgets["type_var"].set("Any")
        self.game_library_widgets["sort_var"].set("Title (A-Z)")
        self.game_library_widgets["letter_filter_var"].set("All")
        released_options = self._released_filter_options()
        boolean_options = self._boolean_filter_options()
        self.game_library_widgets["released_var"].set(
            released_options[0][0]
        )
        self.game_library_widgets["sa1_var"].set(boolean_options[0])
        self.game_library_widgets["hall_of_fame_var"].set(
            boolean_options[0]
        )
        self.game_library_widgets["waiting_var"].set(boolean_options[0])
        self.game_library_widgets["header_sort_column"] = "#0"
        self.game_library_widgets["header_sort_descending"] = False
        self.game_library_widgets["jump_var"].set("Top")
        self._populate_game_library()

    def _sort_game_library_from_header(self, column: str) -> None:
        if not self.game_library_widgets:
            return
        current = self.game_library_widgets.get(
            "header_sort_column",
            "#0",
        )
        descending = bool(
            self.game_library_widgets.get(
                "header_sort_descending",
                False,
            )
        )
        if current == column:
            descending = not descending
        else:
            descending = False
        self.game_library_widgets["header_sort_column"] = column
        self.game_library_widgets["header_sort_descending"] = descending
        labels = self.game_library_widgets.get("heading_labels", {})
        label = str(labels.get(column, column))
        self.game_library_widgets["sort_var"].set(
            label + (" (Descending)" if descending else " (Ascending)")
        )

    def _update_game_library_sort_headings(self) -> None:
        tree = self.game_library_widgets.get("tree")
        labels = self.game_library_widgets.get("heading_labels", {})
        if tree is None or not isinstance(labels, dict):
            return
        active = self.game_library_widgets.get("header_sort_column", "#0")
        descending = bool(
            self.game_library_widgets.get("header_sort_descending", False)
        )
        for column, label in labels.items():
            suffix = ""
            if column == active:
                suffix = " \u25BC" if descending else " \u25B2"
            try:
                tree.heading(column, text=str(label) + suffix)
            except tk.TclError:
                pass

        pending_search = self.downloader_widgets.get(
            "search_refresh_after_id"
        )
        if pending_search is not None:
            try:
                self.root.after_cancel(pending_search)
            except tk.TclError:
                pass

    def _populate_game_library(self) -> None:
        tree = self.game_library_widgets.get("tree")
        if tree is None:
            return

        search_text = self.game_library_widgets[
            "search_var"
        ].get().strip()
        rating_value = self.game_library_widgets[
            "rating_var"
        ].get()
        difficulty_value = self.game_library_widgets[
            "difficulty_var"
        ].get()
        type_value = self.game_library_widgets[
            "type_var"
        ].get()
        letter_filter = self.game_library_widgets[
            "letter_filter_var"
        ].get()
        released_value = self.game_library_widgets["released_var"].get()
        sa1_value = self.game_library_widgets["sa1_var"].get()
        hall_of_fame_value = self.game_library_widgets[
            "hall_of_fame_var"
        ].get()
        waiting_value = self.game_library_widgets["waiting_var"].get()
        sort_value = self.game_library_widgets[
            "sort_var"
        ].get()
        if sort_value == "Title (A-Z)":
            self.game_library_widgets["header_sort_column"] = "#0"
            self.game_library_widgets["header_sort_descending"] = False
        elif sort_value == "Released (Newest)":
            self.game_library_widgets["header_sort_column"] = "added"
            self.game_library_widgets["header_sort_descending"] = True
        elif sort_value == "Released (Oldest)":
            self.game_library_widgets["header_sort_column"] = "added"
            self.game_library_widgets["header_sort_descending"] = False
        filtered = [
            game
            for game in self.hack_catalog
            if self._game_matches_library_filters(
                game,
                search_text,
                rating_value,
                difficulty_value,
                type_value,
                letter_filter,
                released_value,
                sa1_value,
                hall_of_fame_value,
                waiting_value,
            )
        ]
        title_sort_key = lambda game: self._title_without_leading_article(
            game.get("title", "")
        ).casefold()

        def added_date_sort_key(
            game: dict[str, Any],
            *,
            newest_first: bool,
        ) -> tuple[bool, int, str]:
            added_date = rom_builder_parse_date(
                game.get("added_date", "")
            )
            ordinal = (
                added_date.toordinal()
                if added_date is not None
                else 0
            )
            return (
                added_date is None,
                -ordinal if newest_first else ordinal,
                title_sort_key(game),
            )

        sort_column = str(
            self.game_library_widgets.get("header_sort_column", "#0")
        )
        sort_descending = bool(
            self.game_library_widgets.get("header_sort_descending", False)
        )

        def game_sort_value(game: dict[str, Any]) -> tuple[int, object]:
            if sort_column == "#0":
                raw_value = self._title_without_leading_article(
                    game.get("title", "")
                )
            elif sort_column == "author":
                raw_value = game.get("author", "")
            elif sort_column == "difficulty":
                raw_value = game.get("difficulty", "")
            elif sort_column == "type":
                raw_value = game.get("hack_type", "")
            elif sort_column == "rating":
                raw_value = game.get("rating", "")
            elif sort_column == "exits":
                raw_value = game.get("total_exits", "")
            elif sort_column == "added":
                added_value = rom_builder_parse_date(
                    game.get("added_date", "")
                )
                raw_value = (
                    added_value.toordinal()
                    if added_value is not None
                    else ""
                )
            elif sort_column == "rom":
                raw_value = (
                    "Mapped"
                    if str(game.get("rom_path", "")).strip()
                    else "Auto-find"
                )
            else:
                raw_value = game.get("title", "")
            return self._treeview_sort_value(raw_value)

        present_games = [
            game
            for game in filtered
            if game_sort_value(game)[0] != 9
        ]
        missing_games = [
            game
            for game in filtered
            if game_sort_value(game)[0] == 9
        ]
        present_games.sort(
            key=game_sort_value,
            reverse=sort_descending,
        )
        filtered = present_games + missing_games

        tree.delete(*tree.get_children())
        self.game_library_games_by_iid = {}

        alphabetical_sort = (
            sort_column == "#0" and not sort_descending
        )
        grouped: dict[str, list[dict[str, Any]]] = {}
        if alphabetical_sort:
            for game in filtered:
                segment = self._alphabet_segment(
                    str(game.get("title", ""))
                )
                grouped.setdefault(segment, []).append(game)
            segment_order = [
                "#",
                *[
                    chr(code)
                    for code in range(ord("A"), ord("Z") + 1)
                ],
            ]
        else:
            # Date sorting is global rather than being broken back into
            # alphabetical groups. This keeps newest/oldest ordering exact.
            grouped[""] = list(filtered)
            segment_order = [""]
            self.game_library_widgets["jump_var"].set("Top")

        jump_combo = self.game_library_widgets.get("jump_combo")
        if jump_combo is not None:
            try:
                jump_combo.configure(
                    state=(
                        "readonly"
                        if alphabetical_sort
                        else "disabled"
                    )
                )
            except tk.TclError:
                pass
        open_groups = bool(
            search_text
            or rating_value != "Any"
            or difficulty_value != "Any"
            or type_value != "Any"
            or letter_filter != "All"
            or not self._filter_value_is_any(released_value)
            or not self._filter_value_is_any(sa1_value)
            or not self._filter_value_is_any(hall_of_fame_value)
            or not self._filter_value_is_any(waiting_value)
        )

        game_number = 0
        for segment in segment_order:
            games = grouped.get(segment, [])
            if not games:
                continue

            parent_iid = ""
            if alphabetical_sort:
                parent_iid = "segment::" + segment
                tree.insert(
                    "",
                    "end",
                    iid=parent_iid,
                    text=f"{segment}  ({len(games):,})",
                    values=("", "", "", "", "", "", ""),
                    open=open_groups,
                )

            for game in games:
                child_iid = f"game::{game_number}"
                game_number += 1
                rating = game.get("rating")
                rating_text = (
                    f"{float(rating):.2f}".rstrip("0").rstrip(".")
                    if rating is not None
                    else "—"
                )
                rom_text = (
                    "Mapped"
                    if str(game.get("rom_path", "")).strip()
                    else "Auto-find"
                )
                tree.insert(
                    parent_iid,
                    "end",
                    iid=child_iid,
                    text=str(game.get("title", "")),
                    values=(
                        str(game.get("author", "Unknown")),
                        str(game.get("difficulty", "Unknown")),
                        str(game.get("hack_type", "Unknown")),
                        rating_text,
                        str(game.get("total_exits", "Unknown")),
                        format_display_date(
                            game.get("added_date", "")
                        ),
                        rom_text,
                    ),
                    tags=(),
                )
                self.game_library_games_by_iid[
                    child_iid
                ] = game

        if hasattr(self, "game_library_count_var"):
            self.game_library_count_var.set(
                self._format_ui_text(
                    "{filtered} of {total} games",
                    filtered=f"{len(filtered):,}",
                    total=f"{len(self.hack_catalog):,}",
                )
            )

        if filtered and alphabetical_sort:
            self.root.after_idle(
                self._jump_to_library_segment
            )

        self.root.after_idle(
            self._sync_library_expand_button
        )
        self._apply_statistics_table_colors(
            tree,
            "game_library",
        )
        self._schedule_game_library_difficulty_overlays()
        self._update_game_library_sort_headings()

        if not filtered:
            tree.insert(
                "",
                "end",
                text="No games match the selected filters.",
                values=("", "", "", "", "", "", ""),
            )

    def _schedule_game_library_difficulty_overlays(
        self,
        event=None,
    ) -> None:
        if not self.game_library_widgets:
            return

        pending = self.game_library_widgets.get(
            "difficulty_overlay_after_id"
        )
        if pending is not None:
            return

        self.game_library_widgets[
            "difficulty_overlay_after_id"
        ] = self.root.after_idle(
            self._render_game_library_difficulty_overlays
        )

    def _render_game_library_difficulty_overlays(self) -> None:
        if not self.game_library_widgets:
            return

        self.game_library_widgets[
            "difficulty_overlay_after_id"
        ] = None
        tree = self.game_library_widgets.get("tree")
        if tree is None:
            return

        try:
            if not tree.winfo_exists():
                return
            tree_height = max(1, tree.winfo_height())
        except tk.TclError:
            return

        # Identify only the rows currently on screen. This keeps scrolling
        # smooth even with the full SMW Central catalog loaded.
        visible_iids: list[str] = []
        seen_iids: set[str] = set()
        for sample_y in range(0, tree_height, 4):
            try:
                iid = str(tree.identify_row(sample_y))
            except tk.TclError:
                iid = ""
            if iid and iid not in seen_iids:
                seen_iids.add(iid)
                visible_iids.append(iid)

        cell_boxes: dict[str, tuple[int, int, int, int]] = {}
        for iid in visible_iids:
            try:
                box = tree.bbox(iid, "difficulty")
            except tk.TclError:
                box = ()
            if box:
                cell_boxes[iid] = box

        overlay = self.game_library_widgets.get(
            "difficulty_overlay"
        )
        if not cell_boxes:
            if overlay is not None:
                try:
                    overlay.place_forget()
                except tk.TclError:
                    pass
            return

        palette = self._library_palette()
        reference_box = next(iter(cell_boxes.values()))
        column_x = reference_box[0]
        column_width = reference_box[2]
        overlay_origin_y = min(
            box[1]
            for box in cell_boxes.values()
        )
        overlay_height = max(
            1,
            tree_height - overlay_origin_y,
        )

        if overlay is None:
            overlay = tk.Canvas(
                tree,
                bd=0,
                highlightthickness=0,
                takefocus=False,
            )
            overlay.bind(
                "<Button-1>",
                self._select_game_library_overlay_event,
            )
            overlay.bind(
                "<Button-3>",
                lambda event: self._show_table_appearance_menu(
                    event,
                    tree,
                    "game_library",
                ),
            )
            overlay.bind(
                "<Double-1>",
                self._launch_game_library_overlay_event,
            )
            for wheel_event in (
                "<MouseWheel>",
                "<Button-4>",
                "<Button-5>",
            ):
                overlay.bind(
                    wheel_event,
                    self._scroll_game_library_overlay,
                )
            self.game_library_widgets[
                "difficulty_overlay"
            ] = overlay

        self.game_library_widgets[
            "difficulty_overlay_origin_y"
        ] = overlay_origin_y
        overlay.configure(
            width=column_width,
            height=overlay_height,
            bg=palette["tree"],
        )
        overlay.place(
            x=column_x,
            y=overlay_origin_y,
            width=column_width,
            height=overlay_height,
        )
        overlay.delete("all")

        selected_iids = set(tree.selection())
        for iid, box in cell_boxes.items():
            row_y = box[1] - overlay_origin_y
            row_height = box[3]
            game = self.game_library_games_by_iid.get(iid)
            if game is None:
                background = (
                    palette["selected"]
                    if iid in selected_iids
                    else palette["tree"]
                )
                overlay.create_rectangle(
                    0,
                    row_y,
                    column_width,
                    row_y + row_height,
                    fill=background,
                    outline=self._table_grid_line_color(),
                    width=1,
                )
                continue

            difficulty_name = str(
                game.get("difficulty", "Unknown")
            ).strip() or "Unknown"
            difficulty_color = self._effective_difficulty_color(
                difficulty_name
            )
            text_color = self._tracker_contrast_text_color(
                difficulty_color
            )
            overlay.create_rectangle(
                0,
                row_y,
                column_width,
                row_y + row_height,
                fill=difficulty_color,
                outline=self._table_grid_line_color(),
                width=1,
            )
            create_outlined_canvas_text(
                overlay,
                column_width / 2,
                row_y + row_height / 2,
                text=difficulty_name,
                fill=text_color,
                font=("Segoe UI", 9, "bold"),
                anchor="center",
            )

        # Canvas overrides both ``lift`` and ``tkraise`` with its item-level
        # ``tag_raise`` command. Raise the widget through Tk directly so no
        # canvas item id/tag is required.
        try:
            overlay.tk.call("raise", overlay._w)
        except tk.TclError:
            return

    def _game_library_overlay_iid(self, event) -> str:
        tree = self.game_library_widgets.get("tree")
        if tree is None:
            return ""
        origin_y = int(
            self.game_library_widgets.get(
                "difficulty_overlay_origin_y",
                0,
            )
            or 0
        )
        try:
            return str(
                tree.identify_row(event.y + origin_y)
            )
        except tk.TclError:
            return ""

    def _select_game_library_overlay_event(self, event) -> str:
        tree = self.game_library_widgets.get("tree")
        iid = self._game_library_overlay_iid(event)
        if tree is not None and iid:
            try:
                tree.selection_set(iid)
                tree.focus(iid)
            except tk.TclError:
                pass
        return "break"

    def _launch_game_library_overlay_event(self, event) -> str:
        self._select_game_library_overlay_event(event)
        self._launch_selected_library_game()
        return "break"

    def _scroll_game_library_overlay(self, event) -> str:
        tree = self.game_library_widgets.get("tree")
        if tree is None:
            return "break"
        units = self._fast_scroll_units(event)
        if units:
            try:
                tree.yview_scroll(units, "units")
            except tk.TclError:
                return "break"
            self._schedule_game_library_difficulty_overlays()
        return "break"

    def _selected_library_game(self) -> dict[str, Any] | None:
        tree = self.game_library_widgets.get("tree")
        if tree is None:
            return None

        selected = tree.selection()
        if not selected:
            return None

        return self.game_library_games_by_iid.get(
            selected[0]
        )

    def _update_game_library_selection(self, event=None) -> None:
        self._schedule_game_library_difficulty_overlays()
        game = self._selected_library_game()
        if game is None:
            return

        rating = game.get("rating")
        rating_text = (
            f"{float(rating):.2f}".rstrip("0").rstrip(".")
            if rating is not None
            else "Unrated"
        )
        rom_status = (
            str(game.get("rom_path", ""))
            or (
                "ROM path will be found automatically in the local library"
                if self.platform_var.get() in PLATFORM_LOCAL_EMULATORS
                else "ROM path will be found automatically on the SD card"
            )
        )
        self.game_library_selected_var.set(
            f'{game.get("title", "")} — By {game.get("author", "Unknown")} '
            f'| {game.get("difficulty", "Unknown")} '
            f'| {game.get("hack_type", "Unknown")} '
            f'| Rating {rating_text} | {rom_status}'
        )

    def _open_selected_library_page(self) -> None:
        game = self._selected_library_game()
        if game is None:
            messagebox.showinfo(
                self.platform_var.get() + " Game Library",
                "Select a game first.",
                parent=self.game_library_dialog or self.root,
            )
            return

        page_url = str(game.get("page_url", "")).strip()
        if not page_url:
            messagebox.showerror(
                self.platform_var.get() + " Game Library",
                "This game does not have a stored SMWCentral page.",
                parent=self.game_library_dialog or self.root,
            )
            return

        webbrowser.open_new_tab(page_url)

    def _launch_selected_library_game(self, event=None) -> None:
        game = self._selected_library_game()
        if game is None:
            if event is None:
                messagebox.showinfo(
                    self.platform_var.get() + " Game Library",
                    "Select a game first.",
                    parent=self.game_library_dialog or self.root,
                )
            return

        self._launch_catalog_game(game)

    def _play_random_library_game(self) -> None:
        if not self.game_library_widgets:
            return

        rating_value = self.game_library_widgets[
            "random_rating_var"
        ].get()
        difficulty_value = self.game_library_widgets[
            "random_difficulty_var"
        ].get()
        type_value = self.game_library_widgets[
            "random_type_var"
        ].get()
        released_value = self.game_library_widgets[
            "random_released_var"
        ].get()
        hall_of_fame_value = self.game_library_widgets[
            "random_hall_of_fame_var"
        ].get()

        candidates = [
            game
            for game in self.hack_catalog
            if self._game_matches_library_filters(
                game,
                "",
                rating_value,
                difficulty_value,
                type_value,
                self._translate_ui_text("All"),
                released_value,
                self._translate_ui_text("Any"),
                hall_of_fame_value,
                self._translate_ui_text("Any"),
            )
            and self._catalog_game_has_downloaded_rom(game)
        ]

        if not candidates:
            messagebox.showinfo(
                "Random Game",
                (
                    "No downloaded games match the selected random filters."
                ),
                parent=self.game_library_dialog or self.root,
            )
            return

        game = random.choice(candidates)
        self.game_library_random_var.set(
            "Random selection: "
            + str(game.get("title", "Unknown"))
            + " — launching now."
        )
        self._launch_catalog_game(game)

    @staticmethod
    def _replay_hack_identity(
        game: dict[str, Any],
    ) -> str:
        catalog_key = str(
            game.get("catalog_key", "")
        ).strip()
        if catalog_key:
            return "catalog:" + catalog_key.casefold()
        smwc_id = str(game.get("smwc_id", "")).strip()
        if smwc_id:
            return "smwc:" + smwc_id.casefold()
        return "title:" + normalize_title(
            game.get("title", "")
        )

    @staticmethod
    def _replay_hack_snapshot(
        game: dict[str, Any],
    ) -> dict[str, Any]:
        allowed_fields = (
            "catalog_key",
            "title",
            "author",
            "total_exits",
            "difficulty",
            "hack_type",
            "rating",
            "added_date",
            "download_url",
            "smwc_id",
            "page_url",
            "rom_path",
            "local_rom_path",
            "mapping_key",
            "is_custom",
        )
        return {
            field: game.get(field)
            for field in allowed_fields
            if game.get(field) is not None
        }

    @classmethod
    def _updated_recent_hack_history(
        cls,
        history: list[dict[str, Any]],
        game: dict[str, Any],
        limit: int = 5,
    ) -> list[dict[str, Any]]:
        snapshot = cls._replay_hack_snapshot(game)
        if not str(snapshot.get("title", "")).strip():
            return [
                dict(item)
                for item in history[: max(0, limit)]
                if isinstance(item, dict)
            ]

        wanted_identity = cls._replay_hack_identity(snapshot)
        updated = [snapshot]
        for existing in history:
            if not isinstance(existing, dict):
                continue
            existing_snapshot = cls._replay_hack_snapshot(existing)
            if not str(existing_snapshot.get("title", "")).strip():
                continue
            if (
                cls._replay_hack_identity(existing_snapshot)
                == wanted_identity
            ):
                continue
            updated.append(existing_snapshot)
            if len(updated) >= max(1, limit):
                break
        return updated[: max(1, limit)]

    def _recent_replay_label_map(
        self,
    ) -> dict[str, dict[str, Any]]:
        history = getattr(self, "recent_launched_hacks", [])
        title_counts: dict[str, int] = {}
        for game in history:
            title_key = str(game.get("title", "")).strip().casefold()
            title_counts[title_key] = title_counts.get(title_key, 0) + 1

        label_map: dict[str, dict[str, Any]] = {}
        for position, game in enumerate(history, start=1):
            title = str(game.get("title", "Unknown")).strip() or "Unknown"
            label = title
            if title_counts.get(title.casefold(), 0) > 1:
                author = str(game.get("author", "Unknown")).strip()
                label = f"{title} - {author or 'Unknown'}"
            if label in label_map:
                label = f"{label} [{position}]"
            label_map[label] = game
        return label_map

    def _update_replay_last_hack_button(self) -> None:
        button = getattr(
            self,
            "replay_last_hack_button",
            None,
        )
        combo = getattr(self, "replay_recent_hack_combo", None)
        variable = getattr(self, "replay_recent_hack_var", None)
        label_map = self._recent_replay_label_map()
        self.replay_recent_hack_games = label_map
        labels = list(label_map)

        if variable is not None:
            selected_label = str(variable.get()).strip()
            if selected_label not in label_map:
                variable.set(
                    labels[0]
                    if labels
                    else self._translate_ui_text("No recent hacks")
                )

        if combo is not None:
            try:
                combo.configure(
                    values=labels,
                    # Keep the recent-hack selector editable so users can
                    # drag-select its text (or press Ctrl+A) and clear it in
                    # one action, just like the main hack selector.
                    state="normal" if labels else "disabled",
                    justify="center",
                )
            except tk.TclError:
                pass

        if button is not None:
            try:
                button.configure(
                    state="normal" if labels else "disabled"
                )
            except tk.TclError:
                pass

    def _remember_last_launched_hack(
        self,
        game: dict[str, Any],
    ) -> None:
        snapshot = self._replay_hack_snapshot(game)
        if not str(snapshot.get("title", "")).strip():
            return
        self.last_launched_hack = snapshot
        self.recent_launched_hacks = (
            self._updated_recent_hack_history(
                getattr(self, "recent_launched_hacks", []),
                snapshot,
            )
        )
        self.config["last_launched_hack"] = dict(snapshot)
        self.config["recent_launched_hacks"] = [
            dict(recent_hack)
            for recent_hack in self.recent_launched_hacks
        ]
        try:
            save_config(self.config)
        except OSError:
            pass
        replay_variable = getattr(
            self,
            "replay_recent_hack_var",
            None,
        )
        if replay_variable is not None:
            replay_variable.set("")
        self._update_replay_last_hack_button()

    def _selected_recent_replay_hack(self) -> dict[str, Any] | None:
        variable = getattr(self, "replay_recent_hack_var", None)
        label_map = getattr(self, "replay_recent_hack_games", {})
        if variable is not None and isinstance(label_map, dict):
            selected = label_map.get(str(variable.get()).strip())
            if isinstance(selected, dict):
                return selected
        history = getattr(self, "recent_launched_hacks", [])
        if history and isinstance(history[0], dict):
            return history[0]
        stored = getattr(self, "last_launched_hack", {})
        return stored if isinstance(stored, dict) else None

    def _resolved_replay_hack(
        self,
        stored: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        if stored is None:
            stored = self._selected_recent_replay_hack()
        if not isinstance(stored, dict) or not str(
            stored.get("title", "")
        ).strip():
            return None
        wanted_identity = self._replay_hack_identity(stored)
        for game in self.hack_catalog:
            if self._replay_hack_identity(game) == wanted_identity:
                return game
        return dict(stored)

    def replay_last_hack(self) -> None:
        game = self._resolved_replay_hack()
        if game is None:
            messagebox.showinfo(
                "Replay Recent Hack",
                "Play a hack once and it will appear in the recent list.",
                parent=self.root,
            )
            return
        selected_label = self._selector_label_for_game(game)
        if selected_label in self.main_hack_selector_games:
            self.main_hack_selector_var.set(selected_label)
            self.main_hack_selector_selected_label = selected_label
            self._align_main_hack_selector_text(selected_label)
        self._launch_catalog_game(game)

    def _launch_catalog_game(
        self,
        game: dict[str, Any],
    ) -> None:
        selected_platform = self.platform_var.get().strip() or "FXPAK Pro"
        if self.game_library_launching:
            messagebox.showinfo(
                selected_platform,
                "A game launch is already in progress.",
                parent=self.game_library_dialog or self.root,
            )
            return

        title = str(game.get("title", "Unknown"))
        self.game_library_launching = True
        if hasattr(self, "game_library_status_var"):
            self.game_library_status_var.set(
                f'Finding and launching "{title}" on {selected_platform}...'
            )
        self.status_var.set(
            f'Launching "{title}" on {selected_platform}...'
        )

        launch_thread = threading.Thread(
            target=self._launch_catalog_game_thread,
            args=(dict(game),),
            daemon=True,
        )
        launch_thread.start()

    def _pause_tracker_bridge_for_fxpak_files(
        self,
    ) -> TrackerWorker | None:
        """Temporarily release SNI/QUsb2Snes for exclusive file commands."""
        worker = getattr(self, "worker", None)
        if (
            worker is None
            or worker.thread is None
            or not worker.thread.is_alive()
        ):
            return None
        if not worker.pause_connection(timeout=15.0):
            raise RuntimeError(
                self._translate_ui_text(
                    "The live tracker could not release the FXPAK Pro "
                    "connection for the SD-card transfer. Select Refresh "
                    "and try again."
                )
            )
        return worker

    @staticmethod
    def _resume_tracker_bridge_after_fxpak_files(
        worker: TrackerWorker | None,
    ) -> None:
        if worker is not None:
            worker.resume_connection()

    def _launch_catalog_game_thread(
        self,
        game: dict[str, Any],
    ) -> None:
        paused_worker: TrackerWorker | None = None
        try:
            if (self.platform_var.get().strip() or "FXPAK Pro") == "FXPAK Pro":
                paused_worker = self._pause_tracker_bridge_for_fxpak_files()
            result = self._run_fxpak_game_launch(game)
            self.root.after(
                0,
                lambda: self._finish_catalog_game_launch(
                    game,
                    result,
                    None,
                ),
            )
        except Exception as error:
            self.root.after(
                0,
                lambda launch_error=str(error): (
                    self._finish_catalog_game_launch(
                        game,
                        None,
                        launch_error,
                    )
                ),
            )
        finally:
            self._resume_tracker_bridge_after_fxpak_files(paused_worker)

    def _finish_catalog_game_launch(
        self,
        game: dict[str, Any],
        result: dict[str, str] | None,
        error: str | None,
    ) -> None:
        self.game_library_launching = False
        title = str(game.get("title", "Unknown"))

        if error:
            message = f'Could not launch "{title}": {error}'
            if hasattr(self, "game_library_status_var"):
                self.game_library_status_var.set(message)
            self.status_var.set(message)
            self._show_localized_info(
                self.platform_var.get() + " Launch Failed",
                message,
                parent=self.game_library_dialog or self.root,
            )
            return

        result = result or {}
        rom_path = str(result.get("path", ""))
        method = str(result.get("method", "platform launcher"))
        message = (
            f'Launched "{title}" from {rom_path or "the selected platform"}.'
        )
        if hasattr(self, "game_library_status_var"):
            self.game_library_status_var.set(
                message + "  Method: " + method
            )
        self.status_var.set(message)
        self._remember_last_launched_hack(game)

        # Force the worker to treat every successful app launch as a fresh
        # ROM session. Some platforms switch games without an observable
        # blank interval, and replaying the same title otherwise leaves the
        # previous stopped timer state attached to the new run.
        if self.worker:
            self.worker.notify_catalog_launch()

        selected_platform = self.platform_var.get().strip() or "FXPAK Pro"
        if rom_path and selected_platform == "FXPAK Pro":
            game["rom_path"] = rom_path
            self._save_fxpak_mapping(game, rom_path)
            self._populate_game_library()
        elif rom_path:
            self._save_platform_rom_mapping(
                game,
                selected_platform,
                rom_path,
            )

        if rom_path:
            last_roms = self.config.get("platform_last_roms", {})
            if not isinstance(last_roms, dict):
                last_roms = {}
            last_roms[selected_platform] = {
                "title": title,
                "path": rom_path,
                "updated": datetime.now(timezone.utc).isoformat(),
            }
            self.config["platform_last_roms"] = last_roms
            try:
                save_config(self.config)
            except OSError:
                pass
            if self.worker:
                self.worker.config["platform_last_roms"] = dict(last_roms)

    def _catalog_mapping_key(
        self,
        game: dict[str, Any],
    ) -> str:
        smwc_id = str(game.get("smwc_id", "")).strip()
        if smwc_id:
            return "smwc:" + smwc_id
        return "title:" + normalize_title(game.get("title", ""))

    def _save_platform_rom_mapping(
        self,
        game: dict[str, Any],
        platform: str,
        rom_path: str,
    ) -> None:
        all_mappings = self.config.get("platform_rom_mappings", {})
        if not isinstance(all_mappings, dict):
            all_mappings = {}
        platform_mappings = all_mappings.get(platform, {})
        if not isinstance(platform_mappings, dict):
            platform_mappings = {}
        platform_mappings[self._catalog_mapping_key(game)] = rom_path
        all_mappings[platform] = platform_mappings
        self.config["platform_rom_mappings"] = all_mappings
        try:
            save_config(self.config)
        except OSError:
            pass

    def _resolve_local_rom_path(
        self,
        game: dict[str, Any],
        platform: str,
    ) -> tuple[Path, str]:
        all_mappings = self.config.get("platform_rom_mappings", {})
        if isinstance(all_mappings, dict):
            platform_mappings = all_mappings.get(platform, {})
            if isinstance(platform_mappings, dict):
                mapped_text = str(
                    platform_mappings.get(
                        self._catalog_mapping_key(game),
                        "",
                    )
                ).strip()
                if mapped_text:
                    mapped = Path(mapped_text)
                    if mapped.is_file():
                        return mapped, "saved local ROM mapping"

        local_text = str(game.get("local_rom_path", "")).strip()
        if local_text:
            local_path = Path(local_text)
            if local_path.is_file():
                return local_path, "catalog local ROM path"

        direct_text = str(game.get("rom_path", "")).strip()
        if direct_text:
            direct_path = Path(direct_text)
            if direct_path.is_absolute() and direct_path.is_file():
                return direct_path, "catalog local ROM mapping"

        library_text = str(
            self.config.get("platform_rom_library_folder", "")
            or self.config.get("rom_builder_library_folder", "")
        ).strip()
        library_folder = Path(library_text)
        if not library_text or not library_folder.is_dir():
            raise FileNotFoundError(
                "Set the local ROM library folder in Settings first."
            )

        target_title = str(game.get("title", ""))
        target_key = normalize_title(target_title)
        target_exact_key = unicodedata.normalize(
            "NFKC",
            target_title,
        ).strip().casefold()
        best_path: Path | None = None
        best_score = 0.0
        for candidate in library_folder.rglob("*"):
            if (
                not candidate.is_file()
                or candidate.suffix.casefold()
                not in {".sfc", ".smc", ".fig", ".bin"}
            ):
                continue
            candidate_exact_key = unicodedata.normalize(
                "NFKC",
                candidate.stem,
            ).strip().casefold()
            if target_exact_key and candidate_exact_key == target_exact_key:
                return candidate, "exact local filename match"
            candidate_key = normalize_title(
                clean_rom_filename(candidate.name)
            )
            if not candidate_key:
                continue
            if candidate_key == target_key:
                return candidate, "exact local filename match"
            score = SequenceMatcher(None, target_key, candidate_key).ratio()
            if score > best_score:
                best_score = score
                best_path = candidate

        if best_path is not None and best_score >= 0.72:
            return best_path, f"closest local filename match ({best_score:.0%})"
        raise FileNotFoundError(
            f'No local ROM matching "{game.get("title", "Unknown")}" '
            f"was found under {library_folder}."
        )

    def _send_retroarch_network_command(
        self,
        command: str,
        *,
        expect_response: bool = False,
        timeout: float = 0.75,
    ) -> str | None:
        """Send one command to RetroArch's UDP control interface."""
        host = str(
            self.config.get("retroarch_host", "127.0.0.1")
        ).strip() or "127.0.0.1"
        try:
            port = int(self.config.get("retroarch_port", 55355))
        except (TypeError, ValueError):
            port = 55355

        udp_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        udp_socket.settimeout(max(0.05, float(timeout)))
        try:
            udp_socket.sendto(
                command.encode("utf-8"),
                (host, port),
            )
            if not expect_response:
                return ""
            payload, _ = udp_socket.recvfrom(4096)
            return payload.decode(
                "utf-8",
                errors="ignore",
            ).strip()
        except OSError:
            return None
        finally:
            udp_socket.close()

    def _retroarch_status(self, timeout: float = 0.5) -> str | None:
        return self._send_retroarch_network_command(
            "GET_STATUS",
            expect_response=True,
            timeout=timeout,
        )

    @staticmethod
    def _retroarch_status_content_key(status: str | None) -> str:
        """Return the normalized content name reported by GET_STATUS."""
        if not status or "CONTENTLESS" in status.upper():
            return ""
        fields = status.split(",", 2)
        if len(fields) < 2:
            return ""
        return normalize_title(clean_rom_filename(fields[1].strip()))

    @staticmethod
    def _find_windows_for_executable(executable: Path) -> list[int]:
        """Return visible top-level Windows handles owned by an executable."""
        if os.name != "nt":
            return []

        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        kernel32.OpenProcess.argtypes = [
            wintypes.DWORD,
            wintypes.BOOL,
            wintypes.DWORD,
        ]
        kernel32.OpenProcess.restype = wintypes.HANDLE
        kernel32.QueryFullProcessImageNameW.argtypes = [
            wintypes.HANDLE,
            wintypes.DWORD,
            wintypes.LPWSTR,
            ctypes.POINTER(wintypes.DWORD),
        ]
        kernel32.QueryFullProcessImageNameW.restype = wintypes.BOOL
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        kernel32.CloseHandle.restype = wintypes.BOOL
        user32.IsWindowVisible.argtypes = [wintypes.HWND]
        user32.IsWindowVisible.restype = wintypes.BOOL
        user32.GetWindowThreadProcessId.argtypes = [
            wintypes.HWND,
            ctypes.POINTER(wintypes.DWORD),
        ]
        user32.GetWindowThreadProcessId.restype = wintypes.DWORD
        process_query_limited_information = 0x1000
        expected_path = os.path.normcase(
            os.path.normpath(str(executable.resolve()))
        )
        handles: list[int] = []

        enum_callback_type = ctypes.WINFUNCTYPE(
            wintypes.BOOL,
            wintypes.HWND,
            wintypes.LPARAM,
        )
        user32.EnumWindows.argtypes = [
            enum_callback_type,
            wintypes.LPARAM,
        ]
        user32.EnumWindows.restype = wintypes.BOOL

        def visit_window(hwnd, _lparam):
            if not user32.IsWindowVisible(hwnd):
                return True

            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(
                hwnd,
                ctypes.byref(process_id),
            )
            process_handle = kernel32.OpenProcess(
                process_query_limited_information,
                False,
                process_id.value,
            )
            if not process_handle:
                return True

            try:
                path_buffer = ctypes.create_unicode_buffer(32768)
                path_size = wintypes.DWORD(len(path_buffer))
                if kernel32.QueryFullProcessImageNameW(
                    process_handle,
                    0,
                    path_buffer,
                    ctypes.byref(path_size),
                ):
                    actual_path = os.path.normcase(
                        os.path.normpath(path_buffer.value)
                    )
                    if actual_path == expected_path:
                        handle_value = (
                            hwnd
                            if isinstance(hwnd, int)
                            else ctypes.cast(hwnd, ctypes.c_void_p).value
                        )
                        if handle_value:
                            handles.append(int(handle_value))
            finally:
                kernel32.CloseHandle(process_handle)
            return True

        callback = enum_callback_type(visit_window)
        user32.EnumWindows(callback, 0)
        return handles

    def _post_retroarch_file_drop(
        self,
        executable: Path,
        rom_path: Path,
    ) -> bool:
        """Drop a ROM onto RetroArch's existing Windows content window."""
        if os.name != "nt":
            return False

        window_handles = self._find_windows_for_executable(executable)
        if not window_handles:
            return False

        class Point(ctypes.Structure):
            _fields_ = [
                ("x", wintypes.LONG),
                ("y", wintypes.LONG),
            ]

        class DropFiles(ctypes.Structure):
            _fields_ = [
                ("pFiles", wintypes.DWORD),
                ("pt", Point),
                ("fNC", wintypes.BOOL),
                ("fWide", wintypes.BOOL),
            ]

        shell_payload = (
            str(rom_path.resolve()).encode("utf-16-le")
            + b"\x00\x00\x00\x00"
        )
        header = DropFiles(
            pFiles=ctypes.sizeof(DropFiles),
            pt=Point(0, 0),
            fNC=False,
            fWide=True,
        )
        total_size = ctypes.sizeof(header) + len(shell_payload)
        kernel32 = ctypes.windll.kernel32
        user32 = ctypes.windll.user32
        kernel32.GlobalAlloc.argtypes = [
            wintypes.UINT,
            ctypes.c_size_t,
        ]
        kernel32.GlobalAlloc.restype = wintypes.HGLOBAL
        kernel32.GlobalLock.argtypes = [wintypes.HGLOBAL]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [wintypes.HGLOBAL]
        kernel32.GlobalUnlock.restype = wintypes.BOOL
        kernel32.GlobalFree.argtypes = [wintypes.HGLOBAL]
        kernel32.GlobalFree.restype = wintypes.HGLOBAL
        user32.PostMessageW.argtypes = [
            wintypes.HWND,
            wintypes.UINT,
            wintypes.WPARAM,
            wintypes.LPARAM,
        ]
        user32.PostMessageW.restype = wintypes.BOOL
        global_memory = kernel32.GlobalAlloc(0x0042, total_size)
        if not global_memory:
            return False

        locked_memory = kernel32.GlobalLock(global_memory)
        if not locked_memory:
            kernel32.GlobalFree(global_memory)
            return False

        try:
            base_address = ctypes.cast(
                locked_memory,
                ctypes.c_void_p,
            ).value
            if base_address is None:
                return False
            ctypes.memmove(
                base_address,
                ctypes.byref(header),
                ctypes.sizeof(header),
            )
            ctypes.memmove(
                base_address + ctypes.sizeof(header),
                shell_payload,
                len(shell_payload),
            )
        finally:
            kernel32.GlobalUnlock(global_memory)

        # RetroArch enables WM_DROPFILES on its main graphics window and
        # loads supported content with the already active core. Ownership of
        # the HDROP memory passes to RetroArch when PostMessage succeeds.
        for window_handle in window_handles:
            if user32.PostMessageW(
                window_handle,
                0x0233,
                global_memory,
                0,
            ):
                return True

        kernel32.GlobalFree(global_memory)
        return False

    def _load_retroarch_content_in_place(
        self,
        core_path: Path,
        rom_path: Path,
    ) -> tuple[bool, bool]:
        """Ask a running RetroArch process to load content in its window."""
        original_status = self._retroarch_status()
        if original_status is None:
            return False, False

        had_content = "CONTENTLESS" not in original_status.upper()
        saved_previous_state = False
        if had_content:
            self._send_retroarch_network_command("SAVE_STATE")
            # SAVE_STATE is fire-and-forget. Let RetroArch finish writing
            # before replacing the running content in the same process.
            time.sleep(0.75)
            saved_previous_state = True

        executable = Path(
            str(
                self.config.get(
                    "retroarch_executable_path",
                    "",
                )
            ).strip()
        )
        handoff_sent = self._post_retroarch_file_drop(
            executable,
            rom_path,
        )
        if not handoff_sent:
            # Newer RetroArch builds also expose this Network Commands entry.
            # Keep it as a forward-compatible fallback; v1.22.2 uses the
            # native Windows file-drop path above.
            self._send_retroarch_network_command(
                f"LOAD_CONTENT {core_path}|{rom_path}"
            )

        target_key = normalize_title(clean_rom_filename(rom_path.name))
        load_deadline = time.monotonic() + 12.0
        while time.monotonic() < load_deadline:
            current_status = self._retroarch_status(timeout=0.30)
            current_key = self._retroarch_status_content_key(current_status)
            if current_key and current_key == target_key:
                return True, saved_previous_state
            time.sleep(0.12)

        return False, saved_previous_state

    def _prepare_retroarch_game_switch(
        self,
        *,
        already_saved: bool = False,
    ) -> str:
        """Save and retire a running instance before launching new content."""
        status = self._retroarch_status()
        if status is None:
            return ""

        had_content = "CONTENTLESS" not in status.upper()
        if had_content:
            if not already_saved:
                self._send_retroarch_network_command("SAVE_STATE")
                # SAVE_STATE has no acknowledgement. Give RetroArch enough
                # time to flush the state file before safely closing the core.
                time.sleep(1.0)
            self._send_retroarch_network_command("CLOSE_CONTENT")

            close_deadline = time.monotonic() + 4.0
            while time.monotonic() < close_deadline:
                current_status = self._retroarch_status(timeout=0.35)
                if (
                    current_status is not None
                    and "CONTENTLESS" in current_status.upper()
                ):
                    break
                time.sleep(0.15)

        # The network interface cannot load a new ROM into the existing
        # process. Exit the now-contentless instance so the replacement can
        # own the configured command port and be detected by the tracker.
        # RetroArch can be configured to require two quit presses. Send a
        # second QUIT only when the first one leaves the command interface
        # alive, and keep both attempts within its confirmation window.
        for quit_attempt in range(2):
            self._send_retroarch_network_command("QUIT")
            wait_seconds = 0.75 if quit_attempt == 0 else 4.0
            exit_deadline = time.monotonic() + wait_seconds
            while time.monotonic() < exit_deadline:
                if self._retroarch_status(timeout=0.20) is None:
                    time.sleep(0.25)
                    return (
                        "saved previous state and restarted RetroArch"
                        if had_content
                        else "restarted contentless RetroArch"
                    )
                time.sleep(0.10)

        raise RuntimeError(
            "RetroArch did not close its current instance. Make sure "
            "Network Commands are enabled on the configured port, then "
            "try again."
        )

    def _run_local_emulator_launcher(
        self,
        game: dict[str, Any],
        platform: str,
    ) -> dict[str, str]:
        executable_key = PLATFORM_EXECUTABLE_CONFIG_KEYS[platform]
        executable_text = str(
            self.config.get(executable_key, "")
        ).strip()
        executable = Path(executable_text)
        if not executable_text or not executable.is_file():
            raise FileNotFoundError(
                f"Select the {platform} executable in Settings first."
            )

        rom_path, match_method = self._resolve_local_rom_path(
            game,
            platform,
        )
        command = [str(executable)]
        switch_method = ""
        if platform == "RetroArch":
            core_text = str(
                self.config.get("retroarch_core_path", "")
            ).strip()
            core_path = Path(core_text)
            if not core_text or not core_path.is_file():
                raise FileNotFoundError(
                    "Select a RetroArch SNES core in Settings first."
                )
            command.extend(["-L", str(core_path)])
        command.append(str(rom_path))

        if platform == "RetroArch":
            saved_previous_state = False
            if IS_WINDOWS:
                loaded_in_place, saved_previous_state = (
                    self._load_retroarch_content_in_place(
                        core_path,
                        rom_path,
                    )
                )
                if loaded_in_place:
                    return {
                        "path": str(rom_path),
                        "device": platform,
                        "method": (
                            match_method
                            + "; saved previous state and loaded in the "
                            "existing RetroArch window"
                            if saved_previous_state
                            else match_method
                            + "; loaded in the existing RetroArch window"
                        ),
                    }
                if self._retroarch_status(timeout=0.35) is not None:
                    raise RuntimeError(
                        "RetroArch is still running, but it did not accept the "
                        "new ROM in its existing window. Keep RetroArch's main "
                        "game window open and try again. The tracker left the "
                        "current game running instead of opening a duplicate "
                        "RetroArch window."
                    )
            switch_method = self._prepare_retroarch_game_switch(
                already_saved=saved_previous_state,
            )

        if IS_WINDOWS:
            creation_flags = getattr(
                subprocess,
                "CREATE_NEW_PROCESS_GROUP",
                0,
            )
            subprocess.Popen(
                command,
                cwd=str(executable.parent),
                creationflags=creation_flags,
            )
        else:
            launch_local_application(
                executable,
                command[1:],
            )
        return {
            "path": str(rom_path),
            "device": platform,
            "method": (
                match_method + "; " + switch_method
                if switch_method
                else match_method
            ),
        }

    def _save_fxpak_mapping(
        self,
        game: dict[str, Any],
        rom_path: str,
    ) -> None:
        smwc_id = str(game.get("smwc_id", "")).strip()
        if smwc_id:
            mapping_key = "smwc:" + smwc_id
        else:
            mapping_key = str(
                game.get("mapping_key", "")
            ).casefold().strip()
            if not mapping_key:
                mapping_key = (
                    "title:"
                    + str(game.get("title", "")).casefold().strip()
                )

        mappings = self.config.get(
            "fxpak_rom_mappings",
            {},
        )
        if not isinstance(mappings, dict):
            mappings = {}

        mappings[mapping_key] = rom_path
        self.config["fxpak_rom_mappings"] = mappings
        try:
            save_config(self.config)
        except OSError:
            pass

        try:
            self.stats_db.save_rom_mapping(
                game,
                rom_path,
                device="FXPAK Pro",
                match_method="saved mapping",
            )
        except Exception:
            pass

        for catalog_game in self.hack_catalog:
            same_id = (
                str(catalog_game.get("smwc_id", ""))
                and str(catalog_game.get("smwc_id", ""))
                == str(game.get("smwc_id", ""))
            )
            same_title = normalize_title(
                catalog_game.get("title", "")
            ) == normalize_title(game.get("title", ""))
            if same_id or same_title:
                catalog_game["rom_path"] = rom_path

        if self.worker is not None:
            self.worker.register_fxpak_mapping(
                game,
                rom_path,
            )

    def _run_fxpak_game_launch(
        self,
        game: dict[str, Any],
    ) -> dict[str, str]:
        selected_platform = self.platform_var.get().strip() or "FXPAK Pro"
        if selected_platform in PLATFORM_LOCAL_EMULATORS:
            return self._run_local_emulator_launcher(
                game,
                selected_platform,
            )
        settings = {
            "SDRoot": str(
                self.fxpak_settings.get(
                    "SDRoot",
                    self.config.get(
                        "fxpak_sd_root",
                        "/All_Hacks",
                    ),
                )
            ),
            "WebSocketURL": str(
                self.fxpak_settings.get(
                    "WebSocketURL",
                    self.config.get(
                        "fxpak_websocket_url",
                        QUSB2SNES_URL,
                    ),
                )
            ),
            "DeviceName": str(
                self.fxpak_settings.get(
                    "DeviceName",
                    self.config.get(
                        "fxpak_device_name",
                        "",
                    ),
                )
            ),
            "PythonPath": str(
                self.fxpak_settings.get(
                    "PythonPath",
                    self.config.get(
                        "fxpak_python_path",
                        "",
                    ),
                )
            ),
            "LauncherScriptPath": str(
                self.fxpak_settings.get(
                    "LauncherScriptPath",
                    self.config.get(
                        "fxpak_launcher_script_path",
                        "",
                    ),
                )
            ),
        }

        python_path = Path(settings["PythonPath"])
        script_path = Path(settings["LauncherScriptPath"])

        # Emoji aliases use the in-app launcher because it can repair a
        # missing readable filename and save the SMW Central ID relationship.
        if (
            not rom_builder_fxpak_title_requires_alias(game)
            and python_path.is_file()
            and script_path.is_file()
        ):
            return self._run_installed_fxpak_launcher(
                game,
                settings,
            )

        return self._run_direct_fxpak_launcher(
            game,
            settings,
        )

    def _run_installed_fxpak_launcher(
        self,
        game: dict[str, Any],
        settings: dict[str, str],
    ) -> dict[str, str]:
        request_fd, request_name = tempfile.mkstemp(
            prefix="smw_fxpak_request_",
            suffix=".txt",
        )
        result_fd, result_name = tempfile.mkstemp(
            prefix="smw_fxpak_result_",
            suffix=".txt",
        )
        os.close(request_fd)
        os.close(result_fd)
        request_file = Path(request_name)
        result_file = Path(result_name)

        try:
            request_file.write_text(
                "\n".join(
                    (
                        str(game.get("title", "")),
                        str(game.get("smwc_id", "")),
                        self._normalize_fxpak_sd_path(
                            settings.get("SDRoot", "/All_Hacks")
                        ),
                        str(game.get("rom_path", "")),
                        settings.get("DeviceName", ""),
                        settings.get(
                            "WebSocketURL",
                            QUSB2SNES_URL,
                        ),
                        "",
                    )
                ),
                encoding="utf-8-sig",
            )

            creation_flags = 0
            if os.name == "nt":
                creation_flags = getattr(
                    subprocess,
                    "CREATE_NO_WINDOW",
                    0,
                )

            completed = subprocess.run(
                [
                    settings["PythonPath"],
                    settings["LauncherScriptPath"],
                    "--request",
                    str(request_file),
                    "--result",
                    str(result_file),
                ],
                capture_output=True,
                text=True,
                timeout=180,
                creationflags=creation_flags,
                check=False,
            )

            if not result_file.exists():
                detail = (
                    completed.stderr.strip()
                    or completed.stdout.strip()
                    or f"launcher exit code {completed.returncode}"
                )
                raise RuntimeError(
                    "The installed FXPAK launcher did not return a "
                    "result: " + detail
                )

            result_values: dict[str, str] = {}
            for line in result_file.read_text(
                encoding="utf-8-sig",
                errors="replace",
            ).splitlines():
                if "=" not in line:
                    continue
                key, value = line.split("=", 1)
                result_values[
                    key.strip().upper()
                ] = value.strip()

            if result_values.get("STATUS", "").upper() != "OK":
                raise RuntimeError(
                    result_values.get(
                        "MESSAGE",
                        "The FXPAK launcher reported an unknown error.",
                    )
                )

            return {
                "path": result_values.get("PATH", ""),
                "device": result_values.get("DEVICE", ""),
                "method": result_values.get(
                    "METHOD",
                    "installed FXPAK launcher",
                ),
            }

        finally:
            for path in (request_file, result_file):
                try:
                    path.unlink(missing_ok=True)
                except OSError:
                    pass

