    def _recovery_backup_retention(self) -> int:
        try:
            return max(3, min(50, int(self.config.get("automatic_backup_retention", 10))))
        except (TypeError, ValueError):
            return 10

    def _create_recovery_backup(
        self,
        reason: str = "automatic",
        show_confirmation: bool = False,
    ) -> Path | None:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        safe_reason = re.sub(r"[^a-z0-9_-]+", "_", reason.casefold()).strip("_")
        destination = AUTOMATIC_BACKUP_DIR / (
            f"SMWStreamTracker_{safe_reason or 'backup'}_{timestamp}.zip"
        )
        temporary_database = AUTOMATIC_BACKUP_DIR / ("." + timestamp + ".db")
        try:
            AUTOMATIC_BACKUP_DIR.mkdir(parents=True, exist_ok=True)
            self.stats_db.backup_to(temporary_database)
            metadata = {
                "app": APP_NAME,
                "version": APP_VERSION,
                "created": datetime.now().astimezone().isoformat(timespec="seconds"),
                "reason": reason,
            }
            with zipfile.ZipFile(destination, "w", zipfile.ZIP_DEFLATED) as archive:
                archive.write(temporary_database, "SMWStreamTracker.db")
                if CONFIG_FILE.is_file():
                    archive.write(CONFIG_FILE, "SMWStreamTrackerConfig.json")
                if TIMER_SAVE_FILE.is_file():
                    archive.write(TIMER_SAVE_FILE, "SMWStreamTrackerTimes.json")
                if DEATH_SAVE_FILE.is_file():
                    archive.write(
                        DEATH_SAVE_FILE,
                        "SMWStreamTrackerDeaths.json",
                    )
                if LEVEL_PROGRESS_SAVE_FILE.is_file():
                    archive.write(
                        LEVEL_PROGRESS_SAVE_FILE,
                        "SMWStreamTrackerLevelProgress.json",
                    )
                archive.writestr("backup_info.json", json.dumps(metadata, indent=2))
            backups = sorted(
                AUTOMATIC_BACKUP_DIR.glob("SMWStreamTracker_*.zip"),
                key=lambda item: item.stat().st_mtime,
                reverse=True,
            )
            for obsolete in backups[self._recovery_backup_retention():]:
                try:
                    obsolete.unlink()
                except OSError:
                    pass
            if show_confirmation:
                messagebox.showinfo(
                    "Recovery Backup Created",
                    "A complete recovery backup was created.\n\n" + str(destination),
                    parent=self.root,
                )
            return destination
        except Exception as error:
            append_error_log("Recovery backup failed", traceback.format_exc())
            if show_confirmation:
                messagebox.showerror(
                    "Backup Failed",
                    str(error),
                    parent=self.root,
                )
            return None
        finally:
            try:
                temporary_database.unlink(missing_ok=True)
            except OSError:
                pass

    def _create_daily_recovery_backup(self) -> None:
        today = date.today().isoformat()
        if str(self.config.get("last_automatic_backup_date", "")) == today:
            return
        if self._create_recovery_backup("daily") is not None:
            self.config["last_automatic_backup_date"] = today
            try:
                save_config(self.config)
            except OSError:
                pass

    def _version_tuple(self, value: object) -> tuple[int, ...]:
        numbers = re.findall(r"\d+", str(value or ""))
        return tuple(int(number) for number in numbers[:4]) or (0,)

    def _fetch_update_manifest(self) -> dict[str, Any]:
        manifest_url = str(
            self.config.get("update_manifest_url", DEFAULT_UPDATE_MANIFEST_URL)
        ).strip()
        if not manifest_url.casefold().startswith("https://"):
            raise RuntimeError("The update manifest must use HTTPS.")
        request = Request(
            manifest_url,
            headers={"User-Agent": f"SMWStreamTracker/{APP_VERSION}"},
        )
        with urlopen(request, timeout=20) as response:
            payload = response.read(1024 * 1024 + 1)
        if len(payload) > 1024 * 1024:
            raise RuntimeError("The update manifest is unexpectedly large.")
        # Windows PowerShell 5 commonly writes UTF-8 JSON with a BOM.
        # utf-8-sig accepts both BOM and ordinary BOM-free UTF-8 manifests.
        manifest = json.loads(payload.decode("utf-8-sig"))
        if not isinstance(manifest, dict):
            raise RuntimeError("The update manifest is not valid.")
        if IS_MACOS:
            architecture = system_platform.machine().casefold()
            package_key = (
                "macos_arm64"
                if architecture in {"arm64", "aarch64"}
                else "macos_x86_64"
            )
            mac_package = manifest.get(package_key, manifest.get("macos"))
            if not isinstance(mac_package, dict):
                manifest["platform_package_missing"] = True
                return manifest
            manifest = {**manifest, **mac_package}
            manifest["package_type"] = str(
                mac_package.get("package_type", "dmg")
            ).casefold()
        for field in ("version", "updater_url", "sha256"):
            if not str(manifest.get(field, "")).strip():
                raise RuntimeError("The update manifest is missing " + field + ".")
        updater_url = str(manifest["updater_url"])
        if not updater_url.casefold().startswith("https://"):
            raise RuntimeError("The updater download must use HTTPS.")
        digest = str(manifest["sha256"]).casefold()
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise RuntimeError("The updater SHA-256 value is invalid.")
        return manifest

    def _preserve_current_app_for_rollback(self) -> None:
        if not bool(getattr(sys, "frozen", False)):
            return
        current_executable = Path(sys.executable).resolve()
        if not current_executable.is_file():
            raise RuntimeError("The installed application executable could not be found.")
        ROLLBACK_DIR.mkdir(parents=True, exist_ok=True)
        temporary_executable = ROLLBACK_DIR / "SMWStreamTracker_previous.tmp"
        temporary_hash = ROLLBACK_DIR / "SMWStreamTracker_previous.sha256.tmp"
        try:
            shutil.copy2(current_executable, temporary_executable)
            expected_hash = file_sha256(temporary_executable)
            temporary_hash.write_text(expected_hash + "\n", encoding="ascii")
            os.replace(temporary_executable, ROLLBACK_EXECUTABLE)
            os.replace(temporary_hash, ROLLBACK_HASH_FILE)
        except Exception:
            temporary_executable.unlink(missing_ok=True)
            temporary_hash.unlink(missing_ok=True)
            raise

    def check_for_updates(self, silent: bool = False) -> None:
        if not silent:
            self.status_var.set("Checking securely for updates...")

        def worker() -> None:
            try:
                manifest = self._fetch_update_manifest()
                available = (
                    not bool(manifest.get("platform_package_missing", False))
                    and self._version_tuple(manifest.get("version"))
                    > self._version_tuple(APP_VERSION)
                )
                self.root.after(
                    0,
                    lambda: self._show_update_result(manifest, available, silent),
                )
            except Exception as error:
                append_error_log("Update check failed", traceback.format_exc())
                if not silent:
                    error_text = str(error)
                    self.root.after(
                        0,
                        lambda: messagebox.showerror(
                            "Update Check Failed",
                            "SMW Stream Tracker could not check for updates.\n\n" + error_text,
                            parent=self.root,
                        ),
                    )
        threading.Thread(target=worker, daemon=True).start()
        return True

    def _show_update_result(
        self,
        manifest: dict[str, Any],
        available: bool,
        silent: bool,
    ) -> None:
        if not available:
            self.update_available_version = ""
            self.update_available_manifest = {}
            self._refresh_help_update_badge()
            self.status_var.set("SMW Stream Tracker is up to date.")
            if not silent:
                messagebox.showinfo(
                    self._translate_ui_text("No Update Available"),
                    self._format_ui_text(
                        "You have the latest version ({version}).",
                        version=APP_VERSION,
                    ),
                    parent=self.root,
                )
            return

        self.update_available_version = str(
            manifest.get("version", "")
        ).strip()
        self.update_available_manifest = dict(manifest)
        self._refresh_help_update_badge()
        if silent:
            self.status_var.set(
                self._format_ui_text(
                    "Update {version} is available in Help.",
                    version=self.update_available_version,
                )
            )
            return

        if self.update_dialog is not None:
            try:
                if self.update_dialog.winfo_exists():
                    self.update_dialog.destroy()
            except tk.TclError:
                pass
        palette = self._library_palette()
        dialog = tk.Toplevel(self.root)
        self.update_dialog = dialog
        dialog.title("SMW Stream Tracker Update")
        dialog.configure(bg=palette["window"])
        self._size_dialog_for_ui(dialog, 760, 650, 660, 540)
        self._add_dialog_window_controls(dialog, dialog, palette["window"])
        tk.Label(
            dialog,
            text="UPDATE AVAILABLE",
            font=("Segoe UI", 20, "bold"),
            fg="white",
            bg=THEME["green"],
            padx=18,
            pady=12,
            anchor="w",
        ).pack(fill="x")
        size_value = manifest.get("size", 0)
        try:
            size_text = f"{int(size_value) / 1024 / 1024:.1f} MB"
        except (TypeError, ValueError):
            size_text = "Unknown"
        details = (
            f"Installed version: {APP_VERSION}\n"
            f"New version: {manifest.get('version')}\n"
            f"Release date: {manifest.get('release_date', 'Unknown')}\n"
            f"Download size: {size_text}\n\n"
            "Release notes:\n"
        )
        notes = manifest.get("notes", "No release notes were provided.")
        if isinstance(notes, list):
            notes = "\n".join("- " + str(note) for note in notes)
        content = tk.Text(
            dialog,
            height=14,
            font=("Segoe UI", 11),
            bg=palette["panel"],
            fg=palette["text"],
            wrap="word",
            padx=16,
            pady=16,
            relief="solid",
            bd=1,
        )
        content.pack(fill="both", expand=True, padx=12, pady=12)
        content.insert("1.0", details + str(notes))
        content.configure(state="disabled")
        actions = tk.Frame(dialog, bg=palette["window"])
        actions.pack(fill="x", padx=12, pady=(0, 12))
        self._make_action_button(
            actions,
            "Download & Install",
            lambda: self._download_and_install_update(manifest, dialog),
            THEME["green"],
            THEME["green_dark"],
            width=20,
        ).pack(side="left")
        self._make_action_button(
            actions,
            "Later",
            dialog.destroy,
            "#60758D",
            "#40566E",
            width=10,
        ).pack(side="right")
        dialog.after_idle(
            lambda: self._fit_dialog_height_to_contents(dialog)
        )

    def _download_and_install_update(
        self,
        manifest: dict[str, Any],
        dialog: tk.Toplevel,
    ) -> None:
        dialog.destroy()
        self.status_var.set("Downloading and verifying the update package...")

        def worker() -> None:
            updater_path: Path | None = None
            try:
                UPDATE_DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
                package_extension = (
                    ".dmg"
                    if IS_MACOS
                    and str(manifest.get("package_type", "dmg")).casefold()
                    == "dmg"
                    else ".exe"
                )
                updater_path = UPDATE_DOWNLOAD_DIR / (
                    "SMWStreamTracker_Update_"
                    + str(manifest["version"])
                    + package_extension
                )
                digest = hashlib.sha256()
                request = Request(
                    str(manifest["updater_url"]),
                    headers={"User-Agent": f"SMWStreamTracker/{APP_VERSION}"},
                )
                total = 0
                with urlopen(request, timeout=45) as response, updater_path.open("wb") as output:
                    while True:
                        chunk = response.read(1024 * 1024)
                        if not chunk:
                            break
                        total += len(chunk)
                        if total > 500 * 1024 * 1024:
                            raise RuntimeError("The updater is larger than the 500 MB safety limit.")
                        digest.update(chunk)
                        output.write(chunk)
                if digest.hexdigest().casefold() != str(manifest["sha256"]).casefold():
                    raise RuntimeError("The updater failed its SHA-256 integrity check and was deleted.")

                backup = self._create_recovery_backup("before_update")
                if backup is None:
                    raise RuntimeError("A safety backup could not be created, so the update was stopped.")
                if IS_WINDOWS:
                    self._preserve_current_app_for_rollback()
                self.root.after(0, lambda: self._launch_update_package(updater_path))
            except Exception as error:
                if updater_path is not None:
                    try:
                        updater_path.unlink(missing_ok=True)
                    except OSError:
                        pass
                append_error_log("Update installation failed", traceback.format_exc())
                error_text = str(error)
                self.root.after(
                    0,
                    lambda: messagebox.showerror(
                        "Update Stopped Safely",
                        error_text,
                        parent=self.root,
                    ),
                )
        threading.Thread(target=worker, daemon=True).start()

    def _launch_update_package(self, updater_path: Path) -> None:
        if IS_MACOS:
            try:
                open_local_path(updater_path)
            except OSError as error:
                messagebox.showerror(
                    "Could Not Open Update",
                    str(error),
                    parent=self.root,
                )
                return
            self._show_localized_info(
                "Mac Update Ready",
                (
                    "The verified Mac disk image is open. Drag SMW Stream "
                    "Tracker to Applications and replace the existing copy, "
                    "then reopen it. Your catalog, settings, and stats stay "
                    "in your Library folder."
                ),
                parent=self.root,
            )
            return
        updater_environment = os.environ.copy()
        # A PyInstaller one-file app records its private extraction folder in
        # _PYI_* variables.  The updater inherits those variables and can pass
        # them to the newly installed app after this process has removed that
        # folder, which produces a harmless "Failed to load Python DLL" dialog
        # even though the update succeeded.  Treat the updater and its final
        # app launch as an independent process tree.
        for variable_name in tuple(updater_environment):
            if variable_name.startswith("_PYI_"):
                updater_environment.pop(variable_name, None)
        updater_environment["PYINSTALLER_RESET_ENVIRONMENT"] = "1"
        try:
            subprocess.Popen(
                [str(updater_path), "/SP-"],
                env=updater_environment,
            )
        except OSError as error:
            messagebox.showerror("Could Not Start Updater", str(error), parent=self.root)
            return
        self.shutdown()

    def restore_previous_app_version(self) -> None:
        if not IS_WINDOWS:
            messagebox.showinfo(
                "Rollback on Mac",
                (
                    "Mac app replacement is handled through the verified DMG. "
                    "Tracker data is backed up separately and is not removed "
                    "when the app is replaced."
                ),
                parent=self.root,
            )
            return
        previous_executable = ROLLBACK_EXECUTABLE
        previous_hash_file = ROLLBACK_HASH_FILE
        rollback_script = application_directory() / "rollback_update.ps1"
        if not getattr(sys, "frozen", False):
            messagebox.showinfo(
                "Rollback Available After Installation",
                "App rollback is available in an installed release, not while running from source.",
                parent=self.root,
            )
            return
        if (
            not previous_executable.is_file()
            or not previous_hash_file.is_file()
            or not rollback_script.is_file()
        ):
            messagebox.showinfo(
                self._translate_ui_text("No Previous Version"),
                self._translate_ui_text(
                    "No previous installed app version is available to restore yet."
                ),
                parent=self.root,
            )
            return
        try:
            expected_hash = previous_hash_file.read_text(encoding="ascii").strip().casefold()
            actual_hash = file_sha256(previous_executable).casefold()
        except OSError as error:
            messagebox.showerror(
                "Rollback Stopped Safely",
                "The previous executable could not be verified.\n\n" + str(error),
                parent=self.root,
            )
            return
        if not re.fullmatch(r"[0-9a-f]{64}", expected_hash) or actual_hash != expected_hash:
            messagebox.showerror(
                "Rollback Stopped Safely",
                "The previous executable did not pass its SHA-256 integrity check.",
                parent=self.root,
            )
            return
        if not messagebox.askyesno(
            "Restore Previous App Version",
            "Restore the previous app version? Your tracker data and settings will be backed up first.",
            parent=self.root,
        ):
            return
        if self._create_recovery_backup("before_rollback") is None:
            messagebox.showerror(
                "Rollback Stopped Safely",
                "The recovery backup could not be created.",
                parent=self.root,
            )
            return
        try:
            subprocess.Popen(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-ExecutionPolicy",
                    "Bypass",
                    "-File",
                    str(rollback_script),
                    "-CurrentExe",
                    str(Path(sys.executable)),
                    "-BackupExe",
                    str(previous_executable),
                    "-ProcessId",
                    str(os.getpid()),
                    "-ExpectedSha256",
                    expected_hash,
                ],
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
        except OSError as error:
            messagebox.showerror("Could Not Start Rollback", str(error), parent=self.root)
            return
        self.shutdown()

    def _open_installed_document(self, filename: str) -> None:
        document = installed_document_path(filename)
        if not document.is_file():
            messagebox.showerror(
                APP_NAME,
                filename + " is not installed.",
                parent=self.root,
            )
            return
        open_local_path(document)

    def _selected_readme_path(self) -> Path:
        """Return only the guide selected by Setup, with an English fallback."""
        language = str(getattr(self, "app_language", "en") or "en")
        readme_filename = README_LANGUAGE_FILENAMES.get(
            language,
            README_LANGUAGE_FILENAMES["en"],
        )
        candidates = (
            bundled_resource_path("docs", readme_filename),
            Path(__file__).resolve().parent / "docs" / readme_filename,
            application_directory() / "README.txt",
            bundled_resource_path("docs", README_LANGUAGE_FILENAMES["en"]),
            Path(__file__).resolve().parent
            / "docs"
            / README_LANGUAGE_FILENAMES["en"],
        )
        for candidate in candidates:
            if candidate.is_file():
                return candidate
        return candidates[-1]

    def open_readme_dialog(self) -> None:
        if self.readme_dialog is not None:
            try:
                if self.readme_dialog.winfo_exists():
                    self.readme_dialog.deiconify()
                    self.readme_dialog.lift()
                    self.readme_dialog.focus_force()
                    return
            except tk.TclError:
                pass

        readme_path = self._selected_readme_path()
        try:
            readme_text = readme_path.read_text(
                encoding="utf-8-sig",
                errors="replace",
            )
        except OSError as error:
            messagebox.showerror(
                self._translate_ui_text("Read Me"),
                self._translate_ui_text(
                    "The selected-language Read Me could not be opened."
                )
                + "\n\n"
                + str(error),
                parent=self.root,
            )
            return

        palette = self._library_palette()
        dialog = self._open_in_app_page(
            "readme",
            "Read Me / Setup Guide",
        )
        self.readme_dialog = dialog
        dialog.title("Read Me / Setup Guide - SMW Stream Tracker")
        dialog.configure(bg=palette["window"])
        self._size_dialog_for_ui(dialog, 1040, 820, 720, 560)
        self._add_dialog_window_controls(dialog, dialog, palette["window"])

        tk.Label(
            dialog,
            text="READ ME / SETUP GUIDE",
            font=("Segoe UI", 20, "bold"),
            fg="white",
            bg=THEME["blue"],
            padx=18,
            pady=12,
        ).pack(fill="x")

        guide_frame = tk.Frame(
            dialog,
            bg=palette["panel"],
            highlightbackground=palette["border"],
            highlightthickness=1,
        )
        guide_frame.pack(
            fill="both",
            expand=True,
            padx=12,
            pady=12,
        )
        scrollbar = ttk.Scrollbar(
            guide_frame,
            orient="vertical",
            style="Mario.Vertical.TScrollbar",
        )
        guide = tk.Text(
            guide_frame,
            wrap="word",
            font=("Segoe UI", 10),
            fg=palette["text"],
            bg=palette["panel"],
            insertbackground=palette["text"],
            selectbackground=palette["selected"],
            selectforeground="white",
            relief="flat",
            padx=16,
            pady=14,
            yscrollcommand=scrollbar.set,
        )
        scrollbar.configure(command=guide.yview)
        guide.insert("1.0", readme_text)

        def jump_to_readme_line(target_line: int):
            def jump(_event=None):
                target = f"{target_line}.0"
                guide.see(target)
                guide.mark_set("insert", target)
                guide.focus_set()
                return "break"

            return jump

        for link_number, (toc_line, target_line) in enumerate(
            _readme_toc_targets(readme_text),
            start=1,
        ):
            tag_name = f"readme_toc_link_{link_number}"
            guide.tag_add(
                tag_name,
                f"{toc_line}.0",
                f"{toc_line}.end",
            )
            guide.tag_configure(
                tag_name,
                foreground=THEME["blue"],
                underline=True,
            )
            guide.tag_bind(
                tag_name,
                "<Button-1>",
                jump_to_readme_line(target_line),
            )
            guide.tag_bind(
                tag_name,
                "<Enter>",
                lambda _event: guide.configure(cursor="hand2"),
            )
            guide.tag_bind(
                tag_name,
                "<Leave>",
                lambda _event: guide.configure(cursor="xterm"),
            )
        guide.configure(state="disabled")
        guide.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        self._bind_fast_vertical_scroll(guide)

        actions = tk.Frame(dialog, bg=palette["window"])
        actions.pack(fill="x", padx=12, pady=(0, 12))
        self._make_action_button(
            actions,
            "Visit SMW Central",
            lambda: webbrowser.open(SMW_CENTRAL_WEBSITE_URL),
            THEME["orange"],
            "#A84808",
            width=17,
        ).pack(side="left")

        def close_readme() -> None:
            try:
                dialog.destroy()
            finally:
                self.readme_dialog = None

        self._make_action_button(
            actions,
            "Close",
            close_readme,
            "#60758D",
            "#40566E",
            width=10,
        ).pack(side="right")
        dialog.protocol("WM_DELETE_WINDOW", close_readme)
        self._apply_widget_appearance(
            dialog,
            dark=(self.appearance_var.get() == "dark"),
        )

    def _stop_feedback_webview_process(self) -> None:
        feedback_process = self.feedback_webview_process
        self.feedback_webview_process = None
        if feedback_process is None or feedback_process.poll() is not None:
            return

        try:
            feedback_process.terminate()
            feedback_process.wait(timeout=2)
        except Exception:
            try:
                feedback_process.kill()
            except Exception:
                pass

    def open_feedback_dialog(self) -> None:
        # The Help command is the action: skip an intermediate page and open
        # the anonymous Microsoft Form in the app's private WebView2 window.
        self._stop_feedback_webview_process()
        environment = os.environ.copy()
        for variable_name in tuple(environment):
            if variable_name.startswith("_PYI_"):
                environment.pop(variable_name, None)
        environment["PYINSTALLER_RESET_ENVIRONMENT"] = "1"
        try:
            self.feedback_webview_process = subprocess.Popen(
                _feedback_webview_command(
                    self.appearance_var.get(),
                    self.app_language,
                ),
                env=environment,
                creationflags=getattr(
                    subprocess,
                    "CREATE_NO_WINDOW",
                    0,
                ),
            )
        except OSError as error:
            self.feedback_webview_process = None
            messagebox.showerror(
                "Feedback Form Could Not Be Opened",
                "The anonymous feedback form could not be opened inside "
                "SMW Stream Tracker.\n\n" + str(error),
                parent=self.root,
            )

    def open_discord_community(self) -> None:
        """Open the project Discord invite in the user's default browser."""
        try:
            opened = webbrowser.open(DISCORD_COMMUNITY_URL)
        except (OSError, webbrowser.Error):
            opened = False
        if opened:
            return
        messagebox.showerror(
            "Discord Could Not Be Opened",
            (
                "The Discord invite could not be opened in your default "
                "browser. You can copy this address instead:\n\n"
                + DISCORD_COMMUNITY_URL
            ),
            parent=self.root,
        )

