    def open_output_folder(self) -> None:
        folder_text = self.output_folder_var.get().strip()
        if not folder_text:
            messagebox.showerror(
                APP_NAME,
                "Choose an OBS text folder in OBS Settings first.",
                parent=self.root,
            )
            return

        self.config["output_folder"] = folder_text
        try:
            folder = ensure_obs_text_files(self.config)
        except OSError as error:
            messagebox.showerror(
                APP_NAME,
                f"Could not create the OBS text folder:\n{error}",
                parent=self.root,
            )
            return
        if folder is None:
            return
        open_local_path(folder)

    def _test_selected_platform(self) -> None:
        if not self.save_settings():
            return
        platform = self.platform_var.get().strip() or "FXPAK Pro"
        self.status_var.set(f"Testing {platform}...")

        def run_test() -> None:
            test_worker = TrackerWorker(
                self.config.copy(),
                queue.Queue(),
            )
            ws: websocket.WebSocket | None = None
            try:
                test_worker.start_qusb2snes_if_needed()
                ws, device = test_worker.connect_to_fxpak()
                detected_rom = test_worker.get_loaded_rom_path(ws)
                launch_note = ""
                if platform in PLATFORM_LOCAL_EMULATORS:
                    executable_key = PLATFORM_EXECUTABLE_CONFIG_KEYS[platform]
                    executable_ok = Path(
                        str(self.config.get(executable_key, ""))
                    ).is_file()
                    library_ok = Path(
                        str(
                            self.config.get("platform_rom_library_folder", "")
                            or self.config.get("rom_builder_library_folder", "")
                        )
                    ).is_dir()
                    core_ok = True
                    if platform == "RetroArch":
                        core_ok = Path(
                            str(self.config.get("retroarch_core_path", ""))
                        ).is_file()
                    launch_note = (
                        "\n\n"
                        + self._translate_ui_text("Game launching: ready")
                        if executable_ok and library_ok and core_ok
                        else "\n\n"
                        + self._translate_ui_text(
                            "Live tracking is connected, but game launching still needs the missing path(s) in Settings."
                        )
                    )
                message = (
                    self._format_ui_text(
                        "{platform} is connected through {device}.",
                        platform=platform,
                        device=device,
                    )
                    + (
                        "\n\n"
                        + self._translate_ui_text("Detected ROM:")
                        + f" {clean_rom_filename(detected_rom)}"
                        if detected_rom
                        else "\n\n"
                        + self._translate_ui_text(
                            "The connection is ready; no running ROM was detected."
                        )
                    )
                    + launch_note
                )
                self.root.after(
                    0,
                    lambda: (
                        self.status_var.set(f"{platform} test passed."),
                        messagebox.showinfo(
                            self._translate_ui_text(
                                "Platform Test Passed"
                            ),
                            message,
                            parent=self.root,
                        ),
                    ),
                )
            except Exception as error:
                error_text = str(error)
                self.root.after(
                    0,
                    lambda: (
                        self.status_var.set(
                            f"{platform} test failed: {error_text}"
                        ),
                        messagebox.showerror(
                            self._translate_ui_text(
                                "Platform Test Failed"
                            ),
                            self._format_ui_text(
                                "{platform} could not connect.",
                                platform=platform,
                            )
                            + f"\n\n{error_text}",
                            parent=self.root,
                        ),
                    ),
                )
            finally:
                if ws is not None:
                    try:
                        ws.close()
                    except Exception:
                        pass

        threading.Thread(
            target=run_test,
            daemon=True,
        ).start()

    def _on_platform_selected(self, event=None) -> None:
        platform = self.platform_var.get().strip()
        if platform not in PLATFORM_OPTIONS:
            platform = "FXPAK Pro"
            self.platform_var.set(platform)

        platform_photo = (
            self.platform_icon_photos.get(platform)
            or self.fxpak_icon_photo
        )
        if getattr(self, "platform_icon_label", None) is not None:
            self.platform_icon_label.configure(
                image=platform_photo
            )
            self.platform_icon_label.image = platform_photo
        if getattr(self, "platform_name_label", None) is not None:
            self.platform_name_label.configure(
                text=platform.upper()
            )
        if (
            self.game_library_dialog is not None
            and self.game_library_dialog.winfo_exists()
        ):
            self.game_library_dialog.title(platform + " Game Library")
            if hasattr(self, "game_library_status_var"):
                self.game_library_status_var.set(
                    f"Ready to launch a game on {platform}."
                )

        self.config[
            "selected_platform"
        ] = platform
        try:
            save_config(self.config)
        except OSError:
            pass

        self.connection_var.set(
            f"Switching to {platform}..."
        )
        self.status_var.set(
            f"Selected {platform}. Reconnecting the tracker..."
        )
        if self._tracker_is_running():
            self.refresh_tracker()
        else:
            self.start_tracker()

    def start_tracker(self) -> None:
        if (
            self.worker
            and self.worker.thread
            and self.worker.thread.is_alive()
        ):
            return

        if not self.save_settings():
            return

        self.worker = TrackerWorker(
            self.config.copy(),
            self.event_queue,
        )
        self.worker.start()

        self.status_var.set("Starting tracker…")

    def refresh_tracker(self) -> None:
        if self._tracker_is_running():
            self.restart_after_stop = True
            self.connection_var.set("Refreshing…")
            self.refresh_tracker_button.configure(
                state="disabled",
            )
            worker = self.worker
            if (
                self.platform_var.get().strip() == "FXPAK Pro"
                and self.connection_is_connected
            ):
                self.status_var.set(
                    self._translate_ui_text(
                        "Restarting the running FXPAK Pro game and "
                        "connection…"
                    )
                )
                worker.request_console_refresh()
                # If the bridge stopped responding before it could process
                # Reset, do not leave Refresh disabled indefinitely. The
                # ordinary connection restart still runs as a safe fallback.
                self.root.after(
                    2500,
                    lambda pending_worker=worker: (
                        pending_worker.stop()
                        if (
                            self.restart_after_stop
                            and self.worker is pending_worker
                            and pending_worker.thread is not None
                            and pending_worker.thread.is_alive()
                        )
                        else None
                    ),
                )
            else:
                self.status_var.set(
                    "Refreshing the "
                    + self.platform_var.get()
                    + " connection..."
                )
                worker.stop()
            return

        self.worker = None
        self.restart_after_stop = False
        self.start_tracker()

